import { filter } from 'ramda'

export const filterBy = {
  searchTerm: (searchTerm, playlist) => {
    const ACCENTS_REGEX = /[\u0300-\u036f]/g
    const NORMALIZATION = 'NFD'
    return filter(
      item =>
        item.title
          .normalize(NORMALIZATION)
          .replace(ACCENTS_REGEX, '')
          .toString()
          .toLowerCase()
          .includes(
            searchTerm
              ? searchTerm
                  .toLowerCase()
                  .normalize(NORMALIZATION)
                  .replace(ACCENTS_REGEX, '')
              : searchTerm.normalize(NORMALIZATION).replace(ACCENTS_REGEX, '')
          ),
      playlist
    )
  },
  videoTypes: (videoTypes, playlist) => {
    return filter(item => {
      if (videoTypes.filter(elem => item.videoType.includes(elem)).length > 0)
        return item
    }, playlist)
  },
}
