<template>
  <DialogCard :config="componentConfig.dialogData">
    <Form :config="componentConfig" />
  </DialogCard>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { testMode } from '@/config/env'
import ENTITIES_EVENTS from '@/config/events/databaseAPI/entitiesEvents'
import SALES_DB_API_EVENTS from '@/config/events/databaseAPI/salesEvents'
import SYNCHRONIZATION_EVENTS from '@/config/events/synchronization'
import { customer as customerMapper } from '@/config/storeMapper'
import itemAddedFrom from '@/config/itemAddedFrom'

import paymentMethods from '@/config/paymentMethods'

import {
  cleanObjectObserver,
  getTranslatedText,
  mapStoreObject,
} from '@/tools/data'
import { formatNumberToDb } from '@/tools/numbersFormat'
import { getNow } from '@/tools/dates'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import customersActions from '@/store/customers/actions.types'
import customersViewActions from '@/store/customersView/actions.types'

import setConfig from '@/components/CustomersView/AddCustomerDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import Form from '@/components/shared/Form'

export default {
  name: 'AddCustomerDialog',
  components: { DialogCard, Form },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
      addingCustomer: false,
    }
  },
  computed: {
    ...mapState('customersView', ['addCustomerDialog']),
    ...mapState('usersView', ['selectedUser']),
    ...mapState('account', { accountData: state => state.data }),
    componentConfig() {
      return setConfig(
        {
          isOpen: this.addCustomerDialog.isOpen,
          inputs: this.inputs,
          v: this.$v.inputs,
          routeName: this.$route.name,
          limits: this.accountData.country.limits,
        },
        {
          addCustomer: this.addCustomer,
          closeDialog: this.closeDialog,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('customers', [
      customersActions.createCustomer,
      customersActions.setCustomersFetching,
      customersActions.updateCustomer,
      customersActions.setCustomersError,
    ]),
    ...mapActions('customersView', [
      customersViewActions.setAddCustomerDialogStatus,
    ]),
    setProperties: function() {
      this.componentConfig.fields.forEach(field => {
        this.$set(this.inputs, field.id, '')
        if (field.validators)
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
    },
    async addCustomer() {
      if (this.addingCustomer === true) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'AddCustomerDialog',
        name: 'Submit',
      })
      if (this.$v.inputs.$invalid) {
        Object.keys(this.inputs).forEach(key => {
          if (key in this.$v.inputs) this.$v.inputs[key].$touch()
        })
        return
      }
      this.$loading.show('createCustomer')
      this.addingCustomer = true
      const customer = Object.fromEntries(
        Object.entries(this.inputs).filter(item => item[1] != '')
      )
      customer.debt = 0
      customer.debtLimit = customer.debtLimit
        ? formatNumberToDb(customer.debtLimit)
        : 0
      if (customer.birthdate && customer.birthdate.indexOf('-') > 4) {
        const diff = customer.birthdate.indexOf('-') - 4
        customer.birthdate = customer.birthdate.substring(diff)
      }
      const customerToInsert = mapStoreObject(customer, customerMapper, true)
      this[customersActions.setCustomersFetching](true)
      rendererEventsService.send(ENTITIES_EVENTS.channel, {
        event: ENTITIES_EVENTS.events.addAndUpdateKey.name,
        data: {
          key: 'customers',
          entity: 'customers',
          dataToInsert: customerToInsert,
        },
      })
    },
    closeDialog() {
      Object.keys(this.inputs).forEach(key => {
        if (key in this.$v.inputs) this.$v.inputs[key].$reset()
      })
      Object.keys(this.inputs).forEach(key => (this.inputs[key] = ''))
      this[customersViewActions.setAddCustomerDialogStatus](false)
    },
    async onCustomerCreated(customer) {
      rendererEventsService.send(SYNCHRONIZATION_EVENTS.channel, {
        event: SYNCHRONIZATION_EVENTS.events.createOperation.name,
        data: {
          entityData: customer,
          entityName: 'customers',
        },
      })
      const customerCreated = await this[customersActions.createCustomer]({
        customer,
        userId: this.selectedUser.id,
        initialDebtString: this.getTranslatedText(
          'customersView.addCustomerDialog.initialDebt'
        ),
        amount: formatNumberToDb(this.inputs.debt),
      })
      if (this.inputs.debt > 0) {
        this.createCustomerInitialDebt({
          customer: customerCreated,
          amount: formatNumberToDb(this.inputs.debt),
          itemString: this.getTranslatedText(
            'customersView.addCustomerDialog.initialDebt'
          ),
        })
      } else {
        this[customersActions.setCustomersFetching](false)
        notificationsService.showSuccess(
          'customersView.listView.messages.newCustomerAdded',
          this.$vuetify.lang,
          { timeout: 8000 }
        )
        this.$root.$emit('customerAdded', customer._id)
        this.closeDialog()
        this.addingCustomer = false
      }
    },
    onCustomerCreatedError(error) {
      this[customersActions.setCustomersError](error)
      this[customersActions.setCustomersFetching](false)
      notificationsService.showError(
        'customersView.listView.messages.addNewCustomerError',
        this.$vuetify.lang,
        { timeout: 8000 }
      )
      this.closeDialog()
      this.addingCustomer = false
    },
    createCustomerInitialDebt(data) {
      const { customer, amount, itemString } = data
      const saleData = {
        customer,
        items: [
          {
            cost: -1,
            id: -1,
            isGeneric: 0,
            isGramaje: 0,
            isOpenProduct: 0,
            name: itemString,
            priceFrom: itemAddedFrom.FROM_SCANNER,
            quantity: 1,
            stock: 0,
            timeAdded: getNow(false),
            unitPrice: amount,
            promotionTypeId: 0,
            promotions: [],
            priceWithoutPromotion: amount,
            promotionExtra: 0,
          },
        ],
        promotion: 0,
        promotion_type: 'percent',
        promotionTicketId: 0,
        payOption: paymentMethods.creditKey,
        promotions: [],
      }
      rendererEventsService.send(SALES_DB_API_EVENTS.channel, {
        event: SALES_DB_API_EVENTS.events.createCustomerInitialDebtSale.name,
        data: {
          saleData: saleData,
          userId: this.selectedUser.id,
          totalPrice: amount,
        },
      })
    },
    customerInitialDebtListener(event, payload) {
      const events = SALES_DB_API_EVENTS.events
      const replies = {
        [events.createCustomerInitialDebtSale.replies.success]: () => {
          this[customersActions.updateCustomer](payload.data.customer)
          this[customersActions.setCustomersFetching](false)
          notificationsService.showSuccess(
            'customersView.listView.messages.newCustomerAdded',
            this.$vuetify.lang,
            { timeout: 8000 }
          )
          this.$root.$emit('customerAdded', payload.data.customer.id)
          this.closeDialog()
          this.addingCustomer = false
        },
        [events.createCustomerInitialDebtSale.replies.error]: () => {
          this.addingCustomer = false
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    addOrUpdateKeyListener(event, payload) {
      const addReplies = ENTITIES_EVENTS.events.addAndUpdateKey.replies
      const replies = {
        [`${addReplies.success}-customers`]: () => {
          this.$track({
            type: 'system',
            action: 'create_customer',
            category: this.$route.name,
            screen: `AddCustomerDialog`,
            name: 'Close dialog',
          })
          this.onCustomerCreated(payload.data)
        },
        [`${addReplies.error}-customers`]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: this.$route.name,
            screen: `AddCustomerDialog`,
            name: 'Error creating customer',
          })
          this.onCustomerCreatedError(payload.data)
        },
      }
      if (payload.event in replies) replies[payload.event]()
      this.$loading.hide()
    },
  },
  validations() {
    return this.validators
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      ENTITIES_EVENTS.replyChannel,
      this.addOrUpdateKeyListener
    )
    rendererEventsService.subscribe(
      SALES_DB_API_EVENTS.replyChannel,
      this.customerInitialDebtListener
    )
  },
  mounted: function() {
    this.setProperties()
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      ENTITIES_EVENTS.replyChannel,
      this.addOrUpdateKeyListener
    )
    rendererEventsService.removeListener(
      SALES_DB_API_EVENTS.replyChannel,
      this.customerInitialDebtListener
    )
  },
}
</script>
