<template>
  <v-navigation-drawer
    :value="showListNotifications"
    absolute
    bottom
    right
    temporary
    width="400"
    class="pa-5 pr-0"
    @input="toggleDrawer"
  >
    <ScrollContainer height="98%">
      <p class="text-h6 textPrimary--text text--lighten-1 mb-2">
        {{ getTranslatedText('notificationsView.title') }}
      </p>
      <v-list nav class="px-0">
        <v-list-item
          v-for="(notification, index) in config.notifications"
          :key="index"
          class="px-0 mb-1"
        >
          <NotificationCard :notification="notification" />
        </v-list-item>
        <v-list-item
          v-if="config.notifications.length === 0"
          class="d-block text-center"
        >
          <p class="text-subtitle-1 grey--text text-center">
            {{ getTranslatedText('notificationsView.empty') }}
          </p>
        </v-list-item>
      </v-list>
    </ScrollContainer>
  </v-navigation-drawer>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import SURVEY_API_EVENTS from '@/config/events/serversAPI/surveyEvents'

import { getTranslatedText } from '@/tools/data'
import { getDiffBetweenDates, toDate } from '@/tools/dates'

import rendererEventsService from '@/services/renderer/rendererEvents'

import notificationsActions from '@/store/notifications/actions.types'
import appActions from '@/store/app/actions.types'

import NotificationCard from '@/components/MainView/NotificationsDrawer/NotificationCard'
import setConfig from '@/components/MainView/NotificationsDrawer/config'
import tools from '@/components/MainView/NotificationsDrawer/notificationsDrawer.tools'
import ScrollContainer from '@/components/shared/ScrollContainer'

export default {
  name: 'NotificationsDrawer',
  components: { ScrollContainer, NotificationCard },
  data() {
    return {
      today: toDate(),
    }
  },
  computed: {
    ...mapState('account', { account: state => state.data }),
    ...mapState('notifications', [
      'showListNotifications',
      'notifications',
      'doneNotifications',
      'notificationsLoadedOnce',
    ]),
    ...mapState('vendors', { vendors: state => state.data.vendors }),
    ...mapState('products', { products: state => state.data.products }),
    config() {
      return setConfig(
        { notifications: this.notifications },
        {
          markNotificationDone: this.markNotificationDone,
          vendor: notification => this.goTo(notification),
          productsNoStock: notification => this.goTo(notification),
          productsLowStock: notification => this.goTo(notification),
          survey: this.showSurvey,
        }
      )
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('notifications', [
      notificationsActions.setStatusShowNotifications,
      notificationsActions.setNotifications,
      notificationsActions.addNotifications,
      notificationsActions.removeNotification,
      notificationsActions.resetDoneNotifications,
      notificationsActions.addNotificationLoadedOnce,
      notificationsActions.resetNotificationsLoadedOnce,
    ]),
    ...mapActions('app', [appActions.setSurveyDialog]),
    toggleDrawer(value) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'AppBar',
        name: `${value ? 'Open' : 'Close'} notifications`,
      })
      this.loadNotifications()
      this[notificationsActions.setStatusShowNotifications](value)
      if (value) {
        this.$root.$emit('notificationsWasOpened')
      }
    },
    markNotificationDone(notification) {
      this[notificationsActions.removeNotification](notification)
    },
    loadNotifications() {
      this[notificationsActions.setNotifications]([])
      this.loadPendingSurveys()
      tools.loadVendorsNotifications.call(this)
      tools.loadProductsNotifications.call(this)
      tools.loadNotificationsLoadedOnce.call(this)
    },
    notificationAlreadyDone(type, id) {
      return (
        this.doneNotifications[type] &&
        this.doneNotifications[type].includes(id)
      )
    },
    goTo(notification) {
      const path = tools.getPathByNotification(notification)
      if (!path) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'Notifications',
        name: `Go to ${notification.type}`,
      })
      if (this.$route.fullPath !== path) {
        this.$router.push(path)
        return
      }
      tools.replaceRouteByQuery.call(this, path)
    },
    loadNotificationsIfTodayChanged() {
      if (getDiffBetweenDates(toDate(), this.today, 'day') === 0) {
        return
      }
      this.today = new Date()
      this[notificationsActions.resetDoneNotifications]()
      this[notificationsActions.resetNotificationsLoadedOnce]()
      this.loadNotifications()
    },
    loadPendingSurveys() {
      if (!this.account.pos) {
        return
      }
      rendererEventsService.send(SURVEY_API_EVENTS.channel, {
        event: SURVEY_API_EVENTS.events.getAll.name,
        data: { pos: this.account.pos },
      })
    },
    showSurvey(notification) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'Notifications',
        name: 'See surveys',
      })
      this[appActions.setSurveyDialog]({
        isOpen: true,
        url: notification.data.url,
      })
    },
    createNotificationLoadedOnce(type) {
      if (!type) return
      this[notificationsActions.addNotificationLoadedOnce]({
        type: type,
        id: type,
        description: this.getTranslatedText(
          `notificationsView.${type}.description`
        ),
      })
      this.loadNotifications()
    },
  },
  created() {
    rendererEventsService.subscribe(
      SURVEY_API_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [SURVEY_API_EVENTS.events.getAll.replies.success]: () => {
            this[notificationsActions.addNotifications]({
              notifications: payload.data,
              arrayMethod: 'unshift',
            })
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  beforeMount() {
    this.loadNotifications()
    this.$root.$on('loadNotificationsIsNeeded', this.loadNotifications)
    this.$root.$on(
      'appComponentWasUpdated',
      this.loadNotificationsIfTodayChanged
    )
    this.$root.$on('mlpWasUpdated', () =>
      this.createNotificationLoadedOnce('mlpUpdated')
    )
  },
  beforeDestroy() {
    this[notificationsActions.resetDoneNotifications]()
    this.$root.$off(
      'appComponentWasUpdated',
      this.loadNotificationsIfTodayChanged
    )
    rendererEventsService.removeAllListeners(SURVEY_API_EVENTS.replyChannel)
    this.$root.$off('loadNotificationsIsNeeded', this.loadNotifications)
    this.$root.$off('mlpWasUpdated')
  },
}
</script>
