export default {
  install: (app, options) => {
    app.prototype.$loading = options.reactive({
      isActive: false,
      text: null,
      show: function(text = null) {
        this.isActive = true
        this.text = text
      },
      hide: function() {
        this.isActive = false
        this.text = null
      },
    })
  },
}
