export default {
  channel: 'push-notification',
  replyChannel: 'push-notification-reply',
  events: {
    startFCMService: {
      name: 'start-fcm-service',
      replies: {
        success: 'start-fcm-service-success',
        error: 'start-fcm-service-error',
      },
    },
    onPushNotificationReceived: {
      name: 'push-notification-received',
      replies: {
        success: 'push-notification-received-success',
        error: 'push-notification-received-error',
      },
    },
    createOperationToSendToken: {
      name: 'create-operation-to-send-token',
      replies: {
        success: 'create-operation-to-send-token-success',
        error: 'create-operation-to-send-token-error',
      },
    },
    processPushNotification: {
      name: 'process-push-notification',
      replies: {
        success: 'process-push-notification-success',
        error: 'process-push-notification-error',
      },
    },
  },
}
