import types from '@/store/loyaltyProgramView/mutations.types'

const setSearchTermFilter = (state, payload) => {
  state.filters.searchTerm = payload
}

const setSettingsDialogStatus = (state, payload) => {
  state.settingsDialog.isOpen = payload
}
const setConfirmSettingDialogStatus = (state, payload) => {
  const { isOpen, formPayload = {} } = payload
  state.confirmSettingDialog.isOpen = isOpen
  state.confirmSettingDialog.formPayload = formPayload
}
const setDeleteEnrolledCustomerDialogStatus = (state, payload) => {
  const { isOpen, selectedEnrolledCustomer = [], inBulk = false } = payload
  state.deleteEnrolledCustomerDialog.isOpen = isOpen
  state.deleteEnrolledCustomerDialog.selectedEnrolledCustomer = selectedEnrolledCustomer
  state.deleteEnrolledCustomerDialog.inBulk = inBulk
}

const setAddEnrolledCustomersDialogStatus = (state, payload) => {
  state.addEnrolledCustomersDialog.isOpen = payload
}

const setMessageInformationDialogStatus = (state, payload) => {
  const { isOpen, data } = payload
  state.messageInformationDialog.isOpen = isOpen
  state.messageInformationDialog.data = data
}

const setTutorialVideoDialogStatus = (state, payload) => {
  state.tutorialVideoDialog.isOpen = payload
}
const setSendNotificationsDialogStatus = (state, { isOpen, type = '' }) => {
  state.sendNotificationsDialog.isOpen = isOpen
  state.sendNotificationsDialog.type = type
}

export default {
  [types.SET_SEARCH_TERM_FILTER]: setSearchTermFilter,
  [types.SET_SETTINGS_DIALOG_STATUS]: setSettingsDialogStatus,
  [types.SET_CONFIRM_SETTINGS_DIALOG_STATUS]: setConfirmSettingDialogStatus,
  [types.SET_DELETE_ENROLLED_CUSTOMER_DIALOG_STATUS]: setDeleteEnrolledCustomerDialogStatus,
  [types.SET_ADD_ENROLLED_CUSTOMERS_DIALOG_STATUS]: setAddEnrolledCustomersDialogStatus,
  [types.SET_MESSAGE_INFORMATION_DIALOG_STATUS]: setMessageInformationDialogStatus,
  [types.SET_TUTORIAL_VIDEO_DIALOG_STATUS]: setTutorialVideoDialogStatus,
  [types.SET_SEND_NOTIFICATIONS_DIALOG_STATUS]: setSendNotificationsDialogStatus,
}
