import { promotions } from '@/config/promotions'

import { customPromotion } from '@/tools/customPromotions'

import { saleCanApplyPromotions } from '@/store/sales/actions.tools'

export const getMoreForLessPromotions = (rootGetters, sale, product) => {
  if (
    !saleCanApplyPromotions(sale) ||
    !customPromotion.canBeAppliedToProduct(product)
  ) {
    return []
  }
  const promotionProduct = getPromotionByProduct(rootGetters, product)
  if (!promotionProduct) return []
  const sortedMoreForLess = sortMoreForLessByQuantityDesc(promotionProduct)
  return getPromotionsToBeApplied(product, promotionProduct, sortedMoreForLess)
}

const getPromotionByProduct = (rootGetters, product) => {
  return rootGetters[
    'customPromotions/getCustomPromotionsByProductAndTypeWithFilters'
  ](promotions.SALE_ITEM_MORE_FOR_LESS, { isActive: true, product })[product.id]
}

const sortMoreForLessByQuantityDesc = promotion => {
  return promotion.promotions.sort((promo1, promo2) =>
    promo1.quantity > promo2.quantity ? -1 : 1
  )
}

const getPromotionsToBeApplied = (product, promotionProduct, moreForLess) => {
  const productPromotions = []
  let quantity = product.quantity
  moreForLess.forEach(promo => {
    if (quantity < promo.quantity) return
    const promosToAdd = Math.floor(quantity / promo.quantity)
    productPromotions.push(
      ...new Array(promosToAdd).fill({ ...promo, type: promotionProduct.type })
    )
    quantity = quantity - promo.quantity * promosToAdd
  })
  return productPromotions
}
