import { filter, includes } from 'ramda'

import { normalizeString } from '@/tools/data'

export const getFilteredData = (...args) => {
  const customers = args[0].data.customers
  const customersSearchTerm = normalizeString(
    args[2].customersView.filters.searchTerm || ''
  )
  return filter(
    customer => includes(customersSearchTerm, normalizeString(customer.name)),
    customers
  )
}
