import { pipe, filter, forEach, map, isNil } from 'ramda'

import MLP_API_EVENTS from '@/config/events/databaseAPI/mlpEvents'

import { getObjectCopy, getAccumValuesFromArrayItems } from '@/tools/data'
import { captureException } from '@/tools/exceptions'

import notificationsService from '@/services/renderer/notifications'
import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'

import menuConfig from '../menuConfig'

const initialMenuConfig = getObjectCopy(menuConfig)

export default {
  getVisibleMenuItems: function(menu, selectedUser) {
    if (isNil(menu)) return []

    return pipe(
      filter(item => item.show),
      forEach(item => {
        if (item.children)
          item.children = filter(child => {
            if (
              child.permissionToShow !== undefined &&
              selectedUser.id !== null
            ) {
              return selectedUser[child.permissionToShow] === 0 && child.show
            }
            return child.show
          })(item.children)
      }),
      filter(
        item =>
          (item.show && !item.children) ||
          (item.show && item.children.length > 0)
      )
    )(menu)
  },
  getSidebarHeights: function() {
    const menuChildren = document.getElementById('sidebar-list').children

    const itemsHeight = pipe(
      map(item => (item.id !== 'user-profile-card' ? item.clientHeight : null)),
      filter(item => item !== null)
    )(menuChildren)

    return {
      itemsCount: itemsHeight.length,
      accItemsHeight: getAccumValuesFromArrayItems(itemsHeight, 121),
    }
  },
  updateSidebarStatus: function(newSize, oldSize, options) {
    const { setSidebarStatus, onboardingEnabled } = options
    this.$_updateSidebarStatusWhenWindowWidthChange(
      newSize,
      oldSize,
      setSidebarStatus,
      onboardingEnabled
    )
    // Disabled until we have no more sections
    // this.$_updateItemsWhenWindowHeightDecrese(newSize, oldSize, state)
    // this.$_updateItemsWhenWindowHeightIncrese(newSize, oldSize, state)
  },
  $_updateSidebarStatusWhenWindowWidthChange: function(
    newSize,
    oldSize,
    setSidebarStatus,
    onboardingEnabled
  ) {
    if (onboardingEnabled) return setSidebarStatus(true)
    if (newSize.x !== oldSize.x && newSize.x < 1440) {
      setSidebarStatus(false)
    }

    if (newSize.x !== oldSize.x && newSize.x >= 1440) {
      setSidebarStatus(true)
    }
  },
  $_updateItemsWhenWindowHeightDecrese: function(newSize, oldSize, state) {
    const { itemsCount, accItemsHeight } = state.sidebarHeights
    let upOffset = 100

    for (let i = 1; i <= itemsCount - 2; i++) {
      if (
        newSize.y !== oldSize.y &&
        newSize.y < accItemsHeight[itemsCount - i] + upOffset
      ) {
        i === 1 ? (state.menuExpanded = false) : null
        state.menuConfig[itemsCount - i].expanded = undefined
      }
      upOffset = upOffset + 50
    }
  },
  $_updateItemsWhenWindowHeightIncrese: function(newSize, oldSize, state) {
    const { itemsCount, accItemsHeight } = state.sidebarHeights
    let downOffset = 200

    for (let i = itemsCount - 2; i >= 1; i--) {
      if (
        newSize.y !== oldSize.y &&
        newSize.y >= accItemsHeight[itemsCount - i] + downOffset
      ) {
        i === itemsCount - 2 ? (state.menuExpanded = true) : null
        i > 1 ? (state.menuConfig[itemsCount - i].expanded = true) : null
        i === 1 ? (state.menuExpanded = true) : null
        i === 1 ? (state.menuConfig = getObjectCopy(initialMenuConfig)) : null
      }
      downOffset = downOffset - 50
    }
  },
  onPreferencesClick: function() {
    this.$track({
      type: 'interaction',
      action: 'click',
      category: this.$route.name,
      screen: 'NavigationMenu',
      name: 'Go to preferences',
    })
    if (this.$route.path === '/app/preferences') return
    return this.$router
      .push('/app/preferences')
      .catch(error => captureException(error))
  },
  onSyncClick: function(accountData) {
    this.$track({
      type: 'interaction',
      action: 'click',
      category: this.$route.name,
      screen: 'NavigationMenu',
      name: 'Synchronize pending operations',
    })
    if (navigator.onLine === true) {
      notificationsService.showInfo(
        'notification.synchronization.syncing',
        this.$vuetify.lang
      )
      this.$root.$emit('sendOpsToSync', true)
      this[appActions.reduceSyncOpsCounter]()
      if (this.syncOpsCounter > 0)
        rendererEventsService.send(MLP_API_EVENTS.channel, {
          event: MLP_API_EVENTS.events.downloadMlpUpdatesIfNeeded.name,
          data: {
            country: accountData.country.phoneCode,
            device: accountData.device,
            operator: accountData.operator,
            securityData: accountData.security,
          },
        })
    } else {
      notificationsService.showError(
        'notification.synchronization.networkError',
        this.$vuetify.lang
      )
    }
  },
}
