<template>
  <DialogCard :config="dialogConfig.dialogData" />
</template>

<script>
import { mapActions, mapState } from 'vuex'

import DEVICE_INFO_EVENTS from '@/config/events/deviceInfo'

import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'

import DialogCard from '@/components/shared/DialogCard'
import setConfig from '@/components/TTBlockedDialog/config'

export default {
  name: 'TTBlockedDialog',
  components: { DialogCard },
  computed: {
    ...mapState('app', ['ttBlockedDialog']),
    dialogConfig() {
      return setConfig(
        {
          isOpen: this.ttBlockedDialog.isOpen,
        },
        {
          closeTiendatek: this.closeTiendatek,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.setTTBlockedDialogStatus]),
    closeTiendatek() {
      this[appActions.setTTBlockedDialogStatus](false)
      rendererEventsService.send(DEVICE_INFO_EVENTS.channel, {
        event: DEVICE_INFO_EVENTS.events.closeTiendatek.name,
      })
    },
  },
}
</script>
