import Vue from 'vue'

import logger from '@/tools/logger'

import mutationsTypes from '@/store/customers/mutations.types'

const setFetching = (state, newState) => {
  state.fetching = newState
}

const setError = (state, error) => {
  state.data.customers = []
  state.error = true
  state.errorMessage = error
}

const setCustomers = (state, payload) => {
  state.data.customers = payload
  state.error = false
  state.errorMessage = ''
}

const addCustomer = (state, payload) => state.data.customers.push(payload)

const updateCustomer = (state, payload) => {
  const index = state.data.customers.indexOf(
    state.data.customers.find(customer => customer.id === payload.id)
  )
  logger('info', `Index of the customer to update: ${index}`) // To investigate balance discrepancy errors. Delete it in the future
  Vue.set(state.data.customers, index, payload)
}

const editCustomerField = (state, payload) => {
  const index = state.data.customers.indexOf(
    state.data.customers.find(customer => customer.id === payload.id)
  )
  Vue.set(state.data.customers, index, {
    ...state.data.customers[index],
    ...payload,
  })
}

const deleteCustomer = (state, payload) => {
  const index = state.data.customers.findIndex(
    customer => customer.id === payload
  )
  state.data.customers.splice(index, 1)
}

export default {
  [mutationsTypes.SET_CUSTOMERS]: setCustomers,
  [mutationsTypes.SET_CUSTOMERS_FETCHING]: setFetching,
  [mutationsTypes.SET_CUSTOMERS_ERROR]: setError,
  [mutationsTypes.ADD_CUSTOMER]: addCustomer,
  [mutationsTypes.UPDATE_CUSTOMER]: updateCustomer,
  [mutationsTypes.DELETE_CUSTOMER]: deleteCustomer,
  [mutationsTypes.EDIT_CUSTOMER_FIELD]: editCustomerField,
}
