import { idOperations } from '@/config/cashOperationsVariables'

import { getDateWithFormat, addDays } from '@/tools/dates'
import {
  isChargeOperation,
  isPaidOperation,
  isNeutralOperation,
} from '@/tools/cashOperationsTools'
import { getTicketCodeFromDate } from '@/tools/ticket'
import { normalizeString } from '@/tools/data'

export const operationIsWithinFilter = (filters, operation) => {
  return (
    isInFilterIfExists.rangeDate(filters, operation) &&
    isInFilterIfExists.group(filters, operation) &&
    isInFilterIfExists.operationTypes(filters, operation)
  )
}

const isInFilterIfExists = {
  rangeDate: (filters, operation) => {
    if (!filters.dateRange || !filters.dateRange.length) return true
    const rangeDate = filters.dateRange
    const fromDate = getDateWithFormat(rangeDate[0], 'YYYY-MM-DD')
    const toDate =
      rangeDate[1] === undefined
        ? getDateWithFormat(addDays(rangeDate[0], 1), 'YYYY-MM-DD')
        : getDateWithFormat(addDays(rangeDate[1], 1), 'YYYY-MM-DD')
    return operation.date > fromDate && operation.date < toDate
  },
  group: (filters, operation) => {
    if (!filters.group) return true
    switch (filters.group) {
      case 'charged':
        return isChargeOperation(operation.operationType)
      case 'paid':
        return isPaidOperation(operation.operationType)
      case 'neutral':
        return isNeutralOperation(operation.operationType)
      case 'all':
      default:
        return true
    }
  },
  operationTypes: (filters, operation) => {
    if (!filters.operationTypes || !filters.operationTypes.length) return true
    return filters.operationTypes.includes(operation.operationType)
  },
}

export const ticketNumberIsInSearchTerm = (filters, ticketNumber) => {
  if (!filters.search) return true
  const searchTerm = normalizeString(filters.search)
  return ticketNumber.includes(searchTerm)
}

export const getTicketNumber = operation => {
  if (hasTicketNumber(operation.operationType)) {
    return getTicketCodeFromDate(operation.date)
  }
  return ''
}

const hasTicketNumber = operationType => {
  return [
    idOperations.ID_OPERATION_CASH_SALE,
    idOperations.ID_OPERATION_CREDIT_SALE,
    idOperations.ID_OPERATION_EXTERNAL_PAYMENT_SALE,
    idOperations.ID_OPERATION_OWNER_SALE,
    idOperations.ID_OPERATION_CASH_PURCHASE,
    idOperations.ID_OPERATION_CREDIT_PURCHASE,
  ].includes(operationType)
}
