const setConfig = (state, methods) => ({
  notifications: state.notifications.map(notification => ({
    ...notification,
    icon: notificationIcon[notification.type],
    color: notificationColor[notification.type],
    title: notificationTitle[notification.type],
    button: notificationButton[notification.type]
      ? {
          ...notificationButton[notification.type],
          click: methods[notification.type],
        }
      : null,
    buttonDone: notificationDoneButton[notification.type]
      ? {
          ...notificationDoneButton[notification.type],
          click: methods.markNotificationDone,
        }
      : null,
  })),
})

const notificationIcon = {
  vendor: 'mdi-truck',
  productsNoStock: 'mdi-package-variant-remove',
  productsLowStock: 'mdi-package-variant-minus',
  survey: 'mdi-message-question',
  mlpUpdated: 'mdi-fridge-variant-alert-outline',
}
const notificationColor = {
  vendor: 'orange',
  productsNoStock: 'error',
  productsLowStock: 'orange',
  survey: 'primary',
  mlpUpdated: 'primary',
}
const notificationButton = {
  vendor: { color: 'orange', text: 'notificationsView.vendor.button' },
  productsNoStock: {
    color: 'error',
    text: 'notificationsView.productsNoStock.button',
  },
  productsLowStock: {
    color: 'orange',
    text: 'notificationsView.productsLowStock.button',
  },
  survey: { color: 'primary', text: 'notificationsView.survey.button' },
}
const notificationDoneButton = {
  vendor: { color: 'orange', text: 'notificationsView.doneButton' },
  productsNoStock: { color: 'error', text: 'notificationsView.doneButton' },
  productsLowStock: { color: 'orange', text: 'notificationsView.doneButton' },
  mlpUpdated: { color: 'primary', text: 'notificationsView.doneButton' },
}
const notificationTitle = {
  vendor: 'notificationsView.vendor.title',
  productsNoStock: 'notificationsView.productsNoStock.title',
  productsLowStock: 'notificationsView.productsLowStock.title',
  survey: 'notificationsView.survey.title',
  mlpUpdated: 'notificationsView.mlpUpdated.title',
}

export default setConfig
