import PUSH_NOTIFICATIONS_EVENTS from '@/config/events/pushNotifications'

import logger from '@/tools/logger'
import { decryptValue } from '@/tools/security'

import rendererEventsService from '@/services/renderer/rendererEvents'

import store from '@/store'

let procedence = null

const pushNotificationsService = {
  startService: callFrom => {
    procedence = callFrom
    rendererEventsService.send(PUSH_NOTIFICATIONS_EVENTS.channel, {
      event: PUSH_NOTIFICATIONS_EVENTS.events.startFCMService.name,
    })
  },
  initListeners: () => {
    const { channel, replyChannel, events } = PUSH_NOTIFICATIONS_EVENTS
    rendererEventsService.subscribe(replyChannel, async (event, payload) => {
      const replies = {
        [events.startFCMService.replies.success]: () =>
          fcmServiceStarted({ channel, events }, payload.data),
        [events.startFCMService.replies.error]: () =>
          logger('error', 'notification error: ' + payload.error),
        [events.onPushNotificationReceived.name]: () =>
          onPushNotificationReceived({ channel, events }, payload.notification),
      }
      if (payload.event in replies) replies[payload.event]()
    })
  },
}

const fcmServiceStarted = (apiTools, data) => {
  const { channel, events } = apiTools
  logger('info', `FCM service successfully started`)
  if (procedence > 0)
    rendererEventsService.send(channel, {
      event: events.createOperationToSendToken.name,
      data: {
        pushToken: data.token,
        procedence: procedence,
      },
    })
}

const onPushNotificationReceived = (apiTools, notification) => {
  const { channel, events } = apiTools
  rendererEventsService.send(channel, {
    event: events.processPushNotification.name,
    data: {
      serverNotificationPayload: notification,
      token: {
        tok: decryptValue(store.state.account.data.security.token),
        sec: decryptValue(store.state.account.data.security.secret),
      },
      pos: store.state.account.data.pos,
      device: store.state.account.data.device,
    },
  })
}

export default pushNotificationsService
