import { loyaltyNotificationType } from '@/config/loyaltyProgram'

export const notificationTemplates = (...args) => {
  const state = args[0]
  const { templates } = state
  const notificationTemplates = templates.filter(
    template => template.type === loyaltyNotificationType.NOTIFICATION
  )
  return notificationTemplates
}

export const promotionsTemplates = (...args) => {
  const state = args[0]
  const { templates } = state
  const notificationTemplates = templates.filter(
    template => template.type === loyaltyNotificationType.PROMOTION
  )
  return notificationTemplates
}
