import types from '@/store/operations/mutations.types'

const setOperations = (state, payload) => {
  state.operations = payload
}

const setFetching = (state, newState) => {
  state.fetching = newState
}

const setError = (state, error) => {
  state.users = null
  state.error = true
  state.errorMessage = error
}

const resetErrorStatus = state => {
  state.error = false
  state.errorMessage = ''
}

export default {
  [types.SET_OPERATIONS]: setOperations,
  [types.SET_OPERATIONS_FETCHING]: setFetching,
  [types.SET_OPERATIONS_ERROR]: setError,
  [types.RESET_OPERATIONS_ERROR_STATUS]: resetErrorStatus,
}
