<template>
  <div class="agent-bubble">
    <v-avatar color="primary" size="40">
      <v-icon color="white">mdi-robot-excited</v-icon>
    </v-avatar>
    <div class="bubble-message">
      <div v-html="message" class="bubble-message__text" />
      <div v-if="helpful !== undefined" class="bubble-message__helpful">
        <p class="text-caption">
          {{ getTranslatedText('helpBot.chat.usefulHelpQuestion') }}
        </p>
        <v-btn
          :disabled="helpful !== null"
          text
          icon
          x-small
          class="helpful-yes"
          :class="{ active: helpful === true }"
          @click="$emit('helpfulSelected', true)"
        >
          <v-icon size="small">mdi-thumb-up-outline</v-icon>
        </v-btn>
        <v-btn
          :disabled="helpful !== null"
          text
          icon
          x-small
          class="helpful-no"
          :class="{ active: helpful === false }"
          @click="$emit('helpfulSelected', false)"
        >
          <v-icon size="small">mdi-thumb-down-outline</v-icon>
        </v-btn>
      </div>
      <div v-if="!!options.length" class="bubble-message__options">
        <v-btn
          v-for="(option, index) in options"
          :key="`${option.value}${index}`"
          outlined
          color="primary"
          rounded
          @click="$emit('optionWasSelected', option)"
        >
          {{ option.text }}
        </v-btn>
      </div>
    </div>
  </div>
</template>

<script>
import { getTranslatedText } from '@/tools/data'

export default {
  name: 'BotBubble',
  props: {
    message: {
      type: String,
      default: '',
    },
    options: {
      type: Array,
      default: () => [],
    },
    showFaqs: {
      type: Boolean,
      default: true,
    },
    helpful: {
      type: [Boolean, null, undefined],
      default: undefined,
    },
  },
  methods: { getTranslatedText },
}
</script>
