export const updateCustomerSalesData = (sales, item, receivables) => {
  const customerSales = sales.filter(sale => sale.customer_id === item.id)
  item.sales = customerSales
  item.unpaidSales = []
  customerSales.forEach(sale => {
    const receivable = receivables.find(
      receivable => sale._id == receivable.sales_id
    )
    if (receivable !== undefined) {
      sale['receivable'] = receivable
      item.unpaidSales.push(sale)
    }
  })
  item.unpaidSales.sort((a, b) => new Date(b.sale_date) - new Date(a.sale_date))
  item.salesNumber = customerSales.length
  item.unpaidSalesNumber = customerSales.filter(sale => sale.paid === 0).length
  item.expense = 0
  customerSales.map(sale => (item.expense += sale.final_price))
  item.lastSaleDate =
    customerSales.length < 1
      ? '-'
      : customerSales
          .reduce((prev, current) =>
            prev.sale_date > current.sale_date ? prev : current
          )
          .sale_date.substring(0, 10)
  return item
}
