import { promotions } from '@/config/promotions'

import { normalizeString } from '@/tools/data'
import {
  dateIsAfter,
  dateIsBefore,
  dayIsTodayOrAfter,
  dayIsTodayOrBefore,
  getNow,
} from '@/tools/dates'
import { comboPromotion, customPromotion } from '@/tools/customPromotions'

const ALL_FILTER = 'all'
const FAVORITE_FILTER = 'favorite'
const MORE_FOR_LESS_FILTER = 'moreForLess'
const COMBO_FILTER = 'combo'
const ACTIVE_FILTER = 'active'
const DISABLED_FILTER = 'disabled'

const FILTERS = {
  [FAVORITE_FILTER]: promo => promo.favorite === 1,
  [MORE_FOR_LESS_FILTER]: promo =>
    promo.type === promotions.SALE_ITEM_MORE_FOR_LESS,
  [COMBO_FILTER]: promo => promo.type === promotions.SALE_ITEM_COMBO,
  [ACTIVE_FILTER]: promo => {
    if (!promo.startDate) return promo.active === 1
    if (!promo.finishDate) {
      return dayIsTodayOrBefore(promo.startDate)
    }
    return (
      dayIsTodayOrBefore(promo.startDate) && dayIsTodayOrAfter(promo.finishDate)
    )
  },
  [DISABLED_FILTER]: promo => {
    if (!promo.startDate) return promo.active === 0
    if (!promo.finishDate) {
      return dateIsAfter(promo.startDate, getNow())
    }
    return (
      dateIsAfter(promo.startDate, getNow()) ||
      dateIsBefore(promo.finishDate, getNow())
    )
  },
}

export const getFilteredCustomPromotions = (state, getters, rootState) => {
  const promotions = Object.values(state.data.promotions)
  const filters = rootState.customPromotionsView.filters
  return promotions.filter(promo => {
    let searchHasMatch = true
    if (filters.search && filters.search.length > 2) {
      const search = normalizeString(filters.search)
      searchHasMatch = hasMatchWithSearch(search, promo)
    }
    if (filters.group) {
      if (filters.group === ALL_FILTER) return searchHasMatch
      return FILTERS[filters.group](promo) && searchHasMatch
    }
    return searchHasMatch
  })
}

const hasMatchWithSearch = (search, promo) => {
  if (promo.type === promotions.SALE_ITEM_MORE_FOR_LESS) {
    return (
      normalizeString(promo.product.name).includes(search) ||
      promo.product.upc.includes(search)
    )
  }
  return comboPromotion
    .getProductsKey()
    .some(
      key =>
        normalizeString(promo.promotions[key].name).includes(search) ||
        promo.promotions[key].upc.includes(search)
    )
}

export const getCustomPromotionsByProduct = state => {
  const promotionsByProducts = {}
  Object.values(state.data.promotions).forEach(promo => {
    if (promotions.SALE_ITEM_MORE_FOR_LESS === promo.type) {
      if (!promotionsByProducts[promo.product.id]) {
        promotionsByProducts[promo.product.id] = []
      }
      promotionsByProducts[promo.product.id].push(promo)
      return
    }
    comboPromotion.getProductsKey().forEach(key => {
      if (!promotionsByProducts[promo.promotions[key].id]) {
        promotionsByProducts[promo.promotions[key].id] = []
      }
      promotionsByProducts[promo.promotions[key].id].push(promo)
    })
  })
  return promotionsByProducts
}

export const getCustomPromotionsByProductAndTypeWithFilters = (
  state,
  getters,
  rootState
) => (byType, filterBy = {}) => {
  const promotionsByProductsAndType = {
    [promotions.SALE_ITEM_MORE_FOR_LESS]: {},
    [promotions.SALE_ITEM_COMBO]: {},
  }
  Object.values(state.data.promotions).forEach(promo => {
    if (!promotionPassFilters(rootState, promo, filterBy)) return
    if (promotions.SALE_ITEM_MORE_FOR_LESS === promo.type) {
      promotionsByProductsAndType[promo.type][promo.product.id] = promo
      return
    }
    comboPromotion.getProductsKey().forEach(key => {
      if (!promotionsByProductsAndType[promo.type][promo.promotions[key].id]) {
        promotionsByProductsAndType[promo.type][promo.promotions[key].id] = []
      }
      promotionsByProductsAndType[promo.type][promo.promotions[key].id].push(
        promo
      )
    })
  })
  return promotionsByProductsAndType[byType]
}

const promotionPassFilters = (rootState, promotion, filterBy) => {
  let result = true
  const filters = {
    isActive: () => customPromotion.isActive(promotion),
    product: product =>
      !customPromotion.productPriceWasChanged(promotion, product) &&
      customPromotion.canBeAppliedToProduct(product),
    sale: () => productsInSaleAreCorrect(rootState, promotion),
  }
  Object.keys(filterBy).forEach(key => {
    if (result === false) return
    result = filters[key](filterBy[key])
  })
  return result
}

const productsInSaleAreCorrect = (rootState, promotion) => {
  if (promotion.type === promotions.SALE_ITEM_MORE_FOR_LESS) return true
  const sale = rootState.sales.sales[rootState.salesView.currentSale.saleIndex]
  const keys = comboPromotion.getProductsKey()
  let result = true
  for (const item of sale.items) {
    if (!result) break
    if (item.id === promotion.promotions[keys[0]].id) {
      result =
        customPromotion.canBeAppliedToProduct(item) &&
        !customPromotion.productPriceWasChanged(promotion, item)
    }
    if (item.id === promotion.promotions[keys[1]].id) {
      result =
        customPromotion.canBeAppliedToProduct(item) &&
        !customPromotion.productPriceWasChanged(promotion, item)
    }
  }
  return result
}

export const getDisabledCustomPromotions = promotionsState => {
  return Object.values(promotionsState.data.promotions).filter(promo => {
    if (promo.finishDate && dateIsBefore(promo.finishDate, getNow())) {
      return true
    }
    if (promo.startDate && dateIsAfter(promo.startDate, getNow())) {
      return false
    }
    return promo.active === 0
  })
}
