<template>
  <v-select
    ref="country-select"
    v-model="country"
    :class="['custom-text-field', className]"
    :label="getTranslatedText('starterLayout.login.country')"
    :items="countries"
    item-text="name"
    item-value="localeIsoCode"
    append-icon="mdi-map-marker-outline"
    filled
    rounded
    dense
    :error-messages="onValidateCountry"
    :no-data-text="getTranslatedText('starterLayout.login.selectCountry')"
    @change="v.$reset()"
    @blur="v.$touch()"
    required
  />
</template>

<script>
import countries from '@/config/countries'

export default {
  name: 'CountryInputSelector',
  props: {
    value: {
      required: true,
    },
    v: {
      type: Object,
    },
    className: {
      type: String,
      default: '',
    },
  },
  data() {
    return {
      countries: Object.values(countries),
    }
  },
  computed: {
    country: {
      get() {
        return this.value
      },
      set(newValue) {
        this.$emit('input', newValue)
      },
    },
    onValidateCountry() {
      const errors = []
      if (this.v === undefined || !this.v.$dirty) return errors
      !this.v.required &&
        errors.push(
          this.getTranslatedText('starterLayout.login.countryRequired')
        )
      return errors
    },
  },
  methods: {
    getTranslatedText: function(translateString) {
      return this.$vuetify.lang.t(`$vuetify.${translateString}`)
    },
  },
}
</script>
