<template>
  <DialogCard :config="componentConfig.dialogData">
    <Form :config="componentConfig" />
  </DialogCard>
</template>

<script>
import { isNil } from 'ramda'
import { mapActions, mapState } from 'vuex'

import { testMode } from '@/config/env'
import USERS_EVENTS from '@/config/events/users'

import { cleanObjectObserver } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import appActions from '@/store/app/actions.types'
import usersViewActions from '@/store/usersView/actions.types'

import Form from '@/components/shared/Form'
import DialogCard from '@/components/shared/DialogCard'

import setConfig from '@/components/MainView/ChangeUserDialog/config'

export default {
  name: 'ChangeUserDialog',
  components: { DialogCard, Form },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
      changingUser: false,
    }
  },
  computed: {
    ...mapState('users', ['users']),
    ...mapState('usersView', ['selectedUser']),
    ...mapState('account', { ownerName: state => state.data.name }),
    componentConfig() {
      return setConfig(
        {
          selectedProduct: this.selectedUser,
          inputs: this.inputs,
          v: this.$v.inputs,
          users: this.allUsers,
        },
        {
          closeDialog: this.closeDialog,
          changeUserSelected: this.changeUserSelected,
        }
      )
    },
    allUsers() {
      const allUsers = this.users
      return allUsers
        .filter(user => user.deleted === 0)
        .map(user => {
          return {
            id: user._id,
            text:
              user._id == 1 && this.ownerName.length > 2
                ? this.ownerName.split(' ')[0]
                : user.name,
            password: user.password,
          }
        })
    },
  },
  methods: {
    ...mapActions('app', [appActions.setChangeUserDialogStatus]),
    ...mapActions('usersView', [usersViewActions.setSelectedUser]),
    setProperties: function() {
      this.componentConfig.fields.forEach(field => {
        this.$set(
          this.inputs,
          field.id,
          field.selected ? this[field.selected[0]][field.selected[1]] : ''
        )
        if (field.validators)
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
    },
    changeUserSelected: function() {
      if (this.changingUser === true) return
      if (this.$v.inputs.$invalid) {
        Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$touch())
        return
      }
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'ChangeUser',
        name: 'Submit',
      })
      if (!isNil(testMode)) {
        this.closeDialog()
        return
      }
      this.changingUser = true
      const data = Object.create(this.inputs)
      rendererEventsService.send(USERS_EVENTS.channel, {
        event: USERS_EVENTS.events.changeUser.name,
        data: { selectedUserId: data.user, password: data.password },
      })
    },
    redirectIfNotHasPermission(user) {
      const routePermission = {
        Reports: 'reportPermission',
        LoyaltyProgramConfig: 'loyaltyProgramPermission',
        LoyaltyProgram: 'loyaltyProgramPermission',
        CustomPromotions: 'promotionPermission',
        Operations: 'operationsPermission',
        Expenses: 'expensesPermission',
      }
      if (
        routePermission[this.$router.currentRoute.name] &&
        user[routePermission[this.$router.currentRoute.name]] === 1
      ) {
        this.$router.push({ path: '/app/sales' })
      }
    },
    closeDialog() {
      Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$reset())
      Object.keys(this.inputs).forEach(key => (this.inputs[key] = ''))
      this[appActions.setChangeUserDialogStatus](false)
    },
  },
  validations() {
    return this.validators
  },
  created() {
    rendererEventsService.subscribe(
      USERS_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [USERS_EVENTS.events.changeUser.replies.error]: () => {
            notificationsService.showError(
              payload.data.message,
              this.$vuetify.lang
            )
            this.changingUser = false
          },
          [USERS_EVENTS.events.changeUser.replies.success]: () => {
            notificationsService.showSuccess(
              'notification.users.changed',
              this.$vuetify.lang
            )
            this.closeDialog()
            this[usersViewActions.setSelectedUser](payload.data)
            this.redirectIfNotHasPermission(payload.data)
            this.changingUser = false
          },
        }
        replies[payload.event]()
      }
    )
  },
  mounted: async function() {
    if (this.$barcodeScanner) this.$barcodeScanner.destroy()
    this.setProperties()
  },
  beforeDestroy() {
    this.$root.$emit('enable-scanner', {})
    rendererEventsService.removeAllListeners(USERS_EVENTS.replyChannel)
  },
}
</script>

