import types from './mutations.types'

export const initializeDateRangeFilter = ({ commit, rootState }) => {
  const operations = rootState.operations.operations
  commit(types.SET_DATE_RANGE_FILTER, [
    operations[rootState.operations.operations.length - 1].date,
    operations[0].date,
  ])
}

export const setDateRangeFilter = ({ commit }, payload) => {
  commit(
    types.SET_DATE_RANGE_FILTER,
    payload.length === 2 && payload[0] > payload[1]
      ? [payload[1], payload[0]]
      : payload
  )
}

export const setOperationDetailDialogStatus = ({ commit }, payload) => {
  commit(types.SET_OPERATION_DETAIL_DIALOG_STATUS, payload.isOpen)
  commit(
    types.SET_OPERATION_SELECTED,
    payload.isOpen ? payload.operationSelected : null
  )
}

export const setGroupFilter = ({ commit }, payload) =>
  commit(types.SET_GROUP_FILTER, payload)

export const setOperationTypesFilter = ({ commit }, payload) =>
  commit(types.SET_OPERATION_TYPES_FILTER, payload)

export const setDeleteOperationDialogStatus = ({ commit }, payload) =>
  commit(types.SET_OPERATION_DELETE_DIALOG_STATUS, payload)

export const setDeleteProductDialogStatus = ({ commit }, payload) => {
  commit(types.SET_OPERATION_PRODUCT_DELETE_DIALOG_STATUS, payload.isOpen)
  commit(
    types.SET_OPERATION_PRODUCT_SELECTED,
    payload.isOpen ? payload.productSelected : null
  )
}

export const setSearchFilter = ({ commit }, search) => {
  commit(types.SET_SEARCH_FILTER, search)
}
