import { map } from 'ramda'

import { suppliers as suppliersMapper } from '@/config/storeMapper'

import { mapStoreObject } from '@/tools/data'

import mutationsTypes from './mutations.types'

export const setSuppliersFetching = ({ commit }, payload) =>
  commit(mutationsTypes.SET_SUPPLIERS_FETCHING, payload)

export const setSuppliersError = ({ commit }, payload) =>
  commit(mutationsTypes.SET_SUPPLIERS_ERROR, payload.message)

export const setSuppliers = ({ commit }, payload) => {
  const suppliers = map(
    supplier => mapStoreObject(supplier, suppliersMapper),
    payload.suppliers
  )
  commit(mutationsTypes.SET_SUPPLIERS_FETCHING, false)
  commit(mutationsTypes.SET_SUPPLIERS, suppliers)
}
