<template>
  <div class="chat-bot">
    <v-card-text class="chat-bot__content">
      <div
        v-for="(message, index) in messages"
        :key="`chat-bot-message-${index}`"
      >
        <BotBubble
          v-if="message.agent === 'bot'"
          :message="message.text"
          :options="message.options || []"
          :helpful="message.helpful"
          @optionWasSelected="sendMessage"
          @helpfulSelected="helpful => helpfulSelected(index, helpful)"
        />
        <UserBubble
          v-else-if="message.agent === 'user'"
          :message="message.text"
        />
        <i
          v-else-if="message.agent === 'timestamp'"
          class="text-center textPrimary--text text--lighten-4 d-flex align-center"
        >
          <v-divider />
          <span class="px-6 py-4">
            {{ message.text }}<br />{{ message.time }}
          </span>
          <v-divider />
        </i>
      </div>
      <BotTyping v-if="botIsTyping" />
    </v-card-text>
    <v-card-actions class="chat-bot__input">
      <UserInput
        :bot-is-typing="botIsTyping"
        :has-connection="hasConnection"
        :there-are-select-options="
          !!messages.length && !!messages[messages.length - 1].options
        "
        :has-thread-id="!!threadId"
        ref="userInput"
        @sendMessage="sendMessage"
      />
    </v-card-actions>
  </div>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import CHAT_BOT_DB_API_EVENTS from '@/config/events/databaseAPI/chatBot'

import { getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'

import chatBotActions from '@/store/chatBot/actions.types'

import BotBubble from '@/components/HelpBot/ChatBot/BotBubble'
import UserBubble from '@/components/HelpBot/ChatBot/UserBubble'
import BotTyping from '@/components/HelpBot/ChatBot/BotTyping'
import UserInput from '@/components/HelpBot/ChatBot/UserInput'
import tools from '@/components/HelpBot/ChatBot/chatBot.tools'

export default {
  name: 'ChatBot',
  components: {
    UserInput,
    BotTyping,
    UserBubble,
    BotBubble,
  },
  data() {
    return {
      botIsTyping: false,
      hasConnection: navigator.onLine,
    }
  },
  computed: {
    ...mapState('account', {
      countryCode: state => state.data.country.phoneCode,
      countryLocale: state => state.data.country.localeIsoCode,
    }),
    ...mapState('chatBot', ['messages', 'threadId']),
  },
  methods: {
    getTranslatedText,
    ...mapActions('chatBot', [
      chatBotActions.addMessage,
      chatBotActions.setThreadId,
      chatBotActions.setHelpfulResponse,
    ]),
    init() {
      this.createThreadIdIfItsNecessary(true)
      tools.scrollToBottom.call(this)
    },
    setIsAppOnline() {
      this.hasConnection = navigator.onLine
    },
    createThreadIdIfItsNecessary(fromInit = false) {
      if (this.threadId) return
      rendererEventsService.send(CHAT_BOT_DB_API_EVENTS.channel, {
        event: CHAT_BOT_DB_API_EVENTS.events.createThread.name,
        data: { fromInit },
      })
    },
    sendMessage(message) {
      if (typeof message === 'object') {
        tools.manageOptionSelected.call(this, message)
        return
      }
      this.$track({
        type: 'interaction',
        action: 'submit',
        category: this.$route.name,
        screen: 'ChatBot',
        name: 'Send question',
        extra_data: {
          label1: 'question',
          value1: message,
        },
      })
      if (!this.hasConnection) {
        this[chatBotActions.addMessage](
          tools.getNoInternetConnectionBotResponse.call(this)
        )
        return
      }
      tools.clearTimerToDeleteThread()
      this.botIsTyping = true
      this[chatBotActions.addMessage]({ text: message, agent: 'user' })
      tools.scrollToBottom.call(this)
      rendererEventsService.send(CHAT_BOT_DB_API_EVENTS.channel, {
        event: CHAT_BOT_DB_API_EVENTS.events.sendQuestion.name,
        data: {
          country: this.countryCode,
          message,
          threadId: this.threadId,
        },
      })
    },
    helpfulSelected(index, helpful) {
      this[chatBotActions.setHelpfulResponse]({ index, helpful })
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'ChatBot',
        name: helpful ? 'Send useful help' : 'Send useless help',
        extra_data: {
          label1: 'response',
          value1: this.messages[index].unformatted,
        },
      })
    },
    async chatBotResponseListener(event, payload) {
      const replies = {
        [CHAT_BOT_DB_API_EVENTS.events.createThread.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'response',
            category: this.$route.name,
            screen: 'ChatBot',
            name: 'Create thread',
          })
          this[chatBotActions.setThreadId](payload.data.threadId)
          if (payload.data.fromInit) {
            this[chatBotActions.addMessage](
              tools.getInitialBotMessage.call(this)
            )
          }
          this.executeUXAfterBotResponse()
        },
        [CHAT_BOT_DB_API_EVENTS.events.createThread.replies.error]: () => {
          this[chatBotActions.addMessage](
            tools.getErrorBotGetThreadId.call(this)
          )
          this.executeUXAfterBotResponse()
        },
        [CHAT_BOT_DB_API_EVENTS.events.sendQuestion.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'response',
            category: this.$route.name,
            screen: 'ChatBot',
            name: 'Answer question',
          })
          this[chatBotActions.addMessage]({
            text: payload.data.message,
            unformatted: payload.data.unformatted,
            agent: 'bot',
            threadId: this.threadId,
            helpful: null,
          })
          this.executeUXAfterBotResponse()
          if (tools.hasMaxBotResponseWithSameThreadId.call(this)) {
            tools.showHelpUseFulQuest.call(this)
            return
          }
          tools.startTimerToDeleteThread.call(this)
        },
        [CHAT_BOT_DB_API_EVENTS.events.sendQuestion.replies.error]: () => {
          this[chatBotActions.addMessage](tools.getErrorBotResponse.call(this))
          this.executeUXAfterBotResponse()
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    executeUXAfterBotResponse() {
      this.botIsTyping = false
      setTimeout(() => {
        tools.scrollBot.call(this)
        this.$refs.userInput.focus()
        tools.addListeners.call(this)
      }, 50)
    },
    deleteThread(threadId) {
      rendererEventsService.send(CHAT_BOT_DB_API_EVENTS.channel, {
        event: CHAT_BOT_DB_API_EVENTS.events.deleteThread.name,
        data: {
          threadId,
        },
      })
    },
  },
  created() {
    window.addEventListener('online', this.setIsAppOnline)
    window.addEventListener('offline', this.setIsAppOnline)
  },
  beforeMount() {
    rendererEventsService.subscribe(
      CHAT_BOT_DB_API_EVENTS.replyChannel,
      this.chatBotResponseListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      CHAT_BOT_DB_API_EVENTS.replyChannel,
      this.chatBotResponseListener
    )
  },
}
</script>
