<template>
  <DialogCard :config="dialogConfig.dialogData">
    <Form :config="dialogConfig" />
  </DialogCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import AUTH_EVENTS from '@/config/events/auth'
import countries from '@/config/countries'

import {
  cleanObjectObserver,
  getEmailAccount,
  getPhoneAccount,
} from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'

import setConfig from '@/components/RememberPasswordDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import Form from '@/components/shared/Form'

export default {
  name: 'RememberPasswordDialog',
  components: { DialogCard, Form },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
      auxValidators: { inputs: {} },
    }
  },
  computed: {
    ...mapState('app', ['rememberPasswordDialog', 'countrySelected']),
    ...mapState('account', ['data']),
    dialogConfig() {
      return setConfig(
        {
          isOpen: this.rememberPasswordDialog.isOpen,
          inputs: this.inputs,
          v: this.$v.inputs,
        },
        {
          closeDialog: this.cancelAndClose,
          generateCodeAndSendEmail: this.generateCodeAndSendEmail,
        }
      )
    },
    countryPhoneCode() {
      return this.countrySelected === null
        ? this.data.country.phoneCode
        : countries[this.countrySelected].phoneCode
    },
  },
  methods: {
    ...mapActions('app', [
      appActions.setRememberPasswordDialogStatus,
      appActions.setOneTimePasswordDialogStatus,
    ]),
    setProperties: function() {
      this.dialogConfig.fields.forEach(field => {
        this.$set(this.inputs, field.id, '')
        if (field.validators)
          this.$set(
            this.auxValidators.inputs,
            field.id,
            Array.isArray(field.validators)
              ? field.validators
              : {
                  ...cleanObjectObserver(field.validators),
                }
          )
      })
    },
    cancelAndClose() {
      this[appActions.setRememberPasswordDialogStatus](false)
    },
    generateCodeAndSendEmail() {
      if (this.$v.inputs.$invalid) {
        Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$touch())
        return
      }
      rendererEventsService.send(AUTH_EVENTS.channel, {
        event: AUTH_EVENTS.events.generateCodeAndSendEmail.name,
        data: {
          account: this.inputs['account'].includes('@')
            ? this.inputs['account']
            : getPhoneAccount(this.countryPhoneCode, this.inputs['account']),
        },
      })
    },
    getValidators() {
      let object = { inputs: {} }
      Object.assign(object.inputs, this.auxValidators.inputs)
      object.inputs.account = {
        ...cleanObjectObserver(
          this.inputs.account.includes('@')
            ? this.auxValidators.inputs.account[0]
            : this.auxValidators.inputs.account[1]
        ),
      }
      return object
    },
  },
  watch: {
    'inputs.account'() {
      this.validators = this.getValidators()
    },
  },
  validations() {
    return this.validators
  },
  async mounted() {
    await this.setProperties()
    rendererEventsService.subscribe(
      AUTH_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [AUTH_EVENTS.events.generateCodeAndSendEmail.replies.success]: () => {
            this.cancelAndClose()
            this[appActions.setOneTimePasswordDialogStatus]({
              isOpen: true,
              code: payload.code,
              account: this.inputs['account'].includes('@')
                ? getEmailAccount(this.inputs['account'])
                : getPhoneAccount(
                    this.countryPhoneCode,
                    this.inputs['account']
                  ),
            })
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(AUTH_EVENTS.replyChannel)
  },
}
</script>
