import Vue from 'vue'

import types from '@/store/users/mutations.types'

const setUsers = (state, payload) => {
  state.users = payload
}

const addUser = (state, payload) => {
  state.users.push(payload)
}

const updateUserPermissions = (state, data) => {
  state.users[data.index][data.permission] =
    state.users[data.index][data.permission] === 1 ? 0 : 1
}

const updateUser = (state, payload) => {
  const employeeIndex = state.users.findIndex(user => user._id === payload._id)
  if (!employeeIndex) {
    return
  }
  Vue.set(state.users, employeeIndex, payload)
}

const deleteUser = (state, payload) => {
  state.users[payload].deleted = 1
}

const setFetching = (state, newState) => {
  state.fetching = newState
}

const setError = (state, error) => {
  state.users = null
  state.error = true
  state.errorMessage = error
}

const resetErrorStatus = state => {
  state.error = false
  state.errorMessage = ''
}

const setConfirmationDeletionDialogStatus = (state, isOpen) => {
  state.confirmationDeletionDialog.isOpen = isOpen
}

export default {
  [types.SET_USERS]: setUsers,
  [types.ADD_USER]: addUser,
  [types.UPDATE_USER_PERMISSIONS]: updateUserPermissions,
  [types.UPDATE_USER]: updateUser,
  [types.DELETE_USER]: deleteUser,
  [types.SET_USER_FETCHING]: setFetching,
  [types.SET_USER_ERROR]: setError,
  [types.RESET_USER_ERROR_STATUS]: resetErrorStatus,
  [types.SET_CONFIRMATION_DELETION_DIALOG_STATUS]: setConfirmationDeletionDialogStatus,
}
