import { filterBy } from '@/store/loyaltyProgram/getters.tools'

export const getFilteredData = (...args) => {
  const state = args[0]
  const loyaltyProgramViewState = args[2].loyaltyProgramView
  const { enrolledCustomers } = state.data
  const { searchTerm } = loyaltyProgramViewState.filters
  return searchTerm === null
    ? enrolledCustomers
    : filterBy.searchTerm(searchTerm, enrolledCustomers)
}

export const approvedEnrolledCustomers = (...args) => {
  const state = args[0]
  const { enrolledCustomers } = state.data
  const approvedCustomers = enrolledCustomers.filter(
    enrolledCustomer => enrolledCustomer.status === 1
  )
  const sortedCustomers = approvedCustomers.sort((a, b) => {
    const dateA =
      a.customer.lastSaleDate === '-'
        ? Infinity
        : new Date(a.customer.lastSaleDate)
    const dateB =
      b.customer.lastSaleDate === '-'
        ? Infinity
        : new Date(b.customer.lastSaleDate)
    if (dateA !== Infinity && dateB !== Infinity) {
      return dateB - dateA
    } else {
      return dateA === Infinity ? 1 : -1
    }
  })
  return sortedCustomers
}
