import { isNil } from 'ramda'

import { getCountryDataSearchingByProp } from '@/tools/data'
import { encryptValue } from '@/tools/security'

export const createNewPos = (posData, pass) => {
  const { pos, oper, dev, name, country } = posData
  return {
    pos,
    oper,
    dev: dev ? dev : '01',
    user: name,
    pass,
    country: getCountryDataSearchingByProp('phoneCode', country).localeIsoCode,
  }
}

export const createAccountData = posData => {
  const {
    pos,
    oper,
    dev,
    name,
    country,
    securityData,
    storeName,
    rating,
    loyaltyProgram,
    profile_completed,
    profileCompleted,
  } = posData
  const profileCompletedValue =
    profile_completed !== undefined ? profile_completed : profileCompleted
  const {
    account,
    storeImage,
    storeAddress,
    storePostalCode,
    storeCity,
    storeTown,
    storeState,
    storeLandlinePhone,
    storePhone,
  } = posData
  return {
    pos,
    name,
    operator: oper,
    device: dev ? dev : '01',
    account,
    country: isNaN(country)
      ? getCountryDataSearchingByProp('localeIsoCode', country)
      : getCountryDataSearchingByProp('phoneCode', country),
    security: {
      token: securityData !== null ? encryptValue(securityData.tok) : '',
      secret: securityData !== null ? encryptValue(securityData.sec) : '',
      expirationDate: securityData !== null ? securityData.exp : '',
    },
    storeName: storeName ? storeName : '',
    rating: rating ? rating : 0,
    storeImage: storeImage ? storeImage : '',
    storeAddress: storeAddress ? storeAddress : '',
    storePostalCode: storePostalCode ? storePostalCode : '',
    storeCity: storeCity ? storeCity : '',
    storeTown: storeTown ? storeTown : '',
    storeState: storeState ? storeState : '',
    storeLandlinePhone: storeLandlinePhone ? storeLandlinePhone : '',
    storePhone: storePhone ? storePhone : '',
    loyaltyProgram: {
      loyaltyProgramActived: !isNil(loyaltyProgram)
        ? loyaltyProgram.loyaltyProgramActived
        : 0,
      rewardAmount: !isNil(loyaltyProgram) ? loyaltyProgram.rewardAmount : 0,
      prizeDescription: !isNil(loyaltyProgram)
        ? loyaltyProgram.prizeDescription
        : '',
    },
    profileCompleted: profileCompletedValue,
  }
}

export const getErrorMessage = error => {
  if (error == undefined) return 'starterLayout.login.unknownError'
  return error.toString().includes('starterLayout.login')
    ? error
    : 'starterLayout.login.unknownError'
}
