<template>
  <ToolBar :config="componentConfig" />
</template>

<script>
import { mapActions, mapState } from 'vuex'

import helpCenterViewActions from '@/store/helpCenterView/actions.types'

import config from '@/components/HelpCenterView/HelpCenterToolbar/Filters/config'
import ToolBar from '@/components/shared/ToolBar'

export default {
  name: 'HelpCenterFilter',
  components: { ToolBar },
  computed: {
    ...mapState('helpCenterView', ['filters']),
    ...mapState('helpCenter', ['data']),
    componentConfig() {
      return config(
        {
          data: this.data,
          filters: this.filters,
        },
        {
          setSearchTerm: this[helpCenterViewActions.setSearchTermFilter],
          setSelectedVideoTypes: this[helpCenterViewActions.setVideoTypeFilter],
        }
      )
    },
  },
  methods: {
    ...mapActions('helpCenterView', [
      helpCenterViewActions.setSearchTermFilter,
      helpCenterViewActions.setVideoTypeFilter,
    ]),
  },
}
</script>
