import { idOperations } from '@/config/cashOperationsVariables'

const OWNER_PAYMENT_METHOD_KEY = 'owner'
const OWNER_PAYMENT_METHOD_ID = 0
const CASH_PAYMENT_METHOD_KEY = 'cash'
const CASH_PAYMENT_METHOD_ID = 1
const CREDIT_PAYMENT_METHOD_KEY = 'credit'
const CREDIT_PAYMENT_METHOD_ID = 2
const CARD_PAYMENT_METHOD_KEY = 'card'
const CARD_PAYMENT_METHOD_ID = 5
const QR_PAYMENT_METHOD_KEY = 'qr'
const QR_PAYMENT_METHOD_ID = 4
const BANK_TRANSFER_PAYMENT_METHOD_KEY = 'transfer'
const BANK_TRANSFER_PAYMENT_METHOD_ID = 6
const OTHER_PAYMENT_METHOD_KEY = 'others'
const OTHER_PAYMENT_METHOD_ID = 7

export default Object.freeze({
  ownerKey: OWNER_PAYMENT_METHOD_KEY,
  cashKey: CASH_PAYMENT_METHOD_KEY,
  creditKey: CREDIT_PAYMENT_METHOD_KEY,
  cardKey: CARD_PAYMENT_METHOD_KEY,
  qrKey: QR_PAYMENT_METHOD_KEY,
  transferKey: BANK_TRANSFER_PAYMENT_METHOD_KEY,
  others: OTHER_PAYMENT_METHOD_KEY,
  defaultPaymentMethods: [
    CASH_PAYMENT_METHOD_KEY,
    CREDIT_PAYMENT_METHOD_KEY,
    QR_PAYMENT_METHOD_KEY,
    CARD_PAYMENT_METHOD_KEY,
    OTHER_PAYMENT_METHOD_KEY,
  ],
  getIdOperationFromKey: method => {
    if (method === CASH_PAYMENT_METHOD_KEY) {
      return idOperations.ID_OPERATION_CASH_SALE
    }
    if (method === CREDIT_PAYMENT_METHOD_KEY) {
      return idOperations.ID_OPERATION_CREDIT_SALE
    }
    if (method === OWNER_PAYMENT_METHOD_KEY) {
      return idOperations.ID_OPERATION_OWNER_SALE
    }
    return idOperations.ID_OPERATION_EXTERNAL_PAYMENT_SALE
  },
  getIdPaidFromKey: method => {
    if (
      method === OWNER_PAYMENT_METHOD_KEY ||
      method === CREDIT_PAYMENT_METHOD_KEY
    ) {
      return 0
    }
    return 1
  },
  isCashSale: key => key === CASH_PAYMENT_METHOD_KEY,
  isCreditSale: key => key === CREDIT_PAYMENT_METHOD_KEY,
  isOwnerSale: key => key === OWNER_PAYMENT_METHOD_KEY,
  isExternalPaymentSale: key =>
    [
      CARD_PAYMENT_METHOD_KEY,
      QR_PAYMENT_METHOD_KEY,
      BANK_TRANSFER_PAYMENT_METHOD_KEY,
      OTHER_PAYMENT_METHOD_KEY,
    ].includes(key),
  isCardSale: key => key === CARD_PAYMENT_METHOD_KEY,
  isQrSale: key => key === QR_PAYMENT_METHOD_KEY,
  getPaymentMethodIdFromKey: key => {
    if (key === OWNER_PAYMENT_METHOD_KEY) return OWNER_PAYMENT_METHOD_ID
    if (key === CASH_PAYMENT_METHOD_KEY) return CASH_PAYMENT_METHOD_ID
    if (key === CREDIT_PAYMENT_METHOD_KEY) return CREDIT_PAYMENT_METHOD_ID
    if (key === CARD_PAYMENT_METHOD_KEY) return CARD_PAYMENT_METHOD_ID
    if (key === QR_PAYMENT_METHOD_KEY) return QR_PAYMENT_METHOD_ID
    if (key === BANK_TRANSFER_PAYMENT_METHOD_KEY)
      return BANK_TRANSFER_PAYMENT_METHOD_ID
    if (key === OTHER_PAYMENT_METHOD_KEY) return OTHER_PAYMENT_METHOD_ID
    return undefined
  },
  getPaymentMethodKeyFromId: id => {
    if (id === OWNER_PAYMENT_METHOD_ID) return OWNER_PAYMENT_METHOD_KEY
    if (id === CASH_PAYMENT_METHOD_ID) return CASH_PAYMENT_METHOD_KEY
    if (id === CREDIT_PAYMENT_METHOD_ID) return CREDIT_PAYMENT_METHOD_KEY
    if (id === CARD_PAYMENT_METHOD_ID) return CARD_PAYMENT_METHOD_KEY
    if (id === QR_PAYMENT_METHOD_ID) return QR_PAYMENT_METHOD_KEY
    if (id === BANK_TRANSFER_PAYMENT_METHOD_ID)
      return BANK_TRANSFER_PAYMENT_METHOD_KEY
    if (id === OTHER_PAYMENT_METHOD_ID) return OTHER_PAYMENT_METHOD_KEY
    return undefined
  },
})
