import types from './mutations.types'

export const setAddExpenseDialogStatus = ({ commit }, payload) => {
  commit(types.SET_ADD_EXPENSE_DIALOG_STATUS, payload.isOpen)
  commit(
    types.SET_EXPENSE_SELECTED,
    payload.isOpen ? payload.selectedExpense : null
  )
}

export const setAddOtherExpenseDialogStatus = ({ commit }, payload) =>
  commit(types.SET_ADD_OTHER_EXPENSE_DIALOG_STATUS, payload)

export const setSearchTermFilter = ({ commit }, payload) =>
  commit(types.SET_SEARCH_TERM_FILTER, payload)
