const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-account-key',
    title: 'preferences.rememberPasswordDialog.title',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    persistent: true,
    buttons: {
      accept: false,
      cancel: false,
    },
    height: 200,
    maxWidth: 450,
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.checkCodeAndOpenChangePwDialog(),
  },
})

export default setConfig
