import { required, email, maxValue } from 'vuelidate/lib/validators'

import { validatePhoneNumber } from '@/tools/customValidations'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-account-plus',
    title: 'customersView.addCustomerDialog.title',
    persistent: true,
    titleBackground: '#white',
    titleColor: 'textPrimary',
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    height: 725,
    maxWidth: 500,
    id: 'confirm-add-customer-form',
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: state.routeName,
        screen: `AddCustomerDialog`,
        name: 'Cancel',
      })
      methods.closeDialog()
    },
    onClickAccept: () => methods.addCustomer(),
  },
  fields: [
    {
      id: 'name',
      type: 'input',
      valueType: 'string',
      label: 'customersView.addCustomerDialog.name',
      errorMessage: 'customersView.addCustomerDialog.errorMessage.name',
      color: 'primaryColor',
      prependIcon: 'mdi-account-plus',
      required: true,
      autofocus: true,
      validators: { required },
    },
    {
      id: 'phone',
      type: 'input',
      valueType: 'number',
      label: 'customersView.addCustomerDialog.phone',
      errorMessage: 'customersView.addCustomerDialog.errorMessage.phone',
      color: 'primaryColor',
      prependIcon: 'mdi-cellphone',
      required: true,
      validators:
        state.routeName === 'LoyaltyProgramConfig' ||
        state.routeName === 'LoyaltyProgram'
          ? { required, validatePhoneNumber }
          : { validatePhoneNumber: validateNonRequiredPhoneNumber },
    },
    {
      id: 'gender',
      type: 'select',
      items: ['Hombre', 'Mujer', 'Otro'],
      label: 'customersView.addCustomerDialog.gender',
      color: 'primaryColor',
      prependIcon: 'mdi-account-multiple',
    },
    {
      id: 'email',
      type: 'input',
      valueType: 'string',
      label: 'customersView.addCustomerDialog.email',
      errorMessage: 'customersView.addCustomerDialog.errorMessage.email',
      color: 'primaryColor',
      prependIcon: 'mdi-email',
      validators: { email },
    },
    {
      id: 'address',
      type: 'input',
      valueType: 'string',
      label: 'customersView.addCustomerDialog.address',
      color: 'primaryColor',
      prependIcon: 'mdi-sign-direction',
    },
    {
      id: 'debtLimit',
      type: 'input',
      valueType: 'number',
      label: 'customersView.addCustomerDialog.debtLimit',
      color: 'primaryColor',
      prependIcon: 'mdi-alert-circle',
      errorMessage: 'customersView.addCustomerDialog.errorMessage.debtLimit',
      validators: { maxValue: maxValue(state.limits.maxValuePackagePrice) },
    },
    {
      id: 'debt',
      type: 'input',
      valueType: 'number',
      label: 'customersView.addCustomerDialog.initialDebt',
      color: 'primaryColor',
      prependIcon: 'mdi-currency-usd',
      errorMessage: 'customersView.addCustomerDialog.errorMessage.initialDebt',
      validators: { maxValue: maxValue(state.limits.maxValuePackagePrice) },
    },
  ],
  id: 'confirm-add-customer-form',
})

const validateNonRequiredPhoneNumber = value => {
  if (!value) return true
  return validatePhoneNumber(value)
}

export default setConfig
