import { cashOperation } from '@/config/storeMapper'

import { mapStoreObject } from '@/tools/data'
import logger from '@/tools/logger'

import types from '@/store/operations/mutations.types'
import operationsViewTypes from '@/store/operationsView/mutations.types'

export const setOperationsFetching = ({ commit }, payload) =>
  commit(types.SET_OPERATIONS_FETCHING, payload)

export const setOperationsError = ({ commit }, payload) =>
  commit(types.SET_OPERATIONS_ERROR, payload)

export const fetchOperations = ({ commit }, data) => {
  let operations = data.map(item => mapStoreObject(item, cashOperation))
  commit(types.SET_OPERATIONS, operations)
  commit(
    `operationsView/${operationsViewTypes.SET_DATE_RANGE_FILTER}`,
    [operations[operations.length - 1].date, operations[0].date],
    { root: true }
  )
  commit(types.SET_OPERATIONS_FETCHING, false)
  logger('info', 'Last operations obtained')
}

export const fetchOperationsBetweenDates = ({ commit }, data) => {
  let operations = data.map(item => mapStoreObject(item, cashOperation))
  commit(types.SET_OPERATIONS, operations)
  commit(types.SET_OPERATIONS_FETCHING, false)
  logger('info', 'Operations between dates obtained')
}

export const emptyOperations = ({ commit }) => {
  commit(types.SET_OPERATIONS, [])
}

export const addOperation = ({ commit, state }, data) => {
  const operations = state.operations
  operations.push(data)
  commit(types.SET_OPERATIONS, operations)
}

export const deleteOperation = ({ commit, state }, data) => {
  const operations = state.operations.filter(
    operation => operation.id !== data.id
  )
  commit(types.SET_OPERATIONS, operations)
}
