import dayjs from 'dayjs'

import translatedStrings from '@/i18n/en/shared'

const MIN_TODAY_HOUR_FOR_REPORTS = 5

export const getNow = (withMilliseconds = true) => {
  return withMilliseconds
    ? dayjs().format('YYYY-MM-DD HH:mm:ss.SSS')
    : dayjs().format('YYYY-MM-DD HH:mm:ss')
}

export const getNowUTC = () => dayjs.utc().format()

export const getDateWithFormat = (value, format) => {
  return dayjs(value).format(format)
}

export const formatDate = value => {
  // TODO: if a country has different default date format specify it here
  return dayjs(value).format('DD-MM-YYYY')
}

export const toDate = value => {
  return dayjs(value)
}

export const getDayOfWeek = value => {
  const weekDays = Object.keys(translatedStrings.dates.dayOfWeek)
  return weekDays[dayjs(value).day()]
}

export const getDay = value => {
  return dayjs(value).day()
}

export const getDayOfMonth = value => {
  return dayjs(value).date()
}

export const addDays = (date, daysToAdd) => {
  return dayjs(date).add(daysToAdd, 'day')
}

export const getFileExportData = () => dayjs().format('DD-MM-YYYY')

export const getDiffBetweenDates = (firstDate, secondDate, unit = 'second') => {
  firstDate = dayjs(firstDate)
  return firstDate.diff(secondDate, unit)
}

export const getFirstDayOfWeek = () => {
  const today = new Date()
  const dayOfWeek = today.getDay()
  const diff = today.getDate() - dayOfWeek + (dayOfWeek === 0 ? -6 : 1)
  const firstDay = new Date(today.setDate(diff))
  return firstDay
}

export const subtractTime = (date, value, time) => {
  return dayjs(date).subtract(value, time)
}

export const getTodayForReports = () => {
  const nowHour = parseInt(getDateWithFormat(getNow(), 'HH'))
  if (nowHour < MIN_TODAY_HOUR_FOR_REPORTS) {
    return getDateWithFormat(subtractTime(getNow(), 1, 'day'), 'YYYY-MM-DD')
  }
  return getDateWithFormat(getNow(), 'YYYY-MM-DD')
}

export const dateIsAfter = (firsDate, secondDate, unit = 'day') => {
  return dayjs(firsDate).isAfter(dayjs(secondDate), unit)
}

export const dateIsBefore = (firsDate, secondDate, unit = 'day') => {
  return dayjs(firsDate).isBefore(dayjs(secondDate), unit)
}

export const dateIsSame = (firsDate, secondDate, unit = 'day') => {
  return dayjs(firsDate).isSame(dayjs(secondDate), unit)
}

export const dayIsTodayOrAfter = value => {
  const date = dayjs(value)
  const toDay = dayjs()
  return dateIsAfter(date, toDay) || dateIsSame(date, toDay)
}

export const dayIsTodayOrBefore = value => {
  const date = dayjs(value)
  const toDay = dayjs()
  return dateIsBefore(date, toDay) || dateIsSame(date, toDay)
}
