<template>
  <v-tooltip right nudge-right="12" :color="tooltipColor" :disabled="disabled">
    <template v-slot:activator="{ on }">
      <v-list-item-icon v-on="!sidebarOpened ? on : null">
        <v-badge v-if="data.newFeature" color="primary" dot>
          <v-icon>{{ data.icon }}</v-icon>
        </v-badge>
        <v-icon v-else>{{ data.icon }}</v-icon>
      </v-list-item-icon>

      <v-list-item-title>
        <div class="d-flex align-center">
          <FormattedText
            :value="`mainLayout.navigation['${data.name}']`"
            intl
            color="textPrimary"
            type="text-subtitle-1"
          />
          <v-chip
            v-if="data.newFeature && data.newFeatureText"
            class="ma-1 font-weight-black"
            color="primary"
            small
          >
            <v-icon v-if="data.newFeatureIcon" left small>
              mdi-star
            </v-icon>
            <span class="subtitle-2">{{
              getTranslatedText('mainLayout.navigation.new')
            }}</span>
          </v-chip>
        </div>
      </v-list-item-title>
    </template>
    <FormattedText
      :value="`mainLayout.navigation['${data.name}']`"
      intl
      :color="tooltipTextColor"
    />
  </v-tooltip>
</template>

<script>
import { mapState } from 'vuex'

import { getTranslatedText } from '@/tools/data'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'MainViewSidebarListItem',
  components: {
    FormattedText,
  },
  props: {
    data: {
      type: Object,
      default: null,
    },
    tooltipColor: {
      type: String,
      default: 'primary',
    },
    tooltipTextColor: {
      type: String,
      default: 'white',
    },
    disabled: {
      type: Boolean,
      default: false,
    },
  },
  computed: {
    ...mapState('app', ['sidebarOpened']),
  },
  methods: { getTranslatedText },
}
</script>
