import { captureMessage } from '@/tools/exceptions'
import { encryptValue } from '@/tools/security'

import { getErrorMessage } from '@/store/account/actions.tools'
import types from '@/store/account/mutations.types'
import typesApp from '@/store/app/mutations.types'
import { createAccountData } from '@/store/account/actions.tools'

import { AccountSchema } from '@/models/account'

export const setAccountFetchingStatus = ({ commit }, payload) =>
  commit(types.SET_ACCOUNT_FETCHING, payload)

export const setAccountLoginError = ({ commit }, payload) => {
  commit(types.SET_ACCOUNT_ERROR, getErrorMessage(payload.error))
}

export const setOwnerAndStoreNames = ({ commit }, payload) => {
  commit(types.UPDATE_ACCOUNT_NAME, payload)
}

export const resetErrorStatus = ({ commit }) =>
  commit(types.RESET_ACCOUNT_ERROR_STATUS)

export const setFetching = ({ commit }, payload) =>
  commit(types.SET_ACCOUNT_FETCHING, payload)

// TODO: Rename this action to setPosData and update files dependence
export const setPosDataAfterLogin = ({ commit }, payload) => {
  const accountData = createAccountData(payload.posData)
  const validateAccountData = AccountSchema.isValidSync(accountData, {
    abortEarly: false,
    recursive: true,
  })
  if (validateAccountData !== true) {
    commit(types.SET_ACCOUNT_FETCHING, false)
    commit(types.SET_ACCOUNT_ERROR, getErrorMessage(''))
    captureMessage('Fails account data validation')
    return
  }
  commit(types.SET_ACCOUNT, accountData)
  commit(`app/${typesApp.SET_APP_LOGGED}`, true, { root: true })
  commit(`app/${typesApp.SET_APP_PENDING_SYNC_OPS}`, payload.pendingSyncOps, {
    root: true,
  })
}

export const setSecurityData = ({ commit }, payload) =>
  commit(types.SET_ACCOUNT_SECURITY_DATA, {
    token: encryptValue(payload.tok),
    secret: encryptValue(payload.sec),
    expirationDate: payload.exp,
  })

export const setLoyaltyData = ({ commit }, payload) =>
  commit(types.SET_ACCOUNT_LOYALTY_DATA, payload)
