import types from '@/store/notifications/mutations.types'

const setStatusShowNotifications = (state, status) => {
  state.showListNotifications = status
}

const setNotifications = (state, notifications) => {
  state.notifications = notifications
}

const addNotifications = (state, payload) => {
  const arrayMethod = payload.arrayMethod || 'push'
  if (Array.isArray(payload.notifications)) {
    state.notifications[arrayMethod](...payload.notifications)
    return
  }
  state.notifications[arrayMethod](payload.notifications)
}

const removeNotification = (state, notificationToRemove) => {
  if (!state.doneNotifications[notificationToRemove.type]) {
    state.doneNotifications[notificationToRemove.type] = []
  }
  state.doneNotifications[notificationToRemove.type].push(
    notificationToRemove.id
  )
  const indexFound = state.notifications.findIndex(
    notification =>
      notification.id === notificationToRemove.id &&
      notification.type === notificationToRemove.type
  )
  if (indexFound >= 0) {
    state.notifications.splice(indexFound, 1)
  }
}

const resetDoneNotifications = state => {
  state.doneNotifications = {}
}

const addNotificationLoadedOnce = (state, notification) => {
  if (notificationLoadedOnceExist(state, notification)) return
  state.notificationsLoadedOnce.push(notification)
}

const notificationLoadedOnceExist = (state, notification) => {
  return state.notificationsLoadedOnce.some(
    notificationLoadedOnce => notificationLoadedOnce.id === notification.id
  )
}

const resetNotificationsLoadedOnce = state => {
  state.notificationsLoadedOnce = []
}

export default {
  [types.SET_STATUS_SHOW_NOTIFICATIONS]: setStatusShowNotifications,
  [types.SET_NOTIFICATIONS]: setNotifications,
  [types.ADD_NOTIFICATIONS]: addNotifications,
  [types.REMOVE_NOTIFICATION]: removeNotification,
  [types.RESET_DONE_NOTIFICATIONS]: resetDoneNotifications,
  [types.ADD_NOTIFICATION_LOADED_ONCE]: addNotificationLoadedOnce,
  [types.RESET_NOTIFICATION_LOADED_ONCE]: resetNotificationsLoadedOnce,
}
