<template>
  <transition appear name="fade">
    <v-container fill-height class="login">
      <v-row class="text-center">
        <v-col cols="12" class="pt-0">
          <v-row align="center" justify="center">
            <v-col align="center" justify="center" class="pt-0">
              <Header />
            </v-col>
          </v-row>
        </v-col>
        <v-col cols="12" class="py-0">
          <v-row align="center" justify="center">
            <v-col>
              <WelcomeViewForm />
            </v-col>
          </v-row>
        </v-col>
        <v-col cols="12" class="py-0">
          <v-row align="center" justify="center">
            <v-col align="center" class="py-0">
              <Footer />
            </v-col>
          </v-row>
        </v-col>
      </v-row>
    </v-container>
  </transition>
</template>

<script>
import { mapActions } from 'vuex'

import { getDiffBetweenDates, getNow } from '@/tools/dates'

import appActions from '@/store/app/actions.types'

import Header from '@/components/AuthViews/Header'
import WelcomeViewForm from '@/components/AuthViews/WelcomeView/WelcomeViewForm'
import Footer from '@/components/AuthViews/Footer'

export default {
  name: 'WelcomeView',
  components: {
    Header,
    WelcomeViewForm,
    Footer,
  },
  methods: {
    ...mapActions('app', [
      appActions.setCountrySelected,
      appActions.setOnboardingEnabled,
    ]),
    goToLogin() {
      const countryStorage = JSON.parse(localStorage.getItem('country'))
      if (!countryStorage || !countryStorage.forLogin) return
      localStorage.removeItem('country')
      const lastDays = getDiffBetweenDates(getNow(), countryStorage.time, 'day')
      if (lastDays > 0) return
      this[appActions.setCountrySelected](countryStorage.code)
      this.$router.push({ path: '/login' })
    },
  },
  beforeMount() {
    this[appActions.setOnboardingEnabled](true)
    this.goToLogin()
  },
}
</script>

<style>
.fade-enter {
  opacity: 0;
}

.fade-enter-active {
  transition: opacity 2s ease-out;
}

.login {
  width: 410px;
}
</style>
