<template>
  <v-navigation-drawer
    app
    color="mainBackground"
    :mini-variant="!sidebarOpened"
    permanent
  >
    <v-list
      dense
      nav
      :class="applyWinClass('win-sidebar ')"
      :expand="menuExpanded"
      id="sidebar-list"
    >
      <!-- User info -->
      <UserProfileCard
        :name="data.storeName"
        :avatar="data.storeImage"
        role="Admin"
        :rating="data.rating"
        class="pb-6"
        v-if="sidebarOpened"
        id="user-profile-card"
      ></UserProfileCard>

      <!-- App logo  -->
      <v-list-item class="pl-1 pt-1 sidebar-logo" v-else>
        <img src="@/assets/logos/Icono_PlayStore.svg" height="30px" />
      </v-list-item>

      <!-- Menu items -->
      <div id="sidebar-menu-items">
        <div
          v-for="item in menuItems"
          :key="item.id"
          :id="`sidebar-${item.id}`"
        >
          <!-- Group items -->
          <v-list-group
            :value="item.expanded"
            v-if="item.children"
            class="mt-8"
            :id="item.id"
          >
            <template v-slot:activator>
              <MainViewSidebarGroupItem :data="item" tooltipColor="primary" />
            </template>

            <!-- Nested items-->
            <v-list-item
              :class="!sidebarOpened"
              v-for="child in item.children"
              :key="child.id"
              :id="child.id"
              :to="child.path"
              :ref="child.name"
              exact
              @click="navigationItemWasClicked(child)"
            >
              <MainViewSidebarListItem :data="child" tooltipColor="accent" />
            </v-list-item>
          </v-list-group>

          <!-- Single intems -->
          <v-list-item
            :class="!sidebarOpened"
            :to="item.path"
            :ref="item.name"
            exact
            v-else
            color="primary"
            class="mt-2"
            @click="navigationItemWasClicked(item)"
          >
            <MainViewSidebarListItem :data="item" tooltipColor="primary" />
          </v-list-item>
        </div>
      </div>
    </v-list>

    <!-- Menu footer -->
    <template v-slot:append>
      <v-list-item
        :class="[!sidebarOpened ? 'd-flex justify-center mb-2 px-0' : '']"
      >
        <MainViewSidebarAppVersion
          v-if="sidebarOpened"
          appName="Tiendatek"
          :appVersion="version"
        />

        <v-spacer v-if="sidebarOpened"></v-spacer>

        <div :class="[sidebarOpened ? 'd-flex flex-row' : '']">
          <CustomButton
            fab
            x-small
            :color="pendingSyncOps > 0 ? 'primary' : 'accent'"
            tooltipText="mainLayout.buttons.sync"
            tooltipColor="primary"
            :tooltipPosition="sidebarOpened ? 'top' : 'right'"
            :class="[pendingSyncOps > 0 ? 'pulse-button ' : '']"
            :className="sidebarOpened ? 'mr-2' : 'mb-2'"
            :icon="syncing ? 'mdi-autorenew mdi-spin' : 'the mdi-autorenew'"
            depressed
            @click="onSyncClick(data)"
          />
          <CustomButton
            id="preferences-sidebar-button"
            fab
            x-small
            color="accent"
            tooltipText="mainLayout.buttons.config"
            tooltipColor="primary"
            :tooltipPosition="sidebarOpened ? 'top' : 'right'"
            icon="mdi-cog"
            depressed
            @click="onPreferencesClick()"
          />
        </div>
      </v-list-item>
    </template>
  </v-navigation-drawer>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { applyWinClass } from '@/tools/view'

import appActions from '@/store/app/actions.types'

import UserProfileCard from '@/components/shared/UserProfileCard'
import CustomButton from '@/components/shared/CustomButton'
import MainViewSidebarListItem from '@/components/MainView/MainViewSidebar/MainViewSidebarListItem'
import MainViewSidebarGroupItem from '@/components/MainView/MainViewSidebar/MainViewSidebarGroupItem'
import MainViewSidebarAppVersion from '@/components/MainView/MainViewSidebar/MainViewSidebarAppVersion'

import menuConfig from '../menuConfig'
import methods from './mainViewSidebar.methods'

export default {
  name: 'MainViewLeftSidebar',
  components: {
    UserProfileCard,
    CustomButton,
    MainViewSidebarListItem,
    MainViewSidebarGroupItem,
    MainViewSidebarAppVersion,
  },
  data() {
    return {
      version: process.env.VUE_APP_VERSION,
      menuConfig: menuConfig,
      menuExpanded: true,
      sidebarHeights: {
        accItemsHeight: [],
        itemsCount: null,
      },
    }
  },
  computed: {
    ...mapState('app', [
      'sidebarOpened',
      'windowSize',
      'pendingSyncOps',
      'syncing',
      'onboardingEnabled',
      'syncOpsCounter',
    ]),
    ...mapState('account', ['data']),
    ...mapState('usersView', ['selectedUser']),
    menuItems() {
      return this.getVisibleMenuItems(
        JSON.parse(JSON.stringify(this.menuConfig)),
        this.selectedUser
      )
    },
  },
  methods: {
    ...mapActions('app', [
      appActions.setSidebarStatus,
      appActions.setAppSyncing,
      appActions.reduceSyncOpsCounter,
    ]),
    ...methods,
    applyWinClass,
    navigationItemWasClicked(item) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'NavigationMenu',
        name: `Go to ${item.name}`,
      })
    },
  },
  watch: {
    windowSize(newSize, oldSize) {
      this.updateSidebarStatus(newSize, oldSize, {
        state: this.$data,
        setSidebarStatus: this[appActions.setSidebarStatus],
        onboardingEnabled: this.onboardingEnabled,
      })
    },
  },
  mounted() {
    this.sidebarHeights = this.getSidebarHeights()
  },
}
</script>

<style scoped>
.v-navigation-drawer__content {
  overflow: hidden !important;
}
.v-list-item.sidebar-logo {
  padding-bottom: 73px;
}

.pulse-button {
  border-radius: 50%;
  box-shadow: 0 0 0 0 rgba(0, 0, 0, 1);
  transform: scale(1);
  animation: pulse 1.5s infinite;
}

@keyframes pulse {
  0% {
    transform: scale(1);
    box-shadow: 0 0 0 0 var(--v-primary-base);
  }

  70% {
    transform: scale(1);
    box-shadow: 0 0 0 8px rgba(255, 193, 7, 0.2);
  }

  100% {
    transform: scale(1);
    box-shadow: 0 0 0 0 rgba(255, 193, 7, 0);
  }
}
.win-sidebar {
  border-top: 1px solid var(--v-mainBackground-darken1);
}
</style>
