import Vue from 'vue'
import vuescroll from 'vuescroll'

import colors from 'vuetify/lib/util/colors'

Vue.use(vuescroll, {
  ops: {
    rail: {
      gutterOfEnds: '0px',
      gutterOfSide: '0px',
      size: '28px',
    },
    bar: {
      background: colors.grey.base,
      size: '7px',
    },
    scrollButton: {
      enable: true,
      background: colors.grey.base,
      opacity: 1,
      step: 100,
      mousedownStep: 100,
    },
  },
  name: 'myScroll',
})
