import expenses from '@/config/expenses'

import mutationsTypes from '@/store/expenses/mutations.types'

export const setExpensesFetching = ({ commit }, payload) =>
  commit(mutationsTypes.SET_EXPENSES_FETCHING, payload)

export const setExpensesError = ({ commit }, payload) =>
  commit(mutationsTypes.SET_EXPENSES_ERROR, payload.message)

export const fetchExpenses = async ({ commit }, translateFunction) => {
  const expensesFormatted = []
  expenses.forEach(expense => {
    const toReturn = expense
    toReturn.text = translateFunction(expense.text)
    expensesFormatted.push(toReturn)
  })
  commit(mutationsTypes.SET_EXPENSES, expensesFormatted)
  commit(mutationsTypes.SET_EXPENSES_FETCHING, false)
}
