import types from '@/store/customPromotionsView/mutations.types'

export const updateFilters = ({ commit }, filters) =>
  commit(types.UPDATE_FILTERS, filters)

export const toggleViewMode = ({ commit }) => commit(types.TOGGLE_VIEW_MODE)

export const setDeleteDisabledCustomPromotionsDialogStatus = (
  { commit },
  status
) => commit(types.SET_DELETE_DISABLED_CUSTOM_PROMOTIONS_DIALOG_STATUS, status)

export const setCreateCustomPromotionDialogStatus = ({ commit }, data) =>
  commit(types.SET_CREATE_CUSTOM_PROMOTION_DIALOG_STATUS, data)

export const setEditCustomPromotionDialogStatus = ({ commit }, status) =>
  commit(types.SET_EDIT_CUSTOM_PROMOTION_DIALOG_STATUS, status)

export const setDeleteCustomPromotionDialogStatus = ({ commit }, status) =>
  commit(types.SET_DELETE_CUSTOM_PROMOTION_DIALOG_STATUS, status)

export const toggleAddProductDialog = ({ commit }, resetSearchTerm = true) =>
  commit(types.TOGGLE_ADD_PRODUCT_DIALOG, resetSearchTerm)

export const resetStateValues = ({ commit }) => commit(types.RESET_STATE_VALUES)
