<template>
  <DialogCard :config="dialogConfig.dialogData">
    <v-row class="px-4">
      <FormattedText
        type="text-body-1"
        intl
        value="starterLayout.supportDialog.intro"
      />
    </v-row>
    <v-row class="mt-6 px-4">
      <dl class="fill-width">
        <dt>
          <FormattedText type="text-h6" intl value="shared.phone" />
        </dt>
        <dd v-if="isCountrySelected">
          <FormattedText type="text-body-1" :value="countryPhone" />
        </dd>
        <dd v-else>
          <p
            class="d-flex"
            v-for="country in countries"
            :key="country.localeIsoCode"
          >
            <FormattedText type="text-body-1" :value="country.name" />:
            <FormattedText
              type="text-body-1"
              class="ml-2"
              :value="country.phone"
            />
          </p>
        </dd>
        <dt class="mt-5">
          <FormattedText type="text-h6" intl value="shared.email" />
        </dt>
        <dd>
          <div class="d-flex justify-space-between align-center">
            <FormattedText type="text-body-1" :value="email" />
            <v-btn icon>
              <v-icon @click="copy(email)">
                mdi-content-copy
              </v-icon>
            </v-btn>
          </div>
        </dd>
      </dl>
    </v-row>
  </DialogCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'
import { isEmpty } from 'ramda'

import genericProperties from '@/config/genericProperties'
import countries from '@/config/countries'

import appActions from '@/store/app/actions.types'

import FormattedText from '@/components/shared/FormattedText'
import DialogCard from '@/components/shared/DialogCard'
import setConfig from '@/components/AuthViews/SupportDialog/config'

export default {
  name: 'SupportDialog',
  components: { DialogCard, FormattedText },
  data() {
    return {
      email: genericProperties.support.email,
      country: '',
    }
  },
  computed: {
    ...mapState('app', ['supportDialog', 'countrySelected']),
    ...mapState('account', { accountData: state => state.data }),
    isCountrySelected() {
      return this.getCountry()
    },
    countries() {
      return Object.values(countries)
    },
    countryPhone() {
      return countries[this.country].phone
    },
    dialogConfig() {
      return setConfig(
        { isOpen: this.supportDialog.isOpen },
        {
          closeDialog: this.closeDialog,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.setSupportDialogStatus]),
    closeDialog() {
      this[appActions.setSupportDialogStatus](false)
    },
    copy(item) {
      navigator.clipboard.writeText(item)
    },
    getCountry() {
      if (!isEmpty(this.accountData.account)) {
        this.country = this.accountData.country.localeIsoCode
        return true
      }
      if (this.countrySelected !== '' && this.countrySelected !== null) {
        this.country = this.countrySelected
        return true
      }
      return false
    },
  },
}
</script>
<style lang="scss" scoped>
.fill-width {
  width: 100%;
}
</style>
