<template>
  <v-text-field
    v-model="password"
    class="custom-text-field"
    :label="getTranslatedText(label)"
    :append-icon="showPassword ? 'mdi-eye' : 'mdi-eye-off'"
    :type="showPassword ? 'text' : 'password'"
    filled
    rounded
    dense
    @click:append="showPassword = !showPassword"
    :error-messages="onValidatePassword"
    @input="v.$reset()"
    @blur="v.$touch()"
    required
    :class="className"
    :autofocus="autofocus"
  />
</template>

<script>
import { has } from 'ramda'

export default {
  name: 'PasswordInput',
  props: {
    value: {
      required: true,
    },
    v: {
      type: Object,
    },
    className: {
      type: String,
      default: '',
    },
    label: {
      type: String,
      default: 'starterLayout.login.password',
    },
    autofocus: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      showPassword: false,
    }
  },
  computed: {
    password: {
      get() {
        return this.value
      },
      set(newValue) {
        this.$emit('input', newValue)
      },
    },
    onValidatePassword() {
      const errors = []
      if (this.v === undefined || !this.v.$dirty) return errors
      has('required')(this.v) &&
        !this.v.required &&
        errors.push(
          this.getTranslatedText('starterLayout.login.passwordRequired')
        )
      has('sameAsPassword')(this.v) &&
        !this.v.sameAsPassword &&
        errors.push(
          this.getTranslatedText('starterLayout.signUp.repeatPasswordError')
        )
      has('maxLength')(this.v) &&
        !this.v.maxLength &&
        errors.push(
          this.getTranslatedText('starterLayout.signUp.maxLengthPasswordError')
        )
      has('minLength')(this.v) &&
        !this.v.minLength &&
        errors.push(
          this.getTranslatedText('starterLayout.signUp.minLengthPasswordError')
        )
      return errors
    },
  },
  methods: {
    getTranslatedText: function(translateString) {
      return this.$vuetify.lang.t(`$vuetify.${translateString}`)
    },
  },
}
</script>
