import logger from '@/tools/logger'
import { formatNumberFromDb } from '@/tools/numbersFormat'

import typesApp from '@/store/app/mutations.types'
import types from '@/store/usersView/mutations.types'

export const getEstimatedCash = async ({ commit }, payload) => {
  commit(
    types.SET_USER_ESTIMATED_CASH,
    payload.userInfo.is_store_open === 1
      ? formatNumberFromDb(payload.userInfo.estimated_cash)
      : 0
  )
}

export const setSelectedUser = async ({ commit }, payload) => {
  commit(types.SET_USER_SELECTED, payload)
  commit(`app/${typesApp.ADD_APP_PENDING_SYNC_OP}`, null, { root: true })
}

export const setSelectedUserFromPreferences = ({ commit }, payload) => {
  commit(types.SET_USER_SELECTED, payload)
  logger('info', 'Set selected user')
}

export const setSelectedUserHasSales = ({ commit }, payload) => {
  commit(types.SET_USER_HAS_SALES, payload)
}

export const generateCloseRegisterOperation = async ({ commit }, payload) => {
  commit(types.SET_USER_ESTIMATED_CASH, 0)
  commit(`app/${typesApp.SET_APP_PENDING_SYNC_OPS}`, payload.pendingSyncOps, {
    root: true,
  })
  commit(`app/${typesApp.SET_APP_STORE_OPENED}`, payload.isOpen, { root: true })
}

export const setUserEstimatedCash = ({ commit }, payload) => {
  commit(types.SET_USER_ESTIMATED_CASH, payload)
  commit(`app/${typesApp.ADD_APP_PENDING_SYNC_OP}`, null, { root: true })
}

export const setSelectedUserHasPurchases = ({ commit }, payload) => {
  commit(types.SET_USER_HAS_PURCHASES, payload)
}
