import Vue from 'vue'

import types from '@/store/loyaltyProgram/mutations.types'

const setFetching = (state, newState) => {
  state.fetching = newState
}

const setEnrolledCustomers = (state, payload) => {
  state.data.enrolledCustomers = state.data.enrolledCustomers.concat(payload)
  state.error = false
  state.errorMessage = ''
}

const setEnrolledCustomersError = (state, error) => {
  state.data.enrolledCustomers = []
  state.error = true
  state.errorMessage = error
}

const deleteEnrolledCustomer = (state, enrolledCustomerId) => {
  state.data.enrolledCustomers = state.data.enrolledCustomers.filter(
    enrolledCustomer => enrolledCustomer.customerId !== enrolledCustomerId
  )
}

const updateEnrolledCustomer = (state, payload) => {
  const index = state.data.enrolledCustomers.indexOf(
    state.data.enrolledCustomers.find(
      enrolledCustomer => enrolledCustomer.customerId === payload.customerId
    )
  )
  Vue.set(state.data.enrolledCustomers, index, payload)
}

const updateEnrolledCustomerByProperties = (state, payload) => {
  const index = state.data.enrolledCustomers.findIndex(
    enrolledCustomer => enrolledCustomer.customerId === payload.customerId
  )
  if (index > -1) {
    const enrolledCustomer = state.data.enrolledCustomers[index]
    Vue.set(state.data.enrolledCustomers, index, {
      ...enrolledCustomer,
      ...payload,
      customer: { ...enrolledCustomer.customer, ...payload.customer },
    })
  }
}

const updateLastSaleDate = (state, payload) => {
  const index = state.data.enrolledCustomers.findIndex(
    enrolledCustomer => enrolledCustomer.customerId === payload.customerId
  )
  if (index > -1) {
    Vue.set(state.data.enrolledCustomers, index, {
      ...state.data.enrolledCustomers[index],
      customer: {
        ...state.data.enrolledCustomers[index].customer,
        lastSaleDate: payload.lastSaleDate,
      },
    })
  }
}

export default {
  [types.SET_LOYALTY_FETCHING]: setFetching,
  [types.SET_ENROLLED_CUSTOMERS]: setEnrolledCustomers,
  [types.SET_ENROLLED_CUSTOMERS_ERROR]: setEnrolledCustomersError,
  [types.DELETE_ENROLLED_CUSTOMER]: deleteEnrolledCustomer,
  [types.UPDATE_ENROLLED_CUSTOMER]: updateEnrolledCustomer,
  [types.UPDATE_ENROLLED_CUSTOMER_BY_PROPERTIES]: updateEnrolledCustomerByProperties,
  [types.UPDATE_LAST_SALE_DATE]: updateLastSaleDate,
}
