import { MLP } from '@/config/storeMapper'

import { mapStoreObject } from '@/tools/data'

export const getMLPProducts = async (data, api) => {
  const { property, value, limit } = data
  const MLPSearchResult = await api.MLP.findByProperty(property, value, limit)
  return MLPSearchResult.data.data.map(item => {
    return mapStoreObject(item, MLP)
  })
}

