import types from './mutations.types'

export const setAddCustomerDialogStatus = ({ commit }, payload) => {
  commit(types.SET_ADD_CUSTOMER_DIALOG_STATUS, payload)
}

export const setCustomerDetailDialogStatus = ({ commit }, payload) => {
  commit(types.SET_CUSTOMER_DETAIL_DIALOG_STATUS, payload.isOpen)
  commit(
    types.SET_CUSTOMER_SELECTED,
    payload.isOpen ? payload.selectedCustomer : null
  )
}

export const setSearchTermFilter = ({ commit }, payload) =>
  commit(types.SET_SEARCH_TERM_FILTER, payload)

export const updateSelectedCustomerField = ({ commit }, payload) =>
  commit(types.UPDATE_SELECTED_CUSTOMER_FIELD, payload)

export const setDeleteCustomerDialogStatus = ({ commit }, payload) =>
  commit(types.SET_DELETE_CUSTOMER_DIALOG_STATUS, payload)

export const setSettleDebtDialogStatus = ({ commit }, payload) =>
  commit(types.SET_SETTLE_DEBT_DIALOG_STATUS, payload)

export const setSettleCreditSaleDialogStatus = async ({ commit }, data) => {
  commit(types.SET_SALE_TO_SETTLE_DEBT, data.isOpen ? data.sale : null)
  commit(types.SET_SETTLE_CREDIT_SALE_DIALOG_STATUS, data.isOpen)
}
