const tourService = {
  createTour: (context, options) => {
    return context.$shepherd({
      useModalOverlay: options.useModalOverlay,
      exitOnEsc: false,
      keyboardNavigation: false,
      confirmCancelMessage: options.confirmCancelMessage,
      modalContainer: document.getElementById('app'),
      stepsContainer: document.getElementById('app'),
    })
  },
  addSteps: (context, steps) => {
    steps.forEach(step => {
      const buttons = []
      if ('buttons' in step) {
        step.buttons.forEach(button =>
          buttons.push({
            text: context.getTranslatedText(button.text),
            classes: button.classes,
            action:
              'tourAction' in button
                ? context.tour[button.tourAction]
                : context[button.action],
          })
        )
      }
      context.tour.addStep({
        id: step.id,
        title: 'title' in step ? context.getTranslatedText(step.title) : null,
        text:
          'textRef' in step && context.$refs[step.textRef] !== undefined
            ? context.$refs[step.textRef].innerHTML
            : context.getTranslatedText(step.text),
        classes: step.classes,
        buttons: buttons,
        cancelIcon: {
          enabled: 'cancelIcon' in step ? step.cancelIcon : false,
        },
        attachTo: 'attachTo' in step ? step.attachTo : null,
        advanceOn: 'advanceOn' in step ? step.advanceOn : null,
        popperOptions: 'popperOptions' in step ? step.popperOptions : null,
        canClickTarget: 'canClickTarget' in step ? step.canClickTarget : true,
      })
    })
  },
  addCancelFunctionToSteps: (context, newCancelFunction) => {
    context.tour.steps.forEach(step => (step.cancel = newCancelFunction))
  },
}

export default tourService
