import devtools from '@vue/devtools'
import Vue, { reactive } from 'vue'

import { VueCrashReporter } from '@/config/sentry'
import { isDevelopment, isEnabledDevtoolsStandlone } from '@/config/env'

import logger from '@/tools/logger'

import vuetify from '@/plugins/vuetify'
import loading from '@/plugins/loading'
import pubsub from '@/plugins/pubsub'

import router from '@/router'

import pushNotificationsService from '@/services/renderer/pushNotifications'

import store from '@/store'

import App from '@/App.vue'

import '@/pipes'

import '@/plugins/VueCurrency'
import '@/plugins/scanner'
import '@/plugins/notifications'
import '@/plugins/vuelidate'
import '@/plugins/vuescroll'
import '@/plugins/vueShepherd'

import '@mdi/font/css/materialdesignicons.css'
import 'roboto-fontface/css/roboto/roboto-fontface.css'
import '@/styles/index.scss'
import 'shepherd.js/dist/css/shepherd.css'

import StarterLayout from './layouts/StarterLayout.vue'
import MainLayout from './layouts/MainLayout.vue'

Vue.component('starter-layout', StarterLayout)
Vue.component('main-layout', MainLayout)

Vue.use(pubsub)
Vue.use(loading, { reactive })
Vue.config.productionTip = false
logger('info', 'Loading app')

new Vue({
  router,
  store,
  vuetify,
  render: h => h(App),
}).$mount('#app')

VueCrashReporter()
pushNotificationsService.initListeners()

// This is to connect to the devTools instead of using the devTools installed by Electron
if (
  isDevelopment &&
  isEnabledDevtoolsStandlone?.toLocaleLowerCase() === 'true'
) {
  devtools.connect(/* host, port */)
}
