export default {
  channel: 'auth',
  replyChannel: 'auth-reply',
  events: {
    adminPasswordIsValid: {
      name: 'auth-admin-password-is-valid',
      replies: {
        error: 'auth-admin-password-is-valid-error',
        isValid: 'auth-admin-password-is-valid',
        isNotValid: 'auth-admin-password-is-not-valid',
      },
    },
    generateCodeAndSendEmail: {
      name: 'auth-generate-code-and-send-email',
      replies: {
        success: 'auth-generate-code-and-send-email-success',
        error: 'auth-generate-code-and-send-email-error',
      },
    },
    changeAdminPassword: {
      name: 'auth-change-admin-password',
      replies: {
        success: 'auth-change-admin-password-success',
        error: 'auth-change-admin-password-error',
      },
    },
  },
}
