import mutationsTypes from './mutations.types'

const setSupplierSearchTerm = (state, newState) => {
  state.filters.supplierSearchTerm = newState
}

const setVendorSearchTerm = (state, newState) => {
  state.filters.vendorSearchTerm = newState
}

const setSelectedSupplier = (state, payload) =>
  (state.selectedSupplier = payload)

const setSelectedVendor = (state, payload) => (state.selectedVendor = payload)

export const toggleAddVendorDialog = state => {
  state.addVendorDialog.isOpen = !state.addVendorDialog.isOpen
}

export const toggleVendorDetailDialog = state => {
  state.vendorDetailDialog.isOpen = !state.vendorDetailDialog.isOpen
}

export const togglePurchaseDraftDialog = state => {
  state.purchaseDraftDialog.isOpen = !state.purchaseDraftDialog.isOpen
}

export const updateSelectedVendorField = (state, payload) => {
  state.selectedVendor[payload.field] = payload.value
}

export const setDeleteVendorDialogStatus = (state, payload) => {
  state.deleteVendorDialog.isOpen = payload
}

const setSettleCreditPurchaseDialogStatus = (state, payload) => {
  state.settleCreditPurchaseDialog.isOpen = payload
}

const setPurchaseToSettleDebt = (state, payload) => {
  state.settleCreditPurchaseDialog.purchase = payload
}

const toggleSettleDebtDialogStatus = state => {
  state.settleDebtDialog.isOpen = !state.settleDebtDialog.isOpen
}

const toggleRepeatPurchaseConfirmDialog = state => {
  state.repeatPurchaseConfirmDialog.isOpen = !state.repeatPurchaseConfirmDialog
    .isOpen
}

const setPurchaseSelected = (state, payload) => {
  state.repeatPurchaseConfirmDialog.purchaseSelected = payload
}
const setPurchaseDraft = (state, payload) => {
  state.purchaseDraftDialog.purchaseSelected = payload
}
const setPurchaseDraftOld = (state, payload) => {
  state.purchaseDraftDialog.purchaseOld = payload
}

export default {
  [mutationsTypes.SET_SUPPLIERS_SEARCH_TERM_FILTER]: setSupplierSearchTerm,
  [mutationsTypes.SET_VENDORS_SEARCH_TERM_FILTER]: setVendorSearchTerm,
  [mutationsTypes.SET_SELECTED_SUPPLIER]: setSelectedSupplier,
  [mutationsTypes.SET_SELECTED_VENDOR]: setSelectedVendor,
  [mutationsTypes.SET_ADD_VENDOR_DIALOG_STATUS]: toggleAddVendorDialog,
  [mutationsTypes.SET_VENDOR_DETAIL_DIALOG_STATUS]: toggleVendorDetailDialog,
  [mutationsTypes.SET_PURCHASE_DRAFT_DIALOG_STATUS]: togglePurchaseDraftDialog,
  [mutationsTypes.SET_PURCHASE_DRAFT]: setPurchaseDraft,
  [mutationsTypes.SET_PURCHASE_DRAFT_OLD]: setPurchaseDraftOld,
  [mutationsTypes.UPDATE_SELECTED_VENDOR_FIELD]: updateSelectedVendorField,
  [mutationsTypes.SET_DELETE_VENDOR_DIALOG_STATUS]: setDeleteVendorDialogStatus,
  [mutationsTypes.SET_SETTLE_CREDIT_PURCHASE_DIALOG_STATUS]: setSettleCreditPurchaseDialogStatus,
  [mutationsTypes.SET_PURCHASE_TO_SETTLE_DEBT]: setPurchaseToSettleDebt,
  [mutationsTypes.SET_SETTLE_DEBT_DIALOG_STATUS]: toggleSettleDebtDialogStatus,
  [mutationsTypes.SET_CONFIRM_REPEAT_PURCHASE_DIALOG_STATUS]: toggleRepeatPurchaseConfirmDialog,
  [mutationsTypes.SET_PURCHASE_SELECTED]: setPurchaseSelected,
}
