import { getDay, getNow } from '@/tools/dates'

const loadVendorsNotifications = function() {
  const todayDayOfWeek = getTodayDayOfWeek()
  this.vendors.forEach(vendor => {
    if (!vendor.frequency || vendor.isAirTime === 1) {
      return
    }
    const frequency = vendor.frequency.split(',')
    if (
      frequency[todayDayOfWeek] !== '1' ||
      this.notificationAlreadyDone('vendor', vendor.id)
    ) {
      return
    }
    this.addNotifications({
      notifications: {
        type: 'vendor',
        id: vendor.id,
        description: this.getTranslatedText(
          'notificationsView.vendor.description',
          vendor.name
        ),
      },
    })
  })
}

const getTodayDayOfWeek = () => {
  const tomorrowDayOfWeek = getDay(getNow())
  return tomorrowDayOfWeek === 0 ? 6 : tomorrowDayOfWeek - 1
}

const loadProductsNotifications = function() {
  if (
    this.notificationAlreadyDone('productsLowStock', 'productsLowStock') &&
    this.notificationAlreadyDone('productsNoStock', 'productsNoStock')
  ) {
    return
  }
  const { productsNoStock, productsLowStock } = getLowAndNoStockProducts(
    this.products
  )
  if (
    productsNoStock.length &&
    !this.notificationAlreadyDone('productsNoStock', 'productsNoStock')
  ) {
    this.addNotifications({
      notifications: {
        type: 'productsNoStock',
        id: 'productsNoStock',
        description: this.getTranslatedText(
          'notificationsView.productsNoStock.description',
          productsNoStock.join(', ')
        ),
      },
    })
  }
  if (
    productsLowStock.length &&
    !this.notificationAlreadyDone('productsLowStock', 'productsLowStock')
  ) {
    this.addNotifications({
      notifications: {
        type: 'productsLowStock',
        id: 'productsLowStock',
        description: this.getTranslatedText(
          'notificationsView.productsLowStock.description',
          productsLowStock.join(', ')
        ),
      },
    })
  }
}

const getLowAndNoStockProducts = products => {
  const productsNoStock = []
  const productsLowStock = []
  products.forEach(product => {
    if (product.id > 0 && product.airTime === 0 && product.isGeneric === 0) {
      if (product.quantity <= 0) {
        productsNoStock.push(product.name)
        return
      }
      if (product.quantity <= product.levelWarning) {
        productsLowStock.push(product.name)
      }
    }
  })
  return { productsNoStock, productsLowStock }
}

const replaceRouteByQuery = function(path) {
  const route = path.split('?')
  if (!route[1]) return
  const query = route[1].split('=')
  if (
    !this.$route.query[query[0]] ||
    this.$route.query[query[0]] !== query[1]
  ) {
    this.$router.replace({
      query: { [query[0]]: query[1] },
    })
  }
}

const loadNotificationsLoadedOnce = function() {
  this.addNotifications({
    notifications: this.notificationsLoadedOnce.filter(
      notification =>
        !this.notificationAlreadyDone(notification.type, notification.id)
    ),
  })
}

const getPathByNotification = notification => {
  switch (notification.type) {
    case 'vendor': {
      return `/app/vendors?vendorId=${notification.id}`
    }
    case 'productsNoStock': {
      return '/app/products?filterBy=noStock'
    }
    case 'productsLowStock': {
      return '/app/products?filterBy=lowStock'
    }
  }
  return undefined
}

export default {
  loadVendorsNotifications,
  loadProductsNotifications,
  replaceRouteByQuery,
  loadNotificationsLoadedOnce,
  getPathByNotification,
}
