import types from '@/store/notifications/mutations.types'

export const setStatusShowNotifications = ({ commit }, status) => {
  commit(types.SET_STATUS_SHOW_NOTIFICATIONS, status)
}

export const addNotifications = ({ commit }, payload) => {
  commit(types.ADD_NOTIFICATIONS, payload)
}

export const setNotifications = ({ commit }, notifications) => {
  commit(types.SET_NOTIFICATIONS, notifications)
}

export const removeNotification = ({ commit }, notificationToRemove) => {
  commit(types.REMOVE_NOTIFICATION, notificationToRemove)
}

export const resetDoneNotifications = ({ commit }) => {
  commit(types.RESET_DONE_NOTIFICATIONS)
}

export const addNotificationLoadedOnce = ({ commit }, notification) => {
  commit(types.ADD_NOTIFICATION_LOADED_ONCE, notification)
}

export const resetNotificationsLoadedOnce = ({ commit }) => {
  commit(types.RESET_NOTIFICATION_LOADED_ONCE)
}
