<template>
  <div class="fill-height">
    <PaginatedCards :config="paginatedCardsConfig" />
  </div>
</template>

<script>
import { mapState, mapGetters } from 'vuex'

import VIDEO_WINDOW_EVENTS from '@/config/events/videoWindow'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import setConfig from '@/components/HelpCenterView/HelpCenterList/config'
import PaginatedCards from '@/components/shared/PaginatedCards.vue'

export default {
  name: 'HelpCenterList',
  components: { PaginatedCards },
  computed: {
    ...mapState('app', ['windowSize']),
    ...mapGetters('helpCenter', ['getFilteredData']),
    paginatedCardsConfig() {
      return setConfig(
        {
          windowHeight: this.windowSize.y,
          windowWidth: this.windowSize.x,
          currentCardComponent: 'VideoCard',
          items: this.getFilteredData,
        },
        {
          openPlayerWindow: this.openPlayerWindow,
        }
      )
    },
  },
  methods: {
    openPlayerWindow(item) {
      if (navigator.onLine) {
        rendererEventsService.send(VIDEO_WINDOW_EVENTS.channel, {
          event: VIDEO_WINDOW_EVENTS.events.loadVideoWindow.name,
          data: { video: item },
        })
      } else {
        notificationsService.showError(
          'notification.helpCenter.internetConnectionError',
          this.$vuetify.lang,
          { timeout: 10000 }
        )
      }
    },
  },
}
</script>
