const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-face-agent',
    title: 'starterLayout.login.support',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    buttons: { accept: true, cancel: false },
    acceptButtonText: 'close',
    buttonTextColor: {
      accept: 'white',
    },
    buttonColor: {
      accept: 'primary',
    },
    height: 400,
    maxWidth: 600,
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.closeDialog(),
  },
})

export default setConfig
