import { isDevelopment } from '@/config/env'
import PUBSUB_EVENTS from '@/config/events/pubsub'

import rendererEventsService from '@/services/renderer/rendererEvents'

export default {
  install: app => {
    if (!isDevelopment)
      rendererEventsService.send(PUBSUB_EVENTS.channel, {
        event: PUBSUB_EVENTS.events.startPubsubService.name,
      })
    app.prototype.$track = event => {
      if (!isDevelopment)
        rendererEventsService.send(PUBSUB_EVENTS.channel, {
          event: PUBSUB_EVENTS.events.publishMessage.name,
          data: {
            isAppOnline: navigator.onLine,
            data: { event_data: event },
          },
        })
    }
    app.directive('track', {
      bind: (el, binding) => {
        el.addEventListener('click', () => {
          if (!isDevelopment)
            rendererEventsService.send(PUBSUB_EVENTS.channel, {
              event: PUBSUB_EVENTS.events.publishMessage.name,
              data: {
                isAppOnline: navigator.onLine,
                data: {
                  event_data: {
                    type: 'interaction',
                    action: 'click',
                    category: binding.value.category || '',
                    screen: binding.value.screen || '',
                    name: binding.value.name,
                    extra_data: binding.value.extraData || null,
                  },
                },
              },
            })
        })
      },
      unbind: el => {
        el.removeEventListener('click', () => {})
      },
    })
  },
}
