<template>
  <div>
    <span
      v-if="value === null"
      :class="[type, `${color}--text`, `text--${theme}`, className]"
    >
      <slot />
    </span>
    <template v-else>
      <span
        v-if="link"
        :class="[type, `${color}--text`, `text--${theme}`, className]"
      >
        <a @click="link">
          {{ getTranslatedText(value) }}
        </a>
      </span>
      <span
        v-else
        :class="[type, `${color}--text`, `text--${theme}`, className]"
      >
        {{ getTranslatedText(value) }}
      </span>
    </template>
  </div>
</template>

<script>
export default {
  name: 'FormattedText',
  props: {
    value: {
      type: String,
      default: null,
    },
    intl: {
      type: Boolean,
      default: false,
    },
    type: {
      type: String,
      default: 'body',
    },
    color: {
      type: String,
      default: 'textPrimary',
    },
    theme: {
      type: String,
      default: 'lighten-1',
    },
    className: {
      type: String,
      default: '',
    },
    link: {
      type: Function,
      default: null,
    },
    shorter: {
      type: Boolean,
      default: false,
    },
    shorterValue: {
      type: String,
      default: '20',
    },
  },
  methods: {
    getTranslatedText: function(translateString) {
      if (this.intl) {
        return this.$vuetify.lang.t(`$vuetify.${translateString}`)
      }
      if (this.shorter) {
        return this.$options.filters.truncate(
          translateString,
          Number(this.shorterValue)
        )
      }
      return translateString
    },
  },
}
</script>
