const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-book-cancel-outline',
    title: 'starterLayout.ttBlockedDialog.title',
    messages: ['starterLayout.ttBlockedDialog.message'],
    persistent: true,
    titleBackground: '#white',
    titleColor: 'textPrimary',
    buttons: {
      accept: true,
      cancel: false,
    },
    buttonTextColor: {
      accept: 'white',
    },
    buttonColor: {
      accept: 'primary',
    },
    height: 270,
    maxWidth: 575,
    onClickCancel: () => methods.closeTiendatek(),
    onClickAccept: () => methods.closeTiendatek(),
  },
})

export default setConfig
