<template>
  <v-data-iterator
    :items="config.state.items"
    :items-per-page.sync="itemsPerPage"
    :page.sync="page"
    :sort-by="sortBy"
    :sort-desc="sortDesc"
    :loading="config.state.fetching"
    class="d-flex flex-column paginated-card"
    hide-default-footer
    v-bind="propsIterator"
    @update:sort-by="sortByWasChanged"
    @update:sort-desc="sortDescWasChanged"
  >
    <!-- Loader -->
    <template v-slot:loading>
      <v-overlay
        :value="config.state.fetching"
        absolute
        class="paginated-card__fetching"
        opacity="0.15"
      >
        <SyncLoader :color="loaderColor" class="text-center" />
      </v-overlay>
    </template>
    <!-- List state message -->
    <template v-slot:no-data>
      <div class="fill-height" id="data-iterator-no-data" style="display: none">
        <HelpWatermark :config="noDataMessage" />
      </div>
    </template>
    <!-- Cards list header -->
    <template v-slot:header>
      <div
        class="d-flex justify-space-between paginated-card__header pb-6 px-3"
      >
        <!-- List title -->
        <slot name="title">
          <div class="d-flex align-center paginated-title">
            <v-icon color="primary" large>{{ config.icon }}</v-icon>
            <FormattedText
              intl
              type="text-h6"
              color="textPrimary"
              :value="config.title"
              :class="config.titleClass ? config.titleClass : ''"
            />
            <slot name="headerLeft" />
          </div>
        </slot>
        <!-- List controls -->
        <div class="d-flex align-center paginated-card__header__controls">
          <div
            v-if="
              'filters' in config.state &&
                'superCategories' in config.state.filters
            "
            class="d-flex"
          >
            <v-tooltip bottom color="accent">
              <template v-slot:activator="{ on, attrs }">
                <div v-bind="attrs" v-on="on">
                  <v-chip
                    v-if="config.state.filters.group === 'air-time'"
                    :color="
                      config.state.airtimeBalanceFetching
                        ? 'secondary'
                        : 'primary'
                    "
                    text-color="white"
                    @click="goToAdminPreferences()"
                  >
                    <v-avatar left>
                      <v-icon>mdi-ev-station</v-icon>
                    </v-avatar>

                    {{
                      config.state.airtimeBalance > 0
                        ? formatNumberFromDbToCurrency(
                            config.state.airtimeBalance
                          )
                        : getTranslatedText('airtimeView.buyBalance')
                    }}
                  </v-chip>
                </div>
              </template>
              {{ getTranslatedText('airtimeView.buyBalance') }}
            </v-tooltip>
            <div
              v-for="category in config.state.filters.superCategories"
              :key="category"
              class="pr-3"
            >
              <v-chip color="productPrimary" text-color="white">
                <v-avatar left>
                  <v-icon>mdi-tag-outline</v-icon>
                </v-avatar>
                {{ getTranslatedText(`superCategories.${category}`) }}
              </v-chip>
            </div>
          </div>
          <v-chip
            v-if="groupIcon.length > 0"
            class="ma-2 mb-4"
            color="accent"
            text-color="white"
          >
            <v-avatar left>
              <v-icon middle>{{ groupIcon[0].icon }}</v-icon>
            </v-avatar>
            <FormattedText intl :value="groupIcon[0].title" color="white" />
          </v-chip>
          <!-- Sort -->
          <v-select
            v-if="config.sort"
            v-model="sortBy"
            :items="config.sort.by"
            :item-text="item => getTranslatedText(item.text)"
            :menu-props="{ button: true, offsetY: true }"
            item-value="prop"
            :placeholder="getTranslatedText('shared.sortBy')"
            class="paginated-card__header__controls__sort-selector custom-text-field px-4"
            filled
            rounded
            hide-details
            @change="onSelectClick"
          ></v-select>
          <Button
            v-if="config.sort"
            :color="config.sort.iconColor"
            class="mb-3"
            dark
            tooltipPosition="bottom"
            fab
            small
            depressed
            :icon="sortDesc ? 'mdi-sort-descending' : 'mdi-sort-ascending'"
            @click="onSortButtonClick"
            v-track:click="{
              category: $route.name,
              screen: 'PaginatedCards',
              name: 'Sort direction',
            }"
          />
        </div>
      </div>
    </template>
    <!-- Content -->
    <template v-slot:default="props">
      <transition-group
        id="data-iterator-container"
        appear
        name="slide-in"
        tag="div"
        class="row ma-0 overflow-auto align-items-start paginated-card__content"
        @after-appear="getRowsPerPage()"
      >
        <v-col
          v-for="(item, index) in props.items"
          :key="
            `${
              item.id && item.upc
                ? `card-${item.id}-${item.upc}`
                : `card-${index}`
            }`
          "
          :cols="12 / itemsPerRow"
          class="py-2 item"
          @click="onClickCard(item)"
        >
          <component
            :is="
              config.cardComponents[config.state.currentCardComponent].component
            "
            :data="item"
            :methods="
              config.cardComponents[config.state.currentCardComponent].methods
            "
            :selected="config.state.selectedCard"
            :index="index"
            :truncate="
              config.cardComponents[config.state.currentCardComponent].truncate
            "
            :deleteSelectConfig="
              config.state.bulkDeletion
                ? config.state.bulkDeletion.getDeleteSelectConfig(item)
                : {}
            "
          />
        </v-col>
      </transition-group>
    </template>
    <!-- Footer -->
    <template v-slot:footer>
      <v-row
        class="no-gutters mt-auto py-2 shrink"
        align="center"
        justify="end"
        id="data-iterator-footer"
      >
        <div v-if="config.state.items.length > 0">
          <v-spacer></v-spacer>
          <!-- Pagination -->
          <div class="px-3">
            <span class="mr-4 grey--text">
              {{ getTranslatedText('dataIterator.pageText', page) }}
              <span
                v-text="numberOfPages"
                class="font-weight-bold primary--text"
              ></span>
            </span>
            <v-btn
              small
              dark
              rounded
              color="primary"
              class="mr-1"
              @click="formerPage"
              v-track="{
                category: $route.name,
                screen: 'PaginatedCards',
                name: 'Go to previous page',
              }"
            >
              <v-icon>mdi-chevron-left</v-icon>
            </v-btn>
            <v-btn
              small
              dark
              rounded
              color="primary"
              class="ml-1"
              @click="nextPage"
              v-track="{
                category: $route.name,
                screen: 'PaginatedCards',
                name: 'Go to next page',
              }"
            >
              <v-icon>mdi-chevron-right</v-icon>
            </v-btn>
          </div>
        </div>
      </v-row>
    </template>
  </v-data-iterator>
</template>

<script>
import { isNil } from 'ramda'
import { SyncLoader } from '@saeris/vue-spinners'

import { getTranslatedText } from '@/tools/data'
import { getObjectCopy } from '@/tools/data'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import { captureException } from '@/tools/exceptions'

import FormattedText from '@/components/shared/FormattedText'
import Button from '@/components/shared/CustomButton'
import HelpWatermark from '@/components/shared/HelpWatermark'

export default {
  name: 'PaginatedCards',
  components: {
    FormattedText,
    SyncLoader,
    Button,
    HelpWatermark,
  },
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      rowsPerPage: this.config.rowsPerPage,
      page: this.config.page,
      listViewWidth: null,
      sortBy: this.config.sort ? this.config.sort.sortBy : null,
      sortDesc: this.config.sort ? this.config.sort.sortDesc : null,
      componentWidth: 0,
      clicks: 0,
      timer: null,
      noDataMessage: this.config.noDataMessage,
    }
  },
  computed: {
    propsIterator() {
      const props = {}
      if (this.config.methods.customSort) {
        props.customSort = this.config.methods.customSort
      }
      return props
    },
    numberOfPages() {
      return Math.ceil(this.config.state.items.length / this.itemsPerPage)
    },
    itemsPerRow() {
      if (this.config.isDetail === false) {
        if (this.componentWidth <= 1200) return this.getItemsPerRow('small')
        if (this.componentWidth <= 1500) return this.getItemsPerRow('medium')
        if (this.componentWidth <= 2200) return this.getItemsPerRow('large')
        return this.getItemsPerRow('extraLarge')
      }
      if (this.componentWidth <= 900) return this.getItemsPerRow('small')
      if (this.componentWidth <= 1200) return this.getItemsPerRow('medium')
      if (this.componentWidth <= 2200) return this.getItemsPerRow('large')
      return this.getItemsPerRow('extraLarge')
    },
    itemsPerPage: {
      get() {
        return Math.ceil(this.rowsPerPage * this.itemsPerRow)
      },
      set(newValue) {
        return newValue
      },
    },
    groupIcon() {
      if (!('groups' in this.config)) return []
      return this.config.groups.filter(
        item => item.id === this.config.state.filters.group
      )
    },
    loaderColor() {
      const { light, dark } = this.config.loaderColor
      return this.$vuetify.theme.dark ? dark : light
    },
  },
  methods: {
    getTranslatedText,
    formatNumberFromDbToCurrency,
    getCategoryURL: function(name) {
      return `/supercategories/${name}.svg`
    },
    nextPage() {
      if ('resetScannerStatus' in this.config.methods)
        this.config.methods.resetScannerStatus()
      if (this.page + 1 <= this.numberOfPages) this.page += 1
    },
    formerPage() {
      if ('resetScannerStatus' in this.config.methods)
        this.config.methods.resetScannerStatus()
      if (this.page - 1 >= 1) this.page -= 1
    },
    getRowsPerPage() {
      const container = document.getElementById('data-iterator-container')
      const footer = document.getElementById('data-iterator-footer')
      if (!container || !footer) return
      const minItemHeight = this.config.cardComponents[
        this.config.state.currentCardComponent
      ].cardOffsetHeight
      const containerHeight = !isNil(container)
        ? parseInt(container.clientHeight, 0)
        : parseInt(getComputedStyle(footer).marginTop, 0) + 60
      const newRowsPerPage = Math.floor(
        Math.max(containerHeight, minItemHeight) / minItemHeight
      )
      this.rowsPerPage = newRowsPerPage < 2 ? 3 : newRowsPerPage
    },
    getItemsPerRow(breakpoint) {
      const { itemsPerRow } = this.config.cardComponents[
        this.config.state.currentCardComponent
      ]
      return itemsPerRow[breakpoint]
    },
    getProductsLitstContainerWidth() {
      const container = document.getElementById(`${this.config.containerRef}`)
      return container ? container.offsetWidth : null
    },
    addClassToNoDataParent() {
      setTimeout(() => {
        const noDataElement = document.querySelector('#data-iterator-no-data')
        if (noDataElement) {
          noDataElement.parentElement.classList.add('fill-height')
          noDataElement.style.display = 'block'
        }
      }, 50)
    },
    onClickCard(item) {
      const cleanItem = getObjectCopy(item)
      this.clicks++
      if (this.clicks === 1) {
        var self = this
        this.timer = setTimeout(() => {
          self.clicks = 0
          this.config.methods.onClick(cleanItem)
        }, 200)
      } else {
        clearTimeout(this.timer)
        this.config.methods.onDblClick(cleanItem)
        this.clicks = 0
      }
    },
    onSelectClick() {
      this.$track({
        type: 'interaction',
        action: 'change',
        category: this.$route.name,
        screen: 'PaginatedCards',
        name: 'Select sort by',
      })
      if ('resetScannerStatus' in this.config.methods)
        this.config.methods.resetScannerStatus()
    },
    onSortButtonClick() {
      if ('resetScannerStatus' in this.config.methods)
        this.config.methods.resetScannerStatus()
      return (this.sortDesc = !this.sortDesc)
    },
    goToAdminPreferences() {
      this.$router
        .push({ path: '/app/preferences', query: { tab: 'admin' } })
        .catch(error => captureException(error))
    },
    sortByWasChanged(value) {
      if ('updateSortBy' in this.config.methods) {
        this.config.methods.updateSortBy(value)
      }
    },
    sortDescWasChanged(value) {
      if ('updateSortDesc' in this.config.methods) {
        this.config.methods.updateSortDesc(value)
      }
    },
  },
  watch: {
    'config.state.windowHeight': function(newValue, oldValue) {
      if (oldValue !== newValue) {
        setTimeout(() => {
          this.getRowsPerPage()
        }, 100)
      }
    },
    'config.state.windowWidth': function() {
      this.componentWidth = this.getProductsLitstContainerWidth()
    },
    'config.state.sidebarOpened': function() {
      // Wait menu transition finish finish
      setTimeout(() => {
        this.componentWidth = this.getProductsLitstContainerWidth()
      }, 400)
    },
    'config.state.filters': function() {
      setTimeout(() => {
        this.getRowsPerPage()
      }, 100)
      this.addClassToNoDataParent()
    },
    'config.sort.sortBy': function(newValue) {
      this.sortBy = newValue
    },
  },
  mounted() {
    this.addClassToNoDataParent()
    this.componentWidth = this.getProductsLitstContainerWidth()
  },
}
</script>

<style lang="scss" scoped>
.paginated-card {
  background-color: var(--v-mainBackground-base) !important;
  height: 100%;
  overflow: hidden;
  .paginated-card__fetching {
    height: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-direction: column;
  }
  .paginated-card__header {
    min-height: 90px;
  }
  .paginated-card__header__controls {
    .paginated-card__header__controls__sort-selector {
      width: 250px;
    }
  }
}

#data-iterator-container {
  align-content: flex-start;
}

.slide-in-enter {
  opacity: 0;
  transform: scale(0.8);
}
.slide-in-enter-active {
  transition: all 0.4s ease;
}
.category svg path {
  fill: white;
}
.loader {
  background-color: var(--v-productLoader-base);
}
</style>
