import { isEmpty } from 'ramda'

import { filterBy } from '@/store/helpCenter/getters.tools'

export const getFilteredData = (...args) => {
  const state = args[0]
  const helpCenterView = args[2].helpCenterView
  const { searchTerm, videoTypes } = helpCenterView.filters
  let { videos } = state.data
  if (!isEmpty(videoTypes)) videos = filterBy.videoTypes(videoTypes, videos)
  if (searchTerm !== null) videos = filterBy.searchTerm(searchTerm, videos)
  return videos
}
