import uniqid from 'uniqid'

import priceFrom from '@/config/itemAddedFrom'

import { getNow } from '@/tools/dates'

const getPrices = (product, products) => {
  const productFound = products.find(item => item.upc === product.upc)
  const prices = {
    isPriceChanged: productFound.isPriceChanged,
    isPiecePriceChanged: productFound.isPiecePriceChanged,
    unitPrice: getUnitPriceToSalePrice(product),
    dbPrice: getDbPriceToSalePrice(product, productFound),
  }
  if (product.factor > 0) {
    prices.openProductDbPrices = {
      package: prices.isPriceChanged === 1 ? productFound.price : product.price,
      piece:
        prices.isPiecePriceChanged === 1
          ? productFound.unitProdPrice
          : product.unitProdPrice,
    }
  }
  return prices
}

const getUnitPriceToSalePrice = product => {
  return product.factor > 0 && product.factorSalesBy === 1
    ? product.unitProdPrice
    : product.price
}

const getDbPriceToSalePrice = (product, productFound) => {
  if (product.factor <= 0) return productFound.price
  if (product.factorSalesBy === 0 && product.isPriceChanged === 1) {
    return productFound.price
  }
  if (product.factorSalesBy === 1 && product.isPiecePriceChanged === 1) {
    return productFound.unitProdPrice
  }
  return getUnitPriceToSalePrice(product)
}

const getAddedFrom = product => {
  if (product.isGeneric === 1) return priceFrom.FROM_PRICE
  if (product.airTime > 0) return priceFrom.FROM_AIRTIME_OR_SERVICES
  if (product.isGramaje === 1) return priceFrom.FROM_WEIGHT
  if (product.isStarred === 1) return priceFrom.FROM_FAVORITES
  return priceFrom.FROM_SEARCH
}

const getProductForSale = (product, products) => {
  const productPrices = getPrices(product, products)
  return {
    uniqueId: uniqid(),
    id: product.id,
    stock: product.stock || product.quantity,
    isGramaje: product.isGramaje === 1 ? 1 : 0,
    isOpenProduct: product.factor > 0 ? 1 : 0,
    openProductType: product.factorSalesBy,
    openProductDbPrices: productPrices.openProductDbPrices,
    isGeneric: product.isGeneric === 1 ? 1 : 0,
    isPriceChanged: productPrices.isPriceChanged,
    isPiecePriceChanged: productPrices.isPiecePriceChanged,
    name: product.name,
    quantity: 1,
    unitPrice: productPrices.unitPrice,
    cost: product.cost,
    upc: product.upc,
    timeAdded: getNow(false),
    priceFrom: getAddedFrom(product),
    dbPrice: productPrices.dbPrice,
    levelWarning: product.levelWarning,
    factor: product.factor,
    description: product.alternativeName,
    promotionTypeId: 0,
  }
}

export default {
  getPrices,
  getAddedFrom,
  getProductForSale,
}
