import { enrolledCustomer as enrolledCustomerMapper } from '@/config/storeMapper'

import { mapStoreObject } from '@/tools/data'

import types from '@/store/loyaltyProgram/mutations.types'
import { updateCustomerData } from '@/store/loyaltyProgram/actions.tools'

export const setLoyaltyFetching = ({ commit }, payload) =>
  commit(types.SET_LOYALTY_FETCHING, payload)

export const setEnrolledCustomers = async ({ commit }, data) => {
  const { enrolledCustomers: items, customers, sales } = data
  const customerSales = sales
    .filter(item => item.customer_id > -1)
    .sort((a, b) => new Date(a.sale_date) - new Date(b.sale_date))
  const enrolledCustomers = await items.map(item => {
    item = mapStoreObject(item, enrolledCustomerMapper)
    return updateCustomerData(item, customers, customerSales)
  })
  commit(types.SET_ENROLLED_CUSTOMERS, enrolledCustomers)
  commit(types.SET_LOYALTY_FETCHING, false)
}

export const updateEnrolledCustomer = ({ commit }, data) =>
  commit(types.UPDATE_ENROLLED_CUSTOMER, data)

export const updateEnrolledCustomerByProperties = ({ commit }, data) =>
  commit(types.UPDATE_ENROLLED_CUSTOMER_BY_PROPERTIES, data)

export const updateLastSaleDate = ({ commit }, data) =>
  commit(types.UPDATE_LAST_SALE_DATE, data)

export const setEnrolledCustomersError = ({ commit }, payload) => {
  commit(types.SET_ENROLLED_CUSTOMERS_ERROR, payload.message)
}

export const deleteEnrolledCustomer = ({ commit }, payload) => {
  commit(types.DELETE_ENROLLED_CUSTOMER, payload)
}

export const deleteEnrolledCustomers = ({ commit }, payload) => {
  payload.map(enrolledCustomer => {
    commit(types.DELETE_ENROLLED_CUSTOMER, enrolledCustomer.customerId)
  })
}
