  [types.SET_APP_ZOOM_LEVEL]: setZoomLevel,
  [types.SET_FORCE_CHANGE_DIALOG]: setForceChangeDialog,
  [types.SET_DEFAULT_PRODUCTS_FILTER]: setDefaultProductsFilter,
  [types.SET_ADD_CASH_MOVEMENT_DIALOG_STATUS]: setAddCashMovementDialogStatus,
