  [types.SET_APP_ADD_MARGIN_TICKET_STATUS]: setAddMarginTicketStatus,
  [types.SET_APP_SHOW_SCAN_YOUR_PRODUCTS_DIALOG_STATUS]: setShowScanYourProductsDialogStatus,
