  [types.SET_APP_CONFIRM_CANCEL_TOUR_DIALOG_TOUR]: setConfirmCancelTourDialogTour,
  [types.SET_RESTORE_SOCK_CONFIRMATION_DIALOG_STATUS]: setRestoreStockConfirmationDialogStatus,
  [types.SET_EMPLOYEE_FORM_DIALOG_STATUS]: setEmployeeFormDialogStatus,
  [types.SET_DOWNLOAD_DIALOG_STATUS]: setDownloadDialogStatus,
  [types.SET_APP_ADD_ADMIN_PASSWORD_DIALOG_STATUS]: setAddAdminPasswordDialogStatus,
  [types.SET_APP_ADD_ADMIN_PASSWORD_DIALOG_USERINFO]: setaddAdminPasswordDialogUserInfo,
  [types.SET_APP_ADD_ADMIN_PASSWORD_DIALOG_NEWACCOUNT]: setaddAdminPasswordDialogNewAccount,
  [types.SET_SURVEY_DIALOG]: setSurveyDialog,
  [types.TOGGLE_EXTERNAL_CASH_REGISTER_INFO_DIALOG]: toggleExternalCashRegisterInfoDialog,
  [types.SET_APP_CONFIRM_DEVICE_CHANGE_DIALOG_STATUS]: setConfirmDeviceChangeDialogStatus,
  [types.SET_APP_CONFIRM_DEVICE_CHANGE_DIALOG_DATA]: setConfirmDeviceChangeDialogData,
