import { required } from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    icon: 'mdi-account-switch',
    title: 'mainLayout.user.change',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    messages: ['mainLayout.user.changeText'],
    height: 360,
    maxWidth: 500,
    id: 'change-user-form',
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.changeUserSelected(),
  },
  fields: [
    {
      id: 'user',
      type: 'select',
      items: state.users,
      selected: ['selectedUser', 'id'],
      label: 'mainLayout.user.user',
      color: 'primary',
      validators: { required },
    },
    {
      id: 'password',
      type: 'password',
      validators: { required },
      autofocus: true,
    },
  ],
  id: 'change-user-form',
})

export default setConfig
