import types from '@/store/helpCenterView/mutations.types'

const setSearchTermFilter = (state, payload) => {
  state.filters.searchTerm = payload
}

const setVideoTypeFilter = (state, payload) => {
  state.filters.videoTypes = payload
}

export default {
  [types.SET_SEARCH_TERM_FILTER]: setSearchTermFilter,
  [types.SET_VIDEO_TYPE_FILTER]: setVideoTypeFilter,
}
