import types from '@/store/usersView/mutations.types'

const setSelectedUser = (state, payload) => {
  state.selectedUser = payload
}

const setEstimatedCash = (state, payload) => {
  state.estimatedCash = payload
}

const setSelectedUserHasSales = (state, payload) => {
  state.selectedUser.hasSales = payload
}

const setSelectedUserHasPurchases = (state, payload) => {
  state.selectedUser.hasPurchases = payload
}

export default {
  [types.SET_USER_SELECTED]: setSelectedUser,
  [types.SET_USER_ESTIMATED_CASH]: setEstimatedCash,
  [types.SET_USER_HAS_SALES]: setSelectedUserHasSales,
  [types.SET_USER_HAS_PURCHASES]: setSelectedUserHasPurchases,
}
