import { append, indexOf, find, update, remove } from 'ramda'

import mutationsTypes from './mutations.types'

const setFetching = (state, newState) => {
  state.fetching = newState
}

const setError = (state, error) => {
  state.data.vendors = []
  state.error = true
  state.errorMessage = error
}

const setVendors = (state, payload) => {
  state.data.vendors = payload
  state.error = false
  state.errorMessage = ''
}

const addVendor = (state, payload) => {
  state.data.vendors = append(payload, state.data.vendors)
}

const updateVendor = (state, payload) => {
  const vendorIndex = indexOf(
    find(vendor => vendor.id === payload.id, state.data.vendors),
    state.data.vendors
  )
  state.data.vendors = update(vendorIndex, payload, state.data.vendors)
}
const deleteVendor = (state, payload) => {
  const vendorIndex = indexOf(
    find(vendor => vendor.id === payload.id, state.data.vendors),
    state.data.vendors
  )
  if (vendorIndex === -1) return
  state.data.vendors = remove(vendorIndex, 1, state.data.vendors)
}

export default {
  [mutationsTypes.SET_VENDORS]: setVendors,
  [mutationsTypes.SET_VENDORS_FETCHING]: setFetching,
  [mutationsTypes.SET_VENDORS_ERROR]: setError,
  [mutationsTypes.ADD_VENDOR]: addVendor,
  [mutationsTypes.DELETE_VENDOR]: deleteVendor,
  [mutationsTypes.UPDATE_VENDOR]: updateVendor,
}
