import { filter, find, propEq, includes, isNil } from 'ramda'

import { normalizeString } from '@/tools/data'

export const getFilteredSuppliers = (...args) => {
  const suppliers = args[0].data.suppliers
  const vendors = args[2].vendors.data.vendors
  const supplierSearchTerm = normalizeString(
    args[2].vendorsView.filters.supplierSearchTerm || ''
  )

  return filter(supplier => {
    const isSupplierAdded = !isNil(find(propEq('name', supplier.name), vendors))
    if (!isSupplierAdded) supplier.isSupplierAdded = false
    return (
      includes(supplierSearchTerm, normalizeString(supplier.name)) &&
      !isSupplierAdded
    )
  }, suppliers)
}
