<template>
  <v-form
    ref="form"
    @submit.prevent="'onSubmit' in config ? config.onSubmit : null"
    :id="'id' in config ? config.id : ''"
  >
    <div v-for="field in config.fields" :key="field.id">
      <AccountInput
        :ref="field.id"
        v-if="field.type === 'account'"
        v-model="inputs[field.id]"
        :className="field.className"
        :v="config.state.v[field.id]"
        :label="field.label"
        :icon="field.icon"
        :readonly="field.readonly ? field.readonly : false"
        :autofocus="field.autofocus ? field.autofocus : false"
      />
      <PasswordInput
        :ref="field.id"
        v-if="field.type === 'password' && field.show !== false"
        v-model="inputs[field.id]"
        :className="field.className"
        :v="config.state.v[field.id]"
        :label="field.label"
        :autofocus="field.autofocus ? field.autofocus : false"
      />
      <FormattedText
        v-if="field.type === 'formattedText'"
        :type="field.textType"
        :color="field.color"
        :class="field.class"
        :intl="field.intl"
        :value="field.value"
      />
      <a
        v-if="
          field.type === 'textLink' &&
            (field.show === undefined || field.show === true)
        "
        href="#"
        @click="field.onClick"
      >
        <FormattedText
          :type="field.textType"
          :color="field.color"
          :class="field.class"
          :intl="field.intl"
          :value="field.value"
        />
      </a>
      <CountryInputSelector
        :ref="field.id"
        v-if="field.type === 'countrySelector'"
        v-model="inputs[field.id]"
        :className="field.className"
        :v="config.state.v[field.id]"
        @input="value => inputWasChanged(value, field)"
      />
      <v-text-field
        :ref="field.id"
        v-if="field.type === 'input' && isFieldVisible(field) === true"
        class="custom-text-field"
        v-model="inputs[field.id]"
        :type="field.valueType"
        :step="field.step ? field.step : 0.01"
        :label="getTranslatedText(field.label)"
        :placeholder="
          field.placeholder ? getTranslatedText(field.placeholder) : undefined
        "
        :color="field.color"
        :counter="field.counter"
        filled
        rounded
        dense
        :error-messages="onValidateField(field.id)"
        :autofocus="field.autofocus ? field.autofocus : false"
        :prepend-inner-icon="field.prependIcon ? field.prependIcon : null"
        @input="
          field.id in config.state.v ? config.state.v[field.id].$reset() : null
        "
        @blur="
          field.id in config.state.v ? config.state.v[field.id].$touch() : null
        "
        @change="value => inputWasChanged(value, field)"
      />
      <v-select
        v-if="field.type === 'select'"
        class="custom-text-field"
        v-model="inputs[field.id]"
        :items="field.items"
        :item-text="item => item[field.itemText ? field.itemText : 'text']"
        item-value="id"
        :label="getTranslatedText(field.label)"
        :color="field.color"
        filled
        rounded
        dense
        :error-messages="onValidateField(field.id)"
        :prepend-inner-icon="field.prependIcon ? field.prependIcon : null"
        @input="
          field.id in config.state.v ? config.state.v[field.id].$reset() : null
        "
        @blur="
          field.id in config.state.v ? config.state.v[field.id].$touch() : null
        "
        :ref="`selectInput-${field.id}`"
      />
      <v-checkbox
        :ref="field.id"
        v-if="field.type === 'checkbox'"
        v-model="inputs[field.id]"
        :label="getTranslatedText('starterLayout.signUp.privacy')"
        :class="field.class"
        @click="field.onClick"
      ></v-checkbox>
      <v-radio-group
        v-if="field.type === 'radio' && field.show !== false"
        v-model="inputs[field.id]"
        row
        :mandatory="false"
      >
        <span class="pr-6">
          <FormattedText :value="field.label" color="textPrimary" intl />
        </span>
        <div v-for="option in field.options" :key="option.label">
          <v-radio
            :label="getTranslatedText(option.label)"
            :value="option.value"
            :color="field.color"
          ></v-radio>
        </div>
      </v-radio-group>
      <v-autocomplete
        v-if="field.type === 'autocomplete'"
        class="custom-text-field"
        v-model="inputs[field.id]"
        :items="field.items"
        :item-text="item => item[field.itemText ? field.itemText : 'text']"
        item-value="id"
        :label="getTranslatedText(field.label)"
        :color="field.color"
        filled
        rounded
        dense
        :error-messages="onValidateField(field.id)"
        :prepend-inner-icon="field.prependIcon ? field.prependIcon : null"
        @input="
          field.id in config.state.v ? config.state.v[field.id].$reset() : null
        "
        @blur="
          field.id in config.state.v ? config.state.v[field.id].$touch() : null
        "
      />
    </div>
  </v-form>
</template>

<script>
import { isNil } from 'ramda'

import { removeEmojis } from '@/tools/data'
import { validate } from '@/tools/validations'

import AccountInput from '@/components/shared/AccountInput'
import PasswordInput from '@/components/shared/PasswordInput'
import CountryInputSelector from '@/components/shared/CountryInputSelector'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'Form',
  components: {
    AccountInput,
    PasswordInput,
    CountryInputSelector,
    FormattedText,
  },
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  computed: {
    inputs() {
      return this.config.state.inputs
    },
    errorMessages() {
      let messages = {}
      this.config.fields.forEach(
        field => (messages[field.id] = field.errorMessage)
      )
      return messages
    },
  },
  methods: {
    getTranslatedText: function(translateString) {
      return this.$vuetify.lang.t(`$vuetify.${translateString}`)
    },
    inputWasChanged(value, field) {
      this.limitEmojis(value, field.id)
      if ('changeEvent' in field) {
        field.changeEvent(value, field)
      }
    },
    limitEmojis(value, fieldId) {
      this.inputs[fieldId] = removeEmojis(value)
    },
    onValidateField(idInput) {
      return validate(this.config.state.v, idInput, {
        fn: this.getTranslatedText,
        message: this.errorMessages[idInput],
      })
    },
    isFieldVisible(field) {
      return !isNil(field.visible) ? field.visible : true
    },
  },
}
</script>
