<template>
  <component :is="layout" v-resize="onResize"> </component>
</template>

<script>
import { mapState, mapActions, mapGetters } from 'vuex'

import { testMode } from '@/config/env'
import ROUTER_CHANGES_EVENTS from '@/config/events/routerChanges'
import MLP_API_EVENTS from '@/config/events/databaseAPI/mlpEvents'
import APP_TOOLS_EVENTS from '@/config/events/appTools'
import LICENSE_API_EVENTS from '@/config/events/license'
import HOME_CODES_DB_API_EVENTS from '@/config/events/databaseAPI/byWeightHomeCodesEvents'
import DEVICE_INFO_EVENTS from '@/config/events/deviceInfo'
import PUSH_NOTIFICATIONS_EVENTS from '@/config/events/pushNotifications'
import PUBSUB_EVENTS from '@/config/events/pubsub'
import pushNotificationType from '@/config/pushNotificationType'

import logger from '@/tools/logger'
import { captureException } from '@/tools/exceptions'

import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'
import productsActions from '@/store/products/actions.types'
import accountActions from '@/store/account/actions.types'
import salesViewActions from '@/store/salesView/actions.types'
import customPromotionsActions from '@/store/customPromotions/actions.types'
import salesActions from '@/store/sales/actions.types'

import appSynchronizationTools from '@/app/app.synchronization.tools'
import appPromotionsTools from '@/app/app.customPromotions.tools'
import appPaymentProvidersTools from '@/app/app.paymentProviders.tools'

export default {
  name: 'App',
  computed: {
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
      pendingSyncOps: state => state.pendingSyncOps,
      syncOpsCounter: state => state.syncOpsCounter,
      syncOpsLicenseCounter: state => state.syncOpsLicenseCounter,
      keepMlpUpdating: state => state.keepMlpUpdating,
      isAccountLogged: state => state.isAccountLogged && state.ready,
    }),
    ...mapState('account', { accountData: state => state.data }),
    ...mapState('salesView', {
      paymentProvidersByType: state => state.paymentProvidersByType,
    }),
    ...mapState('customPromotions', {
      lastUpdate: state => state.data.lastUpdate,
      promotions: state => state.data.promotions,
    }),
    ...mapState('usersView', {
      userId: state => state.selectedUser.id,
      selectedUser: state => state.selectedUser,
    }),
    ...mapGetters('customPromotions', [
      'getCustomPromotionsByProduct',
      'getCustomPromotionsByProductAndTypeWithFilters',
    ]),
    layout() {
      return this.$route.meta.layout || 'main-layout'
    },
  },
  methods: {
    ...mapActions('app', [
      appActions.setWindowSize,
      appActions.updateScannerStatus,
      appActions.setPendingSyncOps,
      appActions.setAppSyncing,
      appActions.addPendingSyncOperation,
      appActions.reduceSyncOpsCounter,
      appActions.resetSyncOpsCounter,
      appActions.reduceSyncOpsLicenseCounter,
      appActions.resetSyncOpsLicenseCounter,
      appActions.setAssetsPath,
      appActions.setKeepMlpUpdating,
      appActions.setTTBlockedDialogStatus,
      appActions.setAppIdentifiers,
    ]),
    ...mapActions('products', [
      productsActions.updateProductByProperties,
      productsActions.setByWeightTree,
    ]),
    ...mapActions('account', [accountActions.setSecurityData]),
    ...mapActions('salesView', [salesViewActions.setPaymentProvidersByType]),
    ...mapActions('customPromotions', [
      customPromotionsActions.addCustomPromotions,
      customPromotionsActions.addLastUpdate,
      customPromotionsActions.disableCustomPromotion,
      customPromotionsActions.deleteCustomPromotion,
      customPromotionsActions.bulkCustomPromotionsDeletion,
    ]),
    ...mapActions('sales', [salesActions.removeProductFromAllSales]),
    onResize() {
      this[appActions.setWindowSize]({
        x: window.innerWidth,
        y: window.innerHeight,
      })
    },
    checkDownloadService() {
      this[appActions.reduceSyncOpsCounter]()
      if (this.syncOpsCounter < 1 || this.keepMlpUpdating === true) {
        rendererEventsService.send(MLP_API_EVENTS.channel, {
          event: MLP_API_EVENTS.events.downloadMlpUpdatesIfNeeded.name,
          data: {
            country: this.accountData.country.phoneCode,
            device: this.accountData.device,
            operator: this.accountData.operator,
            securityData: this.accountData.security,
          },
        })
      }
      if (this.syncOpsCounter < 1) {
        appSynchronizationTools.updateDeviceIp.call(this)
      }
    },
    checkLicenseService() {
      this[appActions.reduceSyncOpsLicenseCounter]()
      if (this.syncOpsLicenseCounter < 1) {
        rendererEventsService.send(LICENSE_API_EVENTS.channel, {
          event: LICENSE_API_EVENTS.events.checkExpiration.name,
          data: {
            pos: this.accountData.pos,
          },
        })
      }
    },
    processPushNotificationListener(event, payload) {
      const events = PUSH_NOTIFICATIONS_EVENTS.events
      const replies = {
        [events.processPushNotification.replies.success]: () => {
          if (
            payload.data.pushNotificationType == pushNotificationType.BLOCK_TT
          )
            this[appActions.setTTBlockedDialogStatus](true)
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  watch: {
    $route: function(to) {
      rendererEventsService.send(ROUTER_CHANGES_EVENTS.channel, {
        event: ROUTER_CHANGES_EVENTS.events.routeChange,
        route: to.name,
        user: this.selectedUser,
      })
      if ('sync' in to.meta && to.meta.sync === true) {
        if (this.pendingSyncOps > 0 && navigator.onLine === true) {
          appSynchronizationTools.sendOperations.call(this)
        }
        rendererEventsService.send(LICENSE_API_EVENTS.channel, {
          event: LICENSE_API_EVENTS.events.checkExpiration.name,
          data: {
            pos: this.accountData.pos,
          },
        })
      }
    },
  },
  created() {
    if (testMode) return
    rendererEventsService.send(APP_TOOLS_EVENTS.channel, {
      event: APP_TOOLS_EVENTS.events.getDirPath.name,
      data: { dir: ['assets'] },
    })
    rendererEventsService.subscribe(
      APP_TOOLS_EVENTS.replyChannel,
      async (event, payload) => {
        const events = APP_TOOLS_EVENTS.events
        const replies = {
          [events.getDirPath.replies.success]: () => {
            this[appActions.setAssetsPath](payload.data.path)
          },
          [events.getDirPath.replies.error]: () => {
            logger('error', 'an error ocours getthing dir path')
          },
          [events.setAppIdentifiers.replies.success]: () => {
            this[appActions.setAppIdentifiers](payload.data.idsJson)
            rendererEventsService.send(PUBSUB_EVENTS.channel, {
              event: PUBSUB_EVENTS.events.updatePosInfo.name,
              data: {
                machine_id: payload.data.idsJson.machineId,
                installation_id: payload.data.idsJson.installationId,
                session_id: payload.data.idsJson.sessionId,
                app_version: process.env.VUE_APP_VERSION,
              },
            })
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
    appSynchronizationTools.addListeners.call(this)
    rendererEventsService.subscribe(
      MLP_API_EVENTS.replyChannel,
      (event, payload) => {
        const events = MLP_API_EVENTS.events
        const replies = {
          [events.downloadMlpUpdatesIfNeeded.replies.success]: () => {
            payload.data.productsUpdated.forEach(product =>
              this[productsActions.updateProductByProperties](product)
            )
            this[appActions.setKeepMlpUpdating](payload.data.keepUpdating)
            this[appActions.resetSyncOpsCounter]()
            this.$root.$emit('mlpWasUpdated')
          },
          [events.downloadMlpUpdatesIfNeeded.replies.error]: () => {
            this[appActions.setKeepMlpUpdating](false)
            this[appActions.resetSyncOpsCounter]()
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
    rendererEventsService.subscribe(
      LICENSE_API_EVENTS.replyChannel,
      (event, payload) => {
        const events = LICENSE_API_EVENTS.events
        const replies = {
          [events.checkExpiration.replies.success]: () => {
            this[appActions.resetSyncOpsLicenseCounter]()
          },
          [events.checkExpiration.replies.error]: () => {
            this.$router
              .push({ path: '/app/blocked', query: payload.data })
              .catch(error => captureException(error))
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
    rendererEventsService.subscribe(
      HOME_CODES_DB_API_EVENTS.replyChannel,
      (event, payload) => {
        const events = HOME_CODES_DB_API_EVENTS.events
        const replies = {
          [events.downloadHomesUpdatesIfNeeded.replies.success]: () => {
            if (payload.data.updateStore)
              this[productsActions.setByWeightTree](payload.data.byWeightTree)
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
    rendererEventsService.subscribe(
      DEVICE_INFO_EVENTS.replyChannel,
      (event, payload) => {
        const events = DEVICE_INFO_EVENTS.events
        const replies = {
          [events.checkIfTTIsBlocked.replies.blocked]: () => {
            this[appActions.setTTBlockedDialogStatus](true)
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
    rendererEventsService.subscribe(
      PUSH_NOTIFICATIONS_EVENTS.replyChannel,
      this.processPushNotificationListener
    )
    appPaymentProvidersTools.addListeners.call(this)
    appPromotionsTools.addListeners.call(this)
    rendererEventsService.send(APP_TOOLS_EVENTS.channel, {
      event: APP_TOOLS_EVENTS.events.setAppIdentifiers.name,
    })
  },
  beforeMount() {
    this.$root.$on('sendOpsToSync', notifications =>
      appSynchronizationTools.sendOperations.call(this, notifications)
    )
    this.$root.$on(
      'getPaymentProviders',
      appPaymentProvidersTools.getPaymentProviders
    )
    this.$root.$on('productWasEdited', productId =>
      appPromotionsTools.deactivationPromotion.call(this, productId)
    )
    this.$root.$on('productWasDeleted', data =>
      appPromotionsTools.deletePromotion.call(this, data)
    )
    this.$root.$on('productChangedUnitMeasure', data =>
      appPromotionsTools.deletePromotion.call(this, data)
    )
    this.$root.$on('productsWereBulkDeleted', productsIds =>
      appPromotionsTools.deleteBulkPromotions.call(this, productsIds)
    )
  },
  mounted() {
    if (this.$route.path === '/' && !this.$route.name) {
      this.$router.replace({ name: 'Starter' })
    }
    logger('info', 'App running')
    rendererEventsService.subscribe('database-notification', (event, message) =>
      logger('info', `[${message.code}] ${message.message}`)
    )
    rendererEventsService.subscribe('menu-channel', (channel, arg) => {
      switch (arg) {
        case 'open-preferences':
          this.$route.name !== 'Preferences'
            ? this.$router
                .push({ path: '/app/preferences' })
                .catch(error => captureException(error))
            : null
          break
        case 'open-helpCenter':
          this.$route.name !== 'HelpCenter'
            ? this.$router
                .push({ path: '/app/helpCenter' })
                .catch(error => captureException(error))
            : null
          break
        case 'open-sales':
          this.$route.name !== 'Sales'
            ? this.$router
                .push({ path: '/app/sales' })
                .catch(error => captureException(error))
            : null
          break
        case 'open-products':
          this.$route.name !== 'Products'
            ? this.$router
                .push({ path: '/app/products' })
                .catch(error => captureException(error))
            : null
          break
        case 'open-customers':
          this.$route.name !== 'Customers'
            ? this.$router
                .push({ path: '/app/customers' })
                .catch(error => captureException(error))
            : null
          break
        case 'open-operations':
          this.$route.name !== 'Operations'
            ? this.$router
                .push({ path: '/app/operations' })
                .catch(error => captureException(error))
            : null
          break
      }
    })
    appPromotionsTools.loadPromotions.call(this)
  },
  updated() {
    this.$root.$emit('appComponentWasUpdated')
    appPromotionsTools.loadPromotions.call(this)
  },
  beforeDestroy() {
    this.$root.$off('sendOpsToSync')
    this.$root.$off('getPaymentProviders')
    this.$root.$off('productWasEdited')
    this.$root.$off('productWasDeleted')
    this.$root.$off('productChangedUnitMeasure')
    this.$root.$off('productsWereBulkDeleted')
    rendererEventsService.removeAllListeners(MLP_API_EVENTS.replyChannel)
    rendererEventsService.removeAllListeners(LICENSE_API_EVENTS.replyChannel)
    rendererEventsService.removeAllListeners(DEVICE_INFO_EVENTS.replyChannel)
    rendererEventsService.removeAllListeners(
      PUSH_NOTIFICATIONS_EVENTS.replyChannel
    )
    rendererEventsService.removeListener(
      PUSH_NOTIFICATIONS_EVENTS.replyChannel,
      this.processPushNotificationListener
    )
    appSynchronizationTools.removeListeners()
    appPaymentProvidersTools.removeListeners()
    appPromotionsTools.removeListeners()
  },
}
</script>
