import { idOperations } from '@/config/cashOperationsVariables'
import paymentMethods from '@/config/paymentMethods'
import { promotions } from '@/config/promotions'

import { comboPromotion } from '@/tools/customPromotions'
import productsTools from '@/tools/products'
import { discountTypes, getPercentFromAmount } from '@/tools/promotions'

const checkIfProductsExistInCurrentSale = (currentSaleProducts, product) =>
  !!product && currentSaleProducts.some(item => item.id === product.id)

const getProductPrice = (sale, product) => {
  if (isOwnerSale(sale.payOption)) {
    return getProductCost(product)
  }
  if (product.promotionTypeId === promotions.SALE_ITEM_FREE_PRODUCT) {
    return 0
  }
  if (hasProductTicketAtCostApplied(sale, product)) {
    return getProductCost(product)
  }
  if (product.promotions && product.promotions.length > 0) {
    return getProductPriceWithMoreForLessPromo(product)
  }
  return product.unitPrice
}

const isOwnerSale = payOption => {
  return (
    paymentMethods.isOwnerSale(payOption) ||
    payOption === idOperations.ID_OPERATION_OWNER_SALE
  )
}

const getProductCost = product => {
  if (product.isGeneric) return product.unitPrice || product.price
  if (product.openProductType === 1 && product.factor > 0) {
    return Number((product.cost / product.factor).toFixed(0))
  }
  return product.cost
}

const hasProductTicketAtCostApplied = (sale, product) => {
  return (
    (sale.promotionTicketId === promotions.SALE_TICKET_AT_COST ||
      product.promotionTypeId === promotions.SALE_TICKET_AT_COST) &&
    product.cost > 0 &&
    product.isGeneric !== 1
  )
}

const canApplyTicketAtCost = (promotionTicketId, product) => {
  return (
    isTicketAtCostApplied(promotionTicketId) &&
    product.cost > 0 &&
    product.isGeneric !== 1
  )
}

const isTicketAtCostApplied = promotionTicketId => {
  return promotionTicketId === promotions.SALE_TICKET_AT_COST
}

const getProductPriceWithMoreForLessPromo = (
  product,
  priceKey = 'unitPrice'
) => {
  const { quantity, total } = product.promotions.reduce(
    (result, promo) => {
      result.quantity += promo.quantity
      result.total += promo.total
      return result
    },
    { quantity: 0, total: 0 }
  )
  const quantityRemainder = product.quantity - quantity
  const totalRemainderProducts = product[priceKey] * quantityRemainder
  return Number(
    ((totalRemainderProducts + total) / product.quantity).toFixed(0)
  )
}

const getTotalPriceAndItemsWithCombos = (sale, salePrice, productsStored) => {
  let totalPrice = 0
  let items = []
  const combosByProduct = getCombosInfoByProducts(sale.promotions)
  totalPrice += getTotalPriceAndAddItemsFromSale(
    items,
    combosByProduct,
    sale,
    salePrice
  )
  totalPrice += getTotalPriceAndAddItemsFromCombos(
    items,
    sale,
    combosByProduct,
    salePrice,
    productsStored
  )
  return { items, totalPrice: Number(totalPrice.toFixed(0)) }
}

const getCombosInfoByProducts = combos => {
  return combos.reduce((result, combo) => {
    comboPromotion.getProductsKey().forEach(key => {
      if (!result[combo.promotions[key].id]) {
        result[combo.promotions[key].id] = {
          quantity: 0,
          total: 0,
          product: {},
        }
      }
      result[combo.promotions[key].id].quantity += combo.quantity
      result[combo.promotions[key].id].total +=
        combo.promotions[`${key}PromoUnitPrice`] * combo.quantity
      result[combo.promotions[key].id].product = combo.promotions[key]
    })
    return result
  }, {})
}

const getTotalPriceAndAddItemsFromSale = (
  products,
  combosByProduct,
  sale,
  salePrice
) => {
  let totalPrice = 0
  sale.items.forEach(item => {
    let quantity = item.quantity
    if (combosByProduct[item.id]) {
      quantity += combosByProduct[item.id].quantity
    }
    const unitPrice = getPriceWithPromotions(
      sale,
      salePrice,
      item,
      combosByProduct
    )
    const { promotionTypeId, promotionExtra } = getPromotionTypeAndExtra(
      item,
      sale,
      combosByProduct[item.id]
    )
    products.push({
      ...item,
      unitPrice,
      quantity,
      promotionTypeId,
      promotionExtra,
      priceWithoutPromotion: item.unitPrice,
    })
    totalPrice +=
      item.isGramaje === 1
        ? unitPrice * (quantity / 1000)
        : unitPrice * quantity
    delete combosByProduct[item.id]
  })
  return totalPrice
}

const getPriceWithPromotions = (sale, salePrice, product, combosByProduct) => {
  if (isOwnerSale(sale.payOption)) return product.unitPrice
  let unitPrice = getProductPrice(sale, product)
  if (combosByProduct[product.id] && combosByProduct[product.id].total > 0) {
    unitPrice = Number(
      (
        (unitPrice * product.quantity + combosByProduct[product.id].total) /
        (product.quantity + combosByProduct[product.id].quantity)
      ).toFixed(0)
    )
  }
  if (sale.promotion === 0) return unitPrice
  return getPriceWithTicketDiscount(sale, salePrice, unitPrice)
}

const getPromotionTypeAndExtra = (product, sale, productCombos) => {
  if (paymentMethods.isOwnerSale(sale.payOption)) {
    return {
      promotionTypeId: promotions.NONE,
      promotionExtra: 0,
    }
  }
  if (productCombos) {
    return {
      promotionTypeId: promotions.SALE_ITEM_COMBO,
      promotionExtra: product.unitPrice,
    }
  }
  if (product.promotions && product.promotions.length > 0) {
    return {
      promotionTypeId: promotions.SALE_ITEM_MORE_FOR_LESS,
      promotionExtra: product.promotions[0].promotionId,
    }
  }
  if (product.promotionTypeId === promotions.SALE_ITEM_FREE_PRODUCT) {
    return {
      promotionTypeId: promotions.SALE_ITEM_FREE_PRODUCT,
      promotionExtra: product.unitPrice,
    }
  }
  if (sale.promotionTicketId === promotions.SALE_TICKET_AT_COST) {
    return {
      promotionTypeId: promotions.SALE_TICKET_AT_COST,
      promotionExtra: productCanApplyTicketAtCost(product)
        ? product.unitPrice
        : 0,
    }
  }
  if (product.promotionTypeId !== promotions.NONE) {
    return {
      promotionTypeId: product.promotionTypeId,
      promotionExtra: 0,
    }
  }
  return {
    promotionTypeId:
      sale.promotionTicketId !== 0 ? sale.promotionTicketId : promotions.NONE,
    promotionExtra: 0,
  }
}

const productCanApplyTicketAtCost = item => {
  return item.isGeneric !== 1 && item.cost && item.cost > 0
}

const getTotalPriceAndAddItemsFromCombos = (
  products,
  sale,
  combosByProduct,
  salePrice,
  productsStored
) => {
  let totalPrice = 0
  Object.keys(combosByProduct).forEach(productId => {
    const product = productsTools.getProductForSale(
      {
        ...combosByProduct[productId].product,
        factorSalesBy: combosByProduct[productId].product.factor > 0 ? 0 : 2,
      },
      productsStored
    )
    product.promotions = []
    product.quantity = combosByProduct[productId].quantity
    product.priceWithoutPromotion = product.unitPrice
    product.unitPrice = getPriceWithTicketDiscount(
      sale,
      salePrice,
      Number((combosByProduct[productId].total / product.quantity).toFixed(0))
    )
    product.promotionTypeId = promotions.SALE_ITEM_COMBO
    product.promotionExtra = combosByProduct[productId].product.price
    products.push(product)
    totalPrice += product.unitPrice * product.quantity
  })
  return totalPrice
}

const getPriceWithTicketDiscount = (sale, salePrice, unitPrice) => {
  const { promotion, promotion_type } = sale
  let percentToDiscount = promotion
  if (discountTypes.isDiscountPerAmount(promotion_type)) {
    percentToDiscount = getPercentFromAmount(promotion, salePrice)
  }
  return unitPrice - Number(((unitPrice * percentToDiscount) / 100).toFixed(0))
}

export default {
  getProductPrice,
  checkIfProductsExistInCurrentSale,
  isOwnerSale,
  getProductCost,
  canApplyTicketAtCost,
  isTicketAtCostApplied,
  getProductPriceWithMoreForLessPromo,
  getTotalPriceAndItemsWithCombos,
}
