const config = (state, methods) => {
  return {
    state,
    methods,
    groupClass: 'pr-4',
    groups: [
      {
        id: 'filters-group-01',
        controls: [
          {
            id: 'search-control',
            type: 'input',
            class: 'pr-4',
            label: 'helpCenterView.toolbar.searchField.label',
            placeholder: 'helpCenterView.toolbar.searchField.placeholder',
            icon: 'mdi-magnify',
            backgroundColor: 'cardBackgroundSecondary',
            color: 'primary',
            ref: 'helpCenter-input-search',
            group: 'search',
            onChange: value => methods.setSearchTerm(value),
          },
        ],
      },
      {
        id: 'filters-group-02',
        controls: [
          {
            id: 'videoType-select-control',
            type: 'select',
            label: 'helpCenterView.toolbar.selectVideoTypeField.label',
            valueSelected: state.filters.videoTypes,
            stringValueSelected:
              'helpCenterView.toolbar.selectVideoTypeField.typeSelected',
            backgroundColor: 'cardBackgroundSecondary',
            width: 250,
            items: state.data.videoTypes,
            itemValue: 'value',
            rawText: true,
            onChange: data => {
              methods.setSelectedVideoTypes(data)
            },
            onClick: () => {},
          },
        ],
      },
      {
        id: 'filters-group-03',
        controls: [
          {
            id: 'clear-button-control',
            type: 'button',
            label: 'productsView.toolbar.buttons.clear',
            icon: 'mdi-close-circle',
            group: 'clear',
            color: 'accent',
            onClick: (resetSelector, resetSearchTerm) => {
              methods.setSearchTerm(null)
              methods.setSelectedVideoTypes([])
              resetSelector()
              resetSearchTerm(null)
            },
          },
        ],
      },
    ],
  }
}

export default config
