// TODO; Convert to service or move to tools folder
import Vue from 'vue'

import OpenFolderToast from '@/components/shared/OpenFolderToast'

export default {
  showDefault: function(message, intl, options = {}) {
    Vue.$toast(intl ? intl.t(`$vuetify.${message}`) : message, options)
  },
  showInfo: (message, intl, options = {}, extraMsgValues = []) =>
    Vue.$toast.info(
      intl
        ? extraMsgValues
          ? intl.t(`$vuetify.${message}`, ...extraMsgValues)
          : intl.t(`$vuetify.${message}`)
        : message,
      options
    ),
  showSuccess: (message, intl, options = {}, extraMsgValues = []) => {
    Vue.$toast.success(
      intl
        ? extraMsgValues
          ? intl.t(`$vuetify.${message}`, ...extraMsgValues)
          : intl.t(`$vuetify.${message}`)
        : message,
      options
    )
  },
  showError: (message, intl, options = {}, extraMsgValues = []) =>
    Vue.$toast.error(
      intl
        ? extraMsgValues
          ? intl.t(`$vuetify.${message}`, ...extraMsgValues)
          : intl.t(`$vuetify.${message}`)
        : message,
      options
    ),
  showWarning: (message, intl, options = {}, extraMsgValues = []) =>
    Vue.$toast.warning(
      intl
        ? extraMsgValues
          ? intl.t(`$vuetify.${message}`, ...extraMsgValues)
          : intl.t(`$vuetify.${message}`)
        : message,
      options
    ),
  showOpenFolder: (
    filePath,
    message,
    intl,
    options = {},
    extraMsgValues = []
  ) => {
    const messageFormatted = intl
      ? extraMsgValues
        ? intl.t(`$vuetify.${message}`, ...extraMsgValues)
        : intl.t(`$vuetify.${message}`)
      : message
    return Vue.$toast.info(
      {
        component: OpenFolderToast,
        props: {
          filePath,
          message: messageFormatted,
          tooltipText: intl.t('$vuetify.shared.openFolder'),
        },
      },
      options
    )
  },
}
