import { isNil } from 'ramda'

import {
  captureException as captureExceptionToSentry,
  captureMessage as captureMessageToSentry,
} from '@sentry/electron'

import logger from '@/tools/logger'

export const captureException = (error, message = null) => {
  if (isNil(error)) return
  captureExceptionToSentry(error)
  if (error.message && isNil(message)) logger('error', error.message)
  if (!isNil(message)) logger('error', message)
}

export const captureMessage = (message, captureContex = undefined) => {
  if (isNil(message)) return
  captureMessageToSentry(message, captureContex)
  logger('error', message)
}
