<template>
  <DialogCard :config="dialogConfig.dialogData" />
</template>

<script>
import { mapActions, mapState } from 'vuex'

import appActions from '@/store/app/actions.types'

import DialogCard from '@/components/shared/DialogCard'
import setConfig from '@/components/ConfirmCancelTourDialog/config'

export default {
  name: 'ConfirmCancelTourDialog',
  components: { DialogCard },
  computed: {
    ...mapState('app', ['confirmCancelTourDialog']),
    dialogConfig() {
      return setConfig(
        {
          isOpen: this.confirmCancelTourDialog.isOpen,
          message: this.confirmCancelTourDialog.tour.options
            .confirmCancelMessage,
        },
        {
          closeDialog: this.closeDialog,
          cancelTour: this.cancelTour,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.setConfirmCancelTourDialogStatus]),
    closeDialog() {
      this[appActions.setConfirmCancelTourDialogStatus]({ isOpen: false })
    },
    cancelTour() {
      this.confirmCancelTourDialog.tour.cancel()
      this.closeDialog()
    },
  },
}
</script>
