import { customer as customerMapper } from '@/config/storeMapper'
import paymentMethods from '@/config/paymentMethods'

import logger from '@/tools/logger'
import { mapStoreObject } from '@/tools/data'

import mutationsTypes from '@/store/customers/mutations.types'
import { updateCustomerSalesData } from '@/store/customers/actions.tools'
import typesSales from '@/store/sales/mutations.types'
import typesCustomersView from '@/store/customersView/mutations.types'

export const setCustomersFetching = ({ commit }, payload) =>
  commit(mutationsTypes.SET_CUSTOMERS_FETCHING, payload)

export const setCustomersError = ({ commit }, payload) =>
  commit(mutationsTypes.SET_CUSTOMERS_ERROR, payload.message)

export const fetchCustomers = async ({ commit, rootState }, data) => {
  // TODO: remember to create a new test suite
  const sales = data.sales
    .filter(item => item.customer_id > -1)
    .sort((a, b) => new Date(b.sale_date) - new Date(a.sale_date))
  const customers = await data.customers.map(item => {
    item = mapStoreObject(item, customerMapper)
    item.debt = item.debt === 0 ? 0 : -item.debt
    return updateCustomerSalesData(sales, item, data.receivables)
  })
  commit(mutationsTypes.SET_CUSTOMERS, customers)
  commit(mutationsTypes.SET_CUSTOMERS_FETCHING, false)
  if (rootState.customersView.customerDetailDialog.customerSelected) {
    const customerUpdated = customers.find(
      customer =>
        customer.id ===
        rootState.customersView.customerDetailDialog.customerSelected.id
    )
    commit(
      `customersView/${typesCustomersView.SET_CUSTOMER_SELECTED}`,
      customerUpdated,
      { root: true }
    )
  }
}

export const createCustomer = ({ commit }, data) => {
  const customer = mapStoreObject(data.customer, customerMapper)
  customer.sales = []
  customer.salesNumber = 0
  customer.unpaidSales = []
  customer.unpaidSalesNumber = 0
  customer.expense = 0
  customer.lastSaleDate = '-'
  commit(mutationsTypes.ADD_CUSTOMER, customer)
  logger('info', 'New customer created')
  return customer
}

export const updateCustomer = ({ commit }, data) => {
  commit(mutationsTypes.UPDATE_CUSTOMER, data)
  logger('info', 'Customer updated')
}

export const editCustomerField = ({ commit }, data) => {
  commit(mutationsTypes.EDIT_CUSTOMER_FIELD, data)
  logger('info', 'Customer updated')
}

export const deleteCustomer = ({ commit, rootState }, data) => {
  commit(mutationsTypes.DELETE_CUSTOMER, data)
  logger('info', 'Customer deleted')
  rootState.sales.sales.forEach((sale, index) => {
    if (sale.customer && sale.customer.id == data) {
      commit(
        `sales/${typesSales.UPDATE_CUSTOMER_SELECTED}`,
        {
          customer: '',
          ticketIndex: index,
        },
        { root: true }
      )
      commit(
        `sales/${typesSales.UPDATE_PAY_OPTION_STATUS}`,
        {
          ticketIndex: index,
          option: paymentMethods.cashKey,
        },
        { root: true }
      )
    }
  })
}

export const settleGeneralDebt = ({ commit, rootState }, data) => {
  commit(mutationsTypes.UPDATE_CUSTOMER, data)
  rootState.sales.sales.forEach((sale, index) => {
    if (sale.customer && sale.customer.id == data.id)
      commit(
        `sales/${typesSales.UPDATE_CUSTOMER_SELECTED}`,
        {
          customer: data,
          ticketIndex: index,
        },
        { root: true }
      )
  })
  logger('info', 'General debt settled')
}

export const settleCreditSale = ({ commit, rootState }, data) => {
  commit(mutationsTypes.UPDATE_CUSTOMER, data)
  rootState.sales.sales.forEach((sale, index) => {
    if (sale.customer && sale.customer.id == data.id)
      commit(
        `sales/${typesSales.UPDATE_CUSTOMER_SELECTED}`,
        {
          customer: data,
          ticketIndex: index,
        },
        { root: true }
      )
  })
  logger('info', 'Credit sale settled')
}
