import { pipe, map, dissoc } from 'ramda'

import types from '@/store/users/mutations.types'

export const getUsers = ({ commit }, payload) => {
  const accountUsers = pipe(map(user => dissoc('selected', user)))(payload)
  commit(types.SET_USERS, accountUsers)
}

export const setUsers = ({ commit }, payload) => {
  commit(types.SET_USERS, payload)
}
export const addUser = ({ commit }, payload) => {
  commit(types.ADD_USER, payload)
}

export const updateUser = ({ commit }, payload) => {
  commit(types.UPDATE_USER, payload)
}

export const deleteUser = ({ commit }, payload) => {
  commit(types.DELETE_USER, payload)
}

export const updateUserPermissions = ({ commit }, payload) => {
  commit(types.UPDATE_USER_PERMISSIONS, payload)
}

export const setConfirmationDeletionDialogStatus = ({ commit }, payload) => {
  commit(types.SET_CONFIRMATION_DELETION_DIALOG_STATUS, payload)
}
