import {
  activeOperations,
  chargeOperations,
  paidOperations,
  neutralOperations,
} from '@/config/cashOperationsVariables'

export const getOperationText = operationId => {
  return activeOperations.find(operation => operation.value == operationId).text
}

export const getOperationIcon = operationId => {
  const operation = activeOperations.find(
    operation => operation.value == operationId
  )
  return { icon: operation.icon, color: operation.color }
}

export const isChargeOperation = operationCode =>
  chargeOperations.includes(operationCode)

export const isPaidOperation = operationCode =>
  paidOperations.includes(operationCode)

export const isNeutralOperation = operationCode =>
  neutralOperations.includes(operationCode)
