const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-book-cancel-outline',
    title: 'starterLayout.confirmDeviceChangeDialog.title',
    messages: ['starterLayout.confirmDeviceChangeDialog.message'],
    persistent: true,
    titleBackground: '#white',
    titleColor: 'textPrimary',
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    height: 270,
    maxWidth: 550,
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.continueRestore(),
  },
})

export default setConfig
