<template>
  <DialogCard :config="dialogConfig.dialogData">
    <FormattedText
      class="pb-4"
      type="text-body-2"
      color="primary"
      intl
      value="preferences.rememberPasswordDialog.secondText"
    />
    <v-otp-input
      v-model="otpValue"
      length="5"
      type="number"
      plain
      @finish="onFinish"
    />
  </DialogCard>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import notificationsService from '@/services/renderer/notifications'

import appActions from '@/store/app/actions.types'

import setConfig from '@/components/OneTimePasswordDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'OneTimePasswordDialog',
  components: { DialogCard, FormattedText },
  data() {
    return {
      otpValue: '',
      remainingAttempts: 3,
      account: null,
    }
  },
  computed: {
    ...mapState('app', ['oneTimePasswordDialog']),
    dialogConfig() {
      return setConfig(
        {
          isOpen: this.oneTimePasswordDialog.isOpen,
        },
        {
          closeDialog: this.cancelAndClose,
          checkCodeAndOpenChangePwDialog: this.checkCodeAndOpenChangePwDialog,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [
      appActions.setOneTimePasswordDialogStatus,
      appActions.setChangePasswordDialogStatus,
    ]),
    cancelAndClose() {
      this[appActions.setOneTimePasswordDialogStatus]({ isOpen: false })
    },
    onFinish(otpValue) {
      this.remainingAttempts--
      if (this.oneTimePasswordDialog.code == otpValue) {
        this.cancelAndClose()
        this[appActions.setChangePasswordDialogStatus]({
          isOpen: true,
          account: this.account,
        })
      } else if (this.remainingAttempts === 0) {
        notificationsService.showError(
          'preferences.rememberPasswordDialog.noAttemptsRemaining',
          this.$vuetify.lang
        )
        this.cancelAndClose()
      } else {
        notificationsService.showError(
          'preferences.rememberPasswordDialog.incorrectCode',
          this.$vuetify.lang
        )
        this.otpValue = ''
        document.getElementsByClassName('otp-field-box--0')[0].focus()
      }
    },
  },
  mounted() {
    document.getElementsByClassName('otp-field-box--0')[0].focus()
    this.account = this.oneTimePasswordDialog.account
  },
}
</script>
