import { promotions } from '@/config/promotions'

import { dayIsTodayOrAfter, dayIsTodayOrBefore } from '@/tools/dates'

const FIRST_PRODUCT_KEY = 'firstProduct'
const SECOND_PRODUCT_KEY = 'secondProduct'

const getProductsKey = () => {
  return [FIRST_PRODUCT_KEY, SECOND_PRODUCT_KEY]
}

const getAnotherKey = key => {
  if (key === FIRST_PRODUCT_KEY) return SECOND_PRODUCT_KEY
  return FIRST_PRODUCT_KEY
}

const getPromotionBySecondProduct = (productPromotions, productId) => {
  return productPromotions.find(promoProd =>
    getProductsKey().some(key => promoProd.promotions[key].id === productId)
  )
}

const getPromotionUnitPrices = (firstProduct, secondProduct, total) => {
  const totalWithoutPromotion = firstProduct.price + secondProduct.price
  const discount = Math.abs((total * 100) / totalWithoutPromotion - 100)
  return {
    firstProductPromoUnitPrice: Math.round(
      firstProduct.price - firstProduct.price * (discount / 100)
    ),
    secondProductPromoUnitPrice: Math.round(
      secondProduct.price - secondProduct.price * (discount / 100)
    ),
  }
}

export const comboPromotion = {
  getProductsKey,
  getPromotionBySecondProduct,
  getAnotherKey,
  getPromotionUnitPrices,
}

const isActive = promotion => {
  if (!promotion.startDate) {
    return promotion.active === 1
  }
  if (!promotion.finishDate) {
    return dayIsTodayOrBefore(promotion.startDate)
  }
  return (
    dayIsTodayOrBefore(promotion.startDate) &&
    dayIsTodayOrAfter(promotion.finishDate)
  )
}

const productPriceWasChanged = (promotion, product) => {
  if (promotion.type === promotions.SALE_ITEM_MORE_FOR_LESS) {
    return promotion.product.price !== product.unitPrice
  }
  return promotion.promotions[FIRST_PRODUCT_KEY].id === product.id
    ? promotion.promotions[FIRST_PRODUCT_KEY].price !== product.unitPrice
    : promotion.promotions[SECOND_PRODUCT_KEY].price !== product.unitPrice
}

const canBeAppliedToProduct = product => {
  return (
    product.isGeneric === 0 &&
    product.isGramaje === 0 &&
    ((product.isOpenProduct === 1 && product.openProductType === 0) ||
      (product.isOpenProduct === 0 && product.openProductType === 2)) &&
    product.promotionTypeId !== promotions.SALE_ITEM_FREE_PRODUCT
  )
}

export const customPromotion = {
  isActive,
  productPriceWasChanged,
  canBeAppliedToProduct,
}
