<template>
  <p class="text-body-1 mt-4">
    {{ getTranslatedText('starterLayout.welcome.termsUse.text') }}
    <a
      @click="showUserTerms"
      v-track:click="{
        category: 'Signup',
        screen: 'TermsAlert',
        name: 'Open terms',
      }"
    >
      {{ getTranslatedText('starterLayout.welcome.termsUse.button') }}
    </a>
  </p>
</template>

<script>
import { mapActions } from 'vuex'

import { getTranslatedText } from '@/tools/data'

import appActions from '@/store/app/actions.types'

export default {
  name: 'TermsAlert',
  methods: {
    ...mapActions('app', [appActions.setTermsDialogStatus]),
    getTranslatedText,
    showUserTerms() {
      this[appActions.setTermsDialogStatus](true)
    },
  },
}
</script>
