<template>
  <v-tooltip bottom>
    <template v-slot:activator="{ on }">
      <v-card
        class="mx-auto"
        flat
        color="mainBackground"
        v-on="on"
        @click="goToEditProfile"
      >
        <v-row no-gutters class="align-center justify-center px-4 pt-4">
          <v-col cols="3">
            <v-img :src="shopImg" height="65" width="65" contain />
          </v-col>
          <v-col cols="9" class="pl-1">
            <FormattedText
              :value="name === '' ? 'shared.myStore' : name"
              :intl="name === ''"
              type="text-subtitle-1"
              class="store-name"
              className="font-weight-bold text-height"
              color="textPrimary"
              shorter
              :shorterValue="'18'"
            />
            <v-rating
              length="3"
              dense
              hover
              v-model="rating"
              size="18"
              half-increments
              readonly
              color="primary"
              icon-label="stars"
              class="stars"
            />
          </v-col>
        </v-row>
        <v-row no-gutters class="align-center justify-center px-4 mb-4">
          <FormattedText
            :value="performanceRatingMessage"
            intl
            type="text-caption"
          />
        </v-row>
      </v-card>
    </template>
    <FormattedText value="preferences.profile.editProfile" intl color="white" />
  </v-tooltip>
</template>

<script>
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'UserProfileCard',
  components: { FormattedText },
  props: {
    name: {
      type: String,
      default: '',
    },
    role: {
      type: String,
      required: true,
    },
    rating: {
      type: Number,
      default: 0,
    },
    avatar: {
      type: String,
      default: '',
    },
  },
  computed: {
    shopImg() {
      if (this.avatar.length === 0) return require('@/assets/default_shop.png')
      return `data:image/jpg;base64,${this.avatar}`
    },
    performanceRatingMessage() {
      if (0.0 < this.rating && this.rating < 1.5) {
        return 'mainLayout.profileCard.lowSalesStarsMessage'
      } else if (1.5 <= this.rating && this.rating < 2.0) {
        return 'mainLayout.profileCard.mediumSalesStarsMessage'
      } else if (2.0 <= this.rating && this.rating < 2.5) {
        return 'mainLayout.profileCard.highSalesStarsMessage'
      } else if (this.rating >= 2.5) {
        return 'mainLayout.profileCard.fullSalesStarsMessage'
      } else {
        return 'mainLayout.profileCard.noSalesStarsMessage'
      }
    },
  },
  methods: {
    goToEditProfile() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'NavigationMenu',
        name: 'Go to preferences',
      })
      if (this.$route.path === '/app/preferences') return
      this.$router
        .push({ path: '/app/preferences', query: { tab: 'profile' } })
        .catch()
    },
  },
}
</script>

<style lang="scss" scoped>
.store-name {
  padding-left: 2px;
  :deep(.text-height) {
    line-height: 1rem !important;
  }
}
.stars {
  margin-top: -0.3rem;
}
:deep(.v-rating--dense .v-icon) {
  padding: 0;
}
</style>
