<template>
  <v-alert
    v-if="!isAppOnline"
    icon="mdi-cloud-off-outline"
    dense
    text
    color="error"
    class="mt-4 error-connection__alert"
  >
    <span v-html="getTranslatedText('shared.connectionAlert')" />
  </v-alert>
  <div class="d-flex" v-else>
    <FormattedText
      intl
      value="mainLayout.header.needScanner"
      color="textPrimary"
    />
    <a :href="openGetScannerWeb" target="_blank">
      <FormattedText
        class="pl-1"
        intl
        value="mainLayout.header.getScanner"
        color="textPrimary"
      />
    </a>
  </div>
</template>

<script>
import { mapState } from 'vuex'

import buyYourScannerUrls from '@/config/buyYourScannerUrls'

import { getTranslatedText } from '@/tools/data'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'InfoBannerMenu',
  components: { FormattedText },
  props: {
    isAppOnline: {
      type: Boolean,
      required: true,
    },
  },
  computed: {
    ...mapState('account', {
      country: state => state.data.country,
    }),
    openGetScannerWeb() {
      const countryCode = this.country.localeIsoCode
      return buyYourScannerUrls &&
        Object.hasOwn(buyYourScannerUrls, countryCode)
        ? buyYourScannerUrls[countryCode]
        : buyYourScannerUrls['default']
    },
  },
  methods: {
    getTranslatedText,
  },
}
</script>

<style scoped lang="scss">
.error-connection {
  &__alert {
    animation: shake-alert 0.82s cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
    transform: translate(0, 0);
  }
  &__icon {
    animation: shake-icon 15s cubic-bezier(0.36, 0.07, 0.19, 0.97) infinite;
    transform: translate(0, 0);
  }
}

@keyframes shake-alert {
  10%,
  90% {
    transform: translate(-1px, 0);
  }
  20%,
  80% {
    transform: translate(2px, 0);
  }
  30%,
  50%,
  70% {
    transform: translate(-4px, 0);
  }
  40%,
  60% {
    transform: translate(4px, 0);
  }
}
@keyframes shake-icon {
  0%,
  5.4666%,
  100% {
    transform: translate(0, 0);
  }
  0.54666%,
  4.91994% {
    transform: translate(-1px, 0);
  }
  1.09332%,
  4.37328% {
    transform: translate(2px, 0);
  }
  1.63998%,
  2.7333%,
  3.82662% {
    transform: translate(-4px, 0);
  }
  2.18664%,
  3.27996% {
    transform: translate(4px, 0);
  }
}
</style>
