import { required, decimal, maxLength } from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: state.type === 'moneyIn' ? 'mdi-cash-plus' : 'mdi-cash-minus',
    title:
      state.type === 'moneyIn'
        ? 'mainLayout.user.moneyIn'
        : 'mainLayout.user.moneyOut',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    messages: [
      state.type === 'moneyIn'
        ? 'mainLayout.user.moneyInDialogMessage'
        : 'mainLayout.user.moneyOutDialogMessage',
    ],
    height: 360,
    maxWidth: 500,
    id: 'add-cash-movement-amount-form',
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.addCashMovement(),
  },
  fields: [
    {
      id: 'amount',
      type: 'input',
      valueType: 'number',
      label: 'shared.amount',
      errorMessage: 'mainLayout.user.errorAmount',
      color: 'primaryColor',
      required: true,
      autofocus: true,
      validators: { required, decimal },
    },
    {
      id: 'concept',
      type: 'input',
      valueType: 'text',
      label: 'shared.concept',
      errorMessage: 'mainLayout.user.errorConcept',
      color: 'primaryColor',
      validators: { maxLength: maxLength(50) },
    },
  ],
  id: 'add-cash-movement-amount-form',
})

export default setConfig
