import Vue from 'vue'
import { isNil } from 'ramda'
import * as Sentry from '@sentry/electron'
import * as SentryIntegrations from '@sentry/integrations'

import { sentryDSN } from '@/config/env'

export const ElectronCrashReporter = () =>
  Sentry.init({
    dsn: sentryDSN,
    environment: process.env.NODE_ENV,
    release: process.env.VUE_APP_VERSION,
  })

export const VueCrashReporter = () => {
  return Sentry.init({
    dsn: sentryDSN,
    environment: process.env.NODE_ENV,
    integrations: [
      new SentryIntegrations.Vue({
        Vue,
        logErrors: true,
        tracing: false,
      }),
    ],
    release: process.env.VUE_APP_VERSION,
    debug: true,
  })
}

export const setPostDataTag = (pos, osInfo) => {
  const { width, height } = osInfo.resolution
  Sentry.setTag('pos', !isNil(pos) ? pos : 'not found')
  Sentry.setTag('cpu', !isNil(osInfo) ? osInfo.cpuModel : 'not found')
  Sentry.setTag('cores', !isNil(osInfo) ? osInfo.cpuCores : 'not found')
  Sentry.setTag('memory', !isNil(osInfo) ? osInfo.memory : 'not found')
  Sentry.setTag(
    'resolution',
    !isNil(osInfo) ? `${width}x${height}` : 'not found'
  )
}
