import paymentMethods from '@/config/paymentMethods'

import types from './mutations.types'

const setDeleteConfirmationDialogStatus = state => {
  state.deleteConfirmationDialog.isOpen = !state.deleteConfirmationDialog.isOpen
}

const setNotificationDialogStatus = state => {
  state.notificationDialog.isOpen = !state.notificationDialog.isOpen
}

const toggleGenericProductDialogStatus = (state, payload = null) => {
  state.genericProductDialog.isOpen = !state.genericProductDialog.isOpen
  state.genericProductDialog.product = payload
}

const toggleByWeightProductDialogStatus = state => {
  state.byWeightProductDialog.isOpen = !state.byWeightProductDialog.isOpen
}

const toggleProductTriangulationDialogStatus = state => {
  state.productTriangulationDialog.isOpen = !state.productTriangulationDialog
    .isOpen
}

const toggleAirtimeProductDialogStatus = state => {
  state.airtimeProductDialog.isOpen = !state.airtimeProductDialog.isOpen
}

const setCurrentSale = (state, payload) => {
  state.currentSale.saleIndex = payload
}

const setTicketIdToDelete = (state, payload) => {
  state.deleteConfirmationDialog.ticketId = payload
}

const setFinishingSaleStatus = (state, payload) => {
  state.currentSale.isFinished = payload
}

// View mutations
export const toggleDetailDialog = state => {
  state.productDetailDialog.isOpen = !state.productDetailDialog.isOpen
}

export const toggleAddProductDialog = state => {
  state.newProductDialog.isOpen = !state.newProductDialog.isOpen
}

export const setSelectedProduct = (state, payload) => {
  state.selectedProduct = payload
}

export const setSelectedByWeightCategory = (state, payload) => {
  state.selectedByWeightCategory = payload
}

export const updateSelectedProductField = (state, payload) => {
  state.selectedProduct[payload.field] = payload.value
}

export const setViewComponent = (state, payload) => {
  state.component = payload
}

// Filter mutations
export const setSearchTermFilter = (state, payload) => {
  state.filters.searchTerm = payload
}

export const setGroupFilter = (state, payload) => {
  if (state.filters.setGroup !== payload) {
    state.filters.group = payload
  }
}

export const setSelectedSuperCategories = (state, payload) => {
  state.filters.superCategories = payload
}

export const updateCardComponent = (state, payload) => {
  if (
    state.filters.group === 'generics' ||
    state.filters.group === 'air-time'
  ) {
    state.cardComponent = 'ProductImageCard'
    return
  }
  if (state.filters.group === 'byWeight') {
    payload === true
      ? (state.cardComponent = 'ProductImageCard')
      : (state.cardComponent = 'ProductCard')
    return
  }
  state.cardComponent = 'ProductCard'
}

export const setAssignCustomerDialogStatus = (state, payload) => {
  state.assignCustomerDialog.isOpen = payload
}

export const setOverCreditLimitDialogStatus = (state, payload) => {
  state.overCreditLimitDialog.isOpen = payload
}

export const setFinishSaleDialogStatus = (state, payload) => {
  state.finishSaleDialog.isOpen = payload.isOpen
  state.finishSaleDialog.fromPayButton = payload.fromPayButton
}

export const setScanYourProductsDialogStatus = (state, payload) => {
  state.scanYourProductsDialog.isOpen = payload
}

export const setEnrolledCustomer = (state, payload) => {
  state.finishSaleDialog.selectedEnrolledCustomer = payload
}

export const setPrizeWonDialogStatus = (state, payload) => {
  state.prizeWonDialog.isOpen = payload.isOpen
  state.prizeWonDialog.customerName = payload.customerName
}

export const setPaymentProvidersByType = (state, payload) => {
  const paymentProvidersByType = {}
  payload.forEach(provider => {
    const paymentTypeKey = paymentMethods.getPaymentMethodKeyFromId(
      provider.type
    )
    if (paymentTypeKey === paymentMethods.others) return
    if (!paymentProvidersByType[paymentTypeKey]) {
      paymentProvidersByType[paymentTypeKey] = []
    }
    paymentProvidersByType[paymentTypeKey].push({
      id: provider._id,
      label: provider.name,
      value: provider._id,
      type: paymentTypeKey,
      typeId: provider.type,
      commissions: provider.commissions,
    })
  })
  state.paymentProvidersByType = paymentProvidersByType
}

export const updatePaymentProvidersCommission = (state, payload) => {
  const indexFound = state.paymentProvidersByType[payload.type].findIndex(
    provider => provider.id === payload.id
  )
  state.paymentProvidersByType[payload.type][indexFound].commissions =
    payload.commissions
}

export const setRestorePromotionDialogStatus = (state, payload) => {
  state.restorePromotionDialog = payload
}

export const setListProductPromotionsDialogStatus = (state, payload) => {
  state.listProductPromotionsDialog.isOpen = payload.isOpen
  state.listProductPromotionsDialog.product = payload.product || null
}

export const setTourEnabled = (state, payload) => {
  state.tourEnabled = payload
}

export default {
  [types.SET_DELETE_CONFIRMATION_DIALOG_STATUS]: setDeleteConfirmationDialogStatus,
  [types.SET_NOTIFICATION_DIALOG_STATUS]: setNotificationDialogStatus,
  [types.TOGGLE_GENERIC_PRODUCT_DIALOG_STATUS]: toggleGenericProductDialogStatus,
  [types.TOGGLE_BY_WEIGHT_PRODUCT_DIALOG_STATUS]: toggleByWeightProductDialogStatus,
  [types.TOGGLE_PRODUCT_TRIANGULATION_DIALOG_STATUS]: toggleProductTriangulationDialogStatus,
  [types.TOGGLE_AIRTIME_PRODUCT_DIALOG_STATUS]: toggleAirtimeProductDialogStatus,
  [types.SET_CURRENT_SALE]: setCurrentSale,
  [types.SET_TICKET_ID_TO_DELETE]: setTicketIdToDelete,
  [types.SET_SALE_STATUS]: setFinishingSaleStatus,
  [types.SET_DETAIL_DIALOG_STATUS]: toggleDetailDialog,
  [types.SET_NEW_PRODUCT_DIALOG_STATUS]: toggleAddProductDialog,
  [types.SET_SELECTED_PRODUCT]: setSelectedProduct,
  [types.SET_SELECTED_BY_WEIGHT_CATEGORY]: setSelectedByWeightCategory,
  [types.UPDATE_SELECTED_PRODUCT_FIELD]: updateSelectedProductField,
  [types.SET_VIEW_TYPE]: setViewComponent,
  [types.SET_SEARCH_TERM_FILTER]: setSearchTermFilter,
  [types.SET_GROUP_FILTER]: setGroupFilter,
  [types.SET_SUPER_CATEGORIES_FILTER]: setSelectedSuperCategories,
  [types.UPDATE_CARD_COMPONENT]: updateCardComponent,
  [types.SET_ASSIGN_CUSTOMER_DIALOG_STATUS]: setAssignCustomerDialogStatus,
  [types.SET_OVER_CREDIT_LIMIT_DIALOG_STATUS]: setOverCreditLimitDialogStatus,
  [types.SET_FINISH_SALE_DIALOG_STATUS]: setFinishSaleDialogStatus,
  [types.SET_SCAN_YOUR_PRODUCTS_DIALOG_STATUS]: setScanYourProductsDialogStatus,
  [types.SET_ENROLLED_CUSTOMER]: setEnrolledCustomer,
  [types.SET_PRIZE_WON_DIALOG_STATUS]: setPrizeWonDialogStatus,
  [types.SET_PAYMENT_PROVIDERS_BY_TYPE]: setPaymentProvidersByType,
  [types.UPDATE_PAYMENT_PROVIDERS_COMMISSION]: updatePaymentProvidersCommission,
  [types.SET_RESTORE_PROMOTION_DIALOG_STATUS]: setRestorePromotionDialogStatus,
  [types.SET_LIST_PRODUCT_PROMOTIONS_DIALOG_STATUS]: setListProductPromotionsDialogStatus,
  [types.SET_TOUR_ENABLED]: setTourEnabled,
}
