<template>
  <v-alert
    text
    :color="notification.color"
    :icon="notification.icon"
    width="100%"
    outlined
  >
    <h3 class="mt-n1">{{ getTranslatedText(notification.title) }}</h3>
    {{ notification.description | truncate(150) }}
    <div class="text-right mt-2">
      <v-btn
        v-if="notification.buttonDone"
        plain
        small
        :ripple="false"
        :color="notification.buttonDone.color"
        ref="notificationButtonDone"
        @click="notification.buttonDone.click(notification)"
        v-track:click="{
          category: $route.name,
          screen: 'Notifications',
          name: `Mark notification ${notification.type} done`,
        }"
      >
        {{ getTranslatedText(notification.buttonDone.text) }}
      </v-btn>
      <v-btn
        v-if="notification.button"
        class="ml-2"
        outlined
        small
        :ripple="false"
        :color="notification.button.color"
        ref="notificationButtonAction"
        @click="notification.button.click(notification)"
      >
        {{ getTranslatedText(notification.button.text) }}
      </v-btn>
    </div>
  </v-alert>
</template>

<script>
import { getTranslatedText } from '@/tools/data'

export default {
  name: 'NotificationCard',
  props: {
    notification: {
      type: Object,
      required: true,
    },
  },
  methods: { getTranslatedText },
}
</script>
