<template>
  <DialogCard :config="dialogConfig.dialogData">
    <Form :config="dialogConfig" />
  </DialogCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import AUTH_EVENTS from '@/config/events/auth'

import { cleanObjectObserver } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import appActions from '@/store/app/actions.types'

import setConfig from '@/components/ChangePasswordDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import Form from '@/components/shared/Form'

export default {
  name: 'ChangePasswordDialog',
  components: { DialogCard, Form },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
      changingPassword: false,
    }
  },
  computed: {
    ...mapState('app', ['changePasswordDialog']),
    ...mapState('account', ['data']),
    dialogConfig() {
      return setConfig(
        {
          isOpen: this.changePasswordDialog.isOpen,
          inputs: this.inputs,
          v: this.$v.inputs,
          routeName: this.$route.name,
        },
        {
          closeDialog: this.cancelAndClose,
          changePassword: this.changePassword,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.setChangePasswordDialogStatus]),
    setProperties: function() {
      this.dialogConfig.fields.forEach(field => {
        this.$set(this.inputs, field.id, '')
        if (field.validators)
          this.$set(
            this.validators.inputs,
            field.id,
            Array.isArray(field.validators)
              ? field.validators
              : { ...cleanObjectObserver(field.validators) }
          )
      })
    },
    cancelAndClose() {
      Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$reset())
      Object.keys(this.inputs).forEach(key => (this.inputs[key] = ''))
      this[appActions.setChangePasswordDialogStatus]({ isOpen: false })
    },
    changePassword() {
      if (this.changingPassword === true) return
      if (this.$v.inputs.$invalid) {
        Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$touch())
        return
      }
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'ChangePasswordDialog',
        name: 'Submit',
      })
      this.changingPassword = true
      rendererEventsService.send(AUTH_EVENTS.channel, {
        event: AUTH_EVENTS.events.changeAdminPassword.name,
        data: {
          account: this.changePasswordDialog.account,
          passwords: this.inputs,
          localChange: this.data.account.length > 1,
        },
      })
    },
  },
  validations() {
    return this.validators
  },
  async mounted() {
    await this.setProperties()
    rendererEventsService.subscribe(
      AUTH_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [AUTH_EVENTS.events.changeAdminPassword.replies.success]: () => {
            this.$track({
              type: 'system',
              action: 'change_password',
              category: this.$route.name,
              screen: 'ChangePasswordDialog',
              name: 'Close dialog',
            })
            notificationsService.showSuccess(
              'preferences.changePasswordDialog.success',
              this.$vuetify.lang,
              { timeout: 5000 }
            )
            this.changingPassword = false
            this.cancelAndClose()
          },
          [AUTH_EVENTS.events.changeAdminPassword.replies.error]: () => {
            this.$track({
              type: 'system',
              action: 'error',
              category: this.$route.name,
              screen: 'ChangePasswordDialog',
              name: 'Error changing password',
            })
            notificationsService.showError(
              'preferences.changePasswordDialog.error',
              this.$vuetify.lang,
              { timeout: 5000 }
            )
            this.changingPassword = false
            this.cancelAndClose()
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(AUTH_EVENTS.replyChannel)
  },
}
</script>
