<template>
  <div>
    <div
      class="d-inline-flex"
      :class="config.groupClass"
      v-for="group in config.groups"
      :key="group.id"
    >
      <div
        v-for="control in group.controls"
        :key="control.id"
        :id="`${control.ref}-div`"
        @click="
          'onClick' in control && control.type === 'input'
            ? control.onClick(resetSelector)
            : null
        "
      >
        <v-text-field
          :color="control.color || 'primary'"
          v-if="control.type === 'input'"
          v-model="inputs[control.id]"
          class="custom-text-field"
          :class="control.class"
          :style="{ width: `${control.width}px` }"
          filled
          rounded
          clearable
          :id="control.ref"
          :label="getTranslatedText(control.label)"
          :placeholder="getTranslatedText(control.placeholder)"
          :append-icon="control.icon"
          :input="control.onChange(inputs[control.id])"
          v-on:keyup.enter="
            'onEnter' in control ? control.onEnter(inputs[control.id]) : null
          "
          v-track:click="{
            category: $route.name,
            screen: 'ToolBar',
            name: getTrackNameFromId(control.id),
          }"
        ></v-text-field>

        <Button
          v-if="control.type === 'button' && showControl(control)"
          :class="control.class ? control.class : 'pt-2 px-1'"
          tooltipPosition="bottom"
          fab
          dark
          small
          depressed
          :color="control.color || 'buttonPrimary'"
          :icon="control.icon"
          :tooltipText="control.label"
          :btnValue="control.id"
          :id="control.id"
          @click="control.onClick(resetSelector, resetSearchTerm)"
          v-track:click="{
            category: $route.name,
            screen: 'ToolBar',
            name: getTrackNameFromId(control.id),
          }"
        />
        <v-select
          v-if="control.type === 'select'"
          :id="control.id"
          v-model="selectors[control.id]"
          :items="
            'limit' in control
              ? selectors[control.id] &&
                selectors[control.id].length < control.limit
                ? control.items
                : getItemsStructure(config, control)
              : control.items
          "
          :item-text="
            item =>
              control.rawText
                ? item.text
                : getTranslatedText(
                    'group' in control
                      ? `${control.group}.${item.text}`
                      : item.text
                  )
          "
          :item-value="'itemValue' in control ? control.itemValue : 'text'"
          filled
          multiple
          rounded
          class="custom-text-field"
          :style="{ width: `${control.width}px` }"
          :append-icon="control.icon"
          chips
          single-line
          :label="getTranslatedText(`${control.label}`)"
          :menu-props="{ button: true, offsetY: true }"
          @change="control.onChange(selectors[control.id])"
          @click="control.onClick(resetSelector, resetSearchTerm)"
          v-track:click="{
            category: $route.name,
            screen: 'ToolBar',
            name: getTrackNameFromId(control.id),
          }"
        >
          <template v-slot:selection="{ index }">
            <v-chip v-if="index === 0" color="primary" text-color="white">
              <span>
                <b>
                  {{
                    'valuesSelected' in control
                      ? control.valuesSelected.length
                      : selectors[control.id].length
                  }}
                </b>
                {{ getTranslatedText(control.stringValueSelected) }}
              </span>
            </v-chip>
          </template>
        </v-select>
        <v-menu
          v-if="control.type === 'dateRange'"
          :ref="control.ref"
          v-model="dateRanges[control.id]"
          :close-on-content-click="false"
          :return-value.sync="inputs[control.id]"
          :color="control.color || 'primary'"
          transition="scale-transition"
          offset-y
          min-width="auto"
          @input="trackEvent(getTrackNameFromId(control.id))"
        >
          <template v-slot:activator="{ on, attrs }">
            <v-text-field
              :value="formatDateRange(control.value)"
              :label="getTranslatedText(control.label)"
              :append-icon="control.icon"
              readonly
              class="custom-text-field"
              :style="{ width: `${control.width}px` }"
              filled
              rounded
              v-bind="attrs"
              v-on="on"
            />
          </template>
          <v-date-picker
            v-model="inputs[control.id]"
            no-title
            range
            :first-day-of-week="1"
            :locale="datePickerLocale"
          >
            <v-spacer />
            <v-btn text color="primary" @click="dateRanges[control.id] = false">
              {{ getTranslatedText('shared.cancel') }}
            </v-btn>
            <v-btn text color="primary" @click="confirmDatePick(control)">
              {{ getTranslatedText('shared.accept') }}
            </v-btn>
          </v-date-picker>
        </v-menu>
        <ButtonDropdown
          fab
          depressed
          small
          dark
          v-if="control.type === 'buttonDropdown'"
          :class="control.class ? control.class : 'pt-2 px-1'"
          :color="control.color"
          :textColor="control.textColor"
          :icon="control.icon"
          :tooltipText="control.label"
          :btnValue="control.id"
          :id="control.id"
          :items="control.items"
          :listItemType="control.listItemType"
        />
        <PopoverMenu
          v-if="control.type === 'popoverMenu'"
          fab
          depressed
          small
          dark
          :class="control.class ? control.class : 'pt-2 px-1'"
          :color="control.color"
          :textColor="control.textColor"
          :icon="control.icon"
          :tooltipText="control.label"
          :btnValue="control.id"
          :id="control.id"
          :url="control.url"
          @click="control.onClick"
          :disabled="control.disabled"
          v-track:click="{
            category: $route.name,
            screen: 'ToolBar',
            name: getTrackNameFromId(control.id),
          }"
        />
      </div>
    </div>
  </div>
</template>

<script>
import { mapState } from 'vuex'
import { isEmpty, isNil } from 'ramda'

import { formatDate } from '@/tools/dates'

import Button from '@/components/shared/CustomButton'
import ButtonDropdown from '@/components/shared/ButtonDropdown'
import PopoverMenu from '@/components/shared/PopoverMenu'

export default {
  name: 'ToolBar',
  components: {
    Button,
    ButtonDropdown,
    PopoverMenu,
  },
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      selectors: {},
      inputs: {},
      dateRanges: {},
    }
  },
  computed: {
    ...mapState('account', ['data']),
    datePickerLocale() {
      return `${this.data.country.language}-${this.data.country.localeIsoCode}`
    },
  },
  methods: {
    showControl: function(control) {
      return isNil(control.show) ? true : control.show
    },
    getTranslatedText: function(translateString) {
      return this.$vuetify.lang.t(`$vuetify.${translateString}`)
    },
    setSelectProperties: function() {
      this.config.groups.forEach(group => {
        group.controls.forEach(control => {
          if (control.type === 'select') {
            this.$set(this.selectors, control.id, [])
          } else if (control.type === 'input') {
            this.$set(this.inputs, control.id, null)
          } else if (control.type === 'dateRange') {
            this.$set(this.dateRanges, control.id, false)
            this.$set(this.inputs, control.id, null)
          }
        })
      })
    },
    formatDateRange(input) {
      if (input === null || input === undefined || isEmpty(input)) return input
      if (input.length === 1 || input[0] === input[1])
        return formatDate(input[0])
      const fromDate = formatDate(input[input[0] < input[1] ? 0 : 1])
      const toDate = formatDate(input[input[0] < input[1] ? 1 : 0])
      return `${this.getTranslatedText(
        'operationsView.listView.from'
      )} ${fromDate} ${this.getTranslatedText(
        'operationsView.listView.to'
      )} ${toDate}`
    },
    resetSelector: function() {
      Object.keys(this.selectors).forEach(key => (this.selectors[key] = []))
    },
    resetSearchTerm: function() {
      Object.keys(this.inputs).forEach(key => (this.inputs[key] = null))
    },
    setSelectValue: function(item) {
      return { id: item.id, text: item.text }
    },
    confirmDatePick: function(control) {
      control.onChange(this.inputs[control.id])
      this.dateRanges[control.id] = false
    },
    getItemsStructure(config, control) {
      return config.state.filters.superCategories.map(category => {
        const item = control.items.find(item => item.text === category)
        return {
          id: item ? item.id : 0,
          text: category,
        }
      })
    },
    trackEvent(name) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'ToolBar',
        name,
      })
    },
    getTrackNameFromId(id) {
      return id
        .split('-')
        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
        .join(' ')
    },
  },
  created() {
    this.setSelectProperties()
  },
  mounted() {
    this.$root.$on('reset', () => {
      this.resetSelector()
      this.resetSearchTerm()
    })
    this.$root.$on(
      'default-value',
      ({ input, value }) => (this.inputs[input] = value)
    )
  },
}
</script>
