import {
  find,
  findIndex,
  hasPath,
  isNil,
  map,
  pipe,
  propEq,
  toPairs,
  whereEq,
} from 'ramda'

import types from '@/store/purchasesView/mutations.types'

export const setSearchTermFilter = (state, payload) => {
  state.filters.searchTerm = payload
}

export const setGroupFilter = (state, payload) => {
  if (state.filters.setGroup !== payload) {
    state.filters.group = payload
  }
}

export const setSelectedSuperCategories = (state, payload) => {
  state.filters.superCategories = payload
}

export const setSelectedProduct = (state, payload) => {
  state.selectedProduct = payload
}

export const setUnitCostInSelectedProduct = (state, unitCost) => {
  if (!state.selectedProduct || !unitCost) {
    return
  }
  state.selectedProduct.product.cost = unitCost
  state.selectedProduct.product.costWithoutTaxAndPromotion = unitCost
}

export const setViewComponent = (state, payload) => {
  state.component = payload
}

export const updateCardComponent = (state, payload) => {
  if (state.filters.group === 'generics') {
    state.cardComponent = 'ProductImageCard'
    return
  }
  if (state.filters.group === 'byWeight') {
    payload === true
      ? (state.cardComponent = 'ProductImageCard')
      : (state.cardComponent = 'ProductCard')
    return
  }
  state.cardComponent = 'ProductCard'
}

export const setSelectedPurchase = (
  state,
  payload = {
    _id: -1,
    cost: 0,
    vendor_id: -1,
    creation_date: '',
    delivery_date: '',
    status: '1',
    notes: '',
    category_id: null,
    subcategory_id: null,
    source: 1,
    promotion: 0,
    items: [],
    returnItems: [],
    print: false,
  }
) => {
  state.selectedPurchase = Object.assign(state.selectedPurchase, payload)
}

const setProductTriangulationDialogStatus = (state, payload) => {
  state.productTriangulationDialog.isOpen = payload
}

const addProductToPurchase = (state, product) => {
  const ticketItems = state.selectedPurchase.items
  const isNewProduct = pipe(
    find(propEq('upc', product.upc)),
    isNil()
  )(ticketItems)
  const productIndex =
    isNewProduct === false
      ? findIndex(propEq('upc', product.upc))(ticketItems)
      : null
  if (isNewProduct === true || product.isGeneric === 1) {
    ticketItems.push(product)
    return
  }
  if (product.isGramaje === 0) {
    ticketItems[productIndex].quantity = ticketItems[productIndex].quantity + 1
    return
  }
  if (product.isGramaje === 1) {
    ticketItems[productIndex].quantity = product.quantity
    ticketItems[productIndex].unitPrice = product.unitPrice
  }
}

const removeProductFromPurchase = (state, payload) => {
  const ticketItems = state.selectedPurchase.items
  const itemIndex = ticketItems.findIndex(
    product => product.upc === payload.upcProduct
  )
  if (itemIndex >= 0) {
    ticketItems.splice(itemIndex, 1)
  }
}

const updateProductFromPurchase = (state, payload) => {
  const products = state.selectedPurchase.items
  const productIndex = hasPath(['upc'], payload)
    ? findIndex(propEq('upc', payload.upc))(products)
    : findIndex(propEq('uniqueId', payload.uniqueId))(products)
  const propsToUpdate = pipe(
    toPairs,
    map(item => item[0])
  )(payload)
  map(
    prop => (state.selectedPurchase.items[productIndex][prop] = payload[prop]),
    propsToUpdate
  )
}

const toggleConfirmPurchaseDialogStatus = state => {
  state.confirmPurchaseDialog.isOpen = !state.confirmPurchaseDialog.isOpen
}

const updateTotalCostPurchase = (state, payload) => {
  state.selectedPurchase.cost = payload
}

const setSelectedByWeightCategory = (state, payload) => {
  state.selectedByWeightCategory = payload
}

const toggleByWeightProductDialogStatus = state => {
  state.byWeightProductDialog.isOpen = !state.byWeightProductDialog.isOpen
}

const setFinishingPurchaseStatus = (state, payload) => {
  state.currentPurchase.isFinishing = payload
}

const updatePrintTicketStatus = state => {
  state.selectedPurchase.print = !state.selectedPurchase.print
}

const updatePayOptionStatus = (state, option) => {
  state.selectedPurchase.payOption = option
}

export const toggleOverCreditLimitDialogStatus = state => {
  state.overCreditLimitDialog.isOpen = !state.overCreditLimitDialog.isOpen
}

export const setAddProductDialogStatus = (state, status) => {
  const { isOpen, fromReturnProductDialog = false, barcode = null } = status
  state.newProductDialog.isOpen = isOpen
  state.newProductDialog.fromReturnProductDialog = fromReturnProductDialog
  state.newProductDialog.barcode = fromReturnProductDialog ? barcode : null
}

export const toggleDetailDialog = state => {
  state.productDetailDialog.isOpen = !state.productDetailDialog.isOpen
}

export const updateSelectedProductField = (state, payload) => {
  state.selectedProduct[payload.field] = payload.value
}

export const setTourEnabled = (state, payload) => {
  state.tourEnabled = payload
}

export const setPromotionTicketDialogStatus = (state, status) => {
  state.promotionTicketDialog.isOpen = status
}

export const addPromotionTicket = (state, payload) => {
  state.selectedPurchase.promotion = payload.promotion
  state.selectedPurchase.promotion_type = payload.type
}

export const setReturnProductDialogStatus = (state, status) => {
  const { isOpen, isFromTicket = false, returnProduct = null } = status
  state.returnProductDialog.isOpen = isOpen
  state.returnProductDialog.isFromTicket = isFromTicket
  state.returnProductDialog.returnProduct = returnProduct
}

export const setReturnProductsToPurchase = (state, payload) => {
  state.selectedPurchase.returnItems = payload
}

const addReturnProductToPurchase = (state, returnProduct) => {
  const ticketReturnItems = state.selectedPurchase.returnItems
  const isNewProduct = pipe(
    find(
      whereEq({
        purchaseOrderId: returnProduct.purchaseOrderId,
        productReturnId: returnProduct.productReturnId,
      })
    ),
    isNil
  )(ticketReturnItems)
  if (!isNewProduct) return
  ticketReturnItems.push(returnProduct)
}

const updateReturnProductToPurchase = (state, payload) => {
  const ticketReturnItems = state.selectedPurchase.returnItems
  const itemIndex = hasPath(['productReturnId'], payload)
    ? findIndex(propEq('productReturnId', payload.productReturnId))(
        ticketReturnItems
      )
    : findIndex(propEq('uniqueId', payload.uniqueId))(ticketReturnItems)
  const propsToUpdate = pipe(
    toPairs,
    map(item => item[0])
  )(payload)
  map(
    prop =>
      (state.selectedPurchase.returnItems[itemIndex][prop] = payload[prop]),
    propsToUpdate
  )
}

const removeReturnProductFromPurchase = (state, payload) => {
  const ticketReturnItems = state.selectedPurchase.returnItems
  const itemIndex = ticketReturnItems.findIndex(
    returnProduct =>
      returnProduct.productReturnId === payload.returnProductId ||
      returnProduct.productChangeId === payload.returnProductId
  )
  if (itemIndex >= 0) {
    ticketReturnItems.splice(itemIndex, 1)
  }
}

export const setHiddenReturnProductDialog = (state, payload) => {
  state.returnProductDialog.hidden = payload
}

export default {
  [types.SET_SEARCH_TERM_FILTER]: setSearchTermFilter,
  [types.SET_GROUP_FILTER]: setGroupFilter,
  [types.SET_SUPER_CATEGORIES_FILTER]: setSelectedSuperCategories,
  [types.SET_SELECTED_PRODUCT]: setSelectedProduct,
  [types.SET_VIEW_TYPE]: setViewComponent,
  [types.UPDATE_CARD_COMPONENT]: updateCardComponent,
  [types.SET_SELECTED_PURCHASE]: setSelectedPurchase,
  [types.SET_PRODUCT_TRIANGULATION_DIALOG_STATUS]: setProductTriangulationDialogStatus,
  [types.ADD_PRODUCT_TO_PURCHASE]: addProductToPurchase,
  [types.REMOVE_PRODUCT_FROM_PURCHASE]: removeProductFromPurchase,
  [types.UPDATE_PRODUCT_FROM_PURCHASE]: updateProductFromPurchase,
  [types.TOGGLE_CONFIRM_PURCHASE_DIALOG_STATUS]: toggleConfirmPurchaseDialogStatus,
  [types.UPDATE_TOTAL_COST_PURCHASE]: updateTotalCostPurchase,
  [types.SET_SELECTED_BY_WEIGHT_CATEGORY]: setSelectedByWeightCategory,
  [types.TOGGLE_BY_WEIGHT_PRODUCT_DIALOG_STATUS]: toggleByWeightProductDialogStatus,
  [types.SET_FINISHING_PURCHASE_STATUS]: setFinishingPurchaseStatus,
  [types.UPDATE_PRINT_TICKET_OPTION_STATUS]: updatePrintTicketStatus,
  [types.UPDATE_PAY_OPTION_STATUS]: updatePayOptionStatus,
  [types.TOGGLE_OVER_CREDIT_LIMIT_DIALOG_STATUS]: toggleOverCreditLimitDialogStatus,
  [types.SET_NEW_PRODUCT_DIALOG_STATUS]: setAddProductDialogStatus,
  [types.SET_DETAIL_DIALOG_STATUS]: toggleDetailDialog,
  [types.UPDATE_SELECTED_PRODUCT_FIELD]: updateSelectedProductField,
  [types.SET_TOUR_ENABLED]: setTourEnabled,
  [types.SET_UNIT_COST_IN_SELECTED_PRODUCT]: setUnitCostInSelectedProduct,
  [types.ADD_PROMOTION_TICKET]: addPromotionTicket,
  [types.SET_RETURN_PRODUCT_DIALOG_STATUS]: setReturnProductDialogStatus,
  [types.SET_RETURN_PRODUCTS_TO_PURCHASE]: setReturnProductsToPurchase,
  [types.ADD_RETURN_PRODUCT_TO_PURCHASE]: addReturnProductToPurchase,
  [types.REMOVE_RETURN_PRODUCT_TO_PURCHASE]: removeReturnProductFromPurchase,
  [types.UPDATE_RETURN_PRODUCT_TO_PURCHASE]: updateReturnProductToPurchase,
  [types.SET_HIDDEN_RETURN_PRODUCT_DIALOG]: setHiddenReturnProductDialog,
}
