import SYNCHRONIZATION_EVENTS from '@/config/events/synchronization'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import appActions from '@/store/app/actions.types'
import accountActions from '@/store/account/actions.types'

const addListeners = function() {
  rendererEventsService.subscribe(
    SYNCHRONIZATION_EVENTS.replyChannel,
    async (event, payload) => {
      const events = SYNCHRONIZATION_EVENTS.events
      const replies = {
        [events.createOperation.replies.success]: () =>
          this[appActions.addPendingSyncOperation](),
        [events.deleteOperation.replies.success]: () =>
          this[appActions.addPendingSyncOperation](),
        [events.sendOperations.replies.success]: () => {
          this[appActions.setPendingSyncOps](payload.data.syncOpsCount)
          if (payload.data.newToken)
            this[accountActions.setSecurityData](payload.data.newSecurityData)
          this[appActions.setAppSyncing](false)
          this.checkDownloadService()
          this.checkLicenseService()
        },
        [events.sendOperations.replies.error]: () => {
          this[appActions.setAppSyncing](false)
          this.checkDownloadService()
          this.checkLicenseService()
        },
        [events.sendOperationsWithNotifications.replies.success]: () => {
          this[appActions.setPendingSyncOps](payload.data.syncOpsCount)
          if (payload.data.newToken)
            this[accountActions.setSecurityData](payload.data.newSecurityData)
          this[appActions.setAppSyncing](false)
          this.checkDownloadService()
          this.checkLicenseService()
          setTimeout(() => {
            notificationsService.showSuccess(
              'notification.synchronization.successSyncing',
              this.$vuetify.lang
            )
          }, 3100)
        },
        [events.sendOperationsWithNotifications.replies.error]: () => {
          this[appActions.setAppSyncing](false)
          this.checkDownloadService()
          this.checkLicenseService()
          setTimeout(() => {
            notificationsService.showError(
              'notification.synchronization.errorSyncing',
              this.$vuetify.lang
            )
          }, 3100)
        },
      }
      if (payload.event in replies) replies[payload.event]()
    }
  )
}

const removeListeners = () => {
  rendererEventsService.removeAllListeners(SYNCHRONIZATION_EVENTS.replyChannel)
}

const updateDeviceIp = function() {
  rendererEventsService.send(SYNCHRONIZATION_EVENTS.channel, {
    event: SYNCHRONIZATION_EVENTS.events.updateDeviceIp.name,
    data: { securityData: this.accountData.security },
  })
}

const sendOperations = function(notifications = false) {
  this[appActions.setAppSyncing](true)
  rendererEventsService.send(SYNCHRONIZATION_EVENTS.channel, {
    event: SYNCHRONIZATION_EVENTS.events.sendOperations.name,
    data: {
      accountData: {
        device: this.accountData.device,
        operator: this.accountData.operator,
      },
      online: navigator.onLine,
      pendingSyncOps: this.pendingSyncOps,
      securityData: this.accountData.security,
      notifications,
    },
  })
}

export default {
  addListeners,
  removeListeners,
  updateDeviceIp,
  sendOperations,
}
