<template>
  <DialogCard :config="dialogConfig.dialogData" />
</template>

<script>
import { mapActions, mapState } from 'vuex'

import LOGIN_EVENTS from '@/config/events/login'

import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'
import accountActions from '@/store/account/actions.types'

import DialogCard from '@/components/shared/DialogCard'
import setConfig from '@/components/ConfirmDeviceChangeDialog/config'

export default {
  name: 'ConfirmDeviceChangeDialog',
  components: { DialogCard },
  computed: {
    ...mapState('app', ['confirmDeviceChangeDialog']),
    dialogConfig() {
      return setConfig(
        {
          isOpen: this.confirmDeviceChangeDialog.isOpen,
        },
        {
          closeDialog: this.closeDialog,
          continueRestore: this.continueRestore,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.setConfirmDeviceChangeDialogStatus]),
    ...mapActions('account', [accountActions.setAccountFetchingStatus]),
    closeDialog() {
      this[appActions.setConfirmDeviceChangeDialogStatus]({ isOpen: false })
      this[accountActions.setAccountFetchingStatus](false)
    },
    continueRestore() {
      rendererEventsService.send(LOGIN_EVENTS.channel, {
        event: LOGIN_EVENTS.events.accountLoginProcessFromDifferentDevice.name,
        data: this.confirmDeviceChangeDialog.credentialsData,
      })
      this[appActions.setConfirmDeviceChangeDialogStatus]({ isOpen: false })
    },
  },
}
</script>
