const isValidUPC = upc => {
  const numbers = upc.split('').map(Number)
  const checkNumber = numbers.pop()
  const total = numbers.reduce(
    (sum, number, index) => sum + number * (index % 2 === 0 ? 3 : 1),
    0
  )
  return checkNumber === (10 - (total % 10)) % 10
}

const isValidEAN13 = ean => {
  const numbers = ean.split('').map(Number)
  const checkNumber = numbers.pop()
  const total = numbers.reduce(
    (sum, number, index) => sum + number * (index % 2 === 0 ? 1 : 3),
    0
  )
  return checkNumber === (10 - (total % 10)) % 10
}

const expandUpcEToUpcA = upcE => {
  const numbers = upcE.split('').map(Number)
  const first = numbers[0]
  const checkDigit = numbers[7]
  if ([0, 1, 2].includes(numbers[6])) {
    return `${first}${numbers[1]}${numbers[2]}${numbers[6]}0000${numbers[3]}${numbers[4]}${numbers[5]}${checkDigit}`
  }
  if (numbers[6] === 3) {
    return `${first}${numbers[1]}${numbers[2]}${numbers[3]}00000${numbers[4]}${numbers[5]}${checkDigit}`
  }
  if (numbers[6] === 4) {
    return `${first}${numbers[1]}${numbers[2]}${numbers[3]}${numbers[4]}00000${numbers[5]}${checkDigit}`
  }
  return `${first}${numbers[1]}${numbers[2]}${numbers[3]}${numbers[4]}${numbers[5]}0000${numbers[6]}${checkDigit}`
}

const isValidUPCE = upcE => {
  return isValidUPC(expandUpcEToUpcA(upcE))
}

const isValidateEAN8 = code => {
  const numbers = code.split('').map(Number)
  const checkDigit = numbers.pop()
  const total = numbers.reduce((sum, number, index) => {
    return sum + number * (index % 2 === 0 ? 3 : 1)
  }, 0)
  return checkDigit === (10 - (total % 10)) % 10
}

const isSupportedUpcOrEan = code => {
  if (/^\d{13}$/.test(code)) {
    return isValidEAN13(code)
  }
  if (/^\d{12}$/.test(code)) {
    return isValidUPC(code)
  }
  if (/^\d{8}$/.test(code)) {
    return isValidUPCE(code) || isValidateEAN8(code)
  }
  return false
}

const getRegex = upc => {
  const totalToSubstring = upc.length <= 8 ? 2 : 4
  return new RegExp(
    '^\\d*' + escapeRegex(upc.substring(totalToSubstring)) + '$'
  )
}

const deleteInitialZeros = upc => {
  return upc.replace(/^0+/, '')
}

const availableProduct = product => {
  return product.isGeneric === 0 && product.airTime === 0
}

const escapeRegex = string => {
  return string.replace(/[/\-\\^$*+?.()|[\]{}]/g, '\\$&')
}

export default {
  getRegex,
  availableProduct,
  deleteInitialZeros,
  isSupportedUpcOrEan,
}
