<template>
  <DialogCard :config="componentConfig.dialogData">
    <Form :config="componentConfig" />
  </DialogCard>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import CASH_OPERATIONS_DB_API_EVENTS from '@/config/events/databaseAPI/cashOperationsEvents'
import { idOperations } from '@/config/cashOperationsVariables'

import { cleanObjectObserver } from '@/tools/data'
import { formatNumberToDb, formatNumberFromDb } from '@/tools/numbersFormat'

import notificationsService from '@/services/renderer/notifications'
import rendererEventsService from '@/services/renderer/rendererEvents'

import usersViewActions from '@/store/usersView/actions.types'
import appActions from '@/store/app/actions.types'

import setConfig from '@/components/MainView/AddCashMovementDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import Form from '@/components/shared/Form'

export default {
  name: 'AddCashMovementDialog',
  components: { DialogCard, Form },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
      movingCash: false,
    }
  },
  computed: {
    ...mapState('app', ['addCashMovementDialog']),
    ...mapState('usersView', ['estimatedCash', 'selectedUser']),
    componentConfig() {
      return setConfig(
        {
          opened: this.addCashMovementDialog.isOpen,
          inputs: this.inputs,
          v: this.$v.inputs,
          type: this.addCashMovementDialog.type,
        },
        {
          closeDialog: this.closeDialog,
          addCashMovement: this.addCashMovement,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.setAddCashMovementDialogStatus]),
    ...mapActions('usersView', [usersViewActions.setUserEstimatedCash]),
    setProperties: function() {
      this.componentConfig.fields.forEach(field => {
        this.$set(this.inputs, field.id, '')
        if (field.validators)
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
    },
    addCashMovement() {
      if (this.movingCash === true) return
      if (this.$v.inputs.$invalid) {
        Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$touch())
        return
      }
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen:
          this.addCashMovementDialog.type === 'moneyIn'
            ? 'CashInflow'
            : 'CashOutflow',
        name: 'Submit',
      })
      this.movingCash = true
      rendererEventsService.send(CASH_OPERATIONS_DB_API_EVENTS.channel, {
        event: CASH_OPERATIONS_DB_API_EVENTS.events.cashMovement.name,
        data: {
          cashOp:
            this.addCashMovementDialog.type === 'moneyIn'
              ? idOperations.ID_OPERATION_ADDCASH
              : idOperations.ID_OPERATION_TAKECASH,
          amount: formatNumberToDb(this.inputs.amount),
          concept: this.inputs.concept,
          userId: this.selectedUser.id,
          estimatedCash: this.getEstimatedCash(),
        },
      })
    },
    closeDialog() {
      Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$reset())
      Object.keys(this.inputs).forEach(key => (this.inputs[key] = ''))
      this[appActions.setAddCashMovementDialogStatus]({ isOpen: false })
    },
    getEstimatedCash() {
      const stateEstimatedCash =
        this.estimatedCash === null || this.estimatedCash === undefined
          ? 0
          : this.estimatedCash
      return formatNumberToDb(stateEstimatedCash)
    },
    cashMovementListener(event, payload) {
      const replies = {
        [CASH_OPERATIONS_DB_API_EVENTS.events.cashMovement.replies
          .error]: () => {
          notificationsService.showError(
            this.addCashMovementDialog.type === 'moneyIn'
              ? 'notification.cashMovements.moneyInError'
              : 'notification.cashMovements.moneyOutError',
            this.$vuetify.lang
          )
          this.closeDialog()
          this.movingCash = false
        },
        [CASH_OPERATIONS_DB_API_EVENTS.events.cashMovement.replies
          .success]: () => {
          this[usersViewActions.setUserEstimatedCash](
            formatNumberFromDb(payload.data.estimatedCash)
          )
          notificationsService.showSuccess(
            this.addCashMovementDialog.type === 'moneyIn'
              ? 'notification.cashMovements.moneyIn'
              : 'notification.cashMovements.moneyOut',
            this.$vuetify.lang
          )
          this.closeDialog()
          this.movingCash = false
        },
      }
      replies[payload.event]()
    },
  },
  validations() {
    return this.validators
  },
  mounted: async function() {
    this.$barcodeScanner.destroy()
    this.setProperties()
    rendererEventsService.subscribe(
      CASH_OPERATIONS_DB_API_EVENTS.replyChannel,
      this.cashMovementListener
    )
  },
  beforeDestroy() {
    this.$root.$emit('enable-scanner', {})
    rendererEventsService.removeListener(
      CASH_OPERATIONS_DB_API_EVENTS.replyChannel,
      this.cashMovementListener
    )
  },
}
</script>
