import { promotions } from '@/config/promotions'
import paymentMethods from '@/config/paymentMethods'

export const getProductIndex = (sale, value, findBy = 'upc') => {
  return sale.items.findIndex(item => item[findBy] === value)
}

export const getPromotionSaleIndex = (sale, promotion) => {
  return sale.promotions.findIndex(promo => promo.id === promotion.id)
}

export const saleCanApplyPromotions = sale => {
  return (
    sale.promotionTicketId !== promotions.SALE_TICKET_AT_COST &&
    !paymentMethods.isOwnerSale(sale.payOption)
  )
}
