export const addOrRemoveFavoritesSection = ({ commit, state }, payload) => {
  const mainMenuItems = state.mainMenuItems
  if (mainMenuItems.includes(payload)) {
    mainMenuItems.splice(mainMenuItems.indexOf(payload), 1)
  } else {
    if (mainMenuItems.length > 4) mainMenuItems.shift()
    mainMenuItems.push(payload)
  }
  commit(types.SET_APP_MAIN_MENU_ITEMS, mainMenuItems)
}

export const setPreferencesData = async ({ commit }, payload) => {
  const preferences = payload.preferences
  preferences.forEach(preference => {
    if (preference.preference_name === 'darkMode') {
      commit(types.SET_APP_DARKMODE, preference.preference_value === 'true')
    } else if (preference.preference_name === 'favoriteSections') {
      const menuItems = preference.preference_value.split(',')
      commit(types.SET_APP_MAIN_MENU_ITEMS, menuItems)
    } else if (preference.preference_name === 'language') {
      i18n.locale = preference.preference_value
    } else if (preference.preference_name === 'zoomLevel') {
      commit(types.SET_APP_ZOOM_LEVEL, preference.preference_value)
      setWebFrameZoomLevel(preference.preference_value)
    } else if (preference.preference_name === 'forceChangeDialog') {
      commit(
        types.SET_FORCE_CHANGE_DIALOG,
        preference.preference_value === 'true'
      )
    } else if (preference.preference_name === 'defaultProductsFilter') {
      commit(types.SET_DEFAULT_PRODUCTS_FILTER, preference.preference_value)
    } else if (preference.preference_name === 'printTicketDefault') {
      commit(
        types.SET_APP_PRINT_TICKET_DEFAULT_STATUS,
        preference.preference_value === 'true'
      )
    } else if (preference.preference_name === 'showCustomerDataTicket') {
      commit(
        types.SET_APP_SHOW_CUSTOMER_DATA_TICKET_STATUS,
        preference.preference_value === 'true'
      )
    }
  })
}

export const setZoomLevelFromAppProcess = ({ commit }, payload) => {
  payload.preferences.forEach(preference => {
    if (preference.preference_name === 'zoomLevel') {
      commit(types.SET_APP_ZOOM_LEVEL, preference.preference_value)
      setWebFrameZoomLevel(preference.preference_value)
    }
  })
}

