const setWebFrameZoomLevel = zoomLevel => {
  if (zoomLevel !== 'auto') {
    webFrame.setZoomFactor(zoomLevels[zoomLevel].value)
    return
  }
  const screenSize = window.screen.width + window.screen.height
  if (screenSize >= 4000) webFrame.setZoomFactor(1.1)
  else if (screenSize <= 2250) webFrame.setZoomFactor(0.7)
  else if (screenSize <= 2700) webFrame.setZoomFactor(0.85)
  else webFrame.setZoomFactor(1)
}

