import { filter, includes } from 'ramda'

import { normalizeString } from '@/tools/data'

export const getFilteredVendors = (...args) => {
  const vendors = args[0].data.vendors
  const vendorsSearchTerm = normalizeString(
    args[2].vendorsView.filters.vendorSearchTerm || ''
  )

  return filter(
    vendor =>
      includes(vendorsSearchTerm, normalizeString(vendor.name)) &&
      vendor.isAirTime === 0,
    vendors
  )
}
