import dayjs from 'dayjs'

import chatBotActions from '@/store/chatBot/actions.types'

import helpBotTools from '@/components/HelpBot/helpBot.tools'

const MAX_BOT_MESSAGE_BY_THREAD_ID = 5
const TIME_TO_RESET_THREAD_MS = 600000
const GET_THREAD_ID_AGAIN = 'get_thread_id_again'

let timerToDeleteThread = null
let totalMsgToShowUseful = MAX_BOT_MESSAGE_BY_THREAD_ID

const scrollToBottom = function() {
  const chatContentEl = document.getElementsByClassName('chat-bot__content')[0]
  if (!chatContentEl) return
  chatContentEl.scrollTop = chatContentEl.scrollHeight
  setTimeout(() => {
    chatContentEl.scrollTo({
      behavior: 'smooth',
      top: chatContentEl.scrollTop + 1000,
    })
  }, 20)
}

const scrollBot = function() {
  const chatContentEl = document.getElementsByClassName('chat-bot__content')[0]
  const userBubbles = document.getElementsByClassName('user-bubble')
  const lastUserBubble = userBubbles[userBubbles.length - 1]
  if (!lastUserBubble) return
  setTimeout(() => {
    chatContentEl.scrollTo({
      behavior: 'smooth',
      top: lastUserBubble.offsetTop - lastUserBubble.offsetHeight - 15,
    })
  }, 20)
}

const addListeners = function() {
  const linksEl = document.getElementsByClassName('link-go-to')
  for (let el of linksEl) {
    if (el.hasClickListener) continue
    el.addEventListener('click', () => {
      const path = el.dataset.route
      if (this.$route.path === path) return
      this.$router.push({ path })
    })
    el.hasClickListener = true
  }
}

const getNoInternetConnectionBotResponse = function() {
  this.$track({
    type: 'system',
    action: 'error',
    category: this.$route.name,
    screen: 'HelpBot',
    name: 'Error connection',
  })
  return {
    text: this.getTranslatedText('helpBot.chat.responseNoConnection'),
    agent: 'bot',
  }
}

const getErrorBotResponse = function() {
  return {
    text: this.getTranslatedText(
      'helpBot.chat.responseError',
      helpBotTools.getHelpContact.call(this)
    ),
    agent: 'bot',
  }
}

const getErrorBotGetThreadId = function() {
  const text = this.hasConnection
    ? this.getTranslatedText(
        'helpBot.chat.threadError',
        helpBotTools.getHelpContact.call(this)
      )
    : this.getTranslatedText(
        'helpBot.chat.threadNoConnection',
        helpBotTools.getHelpContact.call(this)
      )
  return {
    text: text,
    agent: 'bot',
    options: [
      {
        text: this.getTranslatedText('helpBot.chat.tryAgain'),
        value: GET_THREAD_ID_AGAIN,
      },
    ],
  }
}

const getInitialBotMessage = function() {
  return {
    agent: 'bot',
    text: this.getTranslatedText('helpBot.chat.regards'),
  }
}

const manageOptionSelected = function(option) {
  if (option.value === GET_THREAD_ID_AGAIN) {
    this.$track({
      type: 'interaction',
      action: 'click',
      category: this.$route.name,
      screen: 'ChatBot',
      name: 'Get thread again',
    })
    this.createThreadIdIfItsNecessary()
    return
  }
  this.$track({
    type: 'interaction',
    action: 'click',
    category: this.$route.name,
    screen: 'ChatBot',
    name: 'Send ok to restart thread',
  })
  this[chatBotActions.addMessage]({ text: option.text, agent: 'user' })
  scrollToBottom.call(this)
  totalMsgToShowUseful = MAX_BOT_MESSAGE_BY_THREAD_ID
  clearTimerToDeleteThread()
  resetThreadId.call(this)
}

const hasMaxBotResponseWithSameThreadId = function() {
  let counter = 0
  for (let message of this.messages) {
    if (counter === totalMsgToShowUseful) break
    if (msgIsFromAgentAndSameThreadId(message, this.threadId)) {
      counter += 1
    }
  }
  return counter >= totalMsgToShowUseful
}

const msgIsFromAgentAndSameThreadId = (message, threadId) => {
  return message.agent === 'bot' && message.threadId === threadId
}

const showHelpUseFulQuest = function() {
  this[chatBotActions.addMessage]({
    text: this.getTranslatedText(
      'helpBot.chat.lastResponse',
      helpBotTools.getHelpContact.call(this)
    ),
    agent: 'bot',
    options: [
      {
        text: this.getTranslatedText('helpBot.chat.okBtn'),
        value: 'ok',
      },
    ],
  })
}

const startTimerToDeleteThread = function() {
  clearTimerToDeleteThread()
  timerToDeleteThread = setTimeout(() => {
    resetThreadId.call(this)
  }, TIME_TO_RESET_THREAD_MS)
}

const clearTimerToDeleteThread = () => {
  if (timerToDeleteThread) {
    clearTimeout(timerToDeleteThread)
  }
}

const resetThreadId = function() {
  this[chatBotActions.addMessage](getBotMessageFinishChat.call(this))
  this.deleteThread(this.threadId)
  this[chatBotActions.setThreadId](null)
  this.createThreadIdIfItsNecessary(true)
}

const getBotMessageFinishChat = function() {
  return {
    text: this.getTranslatedText('helpBot.chat.chatFinished'),
    agent: 'timestamp',
    time: dayjs().format('DD/MM/YYYY - HH:mm'),
  }
}

export default {
  scrollToBottom,
  scrollBot,
  addListeners,
  getNoInternetConnectionBotResponse,
  getErrorBotResponse,
  getErrorBotGetThreadId,
  getInitialBotMessage,
  manageOptionSelected,
  hasMaxBotResponseWithSameThreadId,
  showHelpUseFulQuest,
  startTimerToDeleteThread,
  clearTimerToDeleteThread,
}
