import {
  getTicketNumber,
  ticketNumberIsInSearchTerm,
  operationIsWithinFilter,
} from '@/store/operations/getters.tools'

export const getFilteredData = (...args) => {
  let operations = args[0].operations
  const filters = args[2].operationsView.filters
  return operations.reduce((toShow, operation) => {
    if (operation.extraInfo === 'hideUI') return toShow
    if (!operationIsWithinFilter(filters, operation)) return toShow
    const ticketNumber = getTicketNumber(operation)
    if (!ticketNumberIsInSearchTerm(filters, ticketNumber)) return toShow
    toShow.push({
      ...operation,
      ticketNumber,
    })
    return toShow
  }, [])
}
