import { isNil } from 'ramda'

import countries from '@/config/countries'

import storeProd from '@/store/index'

export const formatNumberFromDbToCurrency = value => {
  return formatNumberToCurrency(formatNumberFromDb(value))
}

export const formatNumberFromDbToCurrencyWithoutDecimals = value => {
  return formatNumberToCurrencyWithoutDecimals(formatNumberFromDb(value))
}

export const formatNumberFromDb = value => {
  if ([null, undefined, '', 0].includes(value)) return value
  const divisor = Math.pow(10, storeProd.getters['account/getCountry'].decimals)
  return divisor === 1 ? parseInt(value) : value / divisor
}

export const formatNumberToDb = value => {
  if ([null, undefined, '', 0].includes(value)) return value
  const divisor = Math.pow(10, storeProd.getters['account/getCountry'].decimals)
  return parseInt((parseFloat(value) * divisor).toFixed(0))
}

export const formatNumberToCurrency = value => {
  const valueFormatted = storeProd.getters[
    'account/getCountry'
  ].currency.format(value)
  return storeProd.getters['account/getCountry'].noCurrencySpace === true
    ? valueFormatted.replace('\xa0', '')
    : valueFormatted
}

export const formatNumberToCurrencyWithoutDecimals = value => {
  const valueFormatted = storeProd.getters[
    'account/getCountry'
  ].currencyWithoutDecimals.format(value)
  return storeProd.getters['account/getCountry'].noCurrencySpace === true
    ? valueFormatted.replace('\xa0', '')
    : valueFormatted
}

export const roundToNearestMultiple = (value, storeTest = null) => {
  const store = storeTest !== null ? storeTest : storeProd
  const multipleToRound = store.getters['account/getCountry'].multipleToRound
  if (value <= 0 || multipleToRound === undefined) return value
  const roundValue = value % multipleToRound
  if (roundValue < multipleToRound / 2) {
    return value - roundValue > 0 ? value - roundValue : multipleToRound
  }
  return value + multipleToRound - roundValue
}

export const moneyTextFieldCountryConfig = () => {
  const countryData = storeProd.getters['account/getCountry']
  return {
    currency: { prefix: countries[countryData.localeIsoCode].prefix },
    locale: countryData.countryTag,
    prefix: '$',
    precision: countryData.decimals,
  }
}

export const hasDecimals = value => value % 1 !== 0

export const formatValueDecimals = value =>
  Number(hasDecimals(value) ? value.toFixed(2) : value)

export const convertByWeightQuantity = (quantity, isKg) =>
  isKg === true ? (quantity || 0) * 1000 : (quantity || 0) / 1000

export const getDecimalsCount = number => {
  if (isNil(number) || isNaN(number)) return
  const numberStr = number.toString()
  return numberStr.includes('.') ? numberStr.split('.')[1].length : 0
}

export const decimal = (number = 0, decimals = 2) =>
  Number(number.toFixed(decimals))
