<template>
  <div class="d-flex" @click="onClick">
    <img
      :src="getPath"
      :class="getFlagStyles"
      :height="height"
      :width="width"
    />
  </div>
</template>

<script>
export default {
  name: 'Flag',
  props: {
    country: {
      type: String,
      default: 'es',
    },
    size: {
      type: String,
      default: 'default',
      validator(x) {
        return [
          'nano',
          'micro',
          'mini',
          'small',
          'default',
          'medium',
          'large',
          'huge',
        ].includes(x)
      },
    },
    height: {
      type: String,
      default: null,
    },
    width: {
      type: String,
      default: null,
    },
  },
  computed: {
    getPath: function() {
      const code = (this.country || 'es').toLowerCase()
      return require(`@/assets/flags/${code}.svg`)
    },
    getFlagStyles: function() {
      return [
        this.height === null ? `my-0 flag-${this.size}` : '',
        this.width === null ? `flag-${this.size}` : '',
      ]
    },
  },
  methods: {
    onClick(event) {
      this.$emit('click', event)
    },
  },
}
</script>

<style lang="scss">
$sizes: 'nano', 'micro', 'mini', 'small', 'default', 'medium', 'large', 'huge';

@each $size in $sizes {
  $i: index($sizes, $size) - 1;
  .flag-#{$size} {
    height: 10px + ($i * 5);
  }
}
</style>
