<template>
  <div>
    <v-menu
      bottom
      offset-y
      transition="slide-y-transition"
      :close-on-content-click="false"
      :nudge-width="200"
      :disabled="disabled"
    >
      <template v-slot:activator="{ on: menu }">
        <Button
          v-bind="$attrs"
          v-on="{ ...menu }"
          :color="color"
          :icon="icon"
          :tooltipText="tooltipText"
          :tooltipPosition="tooltipPosition"
          :textColor="textColor"
          @click="onClick"
        />
      </template>
      <v-card>
        <webview :src="url" class="webview-container" />
      </v-card>
    </v-menu>
  </div>
</template>

<script>
import Button from '@/components/shared/CustomButton'

export default {
  name: 'PopoverButton',
  components: { Button },
  props: {
    url: {
      type: String,
      required: false,
    },
    icon: {
      type: String,
      default: '',
    },
    tooltipText: {
      type: String,
      default: '',
    },
    tooltipPosition: {
      type: String,
      default: 'bottom',
    },
    color: {
      type: String,
      default: 'primary',
    },
    textColor: {
      type: String,
      default: 'white',
    },
    disabled: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      dff: false,
    }
  },
  methods: {
    onClick(event) {
      this.$emit('click', event)
    },
  },
}
</script>

<style lang="scss" scoped>
.webview-container {
  height: 400px;
  width: 700px;
}
.filter-button.theme--light.v-btn--active::before {
  opacity: 0.6;
}
.filter-button.theme--light.v-btn:hover::before {
  opacity: 0.3;
}
</style>
