import Vue from 'vue'
import Vuetify from 'vuetify/lib'

import IconReturnProduct from '@/components/icons/IconReturnProduct'
import IconCurrencyUsdCircle from '@/components/icons/IconCurrencyUsdCircle'

import i18n from './i18n'
import light from '@/themes/light'
import dark from '@/themes/dark'

Vue.use(Vuetify)

export default new Vuetify({
  lang: {
    t: (key, ...params) => i18n.t(key, params),
  },
  theme: {
    options: {
      customProperties: true,
    },
    themes: {
      light: { ...light },
      dark: { ...dark },
    },
  },
  icons: {
    values: {
      returnProduct: {
        component: IconReturnProduct,
      },
      currencyUsdCircle: {
        component: IconCurrencyUsdCircle,
      },
    },
  },
})
