import VideoCard from '@/components/shared/VideoCard'

import light from '@/themes/light'
import dark from '@/themes/dark'

export const setConfig = (state, methods) => ({
  state,
  methods: {
    ...methods,
    onClick: item => methods.openPlayerWindow(item),
    onDblClick: item => methods.openPlayerWindow(item),
  },
  title: 'helpCenterView.helpCenterList.title',
  titleClass: 'pl-2',
  icon: 'mdi-school',
  loaderColor: { light: light.productLoader, dark: dark.productLoader },
  isDetail: false,
  rowsPerPage: 2,
  page: 1,
  cardComponents: {
    VideoCard: {
      component: VideoCard,
      cardOffsetHeight: 180,
      itemsPerRow: {
        small: 4,
        medium: 5,
        large: 5,
        extraLarge: 6,
      },
    },
  },
  noDataMessage: {
    icon: 'mdi-video-off',
    messages: ['helpCenterView.helpCenterList.noData.firstMessage'],
  },
})

export default setConfig
