const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-sync-alert',
    title: 'notification.synchronization.syncOpsPendingOverLimitTitle',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    buttons: {
      cancel: false,
      accept: true,
    },
    buttonTextColor: { accept: 'white' },
    buttonColor: { accept: 'primary' },
    acceptButtonText: 'close',
    messages: ['notification.synchronization.syncOpsPendingOverLimit'],
    height: 250,
    maxWidth: 510,
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.closeDialog(),
  },
})

export default setConfig
