import types from '@/store/airtimeServices/mutations.types'

export const setBalance = ({ commit }, payload) =>
  commit(types.SET_AIRTIME_SERVICES_BALANCE, payload)

export const setBanks = ({ commit }, payload) =>
  commit(types.SET_AIRTIME_SERVICES_BANKS, payload)

export const setAddAirtimeServicesBalanceDialogStatus = ({ commit }, payload) =>
  commit(types.SET_ADD_AIRTIME_SERVICES_BALANCE_DIALOG_STATUS, payload.isOpen)

export const setBalanceFetching = ({ commit }, payload) =>
  commit(types.SET_AIRTIME_BALANCE_FETCHING, payload)

export const setBalanceFetchingError = ({ commit }) =>
  commit(types.SET_AIRTIME_BALANCE_FETCHING)
