import { filter } from 'ramda'

export const filterBy = {
  searchTerm: (searchTerm, enrolledCustomers) => {
    return filter(
      item =>
        item.customer.name
          .toString()
          .toLowerCase()
          .includes(searchTerm ? searchTerm.toLowerCase() : searchTerm) ||
        (item.customer.phone &&
          item.customer.phone.toString().includes(searchTerm)),
      enrolledCustomers
    )
  },
}
