<template>
  <v-overlay
    v-if="showLoading"
    class="text-center"
    absolute
    opacity="0.65"
    z-index="999999"
  >
    <SyncLoader
      :loading="showLoading"
      :class="{ 'mt-n4 mb-4': !!$loading.text }"
      color="#ffffff"
      margin="4px"
    />
    <h3 v-if="$loading.text" class="font-weight-medium">
      {{ getTranslatedText(`mainLayout.loading.texts.${$loading.text}`) }}
    </h3>
    <v-dialog
      v-model="showAlertDialog"
      hide-overlay
      max-width="425"
      content-class="default-dialog"
      persistent
    >
      <v-card>
        <v-card-title>
          {{ getTranslatedText('mainLayout.loading.alert.title') }}
        </v-card-title>
        <v-card-text>
          <p class="text-subtitle-1 mb-1">
            {{ getTranslatedText('mainLayout.loading.alert.text') }}
            <br />
            {{ getTranslatedText('mainLayout.loading.alert.info') }}
          </p>
        </v-card-text>
        <v-card-actions>
          <v-spacer />
          <v-btn color="accent" @click="resetTimer" ref="continueWaiting">
            {{ getTranslatedText('mainLayout.loading.alert.waitingBtn') }}
          </v-btn>
          <v-btn color="primary" @click="reloadApp" ref="reloadApp">
            {{ getTranslatedText('mainLayout.loading.alert.reloadBtn') }}
          </v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>
  </v-overlay>
</template>

<script>
import { SyncLoader } from '@saeris/vue-spinners'

import APP_TOOLS_EVENTS from '@/config/events/appTools'

import { getTranslatedText } from '@/tools/data'
import { captureMessage } from '@/tools/exceptions'

import rendererEventsService from '@/services/renderer/rendererEvents'

const SENTRY_SHOW_ALERT_TAG = 'show_alert'
const SENTRY_RELOAD_APP_TAG = 'reload_app'
const SENTRY_TRACES = {
  [SENTRY_SHOW_ALERT_TAG]: 'Show loading timer exceeded alert',
  [SENTRY_RELOAD_APP_TAG]: 'Reload app',
}

export default {
  name: 'GeneralLoading',
  components: { SyncLoader },
  data() {
    return {
      alertTimer: null,
      showAlertDialog: false,
    }
  },
  computed: {
    showLoading() {
      if (this.$loading.isActive) {
        this.clearTimer()
        this.startTimer()
        return true
      }
      this.clearTimer()
      return false
    },
  },
  methods: {
    getTranslatedText,
    startTimer() {
      this.alertTimer = setTimeout(() => {
        if (!this.$loading.isActive) {
          this.clearTimer()
          return
        }
        this.sentryCaptureMessage(SENTRY_SHOW_ALERT_TAG)
        this.showAlertDialog = true
      }, 60000)
    },
    resetTimer() {
      this.clearTimer()
      this.startTimer()
    },
    clearTimer() {
      this.showAlertDialog = false
      if (this.alertTimer) {
        clearTimeout(this.alertTimer)
        this.alertTimer = null
      }
    },
    reloadApp() {
      this.sentryCaptureMessage(SENTRY_RELOAD_APP_TAG)
      rendererEventsService.send(APP_TOOLS_EVENTS.channel, {
        event: APP_TOOLS_EVENTS.events.reloadApp.name,
      })
    },
    sentryCaptureMessage(tag) {
      captureMessage('Loading excess time', {
        level: 'warning',
        tags: { loading: tag },
        extra: { trace: SENTRY_TRACES[tag], route: this.$route.path },
      })
    },
  },
}
</script>
