import PAYMENT_PROVIDERS_DB_API_EVENTS from '@/config/events/databaseAPI/paymentProvidersEvents'

import rendererEventsService from '@/services/renderer/rendererEvents'

import salesViewActions from '@/store/salesView/actions.types'

const addListeners = function() {
  rendererEventsService.subscribe(
    PAYMENT_PROVIDERS_DB_API_EVENTS.replyChannel,
    (event, payload) => {
      const replies = {
        [PAYMENT_PROVIDERS_DB_API_EVENTS.events.download.replies
          .success]: () => {
          getPaymentProviders()
        },
        [PAYMENT_PROVIDERS_DB_API_EVENTS.events.download.replies.error]: () => {
          getPaymentProviders()
        },
        [PAYMENT_PROVIDERS_DB_API_EVENTS.events.getAll.replies.success]: () => {
          this[salesViewActions.setPaymentProvidersByType](payload.data)
        },
      }
      if (payload.event in replies) replies[payload.event]()
    }
  )
}

const removeListeners = () => {
  rendererEventsService.removeAllListeners(
    PAYMENT_PROVIDERS_DB_API_EVENTS.replyChannel
  )
}

const getPaymentProviders = () => {
  rendererEventsService.send(PAYMENT_PROVIDERS_DB_API_EVENTS.channel, {
    event: PAYMENT_PROVIDERS_DB_API_EVENTS.events.getAll.name,
  })
}

export default {
  addListeners,
  removeListeners,
  getPaymentProviders,
}
