import {
  mapAccum,
  find,
  isNil,
  isEmpty,
  pickAll,
  pipe,
  filter,
  keys,
  reduce,
  fromPairs,
  path,
  toPairs,
  map,
  reverse,
  assoc,
  dissoc,
  indexOf,
} from 'ramda'

import countries from '@/config/countries'

export const getObjectCopy = object => JSON.parse(JSON.stringify(object))

export const getAccumValuesFromArrayItems = (array, init = 0) => {
  const appender = (acc, value) => [acc + value, acc + value]
  return mapAccum(appender, init, array)[1]
}

export function deepCopy(obj, cache = []) {
  if (obj === null || typeof obj !== 'object') {
    return obj
  }

  const hit = find(item => item.original === obj)(cache)

  if (hit) {
    return hit.copy
  }

  const copy = Array.isArray(obj) ? [] : {}

  cache.push({
    original: obj,
    copy,
  })

  Object.keys(obj).forEach(key => {
    copy[key] = deepCopy(obj[key], cache)
  })

  return copy
}

export const buildUID = credentials => {
  const credentialsAreValid = validateObjectKeysFromWhiteList(
    ['account', 'country'],
    credentials
  )

  if (!isNil(credentials) && credentialsAreValid.success === true) {
    if (credentials.account.includes('@'))
      return getEmailAccount(credentials.account)
    const phoneCode = getCountryDataSearchingByProp(
      'localeIsoCode',
      credentials.country
    )
    if (isNil(phoneCode)) return null
    return getPhoneAccount(phoneCode.phoneCode, credentials.account)
  }
  return null
}

export const getEmailAccount = account => {
  return account.trim().toLowerCase()
}

export const getPhoneAccount = (phoneCode, account) => {
  return `${phoneCode.toString().padStart(4, '0')}${account}`.trim()
}

export const getCountryDataSearchingByProp = (prop, value) => {
  return Object.values(countries).find(item => item[prop] === value)
}

export const validateObjectKeysFromWhiteList = (whiteList, object) => {
  if (isNil(whiteList) || isNil(object)) return { fails: [], success: false }
  const result = pipe(
    pickAll,
    filter(prop => prop === undefined),
    keys
  )(whiteList, object)

  return { fails: result, success: result.length === 0 }
}

export const validateListElementsFromWhiteList = (whiteList, list) => {
  if (list.length === 0) return false
  let allEntities = true
  whiteList.forEach(item => {
    if (!list.includes(item)) allEntities = false
  })
  return allEntities
}

export const getTranslatedText = function(translateString, extraValues = null) {
  return extraValues === null
    ? this.$vuetify.lang.t(`$vuetify.${translateString}`)
    : Array.isArray(extraValues)
    ? this.$vuetify.lang.t(`$vuetify.${translateString}`, ...extraValues)
    : this.$vuetify.lang.t(`$vuetify.${translateString}`, extraValues)
}

export const formatText = config => {
  switch (config.type) {
    case 'stock': {
      let unit = config.value === 1 || config.value === -1 ? 'pz' : 'pzs'
      if (config.isGramaje === 1) unit = 'gr'
      return `${config.value} ${unit}`
    }
    case 'money':
      return countries[config.country].currency(config.value)
  }
}

export const idTools = {
  getKey: id =>
    !isNil(id) && !isEmpty(id)
      ? id
          .toString()
          .slice(0, -2)
          .trim()
      : '1',
  getId: (key, device = '01') =>
    !isNil(key) && key !== 0 && key !== '0' && !isEmpty(key)
      ? Number(`${key + 1}${device}`.trim())
      : Number('101'),
}

export const createObjectFromModel = Model => {
  return reduce(
    (obj, item) => {
      return { ...obj, [item['name']]: item.default }
    },
    {},
    Model.properties
  )
}

export const findKey = (key, keys) => {
  if (keys === null || keys === undefined) {
    return key
  }
  const result = pipe(fromPairs, path([key]))(keys)
  return result ? result : null
}

export const mapStoreObject = (object, keys, invert = false) => {
  invert === true ? (keys = map(key => reverse(key))(keys)) : keys
  return pipe(
    toPairs,
    filter(prop => findKey(prop[0], keys) !== null),
    map(prop => [findKey(prop[0], keys), object[prop[0]]]),
    fromPairs
  )(object)
}

export const cleanObjectObserver = object => {
  return Object.keys(object).reduce(
    (res, e) => Object.assign(res, { [e]: object[e] }),
    {}
  )
}

export const updateObjectKeyName = (keyName, newKeyKey, object) => {
  return pipe(assoc('product_code', object[keyName]), dissoc(keyName))(object)
}

export const dissocProp = (prop, data) => map(item => dissoc(prop, item), data)

export const removeDuplicates = (data, prop) =>
  filter(
    obj =>
      indexOf(
        obj[prop],
        map(mapObj => mapObj[prop], data)
      ) === indexOf(obj, data),
    data
  )

export const getDuplicatedItemsByProp = (items, prop) => {
  const repeatedItemsDictionary = pipe(
    map(item => item[prop]),
    reduce((a, b) => ({ ...a, [b]: (a[b] || 0) + 1 }), 0)
  )(items)

  return pipe(
    toPairs,
    filter(item => item[1] > 1 && item[0] !== ''),
    map(item => item[0])
  )(repeatedItemsDictionary)
}

export const checkIfAllObjectPropsAreTrue = obj => {
  const objPropsPairs = toPairs(obj)
  const objPropsValuesAreTrue =
    filter(step => typeof step[1] !== 'boolean')(objPropsPairs).length === 0
  if (objPropsPairs.length === 0) return false
  if (!objPropsValuesAreTrue) return false
  return filter(step => step[1] === false)(objPropsPairs).length === 0
}

export const removeEmojis = text => {
  return text.replace(/[^\x20-\xFF]+ *(?:[^\x20-\xFF]| )*/gm, '')
}

export const getTruncatedText = (text, maxLength) => {
  if (text.length > maxLength) {
    return text.substring(0, maxLength) + '...'
  }
  return text
}

export const normalizeString = str => removeAccents(str.toLowerCase())

const removeAccents = str =>
  str.normalize('NFD').replace(/[\u0300-\u036f]/g, '')
