<template>
  <div>
    <v-menu bottom offset-y transition="slide-y-transition">
      <template v-slot:activator="{ on: menu }">
        <Button
          v-if="!transparent"
          v-bind="$attrs"
          v-on="{ ...menu }"
          :color="color"
          :icon="icon"
          :tooltipText="tooltipText"
          :tooltipPosition="tooltipPosition"
          :textColor="textColor"
        />
        <v-btn v-bind="$attrs" v-on="{ ...menu }" v-else icon :color="color">
          <v-icon>{{ icon }}</v-icon>
        </v-btn>
      </template>
      <v-list v-if="items.length > 0" class="overflow-y-auto" max-height="200">
        <component v-if="!!listItemType" :is="listItemType" :items="items" />
        <v-list-item-group v-else>
          <v-list-item
            v-for="item in items"
            :key="item.id"
            @click="item.click(item)"
          >
            <v-list-item-icon v-if="item.icon">
              <v-icon color="primary">{{ item.icon }}</v-icon>
            </v-list-item-icon>
            <v-list-item-content>
              <v-list-item-title>{{ item.title }}</v-list-item-title>
            </v-list-item-content>
          </v-list-item>
        </v-list-item-group>
      </v-list>
      <v-list v-else>
        <v-list-item>
          <v-list-item-title>
            <FormattedText intl :value="noDataText" />
          </v-list-item-title>
        </v-list-item>
      </v-list>
    </v-menu>
  </div>
</template>

<script>
import Button from '@/components/shared/CustomButton'
import FormattedText from '@/components/shared/FormattedText'
import VideoListItem from '@/components/shared/ButtonDropdown/listItem/VideoListItem'
import TextListItem from '@/components/shared/ButtonDropdown/listItem/TextListItem'

export default {
  name: 'button-dropdown',
  components: { Button, FormattedText, VideoListItem, TextListItem },
  props: {
    items: {
      type: Array,
      required: true,
    },
    listItemType: {
      type: String,
      default: null,
    },
    icon: {
      type: String,
      default: '',
    },
    tooltipText: {
      type: String,
      default: '',
    },
    tooltipPosition: {
      type: String,
      default: 'bottom',
    },
    color: {
      type: String,
      default: 'primary',
    },
    textColor: {
      type: String,
      default: 'white',
    },
    noDataText: {
      type: String,
      default: 'noDataText',
    },
    transparent: {
      type: Boolean,
      default: false,
    },
  },
}
</script>
