import { isNil, reject } from 'ramda'
import Vue from 'vue'

import categories from '@/config/categories'

import mutationsTypes from '@/store/products/mutations.types'

import {
  getPiecesStockValue,
  getPackagesStockValue,
} from '@/components/ProductDetail/DetailsTab/tools'

// Data mutations
const setFetching = (state, newState) => {
  state.fetching = newState
}

const setError = (state, error) => {
  state.data = null
  state.error = true
  state.errorMessage = error
}

const setProducts = (state, payload) => {
  state.data.products = payload
  state.error = false
  state.errorMessage = ''
}

const setSuperCategories = (state, payload) => {
  state.data.superCategories = payload
  state.error = false
  state.errorMessage = ''
}

const setByWeightTree = (state, payload) => {
  state.data.byWeightTree = payload
  state.error = false
  state.errorMessage = ''
}
const updateByWeightTree = (state, payload) => {
  const updateNode = nodes => {
    for (const node of nodes) {
      if (node.upc === payload.upc) {
        node.visible = !!payload.isGramaje
        break
      }
      if (Array.isArray(node.children)) {
        updateNode(node.children)
      }
    }
  }
  updateNode(state.data.byWeightTree)
}

const setProductSimilarUpc = (state, payload) => {
  state.data.productsSimilarUpc = payload
}

const updateProduct = (state, payload) => {
  const index = state.data.products.indexOf(
    state.data.products.find(product => product.id === payload.id)
  )
  const category = categories.find(el => el.id === payload.categoryId)
  payload['categoryName'] = !isNil(category)
    ? category.superCategory
    : categories[0].superCategory
  Vue.set(state.data.products, index, payload)
}

const removeProduct = (state, payload) => {
  state.data.products = state.data.products.filter(
    product => product.id !== payload
  )
  removeSimilarProductUpcFromList(state, [payload])
}

const updateProductStock = (state, payload) => {
  let productIndex = state.data.products.indexOf(
    state.data.products.find(product => product.upc == payload.upc)
  )
  if (productIndex === -1) return
  state.data.products[productIndex].quantity = payload.newStock
  if (state.data.products[productIndex].factor < 1) return
  state.data.products[productIndex].piecesQuantity = getPiecesStockValue(
    payload.newStock,
    state.data.products[productIndex].factor
  )
  state.data.products[productIndex].packagesQuantity = getPackagesStockValue(
    payload.newStock,
    state.data.products[productIndex].factor
  )
}
const updateProductCost = (state, payload) => {
  let productIndex = state.data.products.indexOf(
    state.data.products.find(product => product.upc == payload.upc)
  )
  if (productIndex === -1) return
  state.data.products[productIndex].cost = payload.newCost
  state.data.products[productIndex].iva = payload.iva
}

const updateByProperties = (state, payload) => {
  const product = state.data.products.find(product => product.id === payload.id)
  const index = state.data.products.indexOf(product)
  if (index > -1) {
    Object.keys(payload).forEach(key => (product[key] = payload[key]))
    Vue.set(state.data.products, index, product)
  }
}

const setProduct = (state, payload) => {
  state.data.products.push(payload)
  state.error = false
  state.errorMessage = ''
}

const setMlpFilteredProducts = (state, payload) => {
  state.data.mlp = payload.data
  state.error = false
  state.errorMessage = ''
}

const removeItemFromMlpFilteredProducts = (state, payload) => {
  const mlpData = state.data.mlp
  state.data.mlp = reject(item => item.upc === payload.upc, mlpData)
}

const bulkProductDeletion = (state, productsToDelete) => {
  state.data.products = state.data.products.filter(
    product =>
      !productsToDelete.some(productToDelete => productToDelete === product.id)
  )
  removeSimilarProductUpcFromList(state, productsToDelete)
}

const removeSimilarProductUpcFromList = (state, products) => {
  products.forEach(productId => {
    if (!state.data.productsSimilarUpc[productId]) return
    const matches = state.data.productsSimilarUpc[productId]
    delete state.data.productsSimilarUpc[productId]
    matches.forEach(matchId => {
      const index = state.data.productsSimilarUpc[matchId].indexOf(productId)
      state.data.productsSimilarUpc[matchId].splice(index, 1)
      if (!state.data.productsSimilarUpc[matchId].length) {
        delete state.data.productsSimilarUpc[matchId]
      }
    })
  })
}

export default {
  [mutationsTypes.SET_PRODUCTS]: setProducts,
  [mutationsTypes.SET_PRODUCT]: setProduct,
  [mutationsTypes.SET_SUPER_CATEGORIES]: setSuperCategories,
  [mutationsTypes.SET_BY_WEIGHT_TREE]: setByWeightTree,
  [mutationsTypes.SET_PRODUCTS_SIMILAR_UPC]: setProductSimilarUpc,
  [mutationsTypes.SET_PRODUCTS_OR_SUPER_CATEGORIES_FETCHING]: setFetching,
  [mutationsTypes.SET_PRODUCTS_OR_SUPER_CATEGORIES_ERROR]: setError,
  [mutationsTypes.SET_PRODUCTS_OR_SUPER_CATEGORIES_FETCHING_ERROR]: setError,
  [mutationsTypes.SET_MLP_FILTERED_PRODUCTS]: setMlpFilteredProducts,
  [mutationsTypes.UPDATE_BY_WEIGHT_TREE]: updateByWeightTree,
  [mutationsTypes.UPDATE_PRODUCT]: updateProduct,
  [mutationsTypes.UPDATE_PRODUCT_STOCK]: updateProductStock,
  [mutationsTypes.UPDATE_PRODUCT_COST]: updateProductCost,
  [mutationsTypes.UPDATE_PRODUCT_BY_PROPERTIES]: updateByProperties,
  [mutationsTypes.REMOVE_PRODUCT]: removeProduct,
  [mutationsTypes.REMOVE_ITEM_FROM_MLP_FILTERED_PRODUCTS]: removeItemFromMlpFilteredProducts,
  [mutationsTypes.BULK_PRODUCT_DELETION]: bulkProductDeletion,
}
