import {
  comboPromotion as comboPromotionMapper,
  customPromotion as promotionMapper,
  moreForLessPromotion,
  storeInventory,
} from '@/config/storeMapper'

import { promotions } from '@/config/promotions'

import { mapStoreObject } from '@/tools/data'
import { comboPromotion } from '@/tools/customPromotions'

import types from '@/store/customPromotions/mutations.types'
import typesApp from '@/store/app/mutations.types'

export const addLastUpdate = ({ commit }, lastUpdate) => {
  commit(types.ADD_LAST_UPDATE, lastUpdate)
}

export const addCustomPromotions = ({ commit }, promotions) => {
  const promotionsList = {}
  const deletedPromotions = {}

  promotions.forEach(promo => {
    if (promo.deleted === 1) {
      deletedPromotions[promo._id] = getCustomPromotionMapped(promo)
      return
    }
    promotionsList[promo._id] = getCustomPromotionMapped(promo)
  })
  commit(types.ADD_CUSTOM_PROMOTIONS, promotionsList)
  commit(types.ADD_DELETED_CUSTOM_PROMOTIONS, deletedPromotions)
}

export const saveCustomPromotion = ({ commit, dispatch }, promotion) => {
  const promotionToSave = getCustomPromotionMapped(promotion)
  commit(types.SAVE_CUSTOM_PROMOTION, promotionToSave)
  if (promotionToSave.type === promotions.SALE_ITEM_MORE_FOR_LESS) {
    dispatch('updateMoreForLessPromotionsInSales', promotionToSave.product)
  } else if (promotionToSave.type === promotions.SALE_ITEM_COMBO) {
    dispatch('updateCombosPromotionsInSales', { combo: promotionToSave })
  }
  commit(`app/${typesApp.ADD_APP_PENDING_SYNC_OP}`, null, {
    root: true,
  })
}

export const deleteCustomPromotion = (
  { commit, dispatch, state },
  promotionId
) => {
  const promotionToDelete = state.data.promotions[promotionId]
  commit(types.DELETE_CUSTOM_PROMOTION, promotionId)
  if (promotionToDelete.type === promotions.SALE_ITEM_MORE_FOR_LESS) {
    if (!promotionToDelete.product) return
    dispatch('updateMoreForLessPromotionsInSales', promotionToDelete.product)
  } else if (promotionToDelete.type === promotions.SALE_ITEM_COMBO) {
    dispatch('updateCombosPromotionsInSales', {
      combo: {
        ...promotionToDelete,
        deleted: 1,
      },
    })
  }
  commit(`app/${typesApp.ADD_APP_PENDING_SYNC_OP}`, null, {
    root: true,
  })
}

export const bulkCustomPromotionsDeletion = (
  { commit, state, dispatch },
  promotionsIdsToDelete
) => {
  promotionsIdsToDelete.forEach(promotionId => {
    if (
      state.data.promotions[promotionId].type === promotions.SALE_ITEM_COMBO
    ) {
      dispatch('updateCombosPromotionsInSales', {
        combo: { ...state.data.promotions[promotionId], deleted: 1 },
        fromProductDeleted: true,
      })
    }
  })
  commit(types.BULK_CUSTOM_PROMOTIONS_DELETION, promotionsIdsToDelete)
  commit(`app/${typesApp.ADD_APP_PENDING_SYNC_OP}`, null, {
    root: true,
  })
}

export const disableCustomPromotion = (
  { commit, state, dispatch },
  promotionsId
) => {
  commit(types.DISABLE_CUSTOM_PROMOTION, promotionsId)
  promotionsId.forEach(promotionId => {
    const promotion = state.data.promotions[promotionId]
    if (promotion.type === promotions.SALE_ITEM_MORE_FOR_LESS) {
      dispatch('updateMoreForLessPromotionsInSales', promotion.product)
    } else if (promotion.type === promotions.SALE_ITEM_COMBO) {
      dispatch('updateCombosPromotionsInSales', { combo: promotion })
    }
  })
  commit(`app/${typesApp.ADD_APP_PENDING_SYNC_OP}`, null, {
    root: true,
  })
}

export const updateProduct = ({ commit, getters }, product) => {
  if (!getters.getCustomPromotionsByProduct[product.id]) return
  commit(types.UPDATE_PRODUCT, {
    promotionsToUpdate: getters.getCustomPromotionsByProduct[product.id],
    product,
  })
}

export const updateMoreForLessPromotionsInSales = (
  { rootState, dispatch },
  product
) => {
  rootState.sales.sales.forEach((sale, ticketIndex) => {
    const productIndex = sale.items.findIndex(item => item.id === product.id)
    if (productIndex < 0) return
    dispatch(
      'sales/updateProductFromSale',
      {
        productIndex,
        ticketIndex,
        newData: sale.items[productIndex],
      },
      { root: true }
    )
  })
}

export const updateCombosPromotionsInSales = (context, data) => {
  const { rootState, dispatch } = context
  const { combo, fromProductDeleted } = data
  const sales = rootState.sales.sales
  sales.forEach((sale, ticketIndex) => {
    deleteCombosOnSalesAndUpdateProducts(
      dispatch,
      sale,
      ticketIndex,
      combo,
      fromProductDeleted
    )
    sale.items.forEach((item, productsIndex) => {
      dispatch(
        'sales/updateProductFromSale',
        {
          productIndex: productsIndex,
          ticketIndex,
          newData: sale.items[productsIndex],
        },
        { root: true }
      )
    })
  })
}

const deleteCombosOnSalesAndUpdateProducts = (
  dispatch,
  sale,
  ticketIndex,
  combo,
  fromProductDeleted
) => {
  const comboIndex = sale.promotions.findIndex(promo => promo.id === combo.id)
  if (comboIndex >= 0) {
    dispatch(
      'sales/deleteCombosAndUpdateProducts',
      {
        ticketIndex,
        comboIndex,
        fromProductDeleted,
      },
      { root: true }
    )
  }
}

const getCustomPromotionMapped = promotion => {
  if (promotion.type === promotions.SALE_ITEM_MORE_FOR_LESS) {
    return mapStoreObject(getMoreForLessPromotion(promotion), promotionMapper)
  }
  const combo = getComboPromotion(promotion)
  return mapStoreObject(combo, promotionMapper)
}

const getMoreForLessPromotion = promotion => {
  let product = promotion.product
  if (promotion.products) product = promotion.products[0]
  return {
    ...promotion,
    promotions: promotion.promotions.map(promo => ({
      ...mapStoreObject(promo, moreForLessPromotion),
      promotionUnitPrice: Math.round(promo.total / promo.quantity),
    })),
    product: mapStoreObject(product, storeInventory),
  }
}

const getComboPromotion = promotion => {
  const products = promotion.products.map(prod =>
    mapStoreObject(prod, storeInventory)
  )
  return {
    ...promotion,
    total: promotion.promotions.total,
    promotions: getCombo(promotion.promotions, products),
  }
}

const getCombo = (promotions, products) => {
  if (Object.keys(promotions).length <= 0) return {}
  const { total } = promotions
  const firstProduct = products.find(
    prod => prod.id === promotions.first_product_id
  )
  const secondProduct = products.find(
    prod => prod.id === promotions.second_product_id
  )
  return {
    ...mapStoreObject(promotions, comboPromotionMapper),
    ...comboPromotion.getPromotionUnitPrices(
      firstProduct,
      secondProduct,
      total
    ),

    firstProduct,
    secondProduct,
  }
}
