import supportContact from '@/config/supportContact'

const getHelpContact = function() {
  let helpContact = supportContact[this.countryLocale]
  if (!helpContact) helpContact = supportContact.default
  return Object.keys(helpContact).reduce((text, key) => {
    if (text !== '') {
      text = `${text}<br>`
    }
    text = `${text}- ${this.getTranslatedText(`helpBot.${key}`)} <strong>${
      helpContact[key]
    }</strong>`
    return text
  }, '')
}

export default {
  getHelpContact,
}
