import { testMode } from '@/config/env'

import productsViewActions from '@/store/productsView/action.types'
import purchasesViewActions from '@/store/purchasesView/actions.types'
import salesViewActions from '@/store/salesView/actions.types'

export const getAppLayoutHeaderAndFooterHeight = view => {
  const container = document.getElementById(view)
  const containerPadding = getComputedStyle(container).padding
  const appMenuHeight = document.getElementById('app-menu').offsetHeight
  const footerMenuHeight = document.getElementById('app-footer').offsetHeight

  return parseInt(containerPadding) * 2 + appMenuHeight + footerMenuHeight
}

export const applyWinClass = customClass =>
  process.platform !== 'darwin' ? customClass : null

export const getViewStore = routeName => {
  if (testMode) return 'productsView'
  switch (routeName) {
    case 'Products':
      return 'productsView'
    case 'Purchases':
      return 'purchasesView'
    case 'Sales':
      return 'salesView'
    case 'CustomPromotions':
      return 'customPromotionsView'
  }
}

export const getActionsTypes = routeName => {
  switch (getViewStore(routeName)) {
    case 'productsView':
      return productsViewActions
    case 'purchasesView':
      return purchasesViewActions
    case 'salesView':
      return salesViewActions
  }
}
