<template>
  <div>
    <v-text-field
      v-if="readonly"
      v-model="account"
      :class="['custom-text-field', className]"
      :label="getTranslatedText(label)"
      :append-icon="icon"
      filled
      rounded
      dense
      :readonly="true"
    />
    <v-text-field
      v-else
      v-model="account"
      :class="['custom-text-field', className]"
      :label="getTranslatedText(label)"
      :append-icon="icon"
      filled
      rounded
      dense
      :error-messages="onValidateAccount"
      @input="v.$reset()"
      @blur="v.$touch()"
      required
      :readonly="false"
      :autofocus="autofocus"
    />
  </div>
</template>

<script>
import { has } from 'ramda'

export default {
  name: 'AccountInput',
  props: {
    value: {
      required: true,
    },
    v: {
      type: Object,
    },
    className: {
      type: String,
      default: '',
    },
    readonly: {
      type: Boolean,
      default: false,
    },
    autofocus: {
      type: Boolean,
      default: false,
    },
    label: {
      type: String,
      default: 'starterLayout.login.account',
    },
    icon: {
      type: String,
      default: 'mdi-account-circle-outline',
    },
  },
  computed: {
    account: {
      get() {
        return this.value
      },
      set(newValue) {
        this.$emit('input', newValue)
      },
    },
    onValidateAccount() {
      const errors = []
      if (this.v === undefined || !this.v.$dirty) return errors
      has('required')(this.v) &&
        !this.v.required &&
        errors.push(
          this.getTranslatedText('starterLayout.login.accountRequired')
        )
      has('email')(this.v) &&
        !has('numericAccount')(this.v) &&
        !this.v.email &&
        errors.push(
          this.getTranslatedText('starterLayout.login.accountEmailNoValid')
        )
      if (this.account.includes('@')) {
        has('email')(this.v) &&
          !this.v.email &&
          errors.push(
            this.getTranslatedText('starterLayout.login.accountEmailNoValid')
          )
      } else {
        if (
          (has('numericAccount')(this.v) && !this.v.numericAccount) ||
          (has('maxLength')(this.v) && !this.v.maxLength)
        )
          errors.push(
            this.getTranslatedText('starterLayout.login.accountNumericNoValid')
          )
      }
      return errors
    },
  },
  methods: {
    getTranslatedText: function(translateString) {
      return this.$vuetify.lang.t(`$vuetify.${translateString}`)
    },
  },
}
</script>
