import mutationsTypes from './mutations.types'

export const setSupplierSearchTerm = ({ commit }, payload) =>
  commit(mutationsTypes.SET_SUPPLIERS_SEARCH_TERM_FILTER, payload)

export const setVendorSearchTerm = ({ commit }, payload) =>
  commit(mutationsTypes.SET_VENDORS_SEARCH_TERM_FILTER, payload)

export const setSelectedSupplier = ({ commit }, payload) =>
  commit(mutationsTypes.SET_SELECTED_SUPPLIER, payload)

export const setSelectedVendor = ({ commit }, payload) =>
  commit(mutationsTypes.SET_SELECTED_VENDOR, payload)

export const toggleAddVendorDialog = ({ commit }) =>
  commit(mutationsTypes.SET_ADD_VENDOR_DIALOG_STATUS)

export const toggleVendorDetailDialog = ({ commit }) =>
  commit(mutationsTypes.SET_VENDOR_DETAIL_DIALOG_STATUS)

export const togglePurchaseDraftDialog = ({ commit }, payload) => {
  commit(mutationsTypes.SET_PURCHASE_DRAFT_DIALOG_STATUS)
  commit(
    mutationsTypes.SET_PURCHASE_DRAFT,
    payload?.purchase ? payload.purchase : null
  )
  commit(
    mutationsTypes.SET_PURCHASE_DRAFT_OLD,
    payload?.purchaseOld ? payload.purchaseOld : null
  )
}

export const updateSelectedVendorField = ({ commit }, payload) =>
  commit(mutationsTypes.UPDATE_SELECTED_VENDOR_FIELD, payload)

export const setDeleteVendorDialogStatus = ({ commit }, payload) =>
  commit(mutationsTypes.SET_DELETE_VENDOR_DIALOG_STATUS, payload)

export const setSettleCreditPurchaseDialogStatus = async ({ commit }, data) => {
  commit(
    mutationsTypes.SET_PURCHASE_TO_SETTLE_DEBT,
    data.isOpen ? data.purchase : null
  )
  commit(mutationsTypes.SET_SETTLE_CREDIT_PURCHASE_DIALOG_STATUS, data.isOpen)
}

export const toggleSettleDebtDialogStatus = ({ commit }, payload) =>
  commit(mutationsTypes.SET_SETTLE_DEBT_DIALOG_STATUS, payload)

export const toggleRepeatPurchaseConfirmDialog = ({ commit }, payload) => {
  commit(mutationsTypes.SET_CONFIRM_REPEAT_PURCHASE_DIALOG_STATUS)
  commit(mutationsTypes.SET_PURCHASE_SELECTED, payload ? payload : null)
}
