import {
  maxLength,
  minLength,
  required,
  sameAs,
} from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-account-key',
    title: 'preferences.changePasswordDialog.title',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    messages: ['preferences.changePasswordDialog.text'],
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    height: 360,
    maxWidth: 600,
    id: 'change-password-form',
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: state.routeName,
        screen: 'ChangePasswordDialog',
        name: 'Cancel',
      })
      methods.closeDialog()
    },
    onClickAccept: () => methods.changePassword(),
  },
  fields: [
    {
      id: 'password',
      type: 'password',
      validators: {
        required,
        maxLength: maxLength(30),
        minLength: minLength(4),
      },
      autofocus: true,
      label: 'preferences.changePasswordDialog.newPassword',
    },
    {
      id: 'repeatPassword',
      type: 'password',
      validators: {
        required,
        sameAsPassword: sameAs('password'),
        maxLength: maxLength(30),
        minLength: minLength(4),
      },
      label: 'preferences.changePasswordDialog.repeatPassword',
    },
  ],
  id: 'change-password-form',
})

export default setConfig
