import paymentMethods from '@/config/paymentMethods'

import types from '@/store/sales/mutations.types'
import {
  getProductIndex,
  getPromotionSaleIndex,
} from '@/store/sales/actions.tools'
import {
  applyComboPromotions,
  updateSaleItemsFromDeletedCombos,
} from '@/store/sales/actions.combo.tools'
import { getMoreForLessPromotions } from '@/store/sales/actions.moreForLess.tools'

export const addSale = ({ commit }, payload) => commit(types.ADD_SALE, payload)

export const addProductToCurrentSale = async (context, payload) => {
  const { commit, rootGetters, state, dispatch } = context
  const { currentSale, product, fromApplyCombo } = payload
  const productIndex = getProductIndex(state.sales[currentSale], product.upc)
  if (productIndex < 0) {
    commit(types.ADD_PRODUCT_TO_CURRENT_SALE, {
      currentSale,
      product: {
        ...product,
        promotions: getMoreForLessPromotions(
          rootGetters,
          state.sales[currentSale],
          product
        ),
      },
      fnArray: payload.fnArray,
    })
    if (!fromApplyCombo) {
      applyComboPromotions(context, currentSale)
    }
    return
  }
  let productToUpdate = product
  if (product.isGramaje !== 1 && product.isGeneric !== 1) {
    productToUpdate = {
      ...state.sales[currentSale].items[productIndex],
      quantity: state.sales[currentSale].items[productIndex].quantity + 1,
    }
  }
  if (product.isGeneric === 1) {
    productToUpdate.unitPrice =
      state.sales[currentSale].items[productIndex].unitPrice + product.unitPrice
  }
  dispatch('updateProductFromSale', {
    ticketIndex: currentSale,
    newData: productToUpdate,
    productIndex,
  })
  if (!fromApplyCombo) {
    applyComboPromotions(context, currentSale)
  }
}

export const updateProductQuantity = async (
  { commit, rootGetters, state },
  payload
) => {
  const { ticketIndex, upcProduct } = payload
  const productIndex = getProductIndex(state.sales[ticketIndex], upcProduct)
  const productUpdated = {
    ...state.sales[ticketIndex].items[productIndex],
    quantity: payload.quantity,
  }
  await commit(types.UPDATE_PRODUCT_FROM_SALE, {
    saleIndex: ticketIndex,
    productIndex,
    product: {
      ...productUpdated,
      promotions: getMoreForLessPromotions(
        rootGetters,
        state.sales[ticketIndex],
        productUpdated
      ),
    },
  })
}

export const updatePayOptionStatus = (context, payload) => {
  const { commit, state, dispatch } = context
  commit(types.UPDATE_PAY_OPTION_STATUS, payload)
  if (!paymentMethods.isOwnerSale(payload.payOption)) {
    applyComboPromotions(context, payload.ticketIndex)
  }
  updateProductPromotions({ state, dispatch }, payload.ticketIndex)
}

export const updatePrintTicketStatus = ({ commit }, payload) =>
  commit(types.UPDATE_PRINT_TICKET_OPTION_STATUS, payload)

export const updateCustomerSelected = ({ commit }, payload) =>
  commit(types.UPDATE_CUSTOMER_SELECTED, payload)

export const updateProductFromSale = (context, payload) => {
  const { commit, rootGetters, state } = context
  const { ticketIndex, newData: product } = payload
  let productIndex = payload.productIndex
  if (productIndex === undefined) {
    const findBy = 'uniqueId' in product ? 'uniqueId' : 'upc'
    productIndex = getProductIndex(
      state.sales[ticketIndex],
      product[findBy],
      findBy
    )
  }
  commit(types.UPDATE_PRODUCT_FROM_SALE, {
    saleIndex: ticketIndex,
    productIndex,
    product: {
      ...product,
      openProductType: Number(product.openProductType),
      promotions: getMoreForLessPromotions(
        rootGetters,
        state.sales[ticketIndex],
        {
          ...state.sales[ticketIndex].items[productIndex],
          ...product,
          openProductType: Number(product.openProductType),
        }
      ),
    },
  })
  applyComboPromotions(context, ticketIndex)
}

export const removeSale = ({ commit }, payload) =>
  commit(types.REMOVE_SALE, payload)

export const removeProductFromSale = ({ commit }, payload) =>
  commit(types.REMOVE_PRODUCT_FROM_SALE, payload)

export const resetSale = ({ commit, state }, payload) => {
  commit(types.RESET_SALE, payload.ticketIndex)
  if (payload.customer) {
    state.sales.forEach((sale, index) => {
      if (sale.customer && sale.customer.id == payload.customer.id)
        commit(types.UPDATE_CUSTOMER_SELECTED, {
          customer: payload.customer,
          ticketIndex: index,
        })
    })
  }
}

export const removeProductFromAllSales = ({ commit, state }, payload) => {
  state.sales.forEach((sale, index) =>
    commit(types.REMOVE_PRODUCT_FROM_SALE, {
      upcProduct: payload.product.upc,
      ticketIndex: index,
    })
  )
}

export const updateProductsFieldsFromAllSales = ({ commit }, payload) =>
  commit(types.UPDATE_PRODUCTS_FIELDS_FROM_ALL_SALES, payload)

export const addCashAmount = ({ commit }, payload) =>
  commit(types.ADD_CASH_AMOUNT, payload)

export const updatePromotionTicket = (context, payload) => {
  const { commit, state, dispatch } = context
  commit(types.UPDATE_PROMOTION_TICKET, payload)
  updateProductPromotions({ state, dispatch }, payload.ticketIndex)
  applyComboPromotions(context, payload.ticketIndex)
}

export const resetSaleProductsPromotion = ({ commit }, ticketIndex) =>
  commit(types.RESET_SALE_PRODUCTS_PROMOTION, ticketIndex)

const updateProductPromotions = ({ state, dispatch }, ticketIndex) => {
  state.sales[ticketIndex].items.forEach((product, index) => {
    dispatch('updateProductFromSale', {
      ticketIndex,
      newData: product,
      productIndex: index,
    })
  })
}

export const updateSaleName = ({ commit }, payload) =>
  commit(types.UPDATE_SALE_NAME, payload)

export const updateSalePromotionsQuantity = (
  { state, commit },
  { ticketIndex, promotion, quantity }
) => {
  const indexFound = getPromotionSaleIndex(state.sales[ticketIndex], promotion)
  if (indexFound < 0) return
  const quantityToUpdate =
    state.sales[ticketIndex].promotions[indexFound].quantity + quantity
  if (quantityToUpdate < 1) return
  state.sales[ticketIndex].promotions[indexFound].quantity = quantityToUpdate
  commit(types.UPDATE_SALE_PROMOTIONS, {
    ticketIndex,
    salePromotions: state.sales[ticketIndex].promotions,
  })
}

export const deleteSalePromotions = (
  { state, commit },
  { ticketIndex, promotion, indexPromotionSale }
) => {
  const indexFound =
    indexPromotionSale ||
    getPromotionSaleIndex(state.sales[ticketIndex], promotion)
  if (indexFound < 0) return
  state.sales[ticketIndex].promotions.splice(indexFound, 1)
  commit(types.UPDATE_SALE_PROMOTIONS, {
    ticketIndex,
    salePromotions: state.sales[ticketIndex].promotions,
  })
}

export const deleteCombosAndUpdateProducts = (
  context,
  { ticketIndex, comboIndex, fromProductDeleted }
) => {
  const { state, commit } = context
  updateSaleItemsFromDeletedCombos(
    context,
    [state.sales[ticketIndex].promotions[comboIndex]],
    ticketIndex,
    fromProductDeleted
  )
  state.sales[ticketIndex].promotions.splice(comboIndex, 1)
  commit(types.UPDATE_SALE_PROMOTIONS, {
    ticketIndex,
    salePromotions: state.sales[ticketIndex].promotions,
  })
}
