export const finishSale = async ({ commit }, data) => {
  data.itemsToUpdate.forEach(item =>
    commit(`products/${typesProducts.UPDATE_PRODUCT_STOCK}`, item, {
      root: true,
    })
  )
  if (data.customer) {
    logger('info', 'Updating the customer in the store') // To investigate balance discrepancy errors. Delete it in the future
    commit(`customers/${typesCustomers.UPDATE_CUSTOMER}`, data.customer, {
      root: true,
    })
  }
  if (data.estimatedCash) {
    commit(
      `usersView/${typesUsersView.SET_USER_ESTIMATED_CASH}`,
      formatNumberFromDb(data.estimatedCash),
      { root: true }
    )
  }

  commit(types.SET_SALE_STATUS, false)
  logger('info', `Sale finished`)
}

export const toggleDetailDialog = ({ commit, state }) => {
  if (!state.productDetailDialog.isOpen) {
    if (state.productTriangulationDialog.isOpen) {
      commit(types.TOGGLE_PRODUCT_TRIANGULATION_DIALOG_STATUS)
    }
  }
  commit(types.SET_DETAIL_DIALOG_STATUS)
}

