export const setGroupFilter = (context, payload) => {
  const existByWeightTree =
    context.rootState.products.data.byWeightTree.length > 0 ? true : false
  context.commit(types.SET_GROUP_FILTER, payload)
  context.commit(types.UPDATE_CARD_COMPONENT, existByWeightTree)
}

