const validations = [
  'required',
  'minValue',
  'maxValue',
  'maxDecimals',
  'integer',
  'maxLength',
  'email',
  'sameAs',
  'numericAccount',
  'validatePhoneNumber',
]

export const validate = (
  inputs,
  property,
  translation,
  customValidation = []
) => {
  const errors = []
  if (!Object.hasOwn(inputs, property) || !inputs[property].$dirty) {
    return errors
  }
  const key = translation.key || 'shared.formError'
  validations.forEach(validation => {
    if (
      Object.hasOwn(inputs[property], validation) &&
      !inputs[property][validation]
    ) {
      const message = translation.message || `${key}.${validation}`
      errors.push(translation.fn(`${message}`))
    }
  })
  customValidation.forEach(validation => {
    if (
      Object.hasOwn(inputs[property], validation.name) &&
      !inputs[property][validation.name]
    ) {
      errors.push(translation.fn(validation.error))
    }
  })
  return errors
}
