import types from '@/store/airtimeServices/mutations.types'

const setBalance = (state, payload) => {
  state.balance.amount = payload
}

const setBanks = (state, payload) => {
  state.banks = payload
}

const setAirtimeServicesBalanceDialogStatus = (state, payload) => {
  state.addAirtimeServicesBalanceDialog.isOpen = payload
}

const setBalanceFetching = (state, payload) =>
  (state.balance.fetching = payload)

const setBalanceFetchingError = state => (state.balance.fetching = true)

export default {
  [types.SET_AIRTIME_SERVICES_BALANCE]: setBalance,
  [types.SET_AIRTIME_SERVICES_BANKS]: setBanks,
  [types.SET_ADD_AIRTIME_SERVICES_BALANCE_DIALOG_STATUS]: setAirtimeServicesBalanceDialogStatus,
  [types.SET_AIRTIME_BALANCE_FETCHING]: setBalanceFetching,
  [types.SET_AIRTIME_BALANCE_FETCHING_ERROR]: setBalanceFetchingError,
}
