export const setProductsOrSuperCategoriesFetching = ({ commit }, payload) =>
  commit(mutationsTypes.SET_PRODUCTS_OR_SUPER_CATEGORIES_FETCHING, payload)

export const setProductsOrSuperCategoriesError = ({ commit }, payload) =>
  commit(mutationsTypes.SET_PRODUCTS_OR_SUPER_CATEGORIES_ERROR, payload)

export const fetchProducts = ({ commit, state }, data) => {
  // TODO: Create a new test suite
  const storeInventoryData = data.storeInventory
  const genericsData = data.genericCategories
  const superCategoriesData = data.superCategories.map(item =>
    mapStoreObject(item, superCategories)
  )
  const airtimeServicesData = data.airtimeServices.map(item =>
    mapStoreObject(item, airtimeServices)
  )
  const productsData = storeInventoryData.map(item => {
    const product = mapStoreObject(item, storeInventory)
    const genericCategory = genericsData.find(
      generic => generic.barcode === product.upc
    )
    if (genericCategory) {
      product['image'] = genericCategory.image
      genericsData.splice(genericsData.indexOf(genericCategory), 1)
    }
    product['isStoreInventory'] = 1
    product['isOpenGramaje'] = isOpenGramaje(product)
    setOpenProductStocks(product)
    return product
  })
  genericsData.forEach(generic => {
    productsData.push(getNotInventoryGenericProduct(generic))
  })
  data.byWeightTree.forEach(category => {
    const fakeProduct = createByWeightCategoryProductFake(
      category,
      category.id * -1
    )
    productsData.push(fakeProduct)
  })
  const pieceUPCs = new Set(
    productsData.filter(p => p.isGramaje === 0).map(p => p.upc)
  )
  data.byWeightTree = data.byWeightTree.map(category => ({
    ...category,
    children: category.children.map(child => ({
      ...child,
      children: child.children.map(grandChild => {
        return {
          ...grandChild,
          visible: !pieceUPCs.has(grandChild.upc),
        }
      }),
    })),
  }))

  data.airtimeProviders.forEach(provider => {
    const airtimeProviderServices = airtimeServicesData.filter(
      service => service.providerId === provider.provider_id
    )
    productsData.push(
      getNotInventoryProvidersProduct(provider, airtimeProviderServices)
    )
  })
  commit(mutationsTypes.SET_SUPER_CATEGORIES, superCategoriesData)
  commit(mutationsTypes.SET_PRODUCTS, productsData)
  commit(mutationsTypes.SET_BY_WEIGHT_TREE, data.byWeightTree)
  commit(mutationsTypes.SET_PRODUCTS_OR_SUPER_CATEGORIES_FETCHING, false)
  updateSimilarProduct({ commit, state })
  return { success: true }
}

export const updateSimilarProduct = ({ commit, state }) => {
  const productsMatch = {}
  state.data.products.forEach(product => {
    const upc = upcTools.deleteInitialZeros(product.upc)
    if (productsMatch[product.id] || upc.length <= 4) return
    const regex = upcTools.getRegex(upc)
    const matches = state.data.products.filter(
      prod =>
        upcTools.availableProduct(prod) &&
        prod.id !== product.id &&
        regex.test(prod.upc)
    )
    if (matches.length) {
      matches.push(product)
      matches.forEach(prod => {
        productsMatch[prod.id] = matches.reduce((matchesId, match) => {
          if (match.id !== prod.id) {
            matchesId.push(match.id)
          }
          return matchesId
        }, [])
      })
    }
  })
  commit(mutationsTypes.SET_PRODUCTS_SIMILAR_UPC, productsMatch)
}

export const editProductField = (context, data) => {
  context.commit(`app/${typesApp.ADD_APP_PENDING_SYNC_OP}`, null, {
    root: true,
  })
  const product = mapStoreObject(data, storeInventory)
  product['isStoreInventory'] = 1
  product['isOpenGramaje'] = isOpenGramaje(product)
  setOpenProductStocks(product)
  context.commit(mutationsTypes.UPDATE_PRODUCT, product)
  const productForSale = {
    upc: product.upc,
    newStock: product.quantity,
    cost: product.cost,
  }
  context.commit(
    `sales/${salesMutationsTypes.UPDATE_PRODUCTS_FIELDS_FROM_ALL_SALES}`,
    [productForSale],
    { root: true }
  )
  context.dispatch(
    `customPromotions/${customPromotionsActionsTypes.updateProduct}`,
    product,
    { root: true }
  )
  logger('info', 'Product field updated')
}

export const updateProductByProperties = ({ commit, dispatch }, data) => {
  const product = mapStoreObject(data, storeInventory)
  setOpenProductStocks(product)
  commit(mutationsTypes.UPDATE_PRODUCT_BY_PROPERTIES, product)
  dispatch(
    `customPromotions/${customPromotionsActionsTypes.updateProduct}`,
    product,
    {
      root: true,
    }
  )
  logger('info', 'Product updated')
}

export const updateByWeightTree = ({ commit }, data) => {
  commit(mutationsTypes.UPDATE_BY_WEIGHT_TREE, data)
}

export const removeProduct = (context, productId) => {
  context.commit(mutationsTypes.REMOVE_PRODUCT, productId)
  logger('info', 'Product deleted')
}

export const addProductFromMLP = ({ commit, state }, data) => {
  const { newProduct, currentView, fromImportInventory } = data
  setOpenProductStocks(newProduct)
  commit(mutationsTypes.SET_PRODUCT, newProduct)
  if (!fromImportInventory) {
    updateSimilarProduct({ commit, state })
  }
  if (currentView === 'productsView') {
    commit(
      `productsView/${productsViewMutationsTypes.SET_SELECTED_PRODUCT}`,
      newProduct,
      { root: true }
    )
    commit(
      `productsView/${productsViewMutationsTypes.SET_DETAIL_DIALOG_STATUS}`,
      true,
      { root: true }
    )
  }
  commit(mutationsTypes.SET_PRODUCTS_OR_SUPER_CATEGORIES_FETCHING, false)
  commit(`app/${typesApp.ADD_APP_PENDING_SYNC_OP}`, null, { root: true })
  logger('info', 'Product added to the inventory from the MLP')
}

export const addNewProduct = ({ commit, dispatch, state }, data) => {
  const {
    newProduct,
    currentView,
    index,
    fromReturnProductDialog = false,
  } = data
  commit(mutationsTypes.SET_PRODUCT, newProduct)
  updateSimilarProduct({ commit, state })
  switch (currentView) {
    case 'productsView':
      commit(
        `productsView/${productsViewMutationsTypes.SET_SELECTED_PRODUCT}`,
        newProduct,
        { root: true }
      )
      commit(
        `productsView/${productsViewMutationsTypes.SET_DETAIL_DIALOG_STATUS}`,
        null,
        { root: true }
      )
      break
    case 'salesView': {
      const productToSale = {
        currentSale: index,
        product: {
          uniqueId: uniqid(),
          id: newProduct.id,
          stock: newProduct.quantity,
          isGramaje: newProduct.isGramaje === 1 ? 1 : 0,
          isOpenProduct: newProduct.factor > 0 ? 1 : 0,
          isGeneric: newProduct.isGeneric === 1 ? 1 : 0,
          isPriceChanged: 1,
          openProductType: 0,
          openProductDbPrices: {
            package: newProduct.price,
            piece: null,
          },
          isPiecePriceChanged: 0,
          name: newProduct.name,
          quantity: !isNil(newProduct.amount) ? parseInt(newProduct.amount) : 1,
          unitPrice: newProduct.price,
          cost: newProduct.cost,
          upc: newProduct.upc,
          timeAdded: getNow(false),
          priceFrom: productsTools.getAddedFrom(newProduct),
          dbPrice: newProduct.price,
          levelWarning: 5,
          factor: newProduct.factor,
          promotionTypeId: promotions.NONE,
        },
      }
      dispatch(`sales/${salesActions.addProductToCurrentSale}`, productToSale, {
        root: true,
      })
      break
    }
    case 'purchasesView': {
      if (fromReturnProductDialog) return
      const productToPurchase = {
        purchaseOrderId: index,
        uniqueId: uniqid(),
        id: newProduct.id,
        stock: newProduct.quantity,
        isGramaje: newProduct.isGramaje === 1 ? 1 : 0,
        isOpenProduct: newProduct.factor > 0 ? 1 : 0,
        openProductType: newProduct.factorSalesBy,
        openProductDbPrices: {
          package: newProduct.price,
          piece: null,
        },
        isGeneric: newProduct.isGeneric === 1 ? 1 : 0,
        isPriceChanged: 0,
        name: newProduct.name,
        quantity: !isNil(newProduct.amount) ? parseInt(newProduct.amount) : 1,
        unitPrice: newProduct.price,
        iva: 0,
        cost: 0,
        upc: newProduct.upc,
        timeAdded: getNow(false),
        priceFrom: productsTools.getAddedFrom(newProduct),
        dbPrice: newProduct.price,
        levelWarning: newProduct.levelWarning,
        factor: newProduct.factor,
        promotionTypeId: promotions.NONE,
        promotionExtra: 0,
        costWithoutTaxAndPromotion: 0,
        discountPercent: 0,
        discountAmount: 0,
      }
      commit(
        `purchasesView/${purchasesMutationsTypes.SET_SELECTED_PRODUCT}`,
        { product: productToPurchase },
        { root: true }
      )
      commit(
        `purchasesView/${purchasesMutationsTypes.SET_PRODUCT_TRIANGULATION_DIALOG_STATUS}`,
        true,
        { root: true }
      )
    }
  }
  commit(mutationsTypes.SET_PRODUCTS_OR_SUPER_CATEGORIES_FETCHING, false)
  commit(`app/${typesApp.ADD_APP_PENDING_SYNC_OP}`, true, { root: true })
  logger('info', 'Product added to the inventory')
}

export const setProductsState = ({ commit }, data) =>
  commit(mutationsTypes.SET_PRODUCT, data)

export const setMlpFilteredProducts = ({ commit }, data) => {
  const mlpProductsData = map(item => {
    const product = mapStoreObject(item, storeInventory)
    const category = categories.find(el => el.id === product.categoryId)
    product['isStoreInventory'] = 0
    product['categoryName'] = !isNil(category)
      ? category.superCategory
      : 'other'
    return product
  }, data)
  commit(mutationsTypes.SET_MLP_FILTERED_PRODUCTS, { data: mlpProductsData })
}

export const resetMlpFilteredProducts = ({ commit }) =>
  commit(mutationsTypes.SET_MLP_FILTERED_PRODUCTS, { data: [] })

export const removeProductFromMlpData = ({ commit }, data) => {
  commit(mutationsTypes.REMOVE_ITEM_FROM_MLP_FILTERED_PRODUCTS, data)
}

const setOpenProductStocks = product => {
  if (product.factor < 1) return
  const { quantity, factor } = product
  product['piecesQuantity'] = getPiecesStockValue(quantity, factor)
  product['packagesQuantity'] = getPackagesStockValue(quantity, factor)
}

export const setByWeightTree = ({ commit }, data) =>
  commit(mutationsTypes.SET_BY_WEIGHT_TREE, data)

export const bulkProductDeletion = ({ commit }, data) => {
  commit(mutationsTypes.BULK_PRODUCT_DELETION, data)
  commit(`app/${typesApp.ADD_APP_PENDING_SYNC_OP}`, true, { root: true })
}

const isOpenGramaje = product => {
  const { isGramaje, isGramajeFromMLP } = product
  return isGramaje || isGramajeFromMLP
}
