export const promotions = {
  NONE: 0,
  PURCHASE_ITEM_FREE_UNITS: 11,
  PURCHASE_ITEM_SUBTOTAL_DISCOUNT: 12,
  PURCHASE_ITEM_FREE_PRODUCT: 13,
  PURCHASE_TICKET_DISCOUNT: 14,
  SALE_ITEM_OTHER_PRICE_BY_WEIGHT: 1,
  SALE_ITEM_OTHER_PRICE: 4,
  SALE_TICKET_DISCOUNT: 20,
  SALE_TICKET_AT_COST: 21,
  SALE_ITEM_FREE_PRODUCT: 22,
  SALE_ITEM_MORE_FOR_LESS: 23,
  SALE_ITEM_COMBO: 24,
}

export const getPurchasePriceWithoutPromotion = async (
  databaseAPI,
  item,
  purchase
) => {
  switch (item.promotion_type_id) {
    case promotions.PURCHASE_ITEM_SUBTOTAL_DISCOUNT:
      return item.promotion_extra
    case promotions.PURCHASE_ITEM_FREE_PRODUCT:
      return await getCostFromStoreInventory(databaseAPI, item)
    case promotions.PURCHASE_ITEM_FREE_UNITS:
      return getCostWithoutFreeUnits(item, purchase)
    case promotions.PURCHASE_TICKET_DISCOUNT:
      return getCostWithoutPromotionTicket({
        itemCost: item.purchase_price,
        ticketCost: purchase.cost,
        promotion: purchase.promotion,
      })
    default:
      return item.purchase_price
  }
}

export const getSalePriceWithoutPromotion = (item, sale) => {
  if (
    item.promotion_type_id === promotions.SALE_TICKET_AT_COST ||
    item.promotion_type_id === promotions.SALE_ITEM_FREE_PRODUCT
  ) {
    return item.promotion_extra
  }
  return getCostWithoutPromotionTicket({
    itemCost: item.sales_price,
    ticketCost: sale.final_price,
    promotion: sale.promotion,
  })
}

const getCostFromStoreInventory = async (databaseAPI, item) => {
  try {
    const inventoryItem = (
      await databaseAPI.storeInventory.getById(item.product_id)
    ).data
    if (!inventoryItem) return 0
    return inventoryItem.prod_cost
  } catch (e) {
    return 0
  }
}

const getCostWithoutFreeUnits = (item, purchase) => {
  const cost = Math.round(
    ((item.purchase_quantity + item.promotion_extra) * item.purchase_price) /
      item.purchase_quantity
  )
  return getCostWithoutPromotionTicket({
    itemCost: cost,
    ticketCost: purchase.cost,
    promotion: purchase.promotion,
  })
}

export const getCostWithoutPromotionTicket = data => {
  const { itemCost, ticketCost, promotion, unitCost } = data
  if (promotion <= 0) {
    return itemCost
  }
  const discountPercent = (promotion * 100) / (ticketCost + promotion)
  if (discountPercent === 100) return unitCost
  return Math.round(itemCost / (1 - discountPercent / 100))
}

