import types from './mutations.type'

export const setVideoFetching = ({ commit }, payload) =>
  commit(types.SET_VIDEOS_FETCHING, payload)

export const fetchVideos = async ({ commit }, payload) => {
  commit(types.SET_VIDEOS, payload.videos)
  commit(types.SET_VIDEO_TYPES, payload.videoTypes)
  commit(types.SET_VIDEOS_FETCHING, false)
}
export const fetchVideoTypes = async ({ commit }, payload) =>
  commit(types.SET_VIDEO_TYPES, payload)

export const setVideoError = ({ commit }, error) =>
  commit(types.SET_VIDEOS_ERROR, error.message)
