import { filter } from 'ramda'

import productsConfig from '@/config/products'

import { normalizeString } from '@/tools/data'
import upcTools from '@/tools/upc'

import router from '@/router'

export const filterBy = {
  searchTerm: (searchTerm, products, isScannerActive) => {
    const normalizedSearchTerm = normalizeString(searchTerm)
    return filter(
      isScannerActive === true
        ? item =>
            item.isGeneric === 0 &&
            item.airTime === 0 &&
            (normalizeString(item.name).includes(normalizedSearchTerm) ||
              item.upc.toString() === searchTerm) &&
            item.upc !== productsConfig.BY_WEIGHT_CATEGORIES_UPC
        : item =>
            item.isGeneric === 0 &&
            item.airTime === 0 &&
            (normalizeString(item.name).includes(normalizedSearchTerm) ||
              item.upc.toString().includes(searchTerm)) &&
            item.upc !== productsConfig.BY_WEIGHT_CATEGORIES_UPC,
      products
    )
  },
  group: (group, products, args = {}) => {
    const currentView = router.history.current.name
    switch (group) {
      case 'all':
        return filter(item => getFilterAll(item), products)
      case 'search':
        return filter(item => getFilterAll(item), products)
      case 'favorites':
        return filter(
          item => item.isStarred === 1 && item.isGeneric === 0,
          products
        )
      case 'services':
        return filter(item => item.airTime > 0, products)
      case 'byWeight':
        return ['Sales', 'Purchases'].includes(currentView) &&
          args.existByWeightTree
          ? filter(item => item.id < -1, products)
          : filter(
              item =>
                item.isGramaje === 1 &&
                item.upc !== productsConfig.BY_WEIGHT_CATEGORIES_UPC,
              products
            )
      case 'superCategories':
        return args.selectedSuperCategories.length === 0
          ? filter(
              item =>
                item.isGeneric === 0 &&
                item.airTime !== 1 &&
                item.upc !== productsConfig.BY_WEIGHT_CATEGORIES_UPC,
              products
            )
          : filter(item => {
              return (
                args.selectedSuperCategories.includes(item.categoryName) &&
                item.isGeneric === 0 &&
                item.airTime !== 1 &&
                item.upc !== productsConfig.BY_WEIGHT_CATEGORIES_UPC
              )
            }, products)
      case 'generics':
        return filter(
          item =>
            item.isGeneric === 1 &&
            item.upc !== productsConfig.BY_WEIGHT_CATEGORIES_UPC,
          products
        )
      case 'air-time':
        return filter(
          item =>
            item.airTime === 1 &&
            item.upc !== productsConfig.BY_WEIGHT_CATEGORIES_UPC &&
            item.upc !== productsConfig.AIRTIME_PRODUCT_UPC,
          products
        )
      case 'openProducts':
        return filter(item => item.factor > 0, products)
      case 'vendor': {
        if (args.vendorId < 0) return []
        return filter(
          item => item.vendorCode === args.vendorId && getFilterAll(item),
          products
        )
      }
      case 'noStock':
        return filter(
          item => getFilterAll(item) && item.quantity <= 0,
          products
        )
      case 'lowStock':
        return filter(
          item =>
            getFilterAll(item) &&
            item.quantity <= item.levelWarning &&
            item.quantity > 0,
          products
        )
      case 'promotions':
        return filter(
          item =>
            getFilterAll(item) &&
            !!args.promotionByProduct[item.id] &&
            args.promotionByProduct[item.id].some(promo => promo.active === 1),
          products
        )
      case 'productsSimilarUpc':
        return filter(
          item =>
            upcTools.availableProduct(item) &&
            !!args.productsSimilarUpc[item.id],
          products
        )
      default:
        return filter(
          item =>
            item.isGeneric === 0 &&
            item.upc !== productsConfig.BY_WEIGHT_CATEGORIES_UPC,
          products
        )
    }
  },
}

const getFilterAll = item => {
  return (
    item.isGeneric === 0 &&
    item.upc !== productsConfig.BY_WEIGHT_CATEGORIES_UPC &&
    item.upc !== productsConfig.AIRTIME_PRODUCT_UPC &&
    item.airTime !== 1
  )
}
