import types from './mutations.types'

export const toggleDetailDialog = ({ commit }) =>
  commit(types.SET_DETAIL_DIALOG_STATUS)

export const toggleAddProductDialog = ({ commit }) =>
  commit(types.SET_NEW_PRODUCT_DIALOG_STATUS)

export const setSelectedProduct = ({ commit }, payload) =>
  commit(types.SET_SELECTED_PRODUCT, payload)

export const updateSelectedProductField = ({ commit }, payload) =>
  commit(types.UPDATE_SELECTED_PRODUCT_FIELD, payload)

export const setViewType = ({ commit }, payload) =>
  commit(types.SET_VIEW_TYPE, payload)

export const setSearchTermFilter = ({ commit }, payload) =>
  commit(types.SET_SEARCH_TERM_FILTER, payload)

export const setGroupFilter = ({ commit }, payload) => {
  commit(types.SET_GROUP_FILTER, payload)
  commit(types.UPDATE_CARD_COMPONENT)
}

export const setSuperCategoriesFilter = ({ commit }, payload) =>
  commit(types.SET_SUPER_CATEGORIES_FILTER, payload)

export const setDeleteProductDialogStatus = ({ commit }, payload) =>
  commit(types.SET_DELETE_PRODUCT_DIALOG, payload)

export const setProductInSaleDialogStatus = ({ commit }, payload) =>
  commit(types.SET_PRODUCT_IN_SALE_DIALOG, payload)

export const setReportDialogStatus = ({ commit }, payload) =>
  commit(types.SET_REPORT_DIALOG_STATUS, payload)

export const setProductsTourEnabled = ({ commit }, payload) =>
  commit(types.SET_PRODUCTS_TOUR_ENABLED, payload)

export const setImportProductsDialog = ({ commit }, payload) =>
  commit(types.SET_IMPORT_PRODUCTS_DIALOG_STATUS, payload)

export const setItemsToDeleteInBulkDeletion = ({ commit }, items) =>
  commit(types.SET_ITEMS_TO_DELETE_IN_BULK_DELETION, items)

