<template>
  <div>
    <v-app-bar
      app
      color="mainBackground"
      height="52"
      flat
      absolute
      id="app-menu"
    >
      <v-app-bar-nav-icon
        @click="toggleSidebar"
        color="textPrimary"
      ></v-app-bar-nav-icon>

      <v-app-bar-nav-icon class="mr-1" v-if="sidebarOpened">
        <img src="../../assets/logos/Icono_PlayStore.svg" height="30px" />
      </v-app-bar-nav-icon>
      <div v-else>
        <v-btn
          v-for="item in menuItems"
          :key="item.name"
          text
          small
          :to="item.path"
          color="primary"
          :ref="item.name"
          v-track:click="{
            category: $route.name,
            screen: 'AppBar',
            name: `Go to ${item.name}`,
          }"
        >
          <FormattedText
            intl
            :value="`mainLayout.navigation['${item.name}']`"
            color="textPrimary"
          />
        </v-btn>
      </div>

      <v-spacer></v-spacer>
      <InfoBannerMenu :is-app-online="isAppOnline" />
      <!-- app state icons -->
      <div class="d-flex mx-4">
        <div class="mr-3">
          <v-icon>{{
            scanner.isActive === true
              ? 'mdi-barcode-scan'
              : 'mdi-keyboard-outline'
          }}</v-icon>
        </div>
        <div class="mr-3">
          <v-icon>
            {{ syncing ? 'mdi-autorenew mdi-spin' : 'mdi-autorenew ' }}
          </v-icon>
        </div>
        <div class="mr-3">
          <v-icon
            :color="isAppOnline ? '' : 'error'"
            :class="{ 'error-connection__icon': !isAppOnline }"
          >
            {{ isAppOnline ? 'mdi-cloud-check' : 'mdi-cloud-off-outline' }}
          </v-icon>
        </div>
        <div class="mr-3">
          <v-badge
            dot
            :value="notifications.length > 0"
            color="red"
            bordered
            overlap
            offset-y="5"
          >
            <v-btn
              icon
              text
              small
              :color="notifications.length > 0 ? 'primary' : ''"
            >
              <v-icon @click="showNotifications">{{
                notifications.length > 0 ? 'mdi-bell-ring' : 'mdi-bell'
              }}</v-icon>
            </v-btn>
          </v-badge>
        </div>
      </div>
      <!-- main app tools -->
      <div class="d-flex" id="main-app-tools">
        <!-- cash menu -->
        <v-tooltip bottom color="accent">
          <template v-slot:activator="{ on, attrs }">
            <div v-bind="attrs" v-on="on">
              <v-menu
                left
                bottom
                offset-y
                nudge-bottom="10"
                nudge-left="5"
                min-width="200"
                transition="slide-y-transition"
              >
                <template v-slot:activator="{ on }">
                  <v-btn
                    fab
                    small
                    elevation="0"
                    class="ml-"
                    v-on="on"
                    color="primary"
                  >
                    <v-icon>mdi-cash-register</v-icon>
                  </v-btn>
                </template>
                <v-list color="mainBackground">
                  <v-list-item-group color="primary" v-model="selectedCashTool">
                    <v-list-item
                      v-if="hasCashInOutPermission"
                      @click="openAddCashMovementDialog('moneyIn')"
                    >
                      <v-list-item-icon class="mr-3">
                        <v-icon>mdi-cash-plus</v-icon>
                      </v-list-item-icon>
                      <v-list-item-title>
                        <a>
                          <FormattedText
                            intl
                            value="mainLayout.user.moneyIn"
                            color="textPrimary"
                          />
                        </a>
                      </v-list-item-title>
                    </v-list-item>
                    <v-list-item
                      v-if="hasCashInOutPermission"
                      @click="openAddCashMovementDialog('moneyOut')"
                    >
                      <v-list-item-icon class="mr-3">
                        <v-icon>mdi-cash-minus</v-icon>
                      </v-list-item-icon>
                      <v-list-item-title>
                        <a>
                          <FormattedText
                            intl
                            value="mainLayout.user.moneyOut"
                            color="textPrimary"
                          />
                        </a>
                      </v-list-item-title>
                    </v-list-item>

                    <v-list-item @click="showAmountDialog">
                      <v-list-item-icon class="mr-3">
                        <v-icon>mdi-cash-lock</v-icon>
                      </v-list-item-icon>
                      <v-list-item-title>
                        <a>
                          <FormattedText
                            intl
                            value="mainLayout.user.closeRegister"
                            color="textPrimary"
                          />
                        </a>
                      </v-list-item-title>
                    </v-list-item>
                  </v-list-item-group>
                </v-list>
              </v-menu>
            </div>
          </template>
          {{ getTranslatedText('mainLayout.user.registerUtilities') }}
        </v-tooltip>
        <!-- user menu -->
        <v-tooltip bottom color="accent">
          <template v-slot:activator="{ on, attrs }">
            <div v-bind="attrs" v-on="on">
              <v-menu
                right
                bottom
                offset-y
                nudge-bottom="10"
                nudge-left="5"
                transition="slide-y-transition"
              >
                <template v-slot:activator="{ on }">
                  <v-btn
                    fab
                    small
                    elevation="0"
                    class="ml-2"
                    v-on="on"
                    color="primary"
                  >
                    <v-icon>mdi-account-circle</v-icon>
                  </v-btn>
                </template>
                <v-list>
                  <v-list-item>
                    <v-list-item-avatar>
                      <v-avatar color="secondary">
                        <span class="white--text text-h6">{{
                          isAdmin ? 'AD' : 'EM'
                        }}</span>
                      </v-avatar>
                    </v-list-item-avatar>
                    <v-list-item-content>
                      <v-list-item-title class="title"
                        ><FormattedText
                          type="text-subtitle"
                          className="font-weight-bold text-height"
                          color="textPrimary"
                          :value="name"
                          style="line-height: 1rem"
                      /></v-list-item-title>
                      <v-list-item-subtitle
                        ><FormattedText
                          type="text-caption"
                          className="text-height"
                          color="textPrimary"
                          intl
                          :value="role"
                          style="line-height: 1rem"
                      /></v-list-item-subtitle>
                    </v-list-item-content>
                    <v-list-item-action>
                      <v-tooltip bottom color="accent">
                        <template v-slot:activator="{ on, attrs }">
                          <div v-bind="attrs" v-on="on">
                            <v-btn
                              fab
                              small
                              color="accent"
                              elevation="0"
                              @click="changeUserDialogStatus(true)"
                            >
                              <v-icon>mdi-account-switch</v-icon>
                            </v-btn>
                          </div>
                        </template>
                        {{ getTranslatedText('mainLayout.user.change') }}
                      </v-tooltip>
                    </v-list-item-action>
                  </v-list-item>
                </v-list>
              </v-menu>
            </div>
          </template>
          {{ getTranslatedText('mainLayout.user.user') }}
        </v-tooltip>
        <HelpBot />
      </div>
    </v-app-bar>
    <!-- main app tools dialogs -->
    <ChangeUserDialog v-if="isChangeUserDialogOpened" />
    <AmountDialog
      v-if="openAmountDialog"
      :opened="openAmountDialog"
      @checkAdjustRegister="checkAdjustRegister"
      @closeDialog="openAmountDialog = false"
    />
    <CloseRegisterResultDialog
      v-if="openCloseRegisterResultDialog"
      :opened="openCloseRegisterResultDialog"
      :adjustData="resultAmountDialogData"
      @closeDialog="openCloseRegisterResultDialog = false"
    />
    <AddCustomerDialog v-if="addCustomerDialog.isOpen" />
    <ConfirmCustomerInvitedDialog v-if="messageInformationDialog.isOpen" />
    <AddCashMovementDialog v-if="addCashMovementDialog.isOpen" />
    <ShowMaxSyncOpsDialog v-if="maxSyncOpsDialog.isOpen" />
    <ConfirmCancelTourDialog v-if="confirmCancelTourDialog.isOpen" />
    <TTBlockedDialog v-if="ttBlockedDialog.isOpen" />
  </div>
</template>
<script>
import { mapState, mapGetters, mapActions } from 'vuex'

import { maxPendingOps } from '@/config/env'

import { getTranslatedText } from '@/tools/data'

import appActions from '@/store/app/actions.types'
import notificationsActions from '@/store/notifications/actions.types'

import FormattedText from '@/components/shared/FormattedText'
import ChangeUserDialog from '@/components/MainView/ChangeUserDialog'
import AmountDialog from '@/components/MainView/AmountDialog'
import CloseRegisterResultDialog from '@/components/MainView/CloseRegisterResultDialog'
import AddCustomerDialog from '@/components/CustomersView/AddCustomerDialog'
import AddCashMovementDialog from '@/components/MainView/AddCashMovementDialog'
import ShowMaxSyncOpsDialog from '@/components/MainView/ShowMaxSyncOpsDialog'
import ConfirmCancelTourDialog from '@/components/ConfirmCancelTourDialog'
import ConfirmCustomerInvitedDialog from '@/components/LoyaltyViews/LoyaltyProgramConfigView/LoyaltyConfigStepper/ConfirmCustomerInvitedDialog'
import TTBlockedDialog from '@/components/TTBlockedDialog'
import HelpBot from '@/components/HelpBot'
import InfoBannerMenu from '@/components/MainView/InfoBannerMenu'

import menuConfig from './menuConfig'

export default {
  name: 'MainViewMainMenu',
  components: {
    HelpBot,
    InfoBannerMenu,
    FormattedText,
    ChangeUserDialog,
    AmountDialog,
    CloseRegisterResultDialog,
    AddCustomerDialog,
    AddCashMovementDialog,
    ShowMaxSyncOpsDialog,
    ConfirmCancelTourDialog,
    ConfirmCustomerInvitedDialog,
    TTBlockedDialog,
  },
  data() {
    return {
      openAmountDialog: false,
      openCloseRegisterResultDialog: false,
      resultAmountDialogData: {},
      isAppOnline: navigator.onLine,
      selectedCashTool: null,
    }
  },
  computed: {
    ...mapState('app', [
      'mainMenuItems',
      'sidebarOpened',
      'isChangeUserDialogOpened',
      'syncing',
      'scanner',
      'addCashMovementDialog',
      'maxSyncOpsDialog',
      'pendingSyncOps',
      'confirmCancelTourDialog',
      'ttBlockedDialog',
    ]),
    ...mapState('customersView', ['addCustomerDialog']),
    ...mapState('usersView', ['selectedUser']),
    ...mapState('loyaltyProgramView', ['messageInformationDialog']),
    ...mapState('account', {
      adminName: state => state.data.name,
      country: state => state.data.country,
    }),
    ...mapState('notifications', ['notifications']),
    menuItems() {
      return this.getUserMenuItems()(menuConfig, this.selectedUser)
    },
    name() {
      let name =
        this.selectedUser.name === 'admin' && this.adminName?.length > 2
          ? this.adminName
          : this.selectedUser.name
      return name ? name.split(' ')[0] : ''
    },
    role() {
      return this.selectedUser.id === 1
        ? 'mainLayout.user.administrator'
        : 'mainLayout.user.employee'
    },
    isAdmin() {
      return this.selectedUser.id === 1 ? true : false
    },
    hasCashInOutPermission() {
      return this.selectedUser.cashInOutPermission === 0
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('app', [
      appActions.toggleSidebarStatus,
      appActions.setChangeUserDialogStatus,
      appActions.setAddCashMovementDialogStatus,
      appActions.setMaxSyncOpsDialogStatus,
    ]),
    ...mapGetters('app', ['getUserMenuItems']),
    ...mapActions('notifications', [
      notificationsActions.setStatusShowNotifications,
    ]),
    checkAdjustRegister(event) {
      this.openAmountDialog = false
      this.resultAmountDialogData = event
      this.openCloseRegisterResultDialog = true
    },
    toggleSidebar() {
      return this[appActions.toggleSidebarStatus]()
    },
    changeUserDialogStatus(status) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'AppBar',
        name: `Change user`,
      })
      return this[appActions.setChangeUserDialogStatus](status)
    },
    setIsAppOnline() {
      this.isAppOnline = navigator.onLine
    },
    openAddCashMovementDialog(type) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'AppBar',
        name: `Add cash ${type === 'moneyIn' ? 'inflow' : 'outflow'}`,
      })
      const data = { isOpen: true, type }
      this[appActions.setAddCashMovementDialogStatus](data)
    },
    showNotifications() {
      this[notificationsActions.setStatusShowNotifications](true)
    },
    showAmountDialog() {
      this.openAmountDialog = true
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'AppBar',
        name: `Close cash register`,
      })
    },
  },
  watch: {
    pendingSyncOps() {
      if (this.pendingSyncOps > maxPendingOps) {
        this[appActions.setMaxSyncOpsDialogStatus](true)
      }
    },
  },
  created() {
    window.addEventListener('online', this.setIsAppOnline)
    window.addEventListener('offline', this.setIsAppOnline)
  },
}
</script>
