import types from '@/store/account/mutations.types'

const setFetching = (state, newState) => {
  state.fetching = newState
}

const setAccount = (state, account) => {
  state.data = account
  state.error = false
  state.errorMessage = ''
}

const setError = (state, error) => {
  state.error = true
  state.errorMessage = error
}

const resetErrorStatus = state => {
  state.error = false
  state.errorMessage = ''
}

const updateAccountName = (state, data) => {
  state.data.name = data.ownerName
  state.data.storeName = data.storeName
  state.data.storeImage = data.storeImage
  state.data.storeAddress = data.storeAddress
  state.data.storePostalCode = data.storePostalCode
  state.data.storeCity = data.storeCity
  state.data.storeTown = data.storeTown
  state.data.storeState = data.storeState
  state.data.storeLandlinePhone = data.storeLandlinePhone
  state.data.storePhone = data.storePhone
}

const setSecurityData = (state, payload) => {
  state.data.security = payload
}

const setLoyaltyData = (state, payload) => {
  state.data.loyaltyProgram = payload
}

export default {
  [types.SET_ACCOUNT]: setAccount,
  [types.UPDATE_ACCOUNT_NAME]: updateAccountName,
  [types.SET_ACCOUNT_FETCHING]: setFetching,
  [types.SET_ACCOUNT_ERROR]: setError,
  [types.RESET_ACCOUNT_ERROR_STATUS]: resetErrorStatus,
  [types.SET_ACCOUNT_SECURITY_DATA]: setSecurityData,
  [types.SET_ACCOUNT_LOYALTY_DATA]: setLoyaltyData,
}
