import { required, email, maxLength } from 'vuelidate/lib/validators'

import { numericAccount } from '@/tools/customValidations'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-account-key',
    title: 'preferences.rememberPasswordDialog.title',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    messages: ['preferences.rememberPasswordDialog.firstText'],
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    height: 300,
    maxWidth: 650,
    id: 'remember-password-form',
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.generateCodeAndSendEmail(),
  },
  fields: [
    {
      id: 'account',
      type: 'account',
      validators: [
        { required, email },
        { required, numericAccount, maxLength: maxLength(10) },
        { required },
      ],
      autofocus: true,
    },
  ],
  id: 'remember-password-form',
})

export default setConfig
