<template>
  <div
    :style="divStyle"
    class="scroll-container"
    :class="{ 'theme--dark': $vuetify.theme.isDark }"
    ref="scrollContainer"
  >
    <slot :hasScroll="hasScroll" />
  </div>
</template>

<script>
export default {
  name: 'ScrollContainer',
  props: {
    maxHeight: {
      type: String,
      default: '100%',
    },
    height: {
      type: String,
      default: '100%',
    },
    scrollX: {
      type: Boolean,
      default: false,
    },
    scrollY: {
      type: Boolean,
      default: true,
    },
    scrollActiveStyle: {
      type: Object,
      default: () => ({}),
    },
  },
  data() {
    return {
      hasScroll: false,
      observer: null,
    }
  },
  computed: {
    divStyle() {
      const defaultStyle = {
        height: this.height,
        'max-height': this.maxHeight,
        'overflow-y': this.scrollY ? 'auto' : 'hidden',
        'overflow-x': this.scrollX ? 'auto' : 'hidden',
      }
      if (this.hasScroll) {
        return { ...defaultStyle, ...this.scrollActiveStyle }
      }
      return defaultStyle
    },
  },
  methods: {
    observeSlotChanges() {
      const scrollContainer = this.$refs.scrollContainer
      this.observer = new MutationObserver(mutations => {
        mutations.forEach(mutation => {
          if (mutation.type === 'childList') {
            this.checkIfHasScroll()
          }
        })
      })
      this.observer.observe(scrollContainer, { childList: true, subtree: true })
    },
    checkIfHasScroll() {
      const div = this.$refs.scrollContainer
      this.hasScroll = div.scrollHeight > div.clientHeight
    },
    scrollToBottom() {
      const div = this.$refs.scrollContainer
      div.scroll({
        top: div.scrollHeight,
        behavior: 'smooth',
      })
    },
    scrollToTop() {
      const div = this.$refs.scrollContainer
      div.scroll({
        top: 0,
        behavior: 'smooth',
      })
    },
  },
  mounted() {
    this.observeSlotChanges()
    this.checkIfHasScroll()
  },
  beforeDestroy() {
    if (this.observer) {
      this.observer.disconnect()
    }
  },
}
</script>

<style scoped lang="scss">
.scroll {
  &-container {
    scroll-behavior: smooth;
    &::-webkit-scrollbar {
      width: 20px;
    }
    &::-webkit-scrollbar-thumb {
      background-color: var(--v-mainBackground-darken1);
      border: 8px solid transparent;
      border-radius: 10px;
      background-clip: content-box;
    }
    &::-webkit-scrollbar-button:single-button {
      width: 20px;
      height: 20px;
      background-size: contain;
      background-repeat: no-repeat;
    }
    &::-webkit-scrollbar-button:single-button:vertical:increment {
      background-image: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><title>menu-down</title><path fill="rgb(153,156,158)" d="M7,10L12,15L17,10H7Z" /></svg>');
    }
    &::-webkit-scrollbar-button:single-button:vertical:decrement {
      background-image: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><title>menu-up</title><path fill="rgb(153,156,158)" d="M7,15L12,10L17,15H7Z" /></svg>');
    }
    &.theme--dark {
      &::-webkit-scrollbar-thumb {
        background-color: var(--v-mainBackground-lighten5);
      }
    }
  }
}
</style>
