import { promotions } from '@/config/promotions'

import {
  decimal,
  formatNumberFromDb,
  formatNumberToDb,
} from '@/tools/numbersFormat'
import { dayIsTodayOrAfter, dayIsTodayOrBefore } from '@/tools/dates'
import { getTotalProductPrice } from '@/tools/ticket'

const NON_PRODUCT_PROMOTIONS = [
  promotions.PURCHASE_TICKET_DISCOUNT,
  promotions.SALE_TICKET_DISCOUNT,
  promotions.SALE_ITEM_OTHER_PRICE,
  promotions.SALE_ITEM_OTHER_PRICE_BY_WEIGHT,
]

export const discountTypes = {
  amount: 'amount',
  percent: 'percent',
  isDiscountPerAmount: type => type === 'amount',
  isDiscountPerPercent: type => type === 'percent',
}

export const getPercentFromAmount = (amount, total) => {
  return decimal((amount * 100) / total)
}

export const getAmountFromPercent = (percent, total) => {
  return (total * percent) / 100
}

export const getDiscountRule = (discountType, total) => {
  return {
    minValue: value => value > 0,
    maxValue: value =>
      discountTypes.isDiscountPerAmount(discountType)
        ? value < formatNumberFromDb(total)
        : value < 100,
  }
}

export const hasPromotion = promotionTypeId => {
  return promotionTypeId && promotionTypeId !== promotions.NONE
}

export const calculateUnitaryCostWithPromotion = product => {
  const {
    promotionTypeId,
    cost,
    quantity,
    promotionExtra,
    isGramaje,
    discountAmount,
    discountPercent,
  } = product
  let unitaryCost = cost
  switch (promotionTypeId) {
    case promotions.PURCHASE_ITEM_FREE_PRODUCT:
      unitaryCost = 0
      break
    case promotions.PURCHASE_ITEM_FREE_UNITS:
      unitaryCost = ((quantity - promotionExtra) * cost) / quantity
      break
    case promotions.PURCHASE_ITEM_SUBTOTAL_DISCOUNT: {
      const totalWithoutDiscount = getTotalProductPrice(product, 'cost')
      if (discountPercent > 0) {
        unitaryCost = isGramaje
          ? (totalWithoutDiscount -
              (totalWithoutDiscount * discountPercent) / 100) /
            (quantity / 1000)
          : (totalWithoutDiscount -
              (totalWithoutDiscount * discountPercent) / 100) /
            quantity
      } else {
        unitaryCost = isGramaje
          ? (totalWithoutDiscount - discountAmount) / (quantity / 1000)
          : (totalWithoutDiscount - discountAmount) / quantity
      }
    }
  }
  return Number(unitaryCost.toFixed())
}

export const getPromotionTicketToDB = ticket => {
  return discountTypes.isDiscountPerPercent(ticket.promotion_type)
    ? formatNumberToDb(
        getAmountFromPercent(ticket.promotion, formatNumberFromDb(ticket.cost))
      )
    : ticket.promotion
}

export const getPromotionTicketToStore = purchaseOrder => {
  return discountTypes.isDiscountPerPercent(purchaseOrder.promotion_type)
    ? getPercentFromAmount(
        formatNumberFromDb(purchaseOrder.promotion),
        formatNumberFromDb(purchaseOrder.cost)
      )
    : purchaseOrder.promotion
}

export const hasProductPromotion = promotionTypeId => {
  if (!promotionTypeId) return false
  return (
    hasPromotion(promotionTypeId) &&
    !NON_PRODUCT_PROMOTIONS.includes(promotionTypeId)
  )
}

export const getTotalTicketWithPromotion = (getPrice, ticket) => {
  const { promotion, promotion_type, items, returnItems } = ticket
  const totalWithoutPromotion = getPrice(items, returnItems)
  if (promotion === 0) return totalWithoutPromotion
  const discount = discountTypes.isDiscountPerPercent(promotion_type)
    ? getAmountFromPercent(promotion, totalWithoutPromotion)
    : promotion
  return totalWithoutPromotion - discount
}

export const customPromotionIsActive = promotion => {
  if (!promotion.startDate) return promotion.active === 1
  if (!promotion.finishDate) {
    return dayIsTodayOrBefore(promotion.startDate)
  }
  return (
    dayIsTodayOrBefore(promotion.startDate) &&
    dayIsTodayOrAfter(promotion.finishDate)
  )
}
