import { filterBy } from '@/store/products/getters.tools'

export const getFilteredData = (...args) => {
  const productsViewState = args[2].productsView
  const isScannerActive = args[2].app.scanner.isActive
  const existByWeightTree =
    args[2].products.data.byWeightTree.length > 0 ? true : false
  const state = args[0]
  const {
    searchTerm,
    group,
    superCategories: selectedSuperCategories,
  } = productsViewState.filters
  const { products, productsSimilarUpc } = state.data

  if (searchTerm !== null)
    return filterBy.searchTerm(searchTerm, products, isScannerActive)
  if (group)
    return filterBy.group(group, products, {
      selectedSuperCategories,
      existByWeightTree,
      productsSimilarUpc,
    })
  return products
}

/**
 *  Get products with stock in the store without counting negative stocks.
 */
export const getOnlyStockedProducts = (...args) => {
  const state = args[0]
  const { products } = state.data
  return products.filter(product => {
    if (product.factor > 0) {
      return product.quantity / product.factor >= 1
    }
    return product.quantity > 0 && product.isGeneric === 0
  })
}
