<template>
  <DialogCard :config="dialogConfig.dialogData">
    <iframe :src="termsToShow" width="970" height="625" frameborder="0" />
  </DialogCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import countries from '@/config/countries'

import appActions from '@/store/app/actions.types'

import setConfig from '@/components/AuthViews/TermsDialog/config'
import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'TermsDialog',
  components: { DialogCard },
  computed: {
    ...mapState('app', ['termsDialog', 'countrySelected']),
    ...mapState('account', ['data']),
    dialogConfig() {
      return setConfig(
        { isOpen: this.termsDialog.isOpen },
        {
          closeDialog: this.cancelAndClose,
        }
      )
    },
    termsToShow() {
      const countryCode =
        this.countrySelected == undefined
          ? this.data.country.localeIsoCode
          : this.countrySelected.toString()
      if (!countryCode) return 'https://www.frogtek.org/legal_apps/52'
      return `https://www.frogtek.org/legal_apps/${countries[countryCode].phoneCode}`
    },
  },
  methods: {
    ...mapActions('app', [appActions.setTermsDialogStatus]),
    cancelAndClose() {
      this[appActions.setTermsDialogStatus](false)
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Signup',
        screen: 'TermsDialog',
        name: 'Close terms',
      })
    },
  },
}
</script>
