<template>
  <v-dialog
    v-model="surveyDialog.isOpen"
    :max-width="900"
    :overlay-opacity="0.15"
    @click:outside="closeSurveyDialog()"
    @keydown="processKeydown"
  >
    <v-card>
      <v-card-text class="pa-0">
        <v-btn
          absolute
          right
          fab
          depressed
          small
          color="primary"
          class="mt-4"
          @click="closeSurveyDialog()"
        >
          <v-icon>mdi-close</v-icon>
        </v-btn>
        <webview
          v-if="surveyDialog.url"
          :src="surveyDialog.url"
          class="survey-webview"
        />
      </v-card-text>
    </v-card>
  </v-dialog>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import SURVEY_API_EVENTS from '@/config/events/serversAPI/surveyEvents'

import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'

export default {
  name: 'SurveyDialog',
  computed: {
    ...mapState('account', { account: state => state.data }),
    ...mapState('app', ['surveyDialog']),
  },
  methods: {
    ...mapActions('app', [appActions.setSurveyDialog]),
    setAndOpenSurveyDialog(survey) {
      this[appActions.setSurveyDialog]({ isOpen: true, ...survey })
    },
    closeSurveyDialog() {
      this[appActions.setSurveyDialog]()
      this.$root.$emit('loadNotificationsIsNeeded')
    },
    processKeydown(event) {
      if (event.code === 'Escape') return this.closeSurveyDialog()
    },
  },
  created() {
    rendererEventsService.subscribe(
      SURVEY_API_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [SURVEY_API_EVENTS.events.getNextSurveyURL.replies.success]: () => {
            if (!payload.data) return
            this.setAndOpenSurveyDialog({ url: payload.data, name: null })
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  beforeMount() {
    if (!this.account.pos) {
      return
    }
    rendererEventsService.send(SURVEY_API_EVENTS.channel, {
      event: SURVEY_API_EVENTS.events.getNextSurveyURL.name,
      data: { pos: this.account.pos },
    })
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(SURVEY_API_EVENTS.replyChannel)
  },
}
</script>

<style scoped lang="scss">
.survey-webview {
  height: 600px;
}
</style>
