<template>
  <v-menu
    v-model="helpIsOpen"
    rounded="xl"
    right
    bottom
    offset-y
    offset-x
    content-class="help-bot"
    :close-on-content-click="false"
    :close-on-click="false"
    @input="initSections"
  >
    <template v-slot:activator="{ attrs, on }">
      <v-btn
        class="ml-2"
        fab
        small
        elevation="0"
        color="help"
        v-bind="attrs"
        v-on="on"
      >
        <v-icon>mdi-help</v-icon>
      </v-btn>
    </template>
    <v-card height="800" width="450" class="help-bot__card">
      <v-card-title
        class="primary help-bot__title d-flex justify-space-between"
      >
        <v-btn
          v-if="showReturnBtn"
          icon
          text
          small
          color="white"
          ref="returnBtn"
          @click="hideFaqResponseAndChat"
        >
          <v-icon>mdi-chevron-left</v-icon>
        </v-btn>
        <span v-else class="help-bot__no-btn" />
        <h5 class="white--text font-weight-medium text-center">
          {{ title }}
        </h5>
        <v-btn
          icon
          text
          small
          color="white"
          @click="helpIsOpen = false"
          v-track:click="{
            category: $route.name,
            screen: 'HelpBot',
            name: 'Close help bot',
          }"
        >
          <v-icon>mdi-window-minimize</v-icon>
        </v-btn>
      </v-card-title>
      <NoConnection v-if="!hasConnection" />
      <FAQSList
        v-show="hasConnection && !chatBotIsShowed"
        :showFaqsResponse.sync="faqsResponseIsShowed"
        ref="faqsContent"
        @openChat="openChatBot"
      />
      <ChatBot v-show="hasConnection && chatBotIsShowed" ref="chatBotContent" />
    </v-card>
  </v-menu>
</template>

<script>
import { getTranslatedText } from '@/tools/data'

import ChatBot from '@/components/HelpBot/ChatBot'
import FAQSList from '@/components/HelpBot/FAQSList'
import NoConnection from '@/components/HelpBot/NoConnection'

export default {
  name: 'HelpBot',
  components: { NoConnection, FAQSList, ChatBot },
  data() {
    return {
      helpIsOpen: false,
      chatBotIsShowed: false,
      faqsResponseIsShowed: false,
      hasConnection: navigator.onLine,
    }
  },
  computed: {
    showReturnBtn() {
      return this.chatBotIsShowed || this.faqsResponseIsShowed
    },
    title() {
      let key = 'help'
      if (this.chatBotIsShowed) {
        key = 'assistant'
      }
      return this.getTranslatedText(`helpBot.title.${key}`)
    },
  },
  methods: {
    getTranslatedText,
    setIsAppOnline() {
      this.hasConnection = navigator.onLine
      if (!this.hasConnection) {
        this.faqsResponseIsShowed = false
        this.chatBotIsShowed = false
      }
    },
    initSections(value) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'HelpBot',
        name:
          value !== undefined
            ? `${value ? 'Open' : 'Close'} help bot`
            : 'Return to help bot',
      })
      if (this.$refs.faqsContent) {
        this.$refs.faqsContent.init()
      }
      if (this.$refs.chatBotContent && this.chatBotIsShowed) {
        this.$refs.chatBotContent.init()
      }
    },
    hideFaqResponseAndChat() {
      this.faqsResponseIsShowed = false
      this.chatBotIsShowed = false
      this.initSections()
    },
    openChatBot() {
      this.$refs.chatBotContent.init()
      this.chatBotIsShowed = true
    },
  },
  created() {
    window.addEventListener('online', this.setIsAppOnline)
    window.addEventListener('offline', this.setIsAppOnline)
  },
  beforeMount() {
    this.$root.$on('notificationsWasOpened', () => {
      this.helpIsOpen = false
    })
  },
  beforeDestroy() {
    this.$root.$off('notificationsWasOpened', () => {
      this.helpIsOpen = false
    })
  },
}
</script>
