import crypto from 'crypto-js'

import { secretKey, isDevelopment } from '@/config/env'

const key = isDevelopment ? secretKey : process.env.VUE_APP_SECRET_KEY

export const hashData = (data, algorithm = 'SHA1') =>
  data ? crypto[algorithm](data).toString() : null

export const encryptValue = value => crypto.AES.encrypt(value, key).toString()

export const decryptValue = value => {
  return crypto.AES.decrypt(value, key).toString(crypto.enc.Utf8)
}
