import Vue from 'vue'
import VueRouter from 'vue-router'

import logger from '@/tools/logger'

import { captureException } from '@/tools/exceptions'

import store from '@/store'

import Starter from '@/views/Starter'
import HelpCenter from '@/views/HelpCenter'
import Welcome from '@/views/Welcome'

import appRoutes from './appRoutes'

const components = [Starter, Welcome, HelpCenter]

Vue.use(VueRouter)

const routes = appRoutes.map(route => {
  if (route.redirect) return route
  return {
    ...route,
    component: components.includes(route.name)
      ? components[route.name]
      : () =>
          import(
            /* webpackChunkName: "[request]" */ `@/views/${route.name}.vue`
          ),
  }
})

const router = new VueRouter({
  mode: process.env.IS_ELECTRON ? 'abstract' : 'history',
  base: process.env.BASE_URL,
  routes,
})

router.beforeEach((to, from, next) => {
  if (process.env.VUE_APP_PROTECTED_ROUTES === 'true') {
    const requiresAuth = to.matched.some(record => record.meta.requiresAuth)
    const requiresUserAuth = to.matched.some(
      record => record.meta.requiresUserAuth
    )
    const isAccountLogged =
      store.state.app.isAccountLogged && store.state.app.ready
    const isStoreOpen = store.state.app.isStoreOpen && store.state.app.ready
    const isLoyaltyProgramActived = !!store.state.account.data.loyaltyProgram
      .loyaltyProgramActived
    if (requiresAuth && !isAccountLogged) {
      logger(
        'info',
        `User is not logged and will be redirected to the country selection view`
      )
      next('/')
    } else if (requiresUserAuth && !isStoreOpen) {
      logger(
        'info',
        `Employee user is not logged and will be redirected to the open register view`
      )
      next('/app/openRegister')
    } else if (
      (to.path === '/welcome' ||
        to.path === '/externalLogin' ||
        to.path === '/login' ||
        to.path === '/sign-up' ||
        to.path === '/sign-up-profile' ||
        to.path === '/restore') &&
      isAccountLogged
    ) {
      logger('info', `User is logged and will be redirected to the next view`)
      next('/app/helpCenter').catch(error => captureException(error))
    } else if (to.path === '/app/openRegister' && isStoreOpen) {
      logger(
        'info',
        `Employee user is logged and will be redirected to the next view`
      )
      next('/app/helpCenter').catch(error => captureException(error))
    } else if (to.path === '/app/loyalty-program' && !isLoyaltyProgramActived) {
      logger(
        'info',
        'Loyalty program is no actived and will be redirected to the loyalty program activation page'
      )
      next('/app/loyalty-program-config')
    } else {
      logger('info', `Navigate to ${to.path}`)
      next()
    }
  } else {
    logger('info', `Navigate to ${to.path}`)
    next()
  }
})

export default router
