import { isNil } from 'ramda'

import { promotions } from '@/config/promotions'
import itemAddedFrom from '@/config/itemAddedFrom'

import { getDateWithFormat } from '@/tools/dates'
import salesTools from '@/tools/sales'

export const getTotalProductPriceWithIva = (product, priceKey = 'price') => {
  const tax = isNil(product.iva) ? 1 : product.iva / 100 + 1
  return product.isGramaje === 1
    ? product[priceKey] * (product.quantity / 1000) * tax
    : product[priceKey] * product.quantity * tax
}

export const getTotalTicketPrice = (
  products,
  priceKey = 'price',
  quantityKey = 'quantity'
) => {
  return products.reduce((total, product) => {
    return total + getTotalProductPrice(product, priceKey, quantityKey)
  }, 0)
}

export const getTotalProductPrice = (
  product,
  priceKey = 'price',
  quantityKey = 'quantity'
) => {
  return product.isGramaje === 1
    ? product[priceKey] * (product[quantityKey] / 1000)
    : product[priceKey] * product[quantityKey]
}

export const getTotalProductPriceWithPromotion = (
  product,
  priceKey = 'price'
) => {
  if (product.promotions && product.promotions.length > 0) {
    return getTotalProductPriceWithMoreForLessPromotions(product, priceKey)
  }
  switch (product.promotionTypeId) {
    case promotions.PURCHASE_ITEM_FREE_PRODUCT:
    case promotions.SALE_ITEM_FREE_PRODUCT:
      return 0
    case promotions.SALE_TICKET_AT_COST: {
      if (product.cost <= 0 || isGenericProduct(product)) {
        return getTotalProductPrice(product, priceKey)
      }
      if (product.isOpenProduct === 1 && product.openProductType === 1) {
        return Number(
          ((product.cost / product.factor) * product.quantity).toFixed(0)
        )
      }
      return getTotalProductPrice(product, 'cost')
    }
    default:
      return getTotalProductPrice(product, priceKey)
  }
}

export const getTotalProductPriceWithMoreForLessPromotions = (
  product,
  priceKey
) => {
  const unitPrice = salesTools.getProductPriceWithMoreForLessPromo(
    product,
    priceKey
  )
  return getTotalProductPriceWithIva(
    { ...product, [priceKey]: unitPrice },
    priceKey
  )
}

const isGenericProduct = product =>
  product.isGeneric === 1 || product.priceFrom === itemAddedFrom.FROM_PRICE

export const getTotalTicketPriceOwnerSale = (products, priceKey = 'price') => {
  return products.reduce(
    (total, product) =>
      total + getTotalProductPriceOwnerSale(product, priceKey),
    0
  )
}

export const getTotalProductPriceOwnerSale = (product, priceKey = 'price') => {
  if (product.isGeneric) return product[priceKey]
  if (product.openProductType === 1 && product.factor > 0) {
    return Number(
      ((product.cost / product.factor) * product.quantity).toFixed(0)
    )
  }
  return getTotalProductPrice(product, 'cost')
}

export const getTicketCodeFromDate = date => {
  return getDateWithFormat(date.split('.')[0], 'YYMMDDHHmmss')
}
