import { toDate } from '@/tools/dates'

import types from './mutations.type'

const setFetching = (state, newState) => {
  state.fetching = newState
}

const setVideos = (state, payload) => {
  state.data.videos = payload
  state.data.lastFetch = toDate()
  state.error = false
  state.errorMessage = ''
}

const setError = (state, error) => {
  state.data.videos = []
  state.error = true
  state.errorMessage = error
}

const setVideoTypes = (state, payload) => {
  state.data.videoTypes = payload
}

export default {
  [types.SET_VIDEOS_FETCHING]: setFetching,
  [types.SET_VIDEOS]: setVideos,
  [types.SET_VIDEO_TYPES]: setVideoTypes,
  [types.SET_VIDEOS_ERROR]: setError,
}
