<template>
  <div class="content">
    <FormattedText :value="message" />
    <v-tooltip bottom>
      <template v-slot:activator="{ on, attrs }">
        <v-btn
          small
          icon
          class="ml-4"
          @click="openFolder"
          v-bind="attrs"
          v-on="on"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
            stroke-linejoin="round"
            class="svg-icon"
          >
            <path stroke="none" d="M0 0h24v24H0z" fill="none" />
            <path
              d="M5 19l2.757 -7.351a1 1 0 0 1 .936 -.649h12.307a1 1 0 0 1 .986 1.164l-.996 5.211a2 2 0 0 1 -1.964 1.625h-14.026a2 2 0 0 1 -2 -2v-11a2 2 0 0 1 2 -2h4l3 3h7a2 2 0 0 1 2 2v2"
            />
          </svg>
        </v-btn>
      </template>
      {{ tooltipText }}
    </v-tooltip>
  </div>
</template>

<script>
import { shell } from '@electron/remote'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'OpenFolderToast',
  components: { FormattedText },
  props: {
    filePath: {
      type: String,
      required: true,
    },
    message: {
      type: String,
      required: true,
    },
    tooltipText: {
      type: String,
      required: true,
    },
  },
  methods: {
    openFolder() {
      shell.showItemInFolder(this.filePath)
    },
  },
}
</script>

<style lang="scss" scoped>
.content {
  display: flex;
  align-items: center;
  column-gap: 1rem;
}
.svg-icon {
  color: white;
  font-size: 2rem;
  transition: transform 0.2s;
}
.svg-icon:hover {
  transform: scale(1.2);
}
</style>
