import { promotions } from '@/config/promotions'

import { comboPromotion, customPromotion } from '@/tools/customPromotions'
import productsTools from '@/tools/products'
import { deepCopy } from '@/tools/data'

import types from '@/store/sales/mutations.types'
import { saleCanApplyPromotions } from '@/store/sales/actions.tools'

export const applyComboPromotions = (context, ticketIndex) => {
  const { state, commit } = context
  const combosInSale = deepCopy(state.sales[ticketIndex].promotions)
  if (!saleCanApplyPromotions(state.sales[ticketIndex])) {
    commit(types.UPDATE_SALE_PROMOTIONS, { ticketIndex, salePromotions: [] })
    updateSaleItemsFromDeletedCombos(context, combosInSale, ticketIndex)
    return
  }
  state.sales[ticketIndex].items.forEach(product => {
    const combosByProduct = getCombosByProduct(context.rootGetters, product)
    if (!combosByProduct) return
    combosByProduct.forEach(combo => {
      const otherProduct = getOtherProductOfComboInSale(
        combo.promotions,
        product,
        state.sales[ticketIndex]
      )
      const comboIndex = findComboIndexInSale(combosInSale, combo)
      if (comboIndex < 0) {
        addCombo(context, {
          otherProduct,
          product,
          combo,
          ticketIndex,
          combosInSale,
        })
        return
      }
      updateCombo(context, {
        combosInSale,
        comboIndex,
        productCombo: combo,
        product,
        otherProduct,
        ticketIndex,
      })
    })
  })
  commit(types.UPDATE_SALE_PROMOTIONS, {
    ticketIndex,
    salePromotions: combosInSale,
  })
}

const getOtherProductOfComboInSale = (combo, product, sale) => {
  let otherProduct = combo.firstProduct
  if (combo.firstProduct.id === product.id) otherProduct = combo.secondProduct
  return sale.items.find(item => item.id === otherProduct.id)
}

const findComboIndexInSale = (combosInSale, combo) => {
  return combosInSale.findIndex(promo => promo.id === combo.id)
}

const addCombo = (context, data) => {
  const { dispatch } = context
  const { combo, product, otherProduct, ticketIndex, combosInSale } = data
  if (!otherProduct) return
  if (!canAddCombo(combo, product, otherProduct)) {
    return
  }
  const comboToAdd = getComboToAdd(combo, product, otherProduct)
  updateEachProduct(dispatch, {
    ticketIndex,
    products: [product, otherProduct],
    comboQuantity: comboToAdd.quantity,
  })
  combosInSale.push(comboToAdd)
}

const canAddCombo = (combo, product, otherProduct) => {
  return (
    comboCanAppliedToProduct(combo, product) &&
    comboCanAppliedToProduct(combo, otherProduct)
  )
}

const updateCombo = (context, data) => {
  const { dispatch } = context
  const {
    combosInSale,
    comboIndex,
    productCombo,
    product,
    otherProduct,
    ticketIndex,
  } = data
  if (!canUpdateCombo(productCombo, product)) {
    updateSaleItemsFromDeletedCombos(
      context,
      [combosInSale[comboIndex]],
      ticketIndex
    )
    combosInSale.splice(comboIndex, 1)
    return
  }
  if (!comboCanAppliedToProduct(combosInSale[comboIndex], otherProduct)) {
    return
  }
  const comboToAdd = getComboToAdd(
    combosInSale[comboIndex],
    product,
    otherProduct
  )
  updateEachProduct(dispatch, {
    ticketIndex,
    products: [product, otherProduct],
    comboQuantity: comboToAdd.quantity,
  })
  combosInSale[comboIndex] = {
    ...comboToAdd,
    quantity: combosInSale[comboIndex].quantity + comboToAdd.quantity,
  }
}

const canUpdateCombo = (combo, product) => {
  return comboCanAppliedToProduct(combo, product)
}

const comboCanAppliedToProduct = (combo, product) => {
  return (
    !!product &&
    customPromotion.canBeAppliedToProduct(product) &&
    !customPromotion.productPriceWasChanged(combo, product)
  )
}

export const updateSaleItemsFromDeletedCombos = (
  context,
  salePromotions,
  ticketIndex,
  fromProductDeleted
) => {
  if (salePromotions.length <= 0) return
  salePromotions.forEach(promo => {
    comboPromotion.getProductsKey().forEach(key => {
      if (productHasBeenUpdated(context, ticketIndex, promo, key)) return
      addNewProductToSale(context, ticketIndex, promo, key, fromProductDeleted)
    })
  })
}

const getComboToAdd = (promo, product, productFound) => {
  const comboQuantity =
    product.quantity > productFound.quantity
      ? productFound.quantity
      : product.quantity
  return {
    ...promo,
    quantity: comboQuantity,
  }
}

const productHasBeenUpdated = (context, ticketIndex, promotion, key) => {
  const { dispatch, state } = context
  let productFound = state.sales[ticketIndex].items.find(
    item => item.id === promotion.promotions[key].id
  )
  if (!productFound) return false
  dispatch('updateProductQuantity', {
    ticketIndex,
    upcProduct: productFound.upc,
    quantity: productFound.quantity + promotion.quantity,
  })
  return true
}

const addNewProductToSale = (
  context,
  ticketIndex,
  promotion,
  key,
  fromProductDeleted
) => {
  const { rootState, dispatch } = context
  if (fromProductDeleted) {
    const productFound = rootState.products.data.products.find(
      item => item.upc === promotion.promotions[key].upc
    )
    if (!productFound) return
  }
  const productToAdd = productsTools.getProductForSale(
    {
      ...promotion.promotions[key],
      factorSalesBy: promotion.promotions[key].factor > 0 ? 0 : 2,
    },
    rootState.products.data.products
  )
  productToAdd.quantity = promotion.quantity
  dispatch('addProductToCurrentSale', {
    currentSale: ticketIndex,
    product: productToAdd,
    fromApplyCombo: true,
    fnArray: 'unshift',
  })
}

const updateEachProduct = (dispatch, data) => {
  const { ticketIndex, products, comboQuantity } = data
  products.forEach(product => {
    if (product.quantity - comboQuantity <= 0) {
      dispatch('removeProductFromSale', {
        upcProduct: product.upc,
        ticketIndex,
      })
      return
    }
    dispatch('updateProductQuantity', {
      ticketIndex,
      upcProduct: product.upc,
      quantity: product.quantity - comboQuantity,
    })
  })
}

const getCombosByProduct = (rootGetters, product) => {
  return rootGetters[
    'customPromotions/getCustomPromotionsByProductAndTypeWithFilters'
  ](promotions.SALE_ITEM_COMBO, { isActive: true })[product.id]
}
