import types from './mutations.types'

// View mutations
export const toggleDetailDialog = state => {
  state.productDetailDialog.isOpen = !state.productDetailDialog.isOpen
}

export const toggleAddProductDialog = state => {
  state.newProductDialog.isOpen = !state.newProductDialog.isOpen
}

export const setSelectedProduct = (state, payload) => {
  state.selectedProduct = payload
}

export const updateSelectedProductField = (state, payload) => {
  state.selectedProduct[payload.field] = payload.value
}

export const setViewComponent = (state, payload) => {
  state.component = payload
}

// Filter mutations
export const setSearchTermFilter = (state, payload) => {
  state.filters.searchTerm = payload
}

export const setGroupFilter = (state, payload) => {
  if (state.filters.setGroup !== payload) {
    state.filters.group = payload
  }
}

export const setSelectedSuperCategories = (state, payload) => {
  state.filters.superCategories = payload
}

export const updateCardComponent = state =>
  state.filters.group === 'generics'
    ? (state.cardComponent = 'GenericCard')
    : (state.cardComponent = 'ProductCard')

export const setDeleteProductDialogStatus = (state, payload) => {
  hideAllSubDialogsOfProductDetails(state, payload)
  state.deleteProductDialog.isOpen = payload
}

export const setProductInSaleDialogStatus = (state, payload) => {
  state.productInSaleDialog.isOpen = payload
}

export const setReportDialogStatus = (state, payload) => {
  hideAllSubDialogsOfProductDetails(state, payload)
  state.reportDialog.isOpen = payload
}

export const setProductsTourEnabled = (state, payload) => {
  state.tourEnabled = payload
}

export const setImportProductsDialog = (state, payload) => {
  state.importProductsDialog.isOpen = payload
}

export const setItemsToDeleteInBulkDeletion = (state, items) => {
  state.bulkDeletion.itemsToDelete = items
}

export const setBulkDeletionStatus = (state, isActive) => {
  state.bulkDeletion.isActive = isActive
}

export const setBulkDeletionDialogStatus = (state, isOpen) => {
  state.bulkDeletion.dialogIsOpen = isOpen
}

export const setWastedProductsDialogStatus = (state, isOpen) => {
  hideAllSubDialogsOfProductDetails(state, isOpen)
  state.wastedProductsDialog.isOpen = isOpen
}

const setDeleteStockModificationOperationDialog = (state, payload) => {
  hideAllSubDialogsOfProductDetails(state, payload.isOpen)
  state.deleteStockModificationOperationDialog.isOpen = payload.isOpen
  state.deleteStockModificationOperationDialog.operation =
    payload.operation || null
}

const hideAllSubDialogsOfProductDetails = (state, isForToOpen) => {
  if (!isForToOpen) return
  state.wastedProductsDialog.isOpen = false
  state.reportDialog.isOpen = false
  state.productInSaleDialog.isOpen = false
  state.deleteProductDialog.isOpen = false
  state.deleteStockModificationOperationDialog.isOpen = false
  state.changeOpenGramajeDialog.isOpen = false
}

export const setChangeOpenGramajeDialog = (state, payload) => {
  state.changeOpenGramajeDialog.isOpen = payload
}

const setSimilarProductsUpcDialog = (state, data) => {
  state.similarProductsUpcDialog.isOpen = data.isOpen
  state.similarProductsUpcDialog.product = data.product
  state.similarProductsUpcDialog.isFromProductDetails =
    data.isFromProductDetails || false
}

export default {
  [types.SET_DETAIL_DIALOG_STATUS]: toggleDetailDialog,
  [types.SET_NEW_PRODUCT_DIALOG_STATUS]: toggleAddProductDialog,
  [types.SET_SELECTED_PRODUCT]: setSelectedProduct,
  [types.UPDATE_SELECTED_PRODUCT_FIELD]: updateSelectedProductField,
  [types.SET_VIEW_TYPE]: setViewComponent,
  [types.SET_SEARCH_TERM_FILTER]: setSearchTermFilter,
  [types.SET_GROUP_FILTER]: setGroupFilter,
  [types.SET_SUPER_CATEGORIES_FILTER]: setSelectedSuperCategories,
  [types.UPDATE_CARD_COMPONENT]: updateCardComponent,
  [types.SET_DELETE_PRODUCT_DIALOG]: setDeleteProductDialogStatus,
  [types.SET_PRODUCT_IN_SALE_DIALOG]: setProductInSaleDialogStatus,
  [types.SET_REPORT_DIALOG_STATUS]: setReportDialogStatus,
  [types.SET_PRODUCTS_TOUR_ENABLED]: setProductsTourEnabled,
  [types.SET_IMPORT_PRODUCTS_DIALOG_STATUS]: setImportProductsDialog,
  [types.SET_ITEMS_TO_DELETE_IN_BULK_DELETION]: setItemsToDeleteInBulkDeletion,
  [types.SET_BULK_DELETION_STATUS]: setBulkDeletionStatus,
  [types.SET_BULK_DELETION_DIALOG_STATUS]: setBulkDeletionDialogStatus,
  [types.SET_WASTED_PRODUCTS_DIALOG_STATUS]: setWastedProductsDialogStatus,
  [types.SET_DELETE_STOCK_MODIFICATION_OPERATION_DIALOG]: setDeleteStockModificationOperationDialog,
  [types.SET_CHANGE_OPEN_GRAMAJE_DIALOG]: setChangeOpenGramajeDialog,
  [types.SET_SIMILAR_PRODUCTS_UPC_DIALOG]: setSimilarProductsUpcDialog,
}
