<template>
  <div class="helpCenter-view">
    <v-container fluid id="helpCenter-id">
      <!-- View toolbar -->
      <v-row no-gutters>
        <v-col
          class="helpCenter-view__filter-toolbar px-6 pt-6"
          id="helpCenter-view__filter-toolbar"
        >
          <HelpCenterToolbar />
        </v-col>
      </v-row>
      <!-- View video cards -->
      <v-row no-gutters>
        <v-col
          class="helpCenter-view__helpCenter-list"
          id="helpCenter-view__helpCenter-list"
          :style="{
            height: `calc(100vh - ${getHelpCenterListStyles}px - 140px)`,
          }"
        >
          <HelpCenterList />
        </v-col>
      </v-row>
    </v-container>
    <div v-show="false" ref="tourSectionsFirstStep">
      <div class="tour-first-step-content">
        <img src="@/assets/logo.png" height="150px" />
        <h1>
          {{ getTranslatedText('tour.sectionsTour.firstStep.firstText') }}
        </h1>
        <h2>
          {{ getTranslatedText('tour.sectionsTour.firstStep.secondText') }}
        </h2>
      </div>
    </div>
    <div v-show="false" ref="tourSectionsThirdStep">
      <span>
        {{ getTranslatedText('tour.sectionsTour.thirdStep.text') }}
      </span>
      <ul>
        <li>
          {{ getTranslatedText('tour.sectionsTour.thirdStep.firstPoint') }}
        </li>
        <li>
          {{ getTranslatedText('tour.sectionsTour.thirdStep.secondPoint') }}
        </li>
        <li>
          {{ getTranslatedText('tour.sectionsTour.thirdStep.thirdPoint') }}
        </li>
      </ul>
    </div>
    <div v-show="false" ref="tourSectionsSixthStep">
      <span>
        {{ getTranslatedText('tour.sectionsTour.sixthStep.text') }}
      </span>
      <ul>
        <li>
          {{ getTranslatedText('tour.sectionsTour.sixthStep.firstPoint') }}
        </li>
        <li>
          {{ getTranslatedText('tour.sectionsTour.sixthStep.secondPoint') }}
        </li>
        <li>
          {{ getTranslatedText('tour.sectionsTour.sixthStep.thirdPoint') }}
        </li>
        <li>
          {{ getTranslatedText('tour.sectionsTour.sixthStep.fourthPoint') }}
        </li>
        <li>
          {{ getTranslatedText('tour.sectionsTour.sixthStep.fifthPoint') }}
        </li>
        <li>
          {{ getTranslatedText('tour.sectionsTour.sixthStep.sixthPoint') }}
        </li>
      </ul>
    </div>
    <div v-show="false" ref="tourSectionsTwelfthStep">
      <div class="tour-first-step-content">
        <v-icon size="90" class="mb-6" color="secondary lighten-1">
          mdi-flag-checkered
        </v-icon>
        <h1>
          {{ getTranslatedText('tour.sectionsTour.twelfthStep.firstText') }}
        </h1>
        <h2>
          {{ getTranslatedText('tour.sectionsTour.twelfthStep.secondText') }}
          <br />
          {{ getTranslatedText('tour.sectionsTour.twelfthStep.thirdText') }}
        </h2>
      </div>
    </div>
  </div>
</template>

<script>
import { mapActions, mapState } from 'vuex'
import { isEmpty } from 'ramda'

import { ytTutorialTiendatek } from '@/config/env'
import YOUTUBE_API_EVENTS from '@/config/events/youtube'
import onboardingTour from '@/config/tours/onboardingTour'

import { getAppLayoutHeaderAndFooterHeight } from '@/tools/view'
import { getTranslatedText } from '@/tools/data'
import { getDiffBetweenDates, toDate } from '@/tools/dates'
import tourTrackTools from '@/tools/tourTrack'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'
import tourService from '@/services/renderer/tour'

import appActions from '@/store/app/actions.types'
import helpCenterActions from '@/store/helpCenter/actions.types'
import helpCenterViewActions from '@/store/helpCenterView/actions.types'

import HelpCenterToolbar from '@/components/HelpCenterView/HelpCenterToolbar'
import HelpCenterList from '@/components/HelpCenterView/HelpCenterList'

export default {
  name: 'HelpCenterView',
  components: { HelpCenterToolbar, HelpCenterList },
  data() {
    return {
      layoutCommonElementsHeight: 0,
      tour: null,
    }
  },
  computed: {
    ...mapState('app', ['onboardingEnabled']),
    ...mapState('usersView', ['selectedUser']),
    ...mapState('helpCenter', {
      tutorials: state => state.data.videos,
      lastFetch: state => state.data.lastFetch,
    }),
    getHelpCenterListStyles() {
      return this.layoutCommonElementsHeight
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('helpCenter', [
      helpCenterActions.setVideoFetching,
      helpCenterActions.fetchVideos,
      helpCenterActions.setVideoError,
    ]),
    ...mapActions('helpCenterView', [
      helpCenterViewActions.setSearchTermFilter,
    ]),
    ...mapActions('app', [
      appActions.setOnboardingEnabled,
      appActions.setConfirmCancelTourDialogStatus,
    ]),
    getLayoutHeight() {
      const layoutComponentsHeight = getAppLayoutHeaderAndFooterHeight(
        'helpCenter-id'
      )
      const helpCenterViewToolbar = document.getElementById(
        'helpCenter-view__filter-toolbar'
      ).offsetHeight
      this.layoutCommonElementsHeight =
        layoutComponentsHeight + helpCenterViewToolbar
    },
    createAndStartTour() {
      this.tour = tourService.createTour(this, onboardingTour.tourOptions)
      tourService.addSteps(this, onboardingTour.steps)
      tourService.addCancelFunctionToSteps(this, () =>
        this[appActions.setConfirmCancelTourDialogStatus]({
          isOpen: true,
          tour: this.tour,
        })
      )
      tourTrackTools.initTracks.call(this, 'HelpCenter')
      this.tour.on('cancel', () => {
        this[appActions.setOnboardingEnabled](false)
      })
      this.tour.on('complete', () => {
        this[appActions.setOnboardingEnabled](false)
      })
      if (this.$router.currentRoute.name === 'HelpCenter') this.tour.start()
    },
    getVideos() {
      this[helpCenterActions.setVideoFetching](true)
      rendererEventsService.send(YOUTUBE_API_EVENTS.channel, {
        event: YOUTUBE_API_EVENTS.events.getPlaylist.name,
        data: {
          playlistId: ytTutorialTiendatek,
        },
      })
    },
    getVideosIfTodayChanged() {
      if (getDiffBetweenDates(toDate(), this.lastFetch, 'day') === 0) {
        return
      }
      this.getVideos()
    },
    youtubeListener(event, payload) {
      const ytReplies = YOUTUBE_API_EVENTS.events.getPlaylist.replies
      const replies = {
        [`${ytReplies.success}`]: () => {
          this[helpCenterActions.fetchVideos](payload.data)
        },
        [`${ytReplies.error}`]: () => {
          this[helpCenterActions.setVideoError](payload.data)
          if (payload.data?.errorConection) {
            notificationsService.showError(
              payload.data.error,
              this.$vuetify.lang,
              { timeout: 10000 }
            )
          }
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    rendererEventsService.subscribe(
      YOUTUBE_API_EVENTS.replyChannel,
      this.youtubeListener
    )
    this.$root.$on('appComponentWasUpdated', this.getVideosIfTodayChanged)
  },
  mounted() {
    if (isEmpty(this.tutorials)) {
      this.getVideos()
    }
    this.getLayoutHeight()
    if (this.onboardingEnabled) {
      setTimeout(() => {
        this.createAndStartTour()
      }, 300)
    }
  },
  beforeDestroy() {
    tourTrackTools.destroyTracks.call(this, 'HelpCenter')
    this.$root.$off('appComponentWasUpdated', this.getVideosIfTodayChanged)
    this[helpCenterViewActions.setSearchTermFilter](null)
    rendererEventsService.removeListener(
      YOUTUBE_API_EVENTS.replyChannel,
      this.youtubeListener
    )
  },
}
</script>

<style lang="scss" scope>
$window-status: 'default', 'minimum';

.helpCenter-view {
  height: 100%;
  width: 100%;
  .helpCenter-view__filter-toolbar {
    background-color: var(--v-mainBackground-base);
  }
  .helpCenter-view__helpCenter-list {
    width: 100%;
  }
}
</style>
