<template>
  <div v-if="!showFaqsResponse" class="faq-list" ref="faqsList">
    <div class="faq-list__content-search">
      <v-text-field
        v-model="search"
        :placeholder="getTranslatedText('helpBot.searchQuestion')"
        persistent-placeholder
        autofocus
        outlined
        color="primary"
        flat
        hide-details
        dense
        rounded
        append-icon="mdi-magnify"
      />
    </div>
    <v-card-text class="faq-list__content pt-16">
      <v-overlay :value="loading" absolute class="faq-list__loading">
        <v-progress-circular indeterminate size="64"></v-progress-circular>
      </v-overlay>
      <v-list class="faq-list__content-list">
        <v-list-item
          v-for="faq in list"
          :key="`faq-${faq.id}`"
          @click="questionWasSelected(faq.id)"
          v-track:click="{
            category: $route.name,
            screen: 'FAQS',
            name: `Select FAQ`,
            extraData: {
              label1: 'question',
              value1: faq.question,
            },
          }"
        >
          <v-list-item-content>
            {{ faq.question }}
          </v-list-item-content>
          <v-list-item-icon>
            <v-icon>mdi-chevron-right</v-icon>
          </v-list-item-icon>
        </v-list-item>
        <v-list-item
          @click="otherQuestionWasSelected"
          v-track:click="{
            category: $route.name,
            screen: 'FAQS',
            name: 'Open chat bot',
          }"
        >
          <v-list-item-icon class="mr-4">
            <v-icon color="primary">mdi-robot-excited</v-icon>
          </v-list-item-icon>
          <v-list-item-content>
            {{ getTranslatedText('helpBot.createQuestion') }}
          </v-list-item-content>
          <v-list-item-icon>
            <v-icon>mdi-chevron-right</v-icon>
          </v-list-item-icon>
        </v-list-item>
      </v-list>
    </v-card-text>
  </div>
  <div v-else-if="responseToShow" class="faq-list" ref="faqResponse">
    <v-card-text class="faq-list__content">
      <h3 class="mb-4 font-weight-medium">{{ responseToShow.question }}</h3>
      <div v-html="responseToShow.response" />
      <br />
      <div v-html="helpContact" />
    </v-card-text>
  </div>
</template>

<script>
import { mapState } from 'vuex'

import CHAT_BOT_DB_API_EVENTS from '@/config/events/databaseAPI/chatBot'

import { getTranslatedText, normalizeString } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'

import faqs from '@/components/HelpBot/FAQSList/faqs'
import helpBotTools from '@/components/HelpBot/helpBot.tools'

export default {
  name: 'FAQSList',
  props: {
    showFaqsResponse: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      search: '',
      responseToShow: null,
      loading: false,
    }
  },
  computed: {
    ...mapState('account', {
      countryLocale: state => state.data.country.localeIsoCode,
    }),
    list() {
      if (!this.search || this.search.trim() === '') {
        return Object.values(faqs)
      }
      const toSearch = normalizeString(this.search.trim())
      return Object.values(faqs).filter(faq => {
        const faqNormalized = normalizeString(faq.question)
        return faqNormalized.includes(toSearch)
      })
    },
    helpContact() {
      return this.getTranslatedText(
        'helpBot.faqContactCenter',
        helpBotTools.getHelpContact.call(this)
      )
    },
  },
  methods: {
    getTranslatedText,
    questionWasSelected(id) {
      this.loading = true
      this.responseToShow = null
      rendererEventsService.send(CHAT_BOT_DB_API_EVENTS.channel, {
        event: CHAT_BOT_DB_API_EVENTS.events.getFAQAnswer.name,
        data: { id },
      })
    },
    otherQuestionWasSelected() {
      this.$emit('openChat')
      this.search = ''
    },
    scrollToTop(fromQuestionSelected = false) {
      if (this.showFaqsResponse && !fromQuestionSelected) return
      const faqsContentEl = document.getElementsByClassName('faq-list')[0]
      setTimeout(() => {
        faqsContentEl.scrollTo({
          top: 0 - faqsContentEl.offsetTop,
        })
      }, 50)
    },
    init() {
      this.search = ''
      this.scrollToTop()
    },
    faqsResponseListener(event, payload) {
      const replies = {
        [CHAT_BOT_DB_API_EVENTS.events.getFAQAnswer.replies.success]: () => {
          this.responseToShow = {
            question: faqs[payload.data.id].question,
            response: payload.data.answer,
          }
          this.search = ''
          this.scrollToTop(true)
          this.loading = false
          this.$emit('update:showFaqsResponse', true)
          this.$track({
            type: 'system',
            action: 'response',
            category: this.$route.name,
            screen: 'FAQS',
            name: 'Answer FAQ',
          })
        },
        [CHAT_BOT_DB_API_EVENTS.events.getFAQAnswer.replies.error]: () => {
          this.responseToShow = {
            question: faqs[payload.data.id].question,
            response: this.getTranslatedText('helpBot.faqResponseError'),
          }
          this.loading = false
          this.$emit('update:showFaqsResponse', true)
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  beforeMount() {
    rendererEventsService.subscribe(
      CHAT_BOT_DB_API_EVENTS.replyChannel,
      this.faqsResponseListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      CHAT_BOT_DB_API_EVENTS.replyChannel,
      this.faqsResponseListener
    )
  },
}
</script>
