const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-whatsapp',
    title: 'loyaltyProgramConfig.stepper.step2.messageInformationDialog.title',
    titleColor: 'textPrimary',
    maxWidth: 600,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: state.routeName,
        screen: 'ConfirmCustomerInvitedDialog',
        name: 'Cancel',
      })
      methods.closeDialog()
    },
    onClickAccept: () => methods.acceptMessageInvitacion(),
  },
})

export default setConfig
