import { filter, includes } from 'ramda'

import { normalizeString } from '@/tools/data'

export const getFilteredData = (...args) => {
  const expenses = args[0].data.expenses
  const expensesSearchTerm = normalizeString(
    args[2].expensesView.filters.searchTerm || ''
  )
  return filter(
    expense => includes(expensesSearchTerm, normalizeString(expense.text)),
    expenses
  )
}
