export default {
  channel: 'account-login',
  replyChannel: 'account-login-reply',
  events: {
    accountLoginProcess: {
      name: 'account-login-process',
      replies: {
        start: 'account-login-process-start',
        success: 'account-login-process-success',
        error: 'account-login-process-error',
        confirmDeviceChange: 'account-login-process-confirm-device-change',
      },
    },
    loginFromUnfinishedRestore: {
      name: 'account-login-from-unfinished-restore',
      replies: {
        success: 'account-login-from-unfinished-restore-success',
        error: 'account-login-from-unfinished-restore-error',
      },
    },
    accountLoginProcessFromDifferentDevice: {
      name: 'account-login-process-from-different-device',
    },
  },
}
