import paymentMethods from '@/config/paymentMethods'

import types from '@/store/sales/mutations.types'

const addSale = (state, payload) => {
  state.sales.push(payload)
}

const removeSale = (state, payload) => {
  state.sales.splice(payload, 1)
}

const addProductToCurrentSale = (state, payload) => {
  const { currentSale, product, fnArray } = payload
  state.sales[currentSale].items[fnArray || 'push'](product)
}

const removeProductFromSale = (state, payload) => {
  const products = state.sales[payload.ticketIndex].items
  const productIndex = products.findIndex(product => {
    if ('uniqueId' in payload) {
      return product.uniqueId === payload.uniqueId
    }
    return product.upc === payload.upcProduct
  })

  if (productIndex < 0) return
  state.sales[payload.ticketIndex].items.splice(productIndex, 1)
}

const updateProductFromSale = (state, payload) => {
  const { saleIndex, productIndex, product } = payload
  if (productIndex < 0) return
  Object.assign(state.sales[saleIndex].items[productIndex], product)
}

const updatePayOptionStatus = (state, payload) => {
  state.sales[payload.ticketIndex].payOption = payload.option
  state.sales[payload.ticketIndex].paySubOption =
    payload.paySubOption || payload.option
}

const updatePrintTicketStatus = (state, payload) => {
  state.sales[payload].print = !state.sales[payload].print
}

const updateCustomerSelected = (state, payload) => {
  state.sales[payload.ticketIndex].customer = payload.customer
  state.sales[payload.ticketIndex].enrolledCustomer =
    payload?.enrolledCustomer || ''
}

const resetSale = (state, payload) => {
  const print = state.sales[payload].print
  state.sales.splice(payload, 1)
  if (state.sales.length < 1)
    state.sales.push({
      ticketId: 1,
      items: [],
      print: print,
      payOption: paymentMethods.cashKey,
      paySubOption: paymentMethods.cashKey,
      others: [],
      customer: '',
      enrolledCustomer: '',
      promotion: 0,
      promotion_type: 'percent',
      promotionTicketId: 0,
      cashAmount: 0,
      name: 'Ticket 1',
      promotions: [],
    })
}

const updateProductsFieldsFromAllSales = (state, payload) => {
  state.sales.forEach(sale => {
    if (sale.items.length === 0) return
    sale.items.forEach(product => {
      const updatedProduct = payload.find(
        updProduct => updProduct.upc === product.upc
      )
      if (updatedProduct) {
        product.stock = updatedProduct.newStock
        product.cost = updatedProduct.cost ?? product.cost
      }
    })
  })
}

const addCashAmount = (state, { ticketIndex, cashAmount }) => {
  state.sales[ticketIndex].cashAmount = cashAmount
}

const updatePromotionTicket = (state, payload) => {
  state.sales[payload.ticketIndex].promotion = payload.discount
  state.sales[payload.ticketIndex].promotion_type = payload.type
  state.sales[payload.ticketIndex].promotionTicketId = payload.promotionTicketId
}

const resetSaleProductsPromotion = (state, ticketIndex) => {
  state.sales[ticketIndex].items.forEach(item => {
    item.promotionTypeId = 0
    item.promotions = []
  })
}

const updateSaleName = (state, { ticketIndex, name }) => {
  state.sales[ticketIndex].name = name
}

const updateSalePromotions = (state, { ticketIndex, salePromotions }) => {
  state.sales[ticketIndex].promotions = salePromotions
}

export default {
  [types.ADD_SALE]: addSale,
  [types.ADD_PRODUCT_TO_CURRENT_SALE]: addProductToCurrentSale,
  [types.UPDATE_PRODUCT_FROM_SALE]: updateProductFromSale,
  [types.UPDATE_PAY_OPTION_STATUS]: updatePayOptionStatus,
  [types.UPDATE_PRINT_TICKET_OPTION_STATUS]: updatePrintTicketStatus,
  [types.UPDATE_CUSTOMER_SELECTED]: updateCustomerSelected,
  [types.REMOVE_SALE]: removeSale,
  [types.REMOVE_PRODUCT_FROM_SALE]: removeProductFromSale,
  [types.RESET_SALE]: resetSale,
  [types.UPDATE_PRODUCTS_FIELDS_FROM_ALL_SALES]: updateProductsFieldsFromAllSales,
  [types.ADD_CASH_AMOUNT]: addCashAmount,
  [types.UPDATE_PROMOTION_TICKET]: updatePromotionTicket,
  [types.RESET_SALE_PRODUCTS_PROMOTION]: resetSaleProductsPromotion,
  [types.UPDATE_SALE_NAME]: updateSaleName,
  [types.UPDATE_SALE_PROMOTIONS]: updateSalePromotions,
}
