<template>
  <DialogCard :config="componentConfig.dialogData">
    <v-checkbox
      v-model="printDailySummary"
      hide-details
      :label="getTranslatedText('mainLayout.user.printDailySummary')"
      @change="printDailyWasUpdated"
    />
  </DialogCard>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import OPEN_REGISTER_EVENTS from '@/config/events/openRegister'
import TTCONTROL_API_EVENTS from '@/config/events/serversAPI/ttcontrolEvents'
import PRINTER_EVENTS from '@/config/events/printer'

import { captureException } from '@/tools/exceptions'
import { formatNumberToDb } from '@/tools/numbersFormat'
import { getTranslatedText } from '@/tools/data'
import { getTodayForReports } from '@/tools/dates'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import usersViewActions from '@/store/usersView/actions.types'

import DialogCard from '@/components/shared/DialogCard'
import setConfig from '@/components/MainView/CloseRegisterResultDialog/config'

export default {
  name: 'CloseRegisterResultDialog',
  components: { DialogCard },
  props: {
    opened: {
      type: Boolean,
      default: false,
    },
    adjustData: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      closingRegister: false,
      printDailySummary: false,
    }
  },
  computed: {
    ...mapState('usersView', ['selectedUser', 'estimatedCash']),
    ...mapState('app', ['addMarginTicket']),
    ...mapState('account', ['data']),
    isOpened() {
      return this.opened
    },
    componentConfig() {
      return setConfig(
        {
          opened: this.isOpened,
          difference: this.adjustData.difference,
        },
        {
          closeDialog: this.closeDialog,
          onAccept: this.onAccept,
        }
      )
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('usersView', [
      usersViewActions.generateCloseRegisterOperation,
    ]),
    onAccept() {
      if (this.closingRegister === true) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'CashDiscrepancy',
        name: 'Submit',
      })
      this.closingRegister = true
      if (this.printDailySummary) {
        rendererEventsService.send(TTCONTROL_API_EVENTS.channel, {
          event: TTCONTROL_API_EVENTS.events.getDailySummaryToPrint.name,
          data: {
            pos: this.data.pos,
            date: getTodayForReports(),
          },
        })
        this.$loading.show('printDailySummary')
      } else {
        this.goToOpenRegister()
      }
    },
    goToOpenRegister() {
      rendererEventsService.send(OPEN_REGISTER_EVENTS.channel, {
        event: OPEN_REGISTER_EVENTS.events.closeRegister.name,
        data: {
          user: this.selectedUser.id,
          amount: formatNumberToDb(this.adjustData.amount),
          difference: formatNumberToDb(this.adjustData.difference),
        },
      })
    },
    closeDialog() {
      this.$emit('closeDialog')
    },
    printDailyWasUpdated(value) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'CashDiscrepancy',
        name: `${value ? 'Mark' : 'Unmark'} print daily summary`,
      })
    },
  },
  mounted() {
    this.$barcodeScanner.destroy()
    rendererEventsService.subscribe(
      OPEN_REGISTER_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [OPEN_REGISTER_EVENTS.events.closeRegister.replies.error]: () => {
            notificationsService.showError(
              payload.data.message,
              this.$vuetify.lang
            )
            this.closingRegister = false
          },
          [OPEN_REGISTER_EVENTS.events.closeRegister.replies.success]: () => {
            this[usersViewActions.generateCloseRegisterOperation]({
              isOpen: false,
              pendingSyncOps: payload.data.pendingSyncOps,
            })
            this.closingRegister = false
            this.$router
              .push({ path: '/app/openRegister' })
              .catch(error => captureException(error))
          },
        }
        replies[payload.event]()
      }
    )
    rendererEventsService.subscribe(
      TTCONTROL_API_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [TTCONTROL_API_EVENTS.events.getDailySummaryToPrint.replies
            .success]: () => {
            rendererEventsService.send(PRINTER_EVENTS.channel, {
              event: PRINTER_EVENTS.events.printSale.name,
              data: {
                ticketToPrint: payload.htmlToPrint,
                addMarginTicket: this.addMarginTicket,
              },
            })
            this.$loading.hide()
            this.goToOpenRegister()
          },
          [TTCONTROL_API_EVENTS.events.getDailySummaryToPrint.replies
            .error]: () => {
            this.$loading.hide()
            notificationsService.showError(
              'reportsView.printDailySummaryDialog.errorNotification',
              this.$vuetify.lang
            )
            this.goToOpenRegister()
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  beforeDestroy() {
    this.$root.$emit('enable-scanner', {})
    rendererEventsService.removeAllListeners(OPEN_REGISTER_EVENTS.replyChannel)
    rendererEventsService.removeAllListeners(TTCONTROL_API_EVENTS.replyChannel)
  },
}
</script>
