<template>
  <v-text-field
    v-model="message"
    :placeholder="inputPlaceholder"
    :disabled="inputDisabled"
    solo
    flat
    hide-details
    dense
    append-icon="mdi-send"
    autofocus
    ref="userInput"
    @click:append="messageMustBeSend"
    @keydown.enter="messageMustBeSend"
  />
</template>

<script>
import { getTranslatedText } from '@/tools/data'

export default {
  name: 'UserInput',
  props: {
    hasConnection: {
      type: Boolean,
      default: false,
    },
    botIsTyping: {
      type: Boolean,
      default: false,
    },
    thereAreSelectOptions: {
      type: Boolean,
      default: false,
    },
    hasThreadId: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      faqSelected: '',
      message: '',
      showFaqs: true,
    }
  },
  computed: {
    inputPlaceholder() {
      let key = 'writeQuestion'
      if (this.thereAreSelectOptions) key = 'selectOption'
      if (!this.hasThreadId) key = 'makeConnection'
      if (!this.hasConnection) key = 'noConnection'
      if (this.botIsTyping) key = 'waitingResponse'
      return this.getTranslatedText(`helpBot.chat.input.${key}`)
    },
    inputDisabled() {
      return (
        this.botIsTyping ||
        !this.hasConnection ||
        this.thereAreSelectOptions ||
        !this.hasThreadId
      )
    },
  },
  methods: {
    getTranslatedText,
    messageMustBeSend() {
      if (!this.message || !this.message.trim()) return
      this.$emit('sendMessage', this.message)
      this.resetInput()
    },
    resetInput() {
      this.faqSelected = ''
      this.message = ''
      this.showFaqs = true
    },
    focus() {
      this.$refs.userInput.focus()
    },
  },
}
</script>
