const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-text-account',
    title: 'starterLayout.common.userTerms',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    persistent: true,
    cancelButtonText: 'starterLayout.welcome.termsUse.close',
    buttonTextColor: {
      cancel: 'white',
    },
    buttons: {
      cancel: true,
      accept: false,
    },
    buttonColor: {
      cancel: 'accent',
    },
    height: 800,
    maxWidth: 1000,
    onClickCancel: () => methods.closeDialog(),
  },
})

export default setConfig
