import mutationsTypes from '@/store/chatBot/mutations.types'

const addMessage = (state, message) => {
  state.messages.push(message)
}

const setThreadId = (state, threadId) => {
  state.threadId = threadId
}

const setHelpfulResponse = (state, data) => {
  const { index, helpful } = data
  state.messages[index].helpful = helpful
}

export default {
  [mutationsTypes.ADD_MESSAGE]: addMessage,
  [mutationsTypes.SET_THREAD_ID]: setThreadId,
  [mutationsTypes.SET_HELPFUL_RESPONSE]: setHelpfulResponse,
}
