import { pipe, filter, chain, map, includes, isNil } from 'ramda'

export const getUserMenuItems = state => (data, selectedUser) => {
  if (isNil(data) || isNil(state) || isNil(state.mainMenuItems)) return []

  return pipe(
    chain(item => (item.children ? map(item => item, item.children) : item)),
    filter(item => {
      if (item.permissionToShow !== undefined && selectedUser.id !== null) {
        return (
          selectedUser[item.permissionToShow] === 0 &&
          includes(item.name, state.mainMenuItems)
        )
      }
      return includes(item.name, state.mainMenuItems)
    })
  )(data)
}
