<template>
  <div :class="className">
    <v-tooltip
      :disabled="!tooltipText"
      v-bind="$attrs"
      :color="tooltipColor"
      :top="tooltipPosition === 'top'"
      :right="tooltipPosition === 'right'"
      :left="tooltipPosition === 'left'"
      :bottom="tooltipPosition === 'bottom'"
    >
      <template v-slot:activator="{ on }">
        <v-btn
          :icon="iconBtn"
          v-bind="$attrs"
          :color="color"
          v-on="on"
          @click="onClick"
          class="filter-button"
          :value="btnValue"
          :form="form"
          :type="type"
          ref="customButton"
          :id="id"
          :loading="isLoading"
          :outlined="btnOutlined"
          :text="btnText"
        >
          <v-icon
            v-if="icon"
            :color="$vuetify.theme.isDark ? iconColorDark : textColor"
          >
            {{ icon }}
          </v-icon>
          <FormattedText
            v-if="text"
            :type="textType"
            :className="textClass"
            :intl="intl"
            :value="text"
            :color="textColor"
          />
        </v-btn>
      </template>
      <FormattedText :value="tooltipText" intl :color="tooltipTextColor" />
    </v-tooltip>
  </div>
</template>

<script>
import FormattedText from '@/components/shared/FormattedText.vue'

export default {
  name: 'CustomButton',
  components: { FormattedText },
  props: {
    iconBtn: {
      type: Boolean,
      default: false,
    },
    iconColorDark: {
      type: String,
      default: 'grey darken-4',
    },
    icon: {
      type: String,
      default: '',
    },
    text: {
      type: String,
      default: '',
    },
    textClass: {
      type: String,
      default: '',
    },
    textType: {
      type: String,
      default: '',
    },
    textColor: {
      type: String,
      default: 'white',
    },
    tooltipText: {
      type: String,
      default: '',
    },
    tooltipTextColor: {
      type: String,
      default: '',
    },
    tooltipColor: {
      type: String,
      default: '',
    },
    tooltipPosition: {
      type: String,
      default: '',
    },
    className: {
      type: String,
      default: '',
    },
    intl: {
      type: Boolean,
      default: false,
    },
    isLoading: {
      type: Boolean,
      default: false,
    },
    btnValue: {
      type: String,
      default: '',
    },
    color: {
      type: String,
      default: 'primary',
    },
    form: {
      type: String,
      default: '',
    },
    type: {
      type: String,
      default: 'button',
    },
    btnText: {
      type: Boolean,
      default: false,
    },
    btnOutlined: {
      type: Boolean,
      default: false,
    },
    id: {
      type: String,
      default: '',
    },
  },
  methods: {
    onClick(event) {
      this.$emit('click', event)
    },
  },
}
</script>

<style lang="scss" scoped>
.filter-button.theme--light.v-btn--active::before {
  opacity: 0.6;
}

.filter-button.theme--light.v-btn:hover::before {
  opacity: 0.3;
}
</style>
