import { required } from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  fields: [
    {
      id: 'country',
      type: 'countrySelector',
      validators: { required },
      changeEvent: methods.countryChanged,
    },
  ],
  id: 'country-selection-form',
  onSubmit: () => {},
})

export default setConfig
