import types from '@/store/expensesView/mutations.types'

const setAddExpenseDialogStatus = (state, payload) => {
  state.addExpenseDialog.isOpen = payload
}

const setExpenseSelected = (state, payload) => {
  state.addExpenseDialog.expenseSelected = payload
}

const setAddOtherExpenseDialogStatus = (state, payload) => {
  state.addOtherExpenseDialog.isOpen = payload
}

const setSearchTermFilter = (state, payload) => {
  state.filters.searchTerm = payload
}

export default {
  [types.SET_ADD_EXPENSE_DIALOG_STATUS]: setAddExpenseDialogStatus,
  [types.SET_EXPENSE_SELECTED]: setExpenseSelected,
  [types.SET_ADD_OTHER_EXPENSE_DIALOG_STATUS]: setAddOtherExpenseDialogStatus,
  [types.SET_SEARCH_TERM_FILTER]: setSearchTermFilter,
}
