import { customer as customerMapper } from '@/config/storeMapper'

import { mapStoreObject } from '@/tools/data'

export const updateCustomerData = (enrolledCustomer, customers, sales) => {
  const customerSales = sales.filter(
    sale => sale.customer_id === enrolledCustomer.customerId
  )
  const customer = customers.filter(
    customer => customer._id === enrolledCustomer.customerId
  )[0]
  enrolledCustomer.status = Number(enrolledCustomer.status)
  enrolledCustomer.customer = mapStoreObject(customer, customerMapper)
  enrolledCustomer.customer.lastSaleDate =
    customerSales.length < 1
      ? '-'
      : customerSales
          .reduce((prev, current) =>
            prev.sale_date > current.sale_date ? prev : current
          )
          .sale_date.substring(0, 10)
  return enrolledCustomer
}
