<template>
  <v-container fluid color="mainBackground">
    <v-row no-gutters id="helpCenter-section">
      <HelpCenterView />
    </v-row>
    <v-row no-gutters id="changelog-section" class="px-8">
      <!-- Title -->
      <div class="d-flex align-center paginated-title">
        <v-icon color="primary" large>mdi-new-box</v-icon>
        <FormattedText
          intl
          type="text-h6"
          color="textPrimary"
          class="pl-2"
          value="mainLayout.changelog.title"
        />
      </div>
      <v-col cols="12">
        <TextCarousel :height="60" :items="changelog" />
      </v-col>
    </v-row>
  </v-container>
</template>

<script>
import { values } from 'ramda'
import { mapState, mapActions } from 'vuex'

import i18n from '@/plugins/i18n'

import notificationsService from '@/services/renderer/notifications'

import suppliersActions from '@/store/suppliers/action.types'

import HelpCenterView from '@/components/HelpCenterView'
import TextCarousel from '@/components/shared/TextCarousel'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'HelpCenter',
  components: {
    HelpCenterView,
    TextCarousel,
    FormattedText,
  },
  data: () => ({
    version: process.env.VUE_APP_VERSION,
    colors: [
      'indigo',
      'warning',
      'pink darken-2',
      'red lighten-1',
      'deep-purple accent-4',
    ],
    changelog: [
      {
        id: 1,
        title: 'Productos a granel báscula',
        description:
          'Ya puedes conectar tu báscula (Torrey) a Tiendatek mediante el puerto COM3',
      },
      {
        id: 2,
        title: 'Productos a granel báscula 2',
        description:
          'Se introducirá el peso automáticamente en los productos a granel mediante la báscula',
      },
      {
        id: 3,
        title: 'Como vendo granel',
        description:
          'Ya puedes modificar el cómo vendes tus productos a granel',
      },
      {
        id: 4,
        title: 'Como vendo granel 2',
        description:
          'Desde los detalles de un producto de granel puedes seleccionar el como lo vendes y especificar el nuevo stock y precio.',
      },
      {
        id: 5,
        title: 'Rendimiento',
        description: 'Se ha mejorado el rendimiento de la aplicación',
      },
      {
        id: 6,
        title: 'Bugs',
        description:
          'Se han corregido una serie de problemas menores para mejorar la estabilidad de la aplicación',
      },
    ],
  }),
  computed: {
    ...mapState('suppliers', { suppliers: state => state.data.suppliers }),
  },
  methods: {
    ...mapActions('suppliers', values(suppliersActions)),
    changeLocale(locale) {
      i18n.locale = locale
      notificationsService.showDefault(
        'notification.preferences.lang',
        this.$vuetify.lang
      )
    },
  },
}
</script>

<style lang="scss">
#changelog-section {
  height: 100%;
  min-height: 150px;
}
</style>
