import mutationsTypes from '@/store/chatBot/mutations.types'

export const addMessage = ({ commit }, data) => {
  commit(mutationsTypes.ADD_MESSAGE, {
    ...data,
    type: data.options ? 'button' : 'text',
    disableInput: !!data.options,
  })
}

export const setThreadId = ({ commit }, threadId) => {
  commit(mutationsTypes.SET_THREAD_ID, threadId)
}

export const setHelpfulResponse = ({ commit }, data) => {
  commit(mutationsTypes.SET_HELPFUL_RESPONSE, data)
}
