import Vue from 'vue'

import { promotions } from '@/config/promotions'

import { comboPromotion } from '@/tools/customPromotions'

import types from '@/store/customPromotions/mutations.types'

export const addLastUpdate = (state, lastUpdate) => {
  state.data.lastUpdate = lastUpdate
}

export const addCustomPromotions = (state, promotions) => {
  state.data.promotions = promotions
}

export const addDeletedCustomPromotions = (state, deletedPromotions) => {
  state.data.deletedPromotions = deletedPromotions
}

export const saveCustomPromotion = (state, promotion) => {
  Vue.set(state.data.promotions, promotion.id, promotion)
}

export const deleteCustomPromotion = (state, promotionId) => {
  Vue.set(state.data.deletedPromotions, promotionId, {
    ...state.data.promotions[promotionId],
    deleted: 1,
  })
  Vue.delete(state.data.promotions, promotionId)
}

export const bulkCustomPromotionsDeletion = (state, promotionsIdsToDelete) => {
  promotionsIdsToDelete.forEach(promotionId => {
    deleteCustomPromotion(state, promotionId)
  })
}

export const disableCustomPromotion = (state, promotionsId) => {
  promotionsId.forEach(promotionId => {
    Vue.set(state.data.promotions, promotionId, {
      ...state.data.promotions[promotionId],
      active: 0,
      startDate: '',
      finishDate: '',
    })
  })
}

export const updateProduct = (state, { promotionsToUpdate, product }) => {
  promotionsToUpdate.forEach(promotion => {
    if (promotion.type === promotions.SALE_ITEM_MORE_FOR_LESS) {
      Vue.set(state.data.promotions, promotion.id, {
        ...promotion,
        product: { ...promotion.product, ...product },
      })
      return
    }
    if (promotion.promotions.firstProduct.id === product.id) {
      Object.assign(promotion.promotions.firstProduct, product)
    }
    if (promotion.promotions.secondProduct.id === product.id) {
      Object.assign(promotion.promotions.secondProduct, product)
    }
    Object.assign(
      promotion.promotions,
      comboPromotion.getPromotionUnitPrices(
        promotion.promotions.firstProduct,
        promotion.promotions.secondProduct,
        promotion.promotions.total
      )
    )
    Vue.set(state.data.promotions, promotion.id, promotion)
  })
}

export default {
  [types.ADD_LAST_UPDATE]: addLastUpdate,
  [types.ADD_CUSTOM_PROMOTIONS]: addCustomPromotions,
  [types.ADD_DELETED_CUSTOM_PROMOTIONS]: addDeletedCustomPromotions,
  [types.SAVE_CUSTOM_PROMOTION]: saveCustomPromotion,
  [types.DELETE_CUSTOM_PROMOTION]: deleteCustomPromotion,
  [types.BULK_CUSTOM_PROMOTIONS_DELETION]: bulkCustomPromotionsDeletion,
  [types.DISABLE_CUSTOM_PROMOTION]: disableCustomPromotion,
  [types.UPDATE_PRODUCT]: updateProduct,
}
