import { filterBy } from '@/store/products/getters.tools'

export const getFilteredProducts = (...args) => {
  const purchasesViewState = args[2].purchasesView
  const isScannerActive = args[2].app.scanner.isActive
  const productsState = args[2].products
  const vendorSelected = args[2].vendorsView.selectedVendor.id
  const existByWeightTree =
    args[2].products.data.byWeightTree.length > 0 ? true : false
  const {
    searchTerm,
    group,
    superCategories: selectedSuperCategories,
  } = purchasesViewState.filters
  const { products } = productsState.data
  if (searchTerm !== null)
    return filterBy.searchTerm(searchTerm, products, isScannerActive)
  if (group)
    return filterBy.group(group, products, {
      selectedSuperCategories,
      existByWeightTree,
      vendorId: vendorSelected,
    })
  return products
}
