<template>
  <DialogCard :config="componentConfig.dialogData">
    <Form :config="componentConfig" />
  </DialogCard>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import OPEN_REGISTER_EVENTS from '@/config/events/openRegister'

import { cleanObjectObserver } from '@/tools/data'
import { formatNumberToDb } from '@/tools/numbersFormat'
import { captureException } from '@/tools/exceptions'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import usersViewActions from '@/store/usersView/actions.types'

import DialogCard from '@/components/shared/DialogCard'
import Form from '@/components/shared/Form'
import setConfig from '@/components/MainView/AmountDialog/config'

export default {
  name: 'AmountDialog',
  components: { DialogCard, Form },
  props: {
    opened: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
    }
  },
  computed: {
    ...mapState('usersView', ['selectedUser', 'estimatedCash']),
    isOpened() {
      return this.opened
    },
    componentConfig() {
      return setConfig(
        {
          opened: this.isOpened,
          inputs: this.inputs,
          v: this.$v.inputs,
        },
        {
          closeDialog: this.closeDialog,
          checkAdjustRegister: this.checkAdjustRegister,
        }
      )
    },
  },
  validations() {
    return this.validators
  },
  methods: {
    ...mapActions('usersView', [
      usersViewActions.generateCloseRegisterOperation,
    ]),
    setProperties: function() {
      this.componentConfig.fields.forEach(field => {
        this.$set(this.inputs, field.id, '')
        if (field.validators)
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
    },
    checkAdjustRegister() {
      if (this.$v.inputs.$invalid) {
        Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$touch())
        return
      }
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'CloseCashRegister',
        name: 'Submit',
      })
      const difference = (
        parseFloat(this.inputs.amount) -
        (this.estimatedCash ? this.estimatedCash : 0)
      ).toFixed(2)

      if (!this.selectedUser.registerAdjustPermission) {
        this.$track({
          type: 'system',
          action: 'show_popup',
          category: this.$route.name,
          screen: 'CloseCashRegister',
          name: 'Show cash adjustment',
        })
        this.$emit('checkAdjustRegister', {
          amount: this.inputs.amount,
          difference,
        })
        return
      }

      rendererEventsService.send(OPEN_REGISTER_EVENTS.channel, {
        event: OPEN_REGISTER_EVENTS.events.closeRegister.name,
        data: {
          user: this.selectedUser.id,
          amount: formatNumberToDb(this.inputs.amount),
          difference: formatNumberToDb(difference),
        },
      })
    },
    closeDialog() {
      Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$reset())
      Object.keys(this.inputs).forEach(key => (this.inputs[key] = ''))
      this.$emit('closeDialog')
    },
  },
  created() {
    rendererEventsService.subscribe(
      OPEN_REGISTER_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [OPEN_REGISTER_EVENTS.events.closeRegister.replies.error]: () => {
            notificationsService.showError(
              payload.data.message,
              this.$vuetify.lang
            )
          },
          [OPEN_REGISTER_EVENTS.events.closeRegister.replies.success]: () => {
            this.$track({
              type: 'system',
              action: 'close_cash_register',
              category: this.$route.name,
              screen: 'CloseCashRegister',
              name: 'Go to open register',
            })
            this[usersViewActions.generateCloseRegisterOperation]({
              isOpen: false,
            })
            this.$router
              .push({ path: '/app/openRegister' })
              .catch(error => captureException(error))
          },
        }
        replies[payload.event]()
      }
    )
  },
  mounted: async function() {
    this.$barcodeScanner.destroy()
    this.setProperties()
  },
  beforeDestroy() {
    this.$root.$emit('enable-scanner', {})
    rendererEventsService.removeAllListeners(OPEN_REGISTER_EVENTS.replyChannel)
  },
}
</script>
