import types from '@/store/customPromotionsView/mutations.types'

let initialState = {}

export const setDefaultState = state => {
  initialState = JSON.parse(JSON.stringify(state))
}

export const updateFilters = (state, filters) => {
  Object.assign(state.filters, filters)
}

export const toggleViewMode = state => {
  state.viewMode = state.viewMode === 'card' ? 'table' : 'card'
}

export const setDeleteDisabledCustomPromotionsDialogStatus = (
  state,
  status
) => {
  state.deleteDisabledCustomPromotionsDialog.isOpen = status
}

export const setCreateCustomPromotionDialogStatus = (
  state,
  { isOpen, type }
) => {
  state.createCustomPromotionDialog.isOpen = isOpen
  state.createCustomPromotionDialog.promotionType = type
}

export const setEditCustomPromotionDialogStatus = (state, status) => {
  state.editCustomPromotionDialog.isOpen = status
}

export const setDeleteCustomPromotionDialogStatus = (state, status) => {
  state.deleteCustomPromotionDialog.isOpen = status
}

export const toggleAddProductDialog = (state, resetSearchTerm) => {
  state.newProductDialog.isOpen = !state.newProductDialog.isOpen
  if (resetSearchTerm) {
    state.filters.searchTerm = null
  }
}

export const resetStateValues = state => {
  const stateNotToReset = { viewMode: state.viewMode }
  Object.assign(
    state,
    JSON.parse(JSON.stringify(initialState)),
    stateNotToReset
  )
}

export default {
  [types.UPDATE_FILTERS]: updateFilters,
  [types.TOGGLE_VIEW_MODE]: toggleViewMode,
  [types.SET_DELETE_DISABLED_CUSTOM_PROMOTIONS_DIALOG_STATUS]: setDeleteDisabledCustomPromotionsDialogStatus,
  [types.SET_CREATE_CUSTOM_PROMOTION_DIALOG_STATUS]: setCreateCustomPromotionDialogStatus,
  [types.SET_EDIT_CUSTOM_PROMOTION_DIALOG_STATUS]: setEditCustomPromotionDialogStatus,
  [types.SET_DELETE_CUSTOM_PROMOTION_DIALOG_STATUS]: setDeleteCustomPromotionDialogStatus,
  [types.TOGGLE_ADD_PRODUCT_DIALOG]: toggleAddProductDialog,
  [types.RESET_STATE_VALUES]: resetStateValues,
}
