import types from './mutations.types'

const setDateRange = (state, payload) => {
  state.filters.dateRange = payload
}

const setGroupFilter = (state, payload) => {
  if (state.filters.setGroup !== payload) {
    state.filters.group = payload
  }
}

const setOperationTypes = (state, payload) => {
  state.filters.operationTypes = payload
}

const setOperationDetailDialogStatus = (state, payload) => {
  state.operationDetailDialog.isOpen = payload
}

const setOperationSelected = (state, payload) => {
  state.operationDetailDialog.operationSelected = payload
}

const setDeleteOperationDialogStatus = (state, payload) => {
  state.deleteOperationDialog.isOpen = payload
}

const setDeleteProductDialogStatus = (state, payload) => {
  state.deleteProductDialog.isOpen = payload
}

const setProductSelected = (state, payload) => {
  state.deleteProductDialog.productSelected = payload
}

const setSearchFilter = (state, search) => {
  state.filters.search = search
}

export default {
  [types.SET_DATE_RANGE_FILTER]: setDateRange,
  [types.SET_GROUP_FILTER]: setGroupFilter,
  [types.SET_OPERATION_TYPES_FILTER]: setOperationTypes,
  [types.SET_OPERATION_DETAIL_DIALOG_STATUS]: setOperationDetailDialogStatus,
  [types.SET_OPERATION_SELECTED]: setOperationSelected,
  [types.SET_OPERATION_DELETE_DIALOG_STATUS]: setDeleteOperationDialogStatus,
  [types.SET_OPERATION_PRODUCT_DELETE_DIALOG_STATUS]: setDeleteProductDialogStatus,
  [types.SET_OPERATION_PRODUCT_SELECTED]: setProductSelected,
  [types.SET_SEARCH_FILTER]: setSearchFilter,
}
