<template>
  <v-card class="px-6 pt-6 pb-2 form-card">
    <div class="primary form-top-bar" />
    <v-card-title class="flex-column justify-center pt-1">
      <FormattedText
        type="text-h6"
        intl
        value="starterLayout.welcome.selectCountry"
      />
    </v-card-title>
    <v-card-text>
      <Form :config="formConfig" />
      <FormattedText
        type="text-body-1"
        intl
        value="starterLayout.welcome.title"
      />
      <CustomButton
        block
        large
        rounded
        :disabled="shouldDisabled"
        @click="routeTo('/externalLogin')"
        :form="formConfig.id"
        text="starterLayout.welcome.createAccount"
        textType="text-button"
        textClass="text-none"
        intl
        class="my-6"
        ref="createAccountSubmit"
        v-track:click="{
          category: 'Signup',
          screen: 'Welcome',
          name: 'Go to register',
        }"
      />
      <CustomButton
        block
        large
        rounded
        btnOutlined
        :disabled="shouldDisabled"
        @click="routeTo('/login')"
        :form="formConfig.id"
        text="starterLayout.welcome.login"
        textType="text-button"
        textClass="text-none"
        :textColor="shouldDisabled ? 'grey' : 'primary'"
        intl
        ref="externalLoginSubmit"
        v-track:click="{
          category: 'Signup',
          screen: 'Welcome',
          name: 'Go to login',
        }"
      />
      <TermsAlert />
    </v-card-text>
  </v-card>
</template>

<script>
import { mapActions } from 'vuex'

import APP_TOOLS_EVENTS from '@/config/events/appTools'
import PUBSUB_EVENTS from '@/config/events/pubsub'
import countries from '@/config/countries'

import { cleanObjectObserver, getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'

import setConfig from '@/components/AuthViews/WelcomeView/WelcomeViewForm/config'
import Form from '@/components/shared/Form'
import FormattedText from '@/components/shared/FormattedText'
import CustomButton from '@/components/shared/CustomButton'
import TermsAlert from '@/components/AuthViews/TermsAlert'

export default {
  name: 'WelcomeViewForm',
  components: {
    TermsAlert,
    FormattedText,
    Form,
    CustomButton,
  },
  data() {
    return {
      country: '',
      inputs: {},
      validators: { inputs: {} },
    }
  },
  computed: {
    shouldDisabled() {
      return (
        !this.$v.inputs.country ||
        (this.$v.inputs.country && this.$v.inputs.country.$invalid)
      )
    },
    formConfig() {
      return setConfig(
        {
          inputs: this.inputs,
          v: this.$v.inputs,
        },
        {
          countryChanged: this.countryChanged,
        }
      )
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('app', [appActions.setCountrySelected]),
    countryChanged(value) {
      this.updateCountryTrack(value)
      this.$track({
        type: 'interaction',
        action: 'change',
        category: 'Signup',
        screen: 'Welcome',
        name: `Change country`,
        extra_data: {
          label1: 'country',
          value1: value,
        },
      })
    },
    setProperties() {
      this.formConfig.fields.forEach(field => {
        this.$set(this.inputs, field.id, '')
        if (field.validators) {
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
        }
      })
    },
    routeTo(route) {
      this.$router.push({ path: route })
    },
    async initialize() {
      await rendererEventsService.send(APP_TOOLS_EVENTS.channel, {
        event: APP_TOOLS_EVENTS.events.getLocation.name,
      })
    },
    locationListener(event, payload) {
      const replies = {
        [APP_TOOLS_EVENTS.events.getLocation.replies.success]: () => {
          this.country = payload.data.country
          this.setProperties()
          this.$track({
            type: 'system',
            action: 'geolocation',
            category: 'Signup',
            screen: 'Welcome',
            name: `Country geolocation`,
            extra_data: {
              label1: 'country',
              value1: this.country || undefined,
            },
          })
          if (this.country && this.country in countries) {
            this.updateCountryTrack(this.country)
            this.inputs.country = this.country
          }
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    updateCountryTrack(value) {
      rendererEventsService.send(PUBSUB_EVENTS.channel, {
        event: PUBSUB_EVENTS.events.updatePosInfo.name,
        data: {
          country: countries[value].phone,
        },
      })
    },
  },
  validations() {
    return this.validators
  },
  watch: {
    'inputs.country'() {
      this.country = this.inputs['country']
      this[appActions.setCountrySelected](this.inputs['country'])
    },
  },
  async mounted() {
    rendererEventsService.subscribe(
      APP_TOOLS_EVENTS.replyChannel,
      this.locationListener
    )
    await this.initialize()
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      APP_TOOLS_EVENTS.replyChannel,
      this.locationListener
    )
  },
}
</script>

<style>
.form-card {
  border-radius: 8px !important;
  position: relative;
}
.form-top-bar {
  height: 8px;
  width: 100%;
  position: absolute;
  top: 0;
  left: 0;
}
</style>
