import { storeInventory } from '@/config/storeMapper'

import { mapStoreObject } from '@/tools/data'
import { formatNumberToDb } from '@/tools/numbersFormat'

export const setValue = (methods, field, newValue) => {
  const value = isNaN(parseInt(newValue)) ? 0 : parseInt(newValue)
  methods.setSelectedProductField({ field: field, value: value })
}

export const setDecimalValue = (methods, field, newValue) => {
  const value = isNaN(parseFloat(newValue)) ? 0 : formatNumberToDb(newValue)
  methods.setSelectedProductField({ field: field, value: value })
}

export const getPackagesStockValue = (quantity, factor) => {
  if (factor <= 1) return 0
  return factor === 0
    ? Math.floor(quantity) | 0
    : Math.floor(quantity / factor) | 0
}

export const setPackagesStockValue = (methods, factor, quantity, newValue) => {
  if (factor <= 1) return
  const value = isNaN(parseInt(newValue)) ? 0 : parseInt(newValue)
  quantity = value * factor + getPiecesStockValue(quantity, factor)
  methods.setSelectedProductField({ field: 'quantity', value: quantity })
}

export const getPiecesStockValue = (quantity, factor) => {
  return factor > 1 ? quantity % factor : quantity
}

export const setPiecesStockValue = (methods, factor, quantity, newValue) => {
  const value = isNaN(parseInt(newValue)) ? 0 : parseInt(newValue)
  quantity = getPackagesStockValue(quantity, factor) * factor + value
  methods.setSelectedProductField({ field: 'quantity', value: quantity })
}

export const setOpenProductStockValue = (methods, field, newValue) => {
  const value = isNaN(parseInt(newValue)) ? 0 : parseInt(newValue)
  methods.setSelectedProductField({ field: field, value: value })
}

export const getPiecePriceValue = (price, unitProdPrice, factor) => {
  return factor > 1 ? unitProdPrice : price
}

export const setPiecePriceValue = (methods, factor, newValue) => {
  const value = isNaN(parseFloat(newValue)) ? 0 : formatNumberToDb(newValue)
  const field = factor > 1 ? 'unitProdPrice' : 'price'
  methods.setSelectedProductField({ field: field, value: value })
}

export const finishPiecePriceEdit = (methods, product) => {
  const data = {}
  const field = product.factor > 1 ? 'unitProdPrice' : 'price'
  data[field] = product[field]
  methods.updateDatabase({
    id: product.id,
    data: mapStoreObject(data, storeInventory, true),
  })
}

export const getPieceCostValue = (cost, factor) => {
  return factor > 1 ? cost / factor : cost
}

export const setPieceCostValue = (methods, factor, newValue) => {
  let value = isNaN(parseFloat(newValue)) ? 0 : formatNumberToDb(newValue)
  value = factor > 1 ? value * factor : value
  methods.setSelectedProductField({ field: 'cost', value: value })
}

export const getPieceMarginValue = (
  price,
  unitProdPrice,
  cost,
  factor,
  tax = 1
) => {
  if (factor <= 1) {
    return getPackageMarginValue(price, cost, tax)
  }
  cost = cost / factor
  if (price < 0 || cost < 0 || !price || !cost) {
    return '?'
  }
  return `${((unitProdPrice / (cost * tax) - 1) * 100).toFixed(2)} %`
}

export const getPackageMarginValue = (price, cost, tax = 1) => {
  if (price < 0 || cost < 0 || !price || !cost) {
    return '?'
  }
  return `${((Number(price) / (Number(cost) * tax) - 1) * 100).toFixed(2)} %`
}
