<template>
  <ToolBar :config="componentConfig" />
</template>

<script>
import { mapActions, mapGetters, mapState } from 'vuex'

import { getTranslatedText } from '@/tools/data'

import usersViewActions from '@/store/usersView/actions.types'

import config from '@/components/HelpCenterView/HelpCenterToolbar/Operations/config'
import ToolBar from '@/components/shared/ToolBar'

export default {
  name: 'HelpCenterOperations',
  components: { ToolBar },
  computed: {
    ...mapGetters('account', ['getPos']),
    ...mapState('usersView', ['selectedUser']),
    componentConfig() {
      return config(
        {},
        {
          getTranslatedText: this.getTranslatedText,
          redoTour: this.redoTour,
        }
      )
    },
  },
  methods: {
    ...mapActions('usersView', [usersViewActions.setSelectedUser]),
    getTranslatedText,
    redoTour(item) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'HelpCenter',
        screen: 'RedoTour',
        name: `Re-do ${item.id} tour`,
      })
      this[usersViewActions.setSelectedUser]({
        ...this.selectedUser,
        [`${item.id}TourDisabled`]: 0,
      })
      this.$router.push({ path: `/app/${item.id}` })
    },
  },
}
</script>
