import types from '@/store/customersView/mutations.types'

const setAddCustomerDialogStatus = (state, payload) => {
  state.addCustomerDialog.isOpen = payload
}

const setCustomerDetailDialogStatus = (state, payload) => {
  state.customerDetailDialog.isOpen = payload
}

const setCustomerSelected = (state, payload) => {
  state.customerDetailDialog.customerSelected = payload
}

const setSearchTermFilter = (state, payload) => {
  state.filters.searchTerm = payload
}

const updateSelectedCustomerField = (state, payload) => {
  state.customerDetailDialog.customerSelected[payload.field] = payload.value
}

const setDeleteCustomerDialogStatus = (state, payload) => {
  state.deleteCustomerDialog.isOpen = payload
}

const setSettleDebtDialogStatus = (state, payload) => {
  state.settleDebtDialog.isOpen = payload
}

const setSettleCreditSaleDialogStatus = (state, payload) => {
  state.settleCreditSaleDialog.isOpen = payload
}

const setSaleToSettleDebt = (state, payload) => {
  state.settleCreditSaleDialog.sale = payload
}

export default {
  [types.SET_ADD_CUSTOMER_DIALOG_STATUS]: setAddCustomerDialogStatus,
  [types.SET_CUSTOMER_DETAIL_DIALOG_STATUS]: setCustomerDetailDialogStatus,
  [types.SET_CUSTOMER_SELECTED]: setCustomerSelected,
  [types.SET_SEARCH_TERM_FILTER]: setSearchTermFilter,
  [types.UPDATE_SELECTED_CUSTOMER_FIELD]: updateSelectedCustomerField,
  [types.SET_DELETE_CUSTOMER_DIALOG_STATUS]: setDeleteCustomerDialogStatus,
  [types.SET_SETTLE_DEBT_DIALOG_STATUS]: setSettleDebtDialogStatus,
  [types.SET_SETTLE_CREDIT_SALE_DIALOG_STATUS]: setSettleCreditSaleDialogStatus,
  [types.SET_SALE_TO_SETTLE_DEBT]: setSaleToSettleDebt,
}
