<template>
  <DialogCard :config="componentConfig.dialogData" />
</template>

<script>
import { mapActions, mapState } from 'vuex'

import appActions from '@/store/app/actions.types'

import setConfig from '@/components/MainView/ShowMaxSyncOpsDialog/config'
import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'ShowMaxSyncOpsDialog',
  components: { DialogCard },
  computed: {
    ...mapState('app', ['maxSyncOpsDialog']),
    componentConfig() {
      return setConfig(
        { opened: this.maxSyncOpsDialog.isOpen },
        { closeDialog: this.closeDialog }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.setMaxSyncOpsDialogStatus]),
    closeDialog() {
      this[appActions.setMaxSyncOpsDialogStatus](false)
    },
  },
}
</script>
