<template>
  <transition appear name="fade">
    <v-container fill-height class="login">
      <v-row class="text-center">
        <v-col cols="12" class="pt-0">
          <v-row align="center" justify="center">
            <v-col align="center" justify="center" class="pt-0">
              <LoginViewHeader />
            </v-col>
          </v-row>
        </v-col>
        <v-col cols="12">
          <v-row align="center" justify="center">
            <v-col>
              <ProgressBar :message="newMessages" />
            </v-col>
          </v-row>
        </v-col>
      </v-row>
    </v-container>
  </transition>
</template>

<script>
import { values, isEmpty } from 'ramda'
import { mapActions, mapState } from 'vuex'

import { isDevelopment, ytTutorialTiendatek } from '@/config/env'
import STARTER_EVENTS from '@/config/events/starter'
import RESTORE_EVENTS from '@/config/events/restore'
import ENTITIES_EVENTS from '@/config/events/databaseAPI/entitiesEvents'
import SUPPLIERS_EVENTS from '@/config/events/databaseAPI/suppliersEvents'
import DIAGNOSTIC_EVENTS from '@/config/events/diagnostic'
import AIRTIME_API_EVENTS from '@/config/events/airtime'
import LICENSE_API_EVENTS from '@/config/events/license'
import {
  PROCEDENCE_STARTER,
  PROCEDENCE_UPDATE,
} from '@/config/pushTokenProcedence'
import YOUTUBE_API_EVENTS from '@/config/events/youtube'
import UPDATER_EVENTS from '@/config/events/updater'
import MLP_API_EVENTS from '@/config/events/databaseAPI/mlpEvents'
import HOME_CODES_DB_API_EVENTS from '@/config/events/databaseAPI/byWeightHomeCodesEvents'
import SYNCHRONIZATION_EVENTS from '@/config/events/synchronization'
import PAYMENT_METHODS_DB_API_EVENTS from '@/config/events/databaseAPI/paymentProvidersEvents'
import DEVICE_INFO_EVENTS from '@/config/events/deviceInfo'
import WHATSAPP_TEMPLATES_API_EVENTS from '@/config/events/serversAPI/whatsappTemplates'
import PUBSUB_EVENTS from '@/config/events/pubsub'
import countries from '@/config/countries'

import { captureException } from '@/tools/exceptions'

import { checkIfAllObjectPropsAreTrue } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import pushNotificationsService from '@/services/renderer/pushNotifications'

import appActions from '@/store/app/actions.types'
import usersActions from '@/store/users/actions.types'
import usersViewActions from '@/store/usersView/actions.types'
import productsActions from '@/store/products/actions.types'
import customersActions from '@/store/customers/actions.types'
import accountActions from '@/store/account/actions.types'
import suppliersActions from '@/store/suppliers/action.types'
import vendorsActions from '@/store/vendors/actions.types'
import airtimeServicesActions from '@/store/airtimeServices/actions.types'
import helpCenterActions from '@/store/helpCenter/actions.types'
import loyaltyProgramActions from '@/store/loyaltyProgram/actions.types'
import whatsappTemplatesActions from '@/store/whatsappTemplates/actions.types'

import LoginViewHeader from '@/components/AuthViews/Header'
import ProgressBar from '@/components/shared/ProgressBar'

export default {
  name: 'Starter',
  components: {
    LoginViewHeader,
    ProgressBar,
  },
  data() {
    return {
      message: 'appInitialization.default',
      starterStatus: {
        products: false,
        customers: false,
        suppliers: false,
        vendors: false,
        assets: false,
        mls: false,
        airtimeServicesBanks: false,
        airtimeProviders: false,
        youtubeVideos: false,
        enrolledCustomers: false,
        paymentProviders: true,
        whatsappTemplates: false,
      },
      goToProfile: false,
    }
  },
  computed: {
    ...mapState('app', ['darkMode', 'isStoreOpen']),
    ...mapState('account', { accountData: state => state.data }),
    ...mapState('helpCenter', { tutorials: state => state.data.videos }),
    newMessages() {
      return this.message
    },
  },
  methods: {
    ...mapActions('account', [
      accountActions.setPosDataAfterLogin,
      accountActions.sendAppVersion,
    ]),
    ...mapActions('app', [
      appActions.setLogged,
      appActions.setReady,
      appActions.setIsStoreOpen,
      appActions.setPreferencesData,
      appActions.setZoomLevelFromAppProcess,
      appActions.setCountrySelected,
      appActions.setShowScanYourProductsDialogStatus,
    ]),
    ...mapActions('users', [usersActions.getUsers]),
    ...mapActions('usersView', [
      usersViewActions.setSelectedUser,
      usersViewActions.getEstimatedCash,
    ]),
    ...mapActions('products', [
      productsActions.fetchProducts,
      productsActions.setProductsOrSuperCategoriesFetching,
      productsActions.setProductsOrSuperCategoriesError,
    ]),
    ...mapActions('customers', [
      customersActions.fetchCustomers,
      customersActions.setCustomersFetching,
      customersActions.setCustomersError,
    ]),
    ...mapActions('helpCenter', [
      helpCenterActions.fetchVideos,
      helpCenterActions.setVideoFetching,
      helpCenterActions.setVideoError,
    ]),
    ...mapActions('suppliers', values(suppliersActions)),
    ...mapActions('vendors', values(vendorsActions)),
    ...mapActions('airtimeServices', [airtimeServicesActions.setBanks]),
    ...mapActions('loyaltyProgram', [
      loyaltyProgramActions.setLoyaltyFetching,
      loyaltyProgramActions.setEnrolledCustomers,
      loyaltyProgramActions.setEnrolledCustomersError,
    ]),
    ...mapActions('whatsappTemplates', [
      whatsappTemplatesActions.setWhatsappTemplates,
    ]),
    onMlsUpdateFinished() {
      this.starterStatus = { ...this.starterStatus, mls: true }
      this[suppliersActions.setSuppliersFetching](true)
      rendererEventsService.send(RESTORE_EVENTS.channel, {
        event: RESTORE_EVENTS.events.restoreAssets.name,
      })
      rendererEventsService.send(ENTITIES_EVENTS.channel, {
        event: ENTITIES_EVENTS.events.getAllByEntities.name,
        data: {
          entitiesToGet: ['suppliers'],
          replyName: 'fetchSuppliers',
        },
      })
    },
  },
  watch: {
    starterStatus: {
      deep: true,
      handler() {
        const isStartterProcessOk = checkIfAllObjectPropsAreTrue(
          this.starterStatus
        )
        if (isStartterProcessOk) {
          rendererEventsService.send(DIAGNOSTIC_EVENTS.channel, {
            event: DIAGNOSTIC_EVENTS.events.checkDatabase.name,
          })
        }
      },
    },
  },
  created() {
    rendererEventsService.send(STARTER_EVENTS.channel, {
      event: STARTER_EVENTS.events.starterProcess.name,
    })
    rendererEventsService.subscribe(
      STARTER_EVENTS.replyChannel,
      async (event, payload) => {
        const replies = {
          [STARTER_EVENTS.events.starterProcess.replies.databaseReady]: () => {
            this.message = 'appInitialization.databaseReady'
          },
          [STARTER_EVENTS.events.starterProcess.replies
            .databaseInitReady]: () => {
            this.message = 'appInitialization.databaseInitReady'
          },
          [STARTER_EVENTS.events.starterProcess.replies
            .databaseUpdated]: () => {
            this.message = 'appInitialization.databaseUpdated'
          },
          [STARTER_EVENTS.events.starterProcess.replies.posExist]: () => {
            this.goToProfile = payload.data.isProfileCompleted === 0
            this[appActions.setPreferencesData](payload.data)
            this.message = 'appInitialization.loadingPos'
            this[accountActions.setPosDataAfterLogin]({
              posData: payload.data.posData,
              pendingSyncOps: payload.data.pendingSyncOps,
            })
            this[usersViewActions.getEstimatedCash]({
              userInfo: payload.data.userInfo,
            })
            if (payload.data.isStoreOpen === 1)
              this[appActions.setIsStoreOpen]()
            this[usersActions.getUsers](payload.data.allUsers)
            if (this.isStoreOpen)
              this[usersViewActions.setSelectedUser](payload.data.selectedUser)
            this.$vuetify.theme.dark = this.darkMode
            this[productsActions.setProductsOrSuperCategoriesFetching](true)
            rendererEventsService.send(PUBSUB_EVENTS.channel, {
              event: PUBSUB_EVENTS.events.updatePosInfo.name,
              data: {
                pos: payload.data.posData.pos,
                country: countries[payload.data.posData.country].phone,
              },
            })
            rendererEventsService.send(ENTITIES_EVENTS.channel, {
              event: ENTITIES_EVENTS.events.getAllByEntities.name,
              data: {
                entitiesToGet: [
                  'storeInventory',
                  'superCategories',
                  'genericCategories',
                  'byWeightHomeCodes',
                  'airtimeProviders',
                  'airtimeServices',
                ],
                replyName: 'fetchProducts',
              },
            })
            this[customersActions.setCustomersFetching](true)
            rendererEventsService.send(ENTITIES_EVENTS.channel, {
              event: ENTITIES_EVENTS.events.getAllByEntities.name,
              data: {
                entitiesToGet: ['sales', 'customers', 'receivables'],
                replyName: 'fetchCustomers',
              },
            })
            this[vendorsActions.setVendorsFetching](true)
            rendererEventsService.send(ENTITIES_EVENTS.channel, {
              event: ENTITIES_EVENTS.events.getAllByEntities.name,
              data: {
                entitiesToGet: ['vendors', 'purchaseOrder', 'payables'],
                replyName: 'fetchVendors',
              },
            })
            if (this.accountData.loyaltyProgram.loyaltyProgramActived === 1) {
              this[loyaltyProgramActions.setLoyaltyFetching](true)
              rendererEventsService.send(ENTITIES_EVENTS.channel, {
                event: ENTITIES_EVENTS.events.getAllByEntities.name,
                data: {
                  entitiesToGet: ['enrolledCustomers', 'customers', 'sales'],
                  replyName: 'fetchEnrolledCustomers',
                },
              })
            } else {
              this.starterStatus = {
                ...this.starterStatus,
                enrolledCustomers: true,
              }
            }
            if (payload.data.lastVersions) {
              rendererEventsService.send(STARTER_EVENTS.channel, {
                event: STARTER_EVENTS.events.checkRemoteDataVersions.name,
                data: { lastVersions: payload.data.lastVersions },
              })
            } else {
              this.starterStatus = {
                ...this.starterStatus,
                assets: true,
                suppliers: true,
                mls: true,
                airtimeProviders: true,
              }
            }
            rendererEventsService.send(AIRTIME_API_EVENTS.channel, {
              event: AIRTIME_API_EVENTS.events.fetchBanks.name,
              data: {
                token: this.accountData.security.token,
              },
            })
            rendererEventsService.send(WHATSAPP_TEMPLATES_API_EVENTS.channel, {
              event:
                WHATSAPP_TEMPLATES_API_EVENTS.events.getWhatsappTemplates.name,
              data: {
                token: this.accountData.security.token,
              },
            })
            pushNotificationsService.startService(
              payload.data.isAppRecentlyUpdated
                ? PROCEDENCE_UPDATE
                : PROCEDENCE_STARTER
            )
            if (isEmpty(this.tutorials)) {
              this[helpCenterActions.setVideoFetching](true)
              rendererEventsService.send(YOUTUBE_API_EVENTS.channel, {
                event: YOUTUBE_API_EVENTS.events.getPlaylist.name,
                data: {
                  playlistId: ytTutorialTiendatek,
                },
              })
            } else {
              this.starterStatus = {
                ...this.starterStatus,
                youtubeVideos: true,
              }
            }
            if (payload.data.posData.scanProductsDialogCounter >= 3)
              this[appActions.setShowScanYourProductsDialogStatus](false)
            rendererEventsService.send(UPDATER_EVENTS.channel, {
              event: UPDATER_EVENTS.events.checkIfBetaUser.name,
              data: {
                token: this.accountData.security.token,
              },
            })
            this[appActions.setReady](true)
          },
          [STARTER_EVENTS.events.starterProcess.replies.loginIsNeeded]: () => {
            this.$track({
              type: 'system',
              action: 'open_app',
              category: 'Starter',
              screen: 'LoginNeeded',
              name: 'App opened',
            })
            this[appActions.setPreferencesData](payload.data)
            this.message = 'appInitialization.loginNeeded'
            rendererEventsService.send(UPDATER_EVENTS.channel, {
              event: UPDATER_EVENTS.events.checkForUpdates.name,
            })
            setTimeout(
              () => {
                this[appActions.setLogged](false)
                this.$router
                  .push({ path: '/welcome' })
                  .catch(error => captureException(error))
                this[appActions.setZoomLevelFromAppProcess]({
                  preferences: payload.data.preferences,
                })
              },
              isDevelopment ? 2000 : 1000
            )
          },
          [STARTER_EVENTS.events.starterProcess.replies
            .unfinishedRestore]: () => {
            this.$track({
              type: 'system',
              action: 'open_app',
              category: 'Starter',
              screen: 'UnfinishedRestore',
              name: 'App opened',
            })
            this[appActions.setPreferencesData](payload.data)
            this.message = 'appInitialization.unfinishedRestoreTitle'
            setTimeout(
              () => {
                this.$router
                  .push({ name: 'UnfinishedRestore' })
                  .catch(error => captureException(error))
                this[appActions.setZoomLevelFromAppProcess]({
                  preferences: payload.data.preferences,
                })
              },
              isDevelopment ? 2000 : 1000
            )
          },
          [STARTER_EVENTS.events.checkRemoteDataVersions.replies
            .mlsToUpdate]: () => {
            this.starterStatus = { ...this.starterStatus, suppliers: false }
            this.starterStatus = { ...this.starterStatus, assets: false }
            rendererEventsService.send(SUPPLIERS_EVENTS.channel, {
              event: SUPPLIERS_EVENTS.events.downloadAndUpdateMls.name,
              data: {
                version: payload.data.mlsDbVersion,
                securityData: this.accountData.security,
                country: this.accountData.country.phoneCode,
              },
            })
          },
          [STARTER_EVENTS.events.checkRemoteDataVersions.replies
            .mlsIsOk]: () => {
            this.starterStatus = { ...this.starterStatus, mls: true }
            rendererEventsService.send(ENTITIES_EVENTS.channel, {
              event: ENTITIES_EVENTS.events.getAllByEntities.name,
              data: {
                entitiesToGet: ['suppliers'],
                replyName: 'fetchSuppliers',
              },
            })
            rendererEventsService.send(RESTORE_EVENTS.channel, {
              event: RESTORE_EVENTS.events.restoreAssets.name,
            })
          },
          [STARTER_EVENTS.events.checkRemoteDataVersions.replies
            .airtimeProvidersToUpdate]: () => {
            rendererEventsService.send(AIRTIME_API_EVENTS.channel, {
              event:
                AIRTIME_API_EVENTS.events.downloadAndUpdateAirtimeProviders
                  .name,
              data: {
                version: payload.data.airtimeProvidersDbVersion,
                securityData: this.accountData.security,
                country: this.accountData.country.phoneCode,
              },
            })
          },
          [STARTER_EVENTS.events.checkRemoteDataVersions.replies
            .airtimeProvidersIsOk]: () => {
            this.starterStatus = {
              ...this.starterStatus,
              airtimeProviders: true,
            }
          },
          [STARTER_EVENTS.events.checkRemoteDataVersions.replies
            .paymentProvidersToUpdate]: () => {
            rendererEventsService.send(PAYMENT_METHODS_DB_API_EVENTS.channel, {
              event: PAYMENT_METHODS_DB_API_EVENTS.events.download.name,
              data: {
                version: payload.data.paymentProvidersDbVersion,
                securityData: this.accountData.security,
                countryCode: this.accountData.country.phoneCode,
              },
            })
          },
          [STARTER_EVENTS.events.checkRemoteDataVersions.replies
            .paymentProvidersIsOk]: () => {
            this.$root.$emit('getPaymentProviders')
            this.starterStatus = {
              ...this.starterStatus,
              paymentProviders: true,
            }
          },
          [STARTER_EVENTS.events.checkRemoteDataVersions.replies
            .noInternetConnection]: () => {
            this.starterStatus = {
              ...this.starterStatus,
              assets: true,
              suppliers: true,
              mls: true,
              airtimeProviders: true,
              paymentProviders: true,
            }
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
    rendererEventsService.subscribe(
      ENTITIES_EVENTS.replyChannel,
      async (event, payload) => {
        const getAllReplies = ENTITIES_EVENTS.events.getAllByEntities.replies
        const replies = {
          [`${getAllReplies.success}-fetchProducts`]: () => {
            this[productsActions.fetchProducts](payload.data)
            this.starterStatus = { ...this.starterStatus, products: true }
          },
          [`${getAllReplies.success}-fetchCustomers`]: () => {
            this[customersActions.fetchCustomers](payload.data)
            this.starterStatus = { ...this.starterStatus, customers: true }
          },
          [`${getAllReplies.success}-fetchSuppliers`]: () => {
            this[suppliersActions.setSuppliers](payload.data)
            this.starterStatus = { ...this.starterStatus, suppliers: true }
          },
          [`${getAllReplies.success}-fetchVendors`]: () => {
            this[vendorsActions.setVendors](payload.data)
            this.starterStatus = { ...this.starterStatus, vendors: true }
          },
          [`${getAllReplies.success}-fetchEnrolledCustomers`]: () => {
            this[loyaltyProgramActions.setEnrolledCustomers](payload.data)
            this.starterStatus = {
              ...this.starterStatus,
              enrolledCustomers: true,
            }
          },
          [`${getAllReplies.error}-fetchProducts`]: () => {
            this[productsActions.setProductsOrSuperCategoriesError](
              payload.data
            )
            this[productsActions.setProductsOrSuperCategoriesFetching](false)
          },
          [`${getAllReplies.error}-fetchCustomers`]: () => {
            this[customersActions.setCustomersError](payload.data)
            this[customersActions.setCustomersFetching](false)
          },
          [`${getAllReplies.error}-fetchSuppliers`]: () => {
            this[suppliersActions.setSuppliersError](payload.data)
            this[suppliersActions.setSuppliersFetching](false)
          },
          [`${getAllReplies.error}-fetchVendors`]: () => {
            this[vendorsActions.setVendorsError](payload.data)
            this[vendorsActions.setVendorsFetching](false)
          },
          [`${getAllReplies.error}-fetchEnrolledCustomers`]: () => {
            this[loyaltyProgramActions.setEnrolledCustomersError](payload.data)
            this[loyaltyProgramActions.setLoyaltyFetching](false)
          },
        }
        if (payload.event in replies) replies[payload.event]()
        const regex = new RegExp(`^${getAllReplies.error}-([\\w-]+)$`)
        const match = payload.event.match(regex)
        if (match) {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Starter',
            screen: 'FetchEntities',
            name: `Error ${match[1]}`,
          })
        }
      }
    )
    rendererEventsService.subscribe(
      SUPPLIERS_EVENTS.replyChannel,
      async (event, payload) => {
        const downloadAndUpdateMlsReplies =
          SUPPLIERS_EVENTS.events.downloadAndUpdateMls.replies
        const replies = {
          [`${downloadAndUpdateMlsReplies.success}`]: () => {
            this.onMlsUpdateFinished()
          },
          [`${downloadAndUpdateMlsReplies.error}`]: () => {
            this.onMlsUpdateFinished()
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
    rendererEventsService.subscribe(
      RESTORE_EVENTS.replyChannel,
      async (event, payload) => {
        const restoreReplies = RESTORE_EVENTS.events.restoreAssets.replies
        const replies = {
          [restoreReplies.success]: () => {
            this.starterStatus = { ...this.starterStatus, assets: true }
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
    rendererEventsService.subscribe(
      DIAGNOSTIC_EVENTS.replyChannel,
      async (event, payload) => {
        const diagnosticReplies = DIAGNOSTIC_EVENTS.events.checkDatabase.replies
        const replies = {
          [diagnosticReplies.success]: () => {
            this.$track({
              type: 'system',
              action: 'open_app',
              category: 'Starter',
              screen: 'PosExist',
              name: 'App opened',
            })
            if (this.goToProfile) {
              this[appActions.setReady](false)
              this[appActions.setCountrySelected](
                this.accountData.country.localeIsoCode
              )
              this.$router.push({ path: '/sign-up-profile' })
              setTimeout(() => this[appActions.setReady](true), 1000)
              return
            }

            this.$router
              .push({
                name: this.isStoreOpen ? 'HelpCenter' : 'OpenRegister',
              })
              .catch(error => captureException(error))
            rendererEventsService.send(MLP_API_EVENTS.channel, {
              event: MLP_API_EVENTS.events.downloadMlpUpdatesIfNeeded.name,
              data: {
                country: this.accountData.country.phoneCode,
                device: this.accountData.device,
                operator: this.accountData.operator,
                securityData: this.accountData.security,
              },
            })
            rendererEventsService.send(HOME_CODES_DB_API_EVENTS.channel, {
              event:
                HOME_CODES_DB_API_EVENTS.events.downloadHomesUpdatesIfNeeded
                  .name,
              data: {
                country: this.accountData.country.phoneCode,
                securityData: this.accountData.security,
              },
            })
            rendererEventsService.send(LICENSE_API_EVENTS.channel, {
              event: LICENSE_API_EVENTS.events.checkExpiration.name,
              data: {
                pos: this.accountData.pos,
              },
            })
            rendererEventsService.send(DEVICE_INFO_EVENTS.channel, {
              event: DEVICE_INFO_EVENTS.events.checkIfTTIsBlocked.name,
              data: {
                pos: this.accountData.pos,
                securityData: this.accountData.security,
              },
            })
            rendererEventsService.send(SYNCHRONIZATION_EVENTS.channel, {
              event: SYNCHRONIZATION_EVENTS.events.updateDeviceIp.name,
              data: { securityData: this.accountData.security },
            })
          },
          [diagnosticReplies.error]: () => {
            this.$track({
              type: 'system',
              action: 'error',
              category: 'Starter',
              screen: 'PosExist',
              name: 'Error when open app',
            })
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
    rendererEventsService.subscribe(
      AIRTIME_API_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [AIRTIME_API_EVENTS.events.fetchBanks.replies.success]: () => {
            this[airtimeServicesActions.setBanks](payload.data.banks)
            this.starterStatus = {
              ...this.starterStatus,
              airtimeServicesBanks: true,
            }
          },
          [AIRTIME_API_EVENTS.events.fetchBanks.replies.error]: () => {
            this.starterStatus = {
              ...this.starterStatus,
              airtimeServicesBanks: true,
            }
          },
          [AIRTIME_API_EVENTS.events.fetchBanks.replies
            .noInternetConnection]: () => {
            this.starterStatus = {
              ...this.starterStatus,
              airtimeServicesBanks: true,
            }
          },
          [AIRTIME_API_EVENTS.events.downloadAndUpdateAirtimeProviders.replies
            .success]: () => {
            this[productsActions.setProductsOrSuperCategoriesFetching](true)
            rendererEventsService.send(ENTITIES_EVENTS.channel, {
              event: ENTITIES_EVENTS.events.getAllByEntities.name,
              data: {
                entitiesToGet: [
                  'storeInventory',
                  'superCategories',
                  'genericCategories',
                  'byWeightHomeCodes',
                  'airtimeProviders',
                  'airtimeServices',
                ],
                replyName: 'fetchProducts',
              },
            })
            setTimeout(() => {
              // TODO: improve this
              this.starterStatus = {
                ...this.starterStatus,
                airtimeProviders: true,
              }
            }, 2000)
          },
          [AIRTIME_API_EVENTS.events.downloadAndUpdateAirtimeProviders.replies
            .error]: () => {
            this.starterStatus = {
              ...this.starterStatus,
              airtimeProviders: true,
            }
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
    rendererEventsService.subscribe(
      WHATSAPP_TEMPLATES_API_EVENTS.replyChannel,
      async (event, payload) => {
        const whatsappEvents = WHATSAPP_TEMPLATES_API_EVENTS.events
        const replies = {
          [whatsappEvents.getWhatsappTemplates.replies.success]: () => {
            this[whatsappTemplatesActions.setWhatsappTemplates](payload.data)
            this.starterStatus = {
              ...this.starterStatus,
              whatsappTemplates: true,
            }
          },
          [whatsappEvents.getWhatsappTemplates.replies.error]: () => {
            this.starterStatus = {
              ...this.starterStatus,
              whatsappTemplates: true,
            }
          },
          [whatsappEvents.getWhatsappTemplates.replies
            .noInternetConnection]: () => {
            this.starterStatus = {
              ...this.starterStatus,
              whatsappTemplates: true,
            }
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
    rendererEventsService.subscribe(
      YOUTUBE_API_EVENTS.replyChannel,
      async (event, payload) => {
        const ytReplies = YOUTUBE_API_EVENTS.events.getPlaylist.replies
        const replies = {
          [`${ytReplies.success}`]: () => {
            this[helpCenterActions.fetchVideos](payload.data)
            this.starterStatus = {
              ...this.starterStatus,
              youtubeVideos: true,
            }
          },
          [`${ytReplies.error}`]: () => {
            this[helpCenterActions.setVideoError](payload.data)
            this.starterStatus = {
              ...this.starterStatus,
              youtubeVideos: true,
            }
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(STARTER_EVENTS.replyChannel)
    rendererEventsService.removeAllListeners(ENTITIES_EVENTS.replyChannel)
    rendererEventsService.removeAllListeners(RESTORE_EVENTS.replyChannel)
    rendererEventsService.removeAllListeners(DIAGNOSTIC_EVENTS.replyChannel)
    rendererEventsService.removeAllListeners(AIRTIME_API_EVENTS.replyChannel)
    rendererEventsService.removeAllListeners(YOUTUBE_API_EVENTS.replyChannel)
    rendererEventsService.removeAllListeners(
      WHATSAPP_TEMPLATES_API_EVENTS.replyChannel
    )
  },
}
</script>

