import mutationsTypes from './mutations.types'

const setFetching = (state, newState) => {
  state.fetching = newState
}

const setError = (state, error) => {
  state.data.customers = []
  state.error = true
  state.errorMessage = error
}

const setSuppliers = (state, payload) => {
  state.data.suppliers = payload
  state.error = false
  state.errorMessage = ''
}

export default {
  [mutationsTypes.SET_SUPPLIERS]: setSuppliers,
  [mutationsTypes.SET_SUPPLIERS_FETCHING]: setFetching,
  [mutationsTypes.SET_SUPPLIERS_ERROR]: setError,
}
