const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon:
      state.difference == 0
        ? 'mdi-trophy'
        : state.difference > 0
        ? 'mdi-plus-box'
        : 'mdi-minus-box',
    title:
      state.difference == 0
        ? 'mainLayout.user.registerAdjustedDialogTitle'
        : 'mainLayout.user.registerNotAdjustedDialogTitle',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    messages:
      state.difference == 0
        ? ['mainLayout.user.registerAdjustedDialog']
        : state.difference > 0
        ? [
            'mainLayout.user.registerNotAdjustedMoreDialogPreMsg',
            'mainLayout.user.registerNotAdjustedMoreDialog',
          ]
        : [
            'mainLayout.user.registerNotAdjustedLessDialogPreMsg',
            'mainLayout.user.registerNotAdjustedLessDialog',
          ],
    extraValuesMessages: [Math.abs(state.difference)],
    height: state.difference == 0 ? 250 : 295,
    maxWidth: 500,
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.onAccept(),
  },
})

export default setConfig
