const cancelTrack = function(category) {
  this.$track({
    type: 'interaction',
    action: 'click',
    category: category,
    screen: `${category}Tour`,
    name: 'Cancel tour',
    ...getExtraDataTour(this.tour),
  })
}

const showTrack = function(category) {
  this.$track({
    type: 'system',
    action: 'show_step_tour',
    category: category,
    screen: `${category}Tour`,
    name: 'Show next step',
    ...getExtraDataTour(this.tour),
  })
}

const startTrack = function(category) {
  this.$track({
    type: 'system',
    action: 'start_tour',
    category: category,
    screen: `${category}Tour`,
    name: 'Show tour',
  })
}

const completeTrack = function(category) {
  this.$track({
    type: 'system',
    action: 'finish_tour',
    category: category,
    screen: `${category}Tour`,
    name: 'Complete tour',
  })
}

const getExtraDataTour = tour => {
  if (!tour.getCurrentStep()) return null
  return {
    extra_data: {
      label1: 'step',
      value1: tour.getCurrentStep().id,
    },
  }
}

const initTracks = function(category) {
  if (!this.tour) return
  this.tour.on('cancel', () => cancelTrack.call(this, category))
  this.tour.on('show', () => showTrack.call(this, category))
  this.tour.on('start', () => startTrack.call(this, category))
  this.tour.on('complete', () => completeTrack.call(this, category))
}

const destroyTracks = function(category) {
  if (!this.tour) return
  this.tour.off('cancel', () => cancelTrack.call(this, category))
  this.tour.off('show', () => showTrack.call(this, category))
  this.tour.off('start', () => startTrack.call(this, category))
  this.tour.off('complete', () => completeTrack.call(this, category))
}
export default {
  initTracks,
  destroyTracks,
}
