export const finishPurchase = async ({ commit, dispatch, rootState }, data) => {
  data.itemsToUpdate.forEach(item => {
    commit(`products/${typesProducts.UPDATE_PRODUCT_STOCK}`, item, {
      root: true,
    })
    commit(`products/${typesProducts.UPDATE_PRODUCT_COST}`, item, {
      root: true,
    })
    const productFound = rootState.products.data.products.find(
      prod => prod.upc === item.upc
    )
    if (productFound) {
      dispatch(
        `customPromotions/${customPromotionsActionsTypes.updateProduct}`,
        productFound,
        { root: true }
      )
    }
  })
  data.returnItemsToUpdate.forEach(returnItem => {
    commit(`products/${typesProducts.UPDATE_PRODUCT_STOCK}`, returnItem, {
      root: true,
    })
    commit(`products/${typesProducts.UPDATE_PRODUCT_COST}`, returnItem, {
      root: true,
    })
    const productFound = rootState.products.data.products.find(
      prod => prod.upc === returnItem.upc
    )
    if (productFound) {
      dispatch(
        `customPromotions/${customPromotionsActionsTypes.updateProduct}`,
        productFound,
        { root: true }
      )
    }
  })
  commit(
    `usersView/${typesUsersView.SET_USER_ESTIMATED_CASH}`,
    formatNumberFromDb(data.estimatedCash),
    { root: true }
  )
  commit(types.SET_FINISHING_PURCHASE_STATUS, false)
  logger('info', `Purchase finished`)
}
