<template>
  <v-list-item-group>
    <v-list-item
      v-for="(item, index) in items"
      :key="index"
      @click="openPlayerWindow(item)"
    >
      <v-list-item-icon>
        <v-icon color="primary">mdi-youtube</v-icon>
      </v-list-item-icon>
      <v-list-item-content>
        <v-list-item-title>{{ item.title }}</v-list-item-title>
      </v-list-item-content>
    </v-list-item>
  </v-list-item-group>
</template>

<script>
import VIDEO_WINDOW_EVENTS from '@/config/events/videoWindow'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

export default {
  name: 'VideoListItem',
  props: {
    items: {
      type: Array,
      required: true,
    },
  },
  methods: {
    openPlayerWindow(item) {
      if (navigator.onLine) {
        rendererEventsService.send(VIDEO_WINDOW_EVENTS.channel, {
          event: VIDEO_WINDOW_EVENTS.events.loadVideoWindow.name,
          data: { video: item },
        })
      } else {
        notificationsService.showError(
          'notification.helpCenter.internetConnectionError',
          this.$vuetify.lang,
          { timeout: 10000 }
        )
      }
    },
  },
}
</script>
