import mutationsTypes from '@/store/expenses/mutations.types'

const setFetching = (state, newState) => {
  state.fetching = newState
}

const setError = (state, error) => {
  state.data.expenses = []
  state.error = true
  state.errorMessage = error
}

const setExpenses = (state, payload) => {
  state.data.expenses = payload
  state.error = false
  state.errorMessage = ''
}

export default {
  [mutationsTypes.SET_EXPENSES]: setExpenses,
  [mutationsTypes.SET_EXPENSES_FETCHING]: setFetching,
  [mutationsTypes.SET_EXPENSES_ERROR]: setError,
}
