export const updateVendorPurchase = (purchaseOrders, vendor, payables) => {
  let vendorPurchases = purchaseOrders.filter(
    purchaseOrder => purchaseOrder.vendor_id === vendor.id
  )
  if (vendorPurchases.length > 0) {
    vendorPurchases = vendorPurchases.sort(
      (a, b) =>
        Number(new Date(b.delivery_date)) - Number(new Date(a.delivery_date))
    )
  }
  vendor.purchases = vendorPurchases
  vendor.payables = []
  vendor.unpaidPayablesNumber = 0
  vendor.debt = 0
  vendor.purchases.forEach(purchase => {
    vendor.expense += purchase.cost
    purchase.hasPromotion = purchase.has_promotion === 1
    const payable = payables.find(
      payable => purchase._id === payable.purchase_id
    )
    if (payable !== undefined) {
      vendor.unpaidPayablesNumber += payable.paid === 1 ? 0 : 1
      vendor.debt += payable.amount - payable.settled
      vendor.payables.push(payable)
    }
  })
  vendor.payables.sort((a, b) => new Date(b.due_date) - new Date(a.due_date))
  vendor.purchaseNumber = vendorPurchases.length
  vendor.payablesNumber = vendor.payables.length
  vendor.expense = 0
  vendor.isSupplierAdded = true
  return vendor
}
