<template>
  <div>
    <v-row no-gutters align="center" class="py-5">
      <v-col
        class=" text-left  py-0 pl-2 d-flex justify-space-around align-center"
      >
        <FormattedText
          type="text-body-2"
          color="primary"
          intl
          value="starterLayout.login.terms"
          :link="openTermsWindow"
          v-track:click="{
            category: 'Signup',
            screen: 'AuthFooter',
            name: 'Open terms',
          }"
        />
        <FormattedText
          type="text-body-2"
          color="primary"
          intl
          value="starterLayout.login.support"
          :link="openSupportWindow"
          v-track:click="{
            category: 'Signup',
            screen: 'AuthFooter',
            name: 'Open support',
          }"
        />
        <img :src="require('../../assets/white_ftk_logo.svg')" height="40" />
      </v-col>
    </v-row>

    <TermsDialog v-if="termsDialog.isOpen" />
    <SupportDialog v-if="supportDialog.isOpen" />
    <RememberPasswordDialog v-if="rememberPasswordDialog.isOpen" />
    <OneTimePasswordDialog v-if="oneTimePasswordDialog.isOpen" />
    <ChangePasswordDialog v-if="changePasswordDialog.isOpen" />
    <ConfirmDeviceChangeDialog v-if="confirmDeviceChangeDialog.isOpen" />
  </div>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import appActions from '@/store/app/actions.types'

import FormattedText from '@/components/shared/FormattedText'
import TermsDialog from '@/components/AuthViews/TermsDialog'
import SupportDialog from '@/components/AuthViews/SupportDialog'
import RememberPasswordDialog from '@/components/RememberPasswordDialog'
import OneTimePasswordDialog from '@/components/OneTimePasswordDialog'
import ChangePasswordDialog from '@/components/ChangePasswordDialog'
import ConfirmDeviceChangeDialog from '@/components/ConfirmDeviceChangeDialog'

export default {
  name: 'AuthViewsFooter',
  components: {
    FormattedText,
    TermsDialog,
    SupportDialog,
    RememberPasswordDialog,
    OneTimePasswordDialog,
    ChangePasswordDialog,
    ConfirmDeviceChangeDialog,
  },
  computed: {
    ...mapState('app', [
      'termsDialog',
      'supportDialog',
      'rememberPasswordDialog',
      'oneTimePasswordDialog',
      'changePasswordDialog',
      'confirmDeviceChangeDialog',
    ]),
  },
  methods: {
    ...mapActions('app', [
      appActions.setTermsDialogStatus,
      appActions.setSupportDialogStatus,
    ]),
    openTermsWindow() {
      this[appActions.setTermsDialogStatus](true)
    },
    openSupportWindow() {
      this[appActions.setSupportDialogStatus](true)
    },
  },
}
</script>
<style lang="scss" scoped>
.main {
  width: 400px;
}
</style>
