<template>
  <v-dialog
    v-model="opened"
    :max-width="config.maxWidth"
    :retain-focus="false"
    eager
    :persistent="!!config.persistent"
    content-class="default-dialog"
    :overlay-opacity="0.15"
    :hide-overlay="hideOverlay"
    @click:outside="outsideIsClicked"
    @keydown="processKeydown"
  >
    <v-card
      class="dialog-style"
      :color="
        config.backgroundColor
          ? config.backgroundColor
          : 'cardBackgroundPrimary'
      "
      :style="cardStyles"
      :id="config.ref"
      v-show="!config.hidden"
    >
      <v-card-title
        v-if="config.title"
        class="simple-title"
        :style="`background-color: ${config.titleBackground};`"
      >
        <v-icon :color="config.titleColor">{{ config.icon }}</v-icon>
        <FormattedText
          type="text-h6"
          intl
          :value="config.title"
          :color="config.titleColor"
          class="title-text"
        />
        <slot name="titleRight" />
      </v-card-title>
      <v-card-text>
        <FormattedText type="body" color="textPrimary" class="body-text">
          <p v-for="msg in config.messages" :key="msg">
            {{
              config.extraValuesMessages
                ? getTranslatedText(msg, config.extraValuesMessages)
                : getTranslatedText(msg)
            }}
          </p>
        </FormattedText>
        <slot></slot>
      </v-card-text>
      <v-card-actions v-if="$slots.footer">
        <v-spacer />
        <slot name="footer" />
      </v-card-actions>
      <v-card-actions v-else-if="buttons.cancel || buttons.accept">
        <slot name="leftFooter" />
        <v-spacer />
        <v-btn
          v-if="buttons.cancel === true"
          :color="config.buttonColor.cancel"
          @click="config.onClickCancel"
          ref="dialogCancel"
        >
          <FormattedText
            intl
            :value="
              config.cancelButtonText !== undefined
                ? config.cancelButtonText
                : 'shared.cancel'
            "
            :color="config.buttonTextColor.cancel"
          />
        </v-btn>
        <v-btn
          v-if="buttons.accept === true"
          :color="config.buttonColor.accept"
          @click="config.onClickAccept"
          ref="dialogAccept"
          :type="'id' in config ? 'submit' : 'button'"
          :form="'id' in config ? config.id : ''"
          :disabled="config.isAcceptButtonDisabled || false"
          :id="`dialog-accept-${config.ref}`"
        >
          <FormattedText
            intl
            :value="
              config.acceptButtonText !== undefined
                ? config.acceptButtonText
                : 'shared.accept'
            "
            :color="config.buttonTextColor.accept"
          />
        </v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script>
import { isNil } from 'ramda'

import { mapState } from 'vuex'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'DialogCard',
  components: {
    FormattedText,
  },
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  computed: {
    ...mapState('app', ['onboardingEnabled']),
    ...mapState('productsView', {
      productsTourEnable: state => state.tourEnabled,
    }),
    ...mapState('purchasesView', {
      purchasesTourEnable: state => state.tourEnabled,
    }),
    cardStyles() {
      const styles = 'cardStyles' in this.config ? this.config.cardStyles : {}
      if (this.config.height) styles.height = `${this.config.height}px`
      return styles
    },
    opened() {
      return 'opened' in this.config ? this.config.opened : true
    },
    buttons() {
      return isNil(this.config.buttons)
        ? { accept: true, cancel: true }
        : {
            accept: this.config.buttons.accept,
            cancel: this.config.buttons.cancel,
          }
    },
    hideOverlay() {
      return (
        this.onboardingEnabled ||
        this.productsTourEnable ||
        this.purchasesTourEnable
      )
    },
  },
  methods: {
    getTranslatedText: function(translateString, values = null) {
      if (values != null)
        return this.$vuetify.lang.t(`$vuetify.${translateString}`, ...values)
      return this.$vuetify.lang.t(`$vuetify.${translateString}`)
    },
    processKeydown(event) {
      if (event.code === 'Escape') return this.config.onClickCancel()
      if (
        (event.code === 'Enter' || event.code === 'NumpadEnter') &&
        this.$slots.default === undefined
      ) {
        return this.config.onClickAccept()
      }
    },
    outsideIsClicked() {
      if (this.config.persistent) return
      this.config.onClickCancel()
    },
  },
}
</script>

<style lang="scss" scoped>
.dialog-style {
  .title-text {
    font-family: Lato, Helvetica, Roboto, Arial, sans-serif;
  }
  .body-text {
    font-family: Lato, Helvetica, Roboto, Arial, sans-serif;
    line-height: 24px;
    font-size: 16px;
    word-break: break-word;
  }
}
</style>
