import { vendor as vendorMapper } from '@/config/storeMapper'

import { mapStoreObject } from '@/tools/data'
import logger from '@/tools/logger'

import { updateVendorPurchase } from './actions.tools'
import mutationsTypes from './mutations.types'

export const setVendorsFetching = ({ commit }, payload) =>
  commit(mutationsTypes.SET_VENDORS_FETCHING, payload)

export const setVendorsError = ({ commit }, payload) =>
  commit(mutationsTypes.SET_VENDORS_ERROR, payload.message)

export const setVendors = ({ commit }, payload) => {
  const vendors = payload.vendors.map(vendor => {
    vendor = mapStoreObject(vendor, vendorMapper)
    return updateVendorPurchase(payload.purchaseOrder, vendor, payload.payables)
  })
  commit(mutationsTypes.SET_VENDORS_FETCHING, false)
  commit(mutationsTypes.SET_VENDORS, vendors)
}

export const addVendor = ({ commit }, payload) => {
  commit(mutationsTypes.ADD_VENDOR, payload)
}

export const deleteVendor = ({ commit }, payload) => {
  commit(mutationsTypes.DELETE_VENDOR, payload)
}

export const updateVendor = ({ commit }, payload) =>
  commit(mutationsTypes.UPDATE_VENDOR, payload)

export const editVendorField = ({ commit }, payload) =>
  commit(mutationsTypes.UPDATE_VENDOR, payload)

export const settleCreditPurchase = ({ commit }, data) => {
  commit(mutationsTypes.UPDATE_VENDOR, data)
  logger('info', 'Credit purchase settled')
}
