import CUSTOM_PROMOTIONS_DB_API_EVENTS from '@/config/events/databaseAPI/customPromotionsEvents'

import { dateIsSame, getNow } from '@/tools/dates'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import customPromotionsActions from '@/store/customPromotions/actions.types'
import salesActions from '@/store/sales/actions.types'

const addListeners = function() {
  rendererEventsService.subscribe(
    CUSTOM_PROMOTIONS_DB_API_EVENTS.replyChannel,
    (event, payload) => {
      const replies = {
        [CUSTOM_PROMOTIONS_DB_API_EVENTS.events.getAll.replies.success]: () => {
          this[customPromotionsActions.addLastUpdate](getNow())
          this[customPromotionsActions.addCustomPromotions](
            payload.data.promotions
          )
        },
        [CUSTOM_PROMOTIONS_DB_API_EVENTS.events.getAll.replies.error]: () => {
          this[customPromotionsActions.addLastUpdate](null)
        },
        [CUSTOM_PROMOTIONS_DB_API_EVENTS.events.disable.replies
          .success]: () => {
          this[customPromotionsActions.disableCustomPromotion](
            payload.data.promotionsId
          )
          notificationsService.showWarning(
            'customPromotionsView.alertDisabled',
            this.$vuetify.lang,
            { timeout: 5000 },
            [payload.data.productName]
          )
        },
        [CUSTOM_PROMOTIONS_DB_API_EVENTS.events.bulkDeletion.replies
          .success]: () => {
          if (!payload.data.fromBulkProductsDeletion) return
          this[customPromotionsActions.bulkCustomPromotionsDeletion](
            payload.data.promotionsIdsDeleted
          )
          if (payload.data.fromMeasureChange) {
            const productsUpc = payload.data.productsAffected
            productsUpc.forEach(product => {
              this[salesActions.removeProductFromAllSales]({
                product: product,
              })
            })
          }
          const message = payload.data.fromMeasureChange
            ? 'customPromotionsView.alertMeasureChange'
            : 'customPromotionsView.alertBulkDelete'
          notificationsService.showWarning(message, this.$vuetify.lang, {
            timeout: 5000,
          })
        },
      }
      if (payload.event in replies) replies[payload.event]()
    }
  )
}

const removeListeners = () => {
  rendererEventsService.removeListener(
    CUSTOM_PROMOTIONS_DB_API_EVENTS.replyChannel,
    addListeners
  )
}

const loadPromotions = function() {
  if (this.layout !== 'main-layout' || !this.isAccountLogged) return
  if (!!this.lastUpdate && dateIsSame(this.lastUpdate, getNow())) {
    return
  }
  rendererEventsService.send(CUSTOM_PROMOTIONS_DB_API_EVENTS.channel, {
    event: CUSTOM_PROMOTIONS_DB_API_EVENTS.events.getAll.name,
  })
}

const deactivationPromotion = function(productId) {
  if (!this.getCustomPromotionsByProduct[productId]) {
    return
  }
  rendererEventsService.send(CUSTOM_PROMOTIONS_DB_API_EVENTS.channel, {
    event: CUSTOM_PROMOTIONS_DB_API_EVENTS.events.disable.name,
    data: {
      promotions: this.getCustomPromotionsByProduct[productId],
      productId,
      userId: -1,
    },
  })
}

const deletePromotion = function({ productId, fromChangeMeasure = false }) {
  if (!this.getCustomPromotionsByProduct[productId]) return
  callDeleteBulkDeletionEvent(
    this.getCustomPromotionsByProduct[productId],
    this.userId,
    fromChangeMeasure
  )
}

const deleteBulkPromotions = function(productsIds) {
  const promotionsToDelete = productsIds.reduce((result, productId) => {
    if (this.getCustomPromotionsByProduct[productId]) {
      result = [...result, ...this.getCustomPromotionsByProduct[productId]]
    }
    return result
  }, [])
  if (!promotionsToDelete.length) return
  callDeleteBulkDeletionEvent(promotionsToDelete, this.userId)
}
const callDeleteBulkDeletionEvent = (
  promotionsToDelete,
  userId,
  fromMeasureChange
) => {
  rendererEventsService.send(CUSTOM_PROMOTIONS_DB_API_EVENTS.channel, {
    event: CUSTOM_PROMOTIONS_DB_API_EVENTS.events.bulkDeletion.name,
    data: {
      promotions: promotionsToDelete,
      fromBulkProductsDeletion: true,
      userId: userId,
      fromMeasureChange: fromMeasureChange,
    },
  })
}

export default {
  addListeners,
  removeListeners,
  deactivationPromotion,
  loadPromotions,
  deletePromotion,
  deleteBulkPromotions,
}
