import { required, decimal } from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-cash-register',
    title: 'mainLayout.user.amountDialogTitle',
    titleBackground: '#white',
    persistent: true,
    titleColor: 'textPrimary',
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    messages: ['mainLayout.user.amountDialog'],
    height: 300,
    maxWidth: 500,
    id: 'close-register-amount-form',
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.checkAdjustRegister(),
  },
  fields: [
    {
      id: 'amount',
      type: 'input',
      valueType: 'number',
      label: 'shared.amount',
      errorMessage: 'mainLayout.user.errorAmount',
      color: 'primaryColor',
      required: true,
      autofocus: true,
      validators: { required, decimal },
    },
  ],
  id: 'close-register-amount-form',
})

export default setConfig
