<template>
  <DialogCard :config="dialogConfig.dialogData">
    <v-row>
      <v-col cols="12">
        <FormattedText
          :value="messageToSend"
          type="text-h6"
          color="textPrimary"
          class="mb-1"
        />
        <div v-if="customersWithIncorrectPhone.length" class="test">
          <FormattedText
            :value="messageNotToSend"
            color="textPrimary"
            type="text-subtitle-1"
            className="font-weight-bold"
          />
          <FormattedText
            value="loyaltyProgramConfig.stepper.step2.messageInformationDialog.messageNotToSendInfo"
            intl
            color="textPrimary"
          />
        </div>
      </v-col>
      <v-col cols="12">
        <div class="body-text italic">
          {{ messageTemplate }}
          <br />
          <br />
          {{ form }}
        </div>
      </v-col>
    </v-row>
  </DialogCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import { getTranslatedText } from '@/tools/data'
import { formatNumberFromDb } from '@/tools/numbersFormat'
import { validatePhoneNumber } from '@/tools/customValidations'

import loyaltyProgramViewActions from '@/store/loyaltyProgramView/actions.types'

import setConfig from '@/components/LoyaltyViews/LoyaltyProgramConfigView/LoyaltyConfigStepper/ConfirmCustomerInvitedDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'ConfirmCustomerInvitedDialog',
  components: { DialogCard, FormattedText },
  computed: {
    ...mapState('loyaltyProgramView', ['messageInformationDialog']),
    ...mapState('account', {
      storePhone: state => state.data.storePhone,
    }),
    dialogConfig() {
      return setConfig(
        {
          opened: this.messageInformationDialog.isOpen,
          routeName: this.$route.name,
        },
        {
          closeDialog: this.closeDialog,
          acceptMessageInvitacion: this.acceptMessageInvitacion,
          track: this.$track,
        }
      )
    },
    customersWithIncorrectPhone() {
      return this.messageInformationDialog.data.customersAdded.filter(
        customer => !validatePhoneNumber(customer.phone)
      )
    },
    messageToSend() {
      return this.getTranslatedText(
        'loyaltyProgramConfig.stepper.step2.messageInformationDialog.messageToSend',
        this.messageInformationDialog.data.customersAdded.length -
          this.customersWithIncorrectPhone.length
      )
    },
    messageNotToSend() {
      return this.getTranslatedText(
        'loyaltyProgramConfig.stepper.step2.messageInformationDialog.messageNotToSend',
        this.customersWithIncorrectPhone.length
      )
    },
    messageTemplate() {
      return `${this.getTranslatedText(
        'loyaltyProgramConfig.stepper.step2.messageInformationDialog.messageTemplate1',
        this.messageInformationDialog.data.loyaltyFormInputs.storeName
      )}
      \n 
      ${this.getTranslatedText(
        'loyaltyProgramConfig.stepper.step2.messageInformationDialog.messageTemplate2',
        formatNumberFromDb(
          this.messageInformationDialog.data.loyaltyFormInputs.rewardAmount
        )
      )} 
      `
    },
    form() {
      return this.getTranslatedText(
        'loyaltyProgramConfig.stepper.step2.messageInformationDialog.messageTemplate3'
      )
    },
    messageEnd() {
      return this.getTranslatedText(
        'loyaltyProgramConfig.stepper.step2.messageInformationDialog.messageEnd',
        this.storePhone
      )
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('loyaltyProgramView', [
      loyaltyProgramViewActions.setMessageInformationDialogStatus,
    ]),
    closeDialog() {
      this[loyaltyProgramViewActions.setMessageInformationDialogStatus]({
        isOpen: false,
      })
    },
    acceptMessageInvitacion() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'ConfirmCustomerInvitedDialog',
        name: 'Confirm',
      })
      this.$root.$emit('loyalty-accept-message-invitation', {
        isAccept: true,
      })
      this.closeDialog()
    },
  },
  beforeDestroy() {
    this.closeDialog()
  },
}
</script>

<style lang="scss" scoped>
.body-text {
  font-family: Lato, Helvetica, Roboto, Arial, sans-serif;
  line-height: 24px;
  font-size: 16px;
  word-break: break-word;
}
.italic {
  font-style: italic;
}
</style>
