<template>
  <v-row>
    <v-list-item-icon v-if="!sidebarOpened">
      <v-tooltip
        right
        nudge-right="12"
        :color="tooltipColor"
        :disabled="disabled"
      >
        <template v-slot:activator="{ on }">
          <v-icon v-on="!sidebarOpened ? on : null">{{ data.icon }}</v-icon>
        </template>
        <FormattedText
          :value="`mainLayout.navigation['${data.name}']`"
          intl
          :color="tooltipTextColor"
        />
      </v-tooltip>
    </v-list-item-icon>

    <v-list-item-title v-if="sidebarOpened">
      <FormattedText
        :value="`mainLayout.navigation['${data.name}']`"
        intl
        color="textPrimary"
        className="text-uppercase font-weight-bold pl-2"
      />
    </v-list-item-title>
  </v-row>
</template>

<script>
import { mapState } from 'vuex'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'MainViewSidebarGroupItem',
  components: {
    FormattedText,
  },
  props: {
    data: {
      type: Object,
      default: null,
    },
    tooltipColor: {
      type: String,
      default: 'textPrimary',
    },
    tooltipTextColor: {
      type: String,
      default: 'white',
    },
    disabled: {
      type: Boolean,
      default: false,
    },
  },
  computed: {
    ...mapState('app', ['sidebarOpened']),
  },
}
</script>
